// The local human house continues to use RuntimeWindowState::economy as the
// sidebar facade and sole authority. Remote human houses retain their own
// serializable economy/tech records here. A local entry deliberately has no
// economy copy, avoiding two sources of truth for the local player.
struct RuntimeHumanHouseAuthority {
    std::size_t slotIndex = 0;
    std::string owner;
    std::string canonicalOwner;
    std::string country;
    bool localFacade = false;
    std::optional<RuntimeEconomyState> remoteEconomy;
    std::optional<TechTreeReport> remoteTechTree;
    bool remoteTechTreeLoaded = false;
};

// Skirmish computer players intentionally keep their economy separate from
// RuntimeEconomyState, which is the local player's sidebar/production model.
// The AI spends real per-house credits, advances on deterministic tick
// deadlines, and persists every deadline so loading a save cannot reset its
// build or attack cadence.
struct RuntimeComputerAiState {
    bool initialized = false;
    std::string owner;
    std::string country;
    std::string difficulty = "Medium";
    RuntimeCellPoint baseCenter;
    int credits = 0;
    int nextThinkTick = 0;
    int nextIncomeTick = 0; // Legacy save field; real mining has no income deadline.
    int nextBuildTick = 0;
    int nextAttackTick = 0;
    int nextRepairTick = 0;
    int productionSerial = 0;
    int incomeEarned = 0;
    int creditsSpent = 0;
    int structuresBuilt = 0;
    int infantryBuilt = 0;
    int unitsBuilt = 0;
    int freeUnitsReceived = 0;
    int attackWaves = 0;
    int attacksOrdered = 0;
    int defenseOrders = 0;
    int tacticalOrders = 0;
    int repairsPerformed = 0;
    int stalledBuilds = 0;
    int lastTargetObjectId = -1;
    std::string lastBuildType;
    std::string status = "waiting for skirmish start";
};

