RuntimeWindowCompletion runtimeWindowCompletionAfterMatch(
    bool confirmedExit,
    bool mainMenuEnabled
) {
    return confirmedExit && mainMenuEnabled
        ? RuntimeWindowCompletion::ReturnToMainMenu
        : RuntimeWindowCompletion::ExitProcess;
}

