constexpr double runtimeCratePowerupDataLimit = 1000000.0;

double runtimeNormalizeCratePowerupData(double data) {
    return std::isfinite(data)
        ? std::clamp(
            data,
            -runtimeCratePowerupDataLimit,
            runtimeCratePowerupDataLimit
        )
        : 0.0;
}

