std::uint64_t runtimeStableHashString(const std::string& value) {
    std::uint64_t hash = 1469598103934665603ull;
    for (unsigned char character : value) {
        hash ^= static_cast<std::uint64_t>(character);
        hash *= 1099511628211ull;
    }
    return hash;
}

void runtimeStableHashMix(std::uint64_t& hash, long long value) {
    hash ^= static_cast<std::uint64_t>(value) + 0x9e3779b97f4a7c15ull
        + (hash << 6)
        + (hash >> 2);
}

void runtimeStableHashMixString(
    std::uint64_t& hash,
    const std::string& value
) {
    runtimeStableHashMix(
        hash,
        static_cast<long long>(runtimeStableHashString(value))
    );
}

std::uint64_t runtimeObjectIdSetHash(
    const std::unordered_set<int>* objectIds
) {
    std::uint64_t hash = 1469598103934665603ull;
    if (objectIds == nullptr || objectIds->empty()) {
        runtimeStableHashMix(hash, 0);
        return hash;
    }

    std::vector<int> sortedIds(objectIds->begin(), objectIds->end());
    std::sort(sortedIds.begin(), sortedIds.end());
    runtimeStableHashMix(hash, static_cast<long long>(sortedIds.size()));
    for (int objectId : sortedIds) {
        runtimeStableHashMix(hash, objectId);
    }
    return hash;
}

