void releaseRuntimeBackBuffer(RuntimeBackBuffer& buffer) {
    if (buffer.memoryDc != nullptr
        && buffer.oldBitmap != nullptr
        && buffer.oldBitmap != HGDI_ERROR) {
        SelectObject(buffer.memoryDc, buffer.oldBitmap);
    }
    if (buffer.bitmap != nullptr) {
        DeleteObject(buffer.bitmap);
    }
    if (buffer.memoryDc != nullptr) {
        DeleteDC(buffer.memoryDc);
    }
    buffer = RuntimeBackBuffer{};
}

bool ensureRuntimeBackBuffer(
    RuntimeBackBuffer& buffer,
    HDC paintDc,
    int width,
    int height
) {
    if (width <= 0 || height <= 0 || paintDc == nullptr) {
        releaseRuntimeBackBuffer(buffer);
        return false;
    }

    if (buffer.memoryDc != nullptr
        && buffer.bitmap != nullptr
        && buffer.pixels != nullptr
        && buffer.width == width
        && buffer.height == height) {
        return true;
    }

    releaseRuntimeBackBuffer(buffer);

    HDC memoryDc = CreateCompatibleDC(paintDc);
    if (memoryDc == nullptr) {
        return false;
    }

    BITMAPINFO bitmapInfo{};
    bitmapInfo.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bitmapInfo.bmiHeader.biWidth = width;
    bitmapInfo.bmiHeader.biHeight = -height;
    bitmapInfo.bmiHeader.biPlanes = 1;
    bitmapInfo.bmiHeader.biBitCount = 32;
    bitmapInfo.bmiHeader.biCompression = BI_RGB;

    void* pixels = nullptr;
    HBITMAP bitmap = CreateDIBSection(
        paintDc,
        &bitmapInfo,
        DIB_RGB_COLORS,
        &pixels,
        nullptr,
        0
    );
    if (bitmap == nullptr || pixels == nullptr) {
        if (bitmap != nullptr) {
            DeleteObject(bitmap);
        }
        DeleteDC(memoryDc);
        return false;
    }

    HGDIOBJ oldBitmap = SelectObject(memoryDc, bitmap);
    if (oldBitmap == nullptr || oldBitmap == HGDI_ERROR) {
        DeleteObject(bitmap);
        DeleteDC(memoryDc);
        return false;
    }

    buffer.memoryDc = memoryDc;
    buffer.bitmap = bitmap;
    buffer.oldBitmap = oldBitmap;
    buffer.pixels = pixels;
    buffer.width = width;
    buffer.height = height;
    buffer.topDownDib = bitmapInfo.bmiHeader.biHeight == -height;
    return true;
}

void resetRuntimePerfPeaks(RuntimePerfCounters& perf) {
    perf.peakSimulationMs = 0.0;
    perf.peakSimMoveMs = 0.0;
    perf.peakSimPathMs = 0.0;
    perf.peakSimRepathCount = 0;
    perf.peakSimPathRequests = 0;
    perf.peakWorldObjectsMs = 0.0;
    perf.peakWorldObjectSortMs = 0.0;
}

void updateRuntimeSimulationPerfPeaks(RuntimePerfCounters& perf) {
    perf.peakSimulationMs =
        std::max(perf.peakSimulationMs, perf.lastSimulationMs);
    perf.peakSimMoveMs =
        std::max(perf.peakSimMoveMs, perf.lastSimMoveMs);
    perf.peakSimPathMs =
        std::max(perf.peakSimPathMs, perf.lastSimPathMs);
    perf.peakSimRepathCount =
        std::max(perf.peakSimRepathCount, perf.lastSimRepathCount);
    perf.peakSimPathRequests =
        std::max(perf.peakSimPathRequests, perf.lastSimPathRequests);
}

double runtimeLastMeasuredSimulationMs(const RuntimePerfCounters& perf) {
    return perf.lastSimEffectsMs
        + perf.lastSimEconomyMs
        + perf.lastSimTriggersMs
        + perf.lastSimBuildMs
        + perf.lastSimGuardMs
        + perf.lastSimMoveMs
        + perf.lastSimAttackMs;
}

void updateRuntimeRenderPerfPeaks(
    RuntimePerfCounters& perf,
    const RuntimeMapRenderStats& stats
) {
    perf.peakWorldObjectsMs =
        std::max(perf.peakWorldObjectsMs, stats.worldObjectsMs);
    perf.peakWorldObjectSortMs =
        std::max(perf.peakWorldObjectSortMs, stats.worldObjectSortMs);
}

