RuntimeLightingConfig runtimeLightingConfigForState(
    const RuntimeWindowState& state
) {
    RuntimeLightingConfig config;
    config.fixedTickHz = std::max(1, state.config.fixedTickHz);
    if (state.rulesLoaded) {
        const SpecialMechanismRules& special =
            state.rules.getSpecialMechanismRules();
        config.ambientChangeRate = special.ambientChangeRate;
        config.ambientChangeStep = special.ambientChangeStep;
    }
    return config;
}

void ensureRuntimeLightingInitialized(RuntimeWindowState& state) {
    if (state.lightingInitialized) {
        return;
    }
    state.lighting.reset(
        state.mapFacts.lighting,
        runtimeLightingConfigForState(state)
    );
    (void)state.lighting.tick(std::max(0, state.tick));
    state.lightingInitialized = true;
}

void ensureRuntimeParticlesInitialized(RuntimeWindowState& state) {
    if (state.particlesInitialized) {
        return;
    }
    state.particles.reset(std::max(1, state.config.fixedTickHz));
    if (!state.particles.alignEmptyStateTick(std::max(0, state.tick))) {
        throw std::logic_error("could not align empty particle authority");
    }
    state.particlesInitialized = true;
    state.particleRenderSnapshots.clear();
    state.particleBeamRenderSnapshots.clear();
    state.particleLocalLightRenderSnapshots.clear();
}

void refreshRuntimeParticleRenderSnapshots(
    RuntimeWindowState& state,
    RuntimeMapRenderContext& context
) {
    ensureRuntimeParticlesInitialized(state);
    state.particleRenderSnapshots = state.particles.renderSnapshots(
        state.rules,
        state.artLoaded ? &state.art : nullptr
    );
    state.particleBeamRenderSnapshots =
        state.particles.beamSnapshots(state.rules);
    state.particleLocalLightRenderSnapshots =
        state.particles.localLightSnapshots(state.rules);
    context.particleSnapshots = &state.particleRenderSnapshots;
    context.particleBeamSnapshots = &state.particleBeamRenderSnapshots;
    context.localLightSnapshots = &state.particleLocalLightRenderSnapshots;
}

RuntimeWorldAudioContext runtimeWorldAudioContext(
    const RuntimeWindowState& state
) {
    RuntimeWorldAudioContext context;
    context.catalog = &state.worldAudioCatalog;
    RuntimeCellPoint listener{-1, -1};
    const RECT viewport = state.cameraClampViewport;
    if (viewport.right > viewport.left && viewport.bottom > viewport.top) {
        POINT center{
            viewport.left + (viewport.right - viewport.left) / 2,
            viewport.top + (viewport.bottom - viewport.top) / 2
        };
        const POINT cell = approximateCellFromScreenPoint(
            state,
            viewport,
            center
        );
        listener = RuntimeCellPoint{cell.x, cell.y};
    } else if (!state.world.getWaypoints().empty()) {
        listener = RuntimeCellPoint{
            state.world.getWaypoints().front().x,
            state.world.getWaypoints().front().y
        };
    } else if (!state.world.getTerrainCells().empty()) {
        listener = RuntimeCellPoint{
            state.world.getTerrainCells().front().x,
            state.world.getTerrainCells().front().y
        };
    }
    if (listener.x >= 0 && listener.y >= 0) {
        context.listenerCellValid = true;
        context.listenerCell.x = listener.x;
        context.listenerCell.y = listener.y;
        const auto terrain = state.terrainByCell.find(
            runtimeCellKey(listener.x, listener.y)
        );
        context.listenerCell.level = terrain != state.terrainByCell.end()
                && terrain->second != nullptr
            ? terrain->second->level
            : 0;
    }
    return context;
}

void initializeRuntimeWorldAudio(RuntimeWindowState& state) {
    state.worldAudioCatalog = RuntimeWorldAudioCatalog{};
    state.worldAudioCatalogLoaded = false;
    if (state.soundLoaded) {
        std::string catalogError;
        state.worldAudioCatalogLoaded = state.worldAudioCatalog.loadFromIni(
            state.soundIni,
            &catalogError,
            nullptr
        );
        if (!state.worldAudioCatalogLoaded && !catalogError.empty()) {
            state.lastRuntimeSound = "world audio catalog: " + catalogError;
        }
    }
    state.worldAudio.reset(RuntimeWorldAudioConfig{
        std::max(1, state.config.fixedTickHz),
        4096U
    });
    state.worldAudioInitialized = true;
}

