bool runtimeProductionItemKeysMatch(
    std::string_view left,
    std::string_view right
) {
    return runtimeBuildLimitKey(std::string(left))
        == runtimeBuildLimitKey(std::string(right));
}

int runtimePendingBuildTypeCount(
    const RuntimeWindowState& state,
    const std::string& owner,
    const std::string& typeId
) {
    if (runtimeBuildLimitKey(owner)
        != runtimeBuildLimitKey(state.economy.owner)) {
        return 0;
    }

    const std::string typeKey = runtimeBuildLimitKey(typeId);
    int count = 0;
    for (const RuntimeProductionLane lane : runtimeProductionLanes) {
        const RuntimeProductionLaneState& laneState =
            state.economy.localProductionLanes.lanes[
                runtimeProductionLaneIndex(lane)
            ];
        count += static_cast<int>(std::count_if(
            laneState.queued.begin(),
            laneState.queued.end(),
            [&](const RuntimeProductionLaneOrder& order) {
                return runtimeBuildLimitKey(order.itemKey) == typeKey;
            }
        ));
        if (laneState.active.has_value()
            && runtimeBuildLimitKey(laneState.active->itemKey) == typeKey) {
            ++count;
        }
        if (laneState.ready.has_value()
            && runtimeBuildLimitKey(laneState.ready->itemKey) == typeKey) {
            ++count;
        }
    }
    return count;
}

int runtimeLimitedBuildHistoryCount(
    const RuntimeWindowState& state,
    const std::string& owner,
    const std::string& typeId
) {
    const auto ownerIt = state.economy.limitedBuildHistoryByOwner.find(
        runtimeBuildLimitKey(owner)
    );
    if (ownerIt == state.economy.limitedBuildHistoryByOwner.end()) {
        return 0;
    }
    const auto typeIt = ownerIt->second.find(runtimeBuildLimitKey(typeId));
    return typeIt == ownerIt->second.end() ? 0 : typeIt->second;
}

void recordRuntimeCompletedBuild(
    RuntimeWindowState& state,
    const std::string& owner,
    const RuntimeBuildCatalogItem& item,
    int count = 1
) {
    recordRuntimeMatchBuild(state, owner, count);
    if (!item.buildLimit.has_value()
        || *item.buildLimit >= 0
        || count <= 0) {
        return;
    }
    int& history = state.economy.limitedBuildHistoryByOwner[
        runtimeBuildLimitKey(owner)
    ][runtimeBuildLimitKey(item.typeId)];
    history = std::min(
        std::numeric_limits<int>::max(),
        history > std::numeric_limits<int>::max() - count
            ? std::numeric_limits<int>::max()
            : history + count
    );
}

void initializeRuntimeLimitedBuildHistory(RuntimeWindowState& state) {
    state.economy.limitedBuildHistoryByOwner.clear();
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        if (!object.alive
            || trimAsciiLocal(object.owner).empty()
            || trimAsciiLocal(object.type).empty()) {
            continue;
        }
        ++state.economy.limitedBuildHistoryByOwner[
            runtimeBuildLimitKey(object.owner)
        ][runtimeBuildLimitKey(object.type)];
    }
}

int runtimeBuildLimitUsedCount(
    const RuntimeWindowState& state,
    const std::string& owner,
    const RuntimeBuildCatalogItem& item,
    bool includePending
) {
    if (!item.buildLimit.has_value()) {
        return 0;
    }
    const int configuredLimit = *item.buildLimit;
    const int builtCount = configuredLimit < 0
        ? runtimeLimitedBuildHistoryCount(state, owner, item.typeId)
        : runtimeLiveOwnedTypeCount(state, owner, item.typeId);
    const int pendingCount = (
        includePending
            ? runtimePendingBuildTypeCount(state, owner, item.typeId)
            : 0
    );
    return static_cast<int>(std::min<long long>(
        static_cast<long long>(std::max(0, builtCount))
            + static_cast<long long>(std::max(0, pendingCount)),
        std::numeric_limits<int>::max()
    ));
}

std::string runtimeBuildLimitBlockReason(
    const RuntimeWindowState& state,
    const std::string& owner,
    const RuntimeBuildCatalogItem& item,
    bool computerPlayer,
    bool includePending
) {
    if (!item.buildLimit.has_value()) {
        return "";
    }
    const int configuredLimit = *item.buildLimit;
    // Vanilla BuildLimit=0 is an AI-only object contract.  Human sidebars
    // keep the cameo disabled while computer production may still select it.
    if (configuredLimit == 0) {
        return computerPlayer
            ? std::string()
            : "disabled by BuildLimit=0";
    }
    const int maximum = runtimeBuildLimitMagnitude(configuredLimit);
    if (runtimeBuildLimitUsedCount(state, owner, item, includePending)
        < maximum) {
        return "";
    }
    return "build limit " + std::to_string(maximum)
        + " reached for " + item.typeId;
}

std::string runtimeStructureBuildSlotBlockReason(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    const std::optional<RuntimeProductionLane> lane =
        runtimeProductionLaneForCatalogItem(state, item);
    if (!lane.has_value()
        || (*lane != RuntimeProductionLane::Structures
            && *lane != RuntimeProductionLane::Armory)) {
        return "";
    }
    const RuntimeProductionLaneState& laneState =
        state.economy.localProductionLanes.lanes[
            runtimeProductionLaneIndex(*lane)
        ];
    if (laneState.ready.has_value()) {
        const std::string typeId = trimAsciiLocal(laneState.ready->itemKey);
        return "place or cancel ready "
            + (typeId.empty() ? std::string("structure") : typeId);
    }

    if (laneState.active.has_value()) {
        const std::string typeId = trimAsciiLocal(
            laneState.active->itemKey
        );
        return (laneState.onHold
                ? "resume or cancel held "
                : "under construction ")
            + (typeId.empty() ? std::string("structure") : typeId);
    }

    if (!laneState.queued.empty()) {
        const std::string typeId = trimAsciiLocal(
            laneState.queued.front().itemKey
        );
        return "already queued "
            + (typeId.empty() ? std::string("structure") : typeId);
    }

    return "";
}

