RuntimeSpecialBuildingContext makeRuntimeSpecialBuildingContext(
    const RuntimeWindowState& state
) {
    RuntimeSpecialBuildingContext context;
    context.rules = state.rulesLoaded ? &state.rules : nullptr;
    context.objects = &state.world.getObjects();
    context.canonicalOwnerId = [&state](const std::string& owner) {
        return runtimeRepairDepotCanonicalOwnerId(state, owner);
    };
    context.ownerIsNeutral = [](const std::string& owner) {
        return runtimeOwnerIsNeutralForAutoTarget(owner);
    };
    context.fixedTickHz = std::max(1, state.config.fixedTickHz);
    return context;
}

#include "ui/sidebar/RuntimePaintSecretLabPhase.inl"

std::optional<RuntimeFactoryPlantCostCategory>
runtimeFactoryPlantCostCategoryForItem(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    if (item.kind == RuntimeBuildKind::Building
        || item.kind == RuntimeBuildKind::Defense) {
        const BuildingType* building = findRuntimeBuildingTypeById(
            state.rules,
            item.typeId
        );
        if (building == nullptr) {
            return std::nullopt;
        }
        const std::string buildCategory = toUpperAsciiLocal(
            trimAsciiLocal(building->buildCat)
        );
        return buildCategory == "COMBAT"
            ? RuntimeFactoryPlantCostCategory::Defenses
            : RuntimeFactoryPlantCostCategory::Buildings;
    }
    if (state.rules.findUnitType("InfantryType", item.typeId) != nullptr) {
        return RuntimeFactoryPlantCostCategory::Infantry;
    }
    if (state.rules.findUnitType("UnitType", item.typeId) != nullptr) {
        return RuntimeFactoryPlantCostCategory::Units;
    }
    if (state.rules.findUnitType("AircraftType", item.typeId) != nullptr) {
        return RuntimeFactoryPlantCostCategory::Aircraft;
    }
    return std::nullopt;
}

int runtimeRawBuildCostForItem(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    if (item.kind == RuntimeBuildKind::Building
        || item.kind == RuntimeBuildKind::Defense) {
        const BuildingType* building = findRuntimeBuildingTypeById(
            state.rules,
            item.typeId
        );
        return building == nullptr ? 0 : std::max(0, building->cost);
    }
    const UnitType* unit = item.kind == RuntimeBuildKind::Infantry
        ? state.rules.findUnitType("InfantryType", item.typeId)
        : state.rules.findUnitType("UnitType", item.typeId);
    if (unit == nullptr && item.kind == RuntimeBuildKind::Unit) {
        unit = state.rules.findUnitType("AircraftType", item.typeId);
    }
    return unit == nullptr ? 0 : std::max(0, unit->cost);
}

int runtimeAdjustedFactoryPlantCost(
    const RuntimeWindowState& state,
    const std::string& owner,
    const RuntimeBuildCatalogItem& item,
    int baseCost,
    const RuntimeFactoryPlantCostSnapshot* costSnapshot = nullptr
) {
    const std::optional<RuntimeFactoryPlantCostCategory> category =
        runtimeFactoryPlantCostCategoryForItem(state, item);
    if (!category.has_value()) {
        return std::max(0, baseCost);
    }
    const RuntimeSpecialBuildingContext context =
        makeRuntimeSpecialBuildingContext(state);
    const auto adjusted = [&](RuntimeFactoryPlantCostCategory costCategory,
                              int cost) {
        if (costSnapshot != nullptr) {
            return costSnapshot->adjustedProductionCost(
                costCategory, std::max(0, cost));
        }
        return RuntimeSpecialBuildingSystem::adjustedProductionCost(
            context,
            owner,
            costCategory,
            std::max(0, cost)
        );
    };

    if (item.kind == RuntimeBuildKind::Building
        || item.kind == RuntimeBuildKind::Defense) {
        const BuildingType* building = findRuntimeBuildingTypeById(
            state.rules,
            item.typeId
        );
        const UnitType* freeUnit = building == nullptr
            || trimAsciiLocal(building->freeUnit).empty()
            ? nullptr
            : findRuntimeUnitTypeById(state.rules, building->freeUnit);
        if (freeUnit != nullptr && freeUnit->cost > 0
            && baseCost >= freeUnit->cost) {
            RuntimeFactoryPlantCostCategory freeUnitCategory =
                RuntimeFactoryPlantCostCategory::Units;
            if (state.rules.findUnitType(
                    "InfantryType",
                    freeUnit->id
                ) != nullptr) {
                freeUnitCategory = RuntimeFactoryPlantCostCategory::Infantry;
            } else if (state.rules.findUnitType(
                           "AircraftType",
                           freeUnit->id
                       ) != nullptr) {
                freeUnitCategory = RuntimeFactoryPlantCostCategory::Aircraft;
            }
            const int structureCost = adjusted(
                *category,
                baseCost - freeUnit->cost
            );
            const int payloadCost = adjusted(
                freeUnitCategory,
                freeUnit->cost
            );
            return structureCost > std::numeric_limits<int>::max()
                    - payloadCost
                ? std::numeric_limits<int>::max()
                : structureCost + payloadCost;
        }
    }
    return adjusted(*category, baseCost);
}

bool refreshRuntimeFactoryPlantCatalog(RuntimeWindowState& state) {
    RuntimePerfTraceScope trace("refreshRuntimeFactoryPlantCatalog", state.tick);
    bool changed = false;
    const RuntimeFactoryPlantCostSnapshot costSnapshot = state.economy.catalog.empty()
        ? RuntimeFactoryPlantCostSnapshot{}
        : RuntimeSpecialBuildingSystem::factoryPlantCostSnapshot(
            makeRuntimeSpecialBuildingContext(state), state.economy.owner);
    for (RuntimeBuildCatalogItem& item : state.economy.catalog) {
        const int adjustedCost = runtimeAdjustedFactoryPlantCost(
            state,
            state.economy.owner,
            item,
            runtimeRawBuildCostForItem(state, item),
            &costSnapshot
        );
        if (item.cost == adjustedCost) {
            continue;
        }
        item.cost = adjustedCost;
        changed = true;
    }
    // The original engine prices an order when it actually enters the active
    // factory. Orders that are still waiting follow the current house
    // multiplier; active and placement-ready orders retain their paid price.
    for (RuntimeProductionLaneState& laneState :
            state.economy.localProductionLanes.lanes) {
        for (RuntimeProductionLaneOrder& order : laneState.queued) {
            const auto catalog = std::find_if(
                state.economy.catalog.begin(),
                state.economy.catalog.end(),
                [&order](const RuntimeBuildCatalogItem& item) {
                    return toUpperAsciiLocal(item.typeId)
                        == toUpperAsciiLocal(order.itemKey);
                }
            );
            if (catalog != state.economy.catalog.end()
                && order.cost != catalog->cost) {
                order.cost = std::max(0, catalog->cost);
                changed = true;
            }
        }
    }
    return changed;
}

RuntimeSpecialBuildingUnlockKind runtimeSpecialUnlockKind(
    const RuntimeBuildCatalogItem& item
) {
    if (item.kind == RuntimeBuildKind::Infantry) {
        return RuntimeSpecialBuildingUnlockKind::Infantry;
    }
    if (item.kind == RuntimeBuildKind::Unit) {
        return RuntimeSpecialBuildingUnlockKind::Unit;
    }
    return RuntimeSpecialBuildingUnlockKind::Building;
}

bool runtimeBuildItemHasSecretLabUnlock(
    const RuntimeWindowState& state,
    const std::string& owner,
    const RuntimeBuildCatalogItem& item
) {
    std::optional<RuntimePerfTraceScope> secretLabQueryTrace;
    if (RuntimeSidebarOwnedQueryDiagnostics::Phase::observes(&state))
        secretLabQueryTrace.emplace("sidebar.secretLab.unlockQuery", state.tick);
    if (auto* phase = RuntimePaintSecretLabPhaseScope::active) {
        if (const auto* context = phase->contextFor(state)) {
            return RuntimeSpecialBuildingSystem::ownerHasSecretLabUnlock(
                *context, owner, runtimeSpecialUnlockKind(item), item.typeId
            );
        }
    }
    return RuntimeSpecialBuildingSystem::ownerHasSecretLabUnlock(
        makeRuntimeSpecialBuildingContext(state),
        owner,
        runtimeSpecialUnlockKind(item),
        item.typeId
    );
}

bool runtimeBuildItemMeetsStolenTechRequirements(
    const RuntimeWindowState& state, const std::string& owner,
    const RuntimeBuildCatalogItem& item
) {
    if (item.kind == RuntimeBuildKind::Building || item.kind == RuntimeBuildKind::Defense) {
        return true;
    }
    const UnitType* unit = findRuntimeUnitTypeById(state.rules, item.typeId);
    return unit == nullptr || state.spies.meetsStolenTechRequirements(owner, *unit);
}

struct RuntimeTechTreeDecision {
    bool staticAllowed = false;
    bool ownerAllowed = false;
    bool techAllowed = false;
    bool factoryAvailable = false;
    bool prerequisitesMet = false;
    bool enoughCredits = false;
    bool canQueue = false;
    bool canStart = false;
    bool lowPower = false;
    bool lowPowerAfterBuild = false;
    int powerNet = 0;
    int powerNetAfterBuild = 0;
    int techLevel = 0;
    int maxTechLevel = 10;
    std::string missingFactory;
    std::string missingPrerequisite;
    std::string reason;
};

RuntimeTechTreeDecision evaluateRuntimeTechTreeDecisionUnmemoized(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    RuntimeTechTreeDecision decision;
    const bool secretLabUnlock = runtimeBuildItemHasSecretLabUnlock(
        state,
        state.economy.owner,
        item
    );
    decision.staticAllowed =
        (item.techTreeAllowed && !item.secretLabInjected)
        || secretLabUnlock;
    decision.ownerAllowed = secretLabUnlock
        || runtimeBuildItemVisibleForPlayerCountry(state, item);
    decision.techLevel = item.techLevel;
    decision.maxTechLevel = state.economy.techLevel;
    decision.techAllowed = secretLabUnlock
        || (item.techLevel >= 0
            && item.techLevel <= state.economy.techLevel);
    decision.factoryAvailable = runtimeOwnerHasCompatibleFactory(
        state,
        state.economy.owner,
        item
    );
    decision.enoughCredits = state.economy.credits >= item.cost;
    decision.powerNet = runtimePowerNet(state);
    decision.powerNetAfterBuild = runtimePowerNetAfterBuildItem(state, item);
    decision.lowPower = decision.powerNet < 0;
    decision.lowPowerAfterBuild = decision.powerNetAfterBuild < 0;

    if (!decision.staticAllowed) {
        decision.reason = item.techTreeBlockedReason.empty()
            ? "blocked by tech tree"
            : item.techTreeBlockedReason;
        return decision;
    }
    if (!decision.ownerAllowed) {
        decision.reason = "wrong country or side";
        return decision;
    }
    if (!decision.techAllowed) {
        decision.reason =
            "requires tech "
            + std::to_string(item.techLevel)
            + "/"
            + std::to_string(state.economy.techLevel);
        return decision;
    }
    if (!runtimeBuildItemMeetsStolenTechRequirements(state, state.economy.owner, item)) {
        decision.reason = "requires stolen technology";
        return decision;
    }
    if (!decision.factoryAvailable) {
        decision.missingFactory = item.requiredFactory;
        decision.reason = item.requiredFactory.empty()
            ? "missing factory"
            : "missing " + item.requiredFactory;
        return decision;
    }

    decision.prerequisitesMet = secretLabUnlock
        || runtimePrerequisitesMet(
            state,
            item.prerequisite,
            &decision.missingPrerequisite
        );
    if (!decision.prerequisitesMet
        && runtimePrerequisiteOverrideMet(
            state,
            item.prerequisiteOverride
        )) {
        decision.prerequisitesMet = true;
        decision.missingPrerequisite.clear();
    }
    if (!decision.prerequisitesMet) {
        decision.reason =
            "missing prerequisite " + decision.missingPrerequisite;
        return decision;
    }

    decision.canQueue = true;
    decision.canStart = decision.enoughCredits;
    if (!decision.enoughCredits) {
        decision.reason = "waiting credits";
    } else if (decision.lowPower) {
        decision.reason = "ready, low power";
    } else if (decision.lowPowerAfterBuild) {
        decision.reason = "ready, will drain power";
    } else {
        decision.reason = "ready";
    }
    return decision;
}

// Window messages and simulation cannot interleave inside this paint scope.
// Catalog decisions are copied by value and never survive the completed paint.
struct RuntimePaintTechTreeMemoScope {
    static inline thread_local RuntimePaintTechTreeMemoScope* active = nullptr;
    RuntimePaintTechTreeMemoScope* previous = active;
    const RuntimeWindowState* state = nullptr;
    const RuntimeBuildCatalogItem* catalogData = nullptr;
    std::size_t catalogCount = 0;
    std::vector<std::optional<RuntimeTechTreeDecision>> decisions;
    std::uint64_t hits = 0;
    RuntimePaintTechTreeMemoScope() { active = this; }
    ~RuntimePaintTechTreeMemoScope() { active = previous; }
};

RuntimeTechTreeDecision evaluateRuntimeTechTreeDecision(
    const RuntimeWindowState& state, const RuntimeBuildCatalogItem& item
) {
    static const bool reference = [] {
        const char* flag = std::getenv("CONCORD_PAINT_TECH_REFERENCE");
        return flag != nullptr && flag[0] == '1' && flag[1] == '\0';
    }();
    auto* memo = RuntimePaintTechTreeMemoScope::active;
    const auto& catalog = state.economy.catalog;
    if (reference || memo == nullptr || catalog.empty())
        return evaluateRuntimeTechTreeDecisionUnmemoized(state, item);
    // An unrelated/temporary catalog item keeps the original path. Comparing
    // integer addresses avoids subtraction/ordering of unrelated pointers.
    const auto begin = reinterpret_cast<std::uintptr_t>(catalog.data());
    const auto address = reinterpret_cast<std::uintptr_t>(&item);
    if (address < begin || address - begin >= catalog.size() * sizeof(RuntimeBuildCatalogItem)
        || (address - begin) % sizeof(RuntimeBuildCatalogItem) != 0)
        return evaluateRuntimeTechTreeDecisionUnmemoized(state, item);
    if (memo->state != &state || memo->catalogData != catalog.data()
        || memo->catalogCount != catalog.size()) {
        memo->state = &state;
        memo->catalogData = catalog.data();
        memo->catalogCount = catalog.size();
        memo->decisions.clear();
        memo->decisions.resize(catalog.size());
    }
    auto& cached = memo->decisions[(address - begin) / sizeof(RuntimeBuildCatalogItem)];
    if (!cached) cached = evaluateRuntimeTechTreeDecisionUnmemoized(state, item);
    else ++memo->hits;
    return *cached;
}

bool runtimeBuildItemUnlockedForSidebar(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    // Progression gates decide whether the cameo exists. Credits, low power,
    // queue occupancy, and hold state are temporary and must not hide it.
    return evaluateRuntimeTechTreeDecision(state, item).canQueue;
}

bool runtimeBuildKindHasUnlockedSidebarItem(
    const RuntimeWindowState& state,
    RuntimeBuildKind kind
) {
    return std::any_of(
        state.economy.catalog.begin(),
        state.economy.catalog.end(),
        [&](const RuntimeBuildCatalogItem& item) {
            return item.kind == kind
                && runtimeBuildItemUnlockedForSidebar(state, item);
        }
    );
}

struct RuntimeBuildAvailability {
    bool canQueue = false;
    bool canStart = false;
    bool enoughCredits = false;
    bool lowPower = false;
    bool lowPowerAfterBuild = false;
    int powerNetAfterBuild = 0;
    RuntimeTechTreeDecision decision;
    std::string reason;
};

RuntimeBuildAvailability runtimeBuildAvailability(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item,
    bool respectStructureQueueLimit = true,
    bool respectBuildLimit = true
) {
    RuntimeBuildAvailability availability;
    availability.decision = evaluateRuntimeTechTreeDecision(state, item);
    availability.canQueue = availability.decision.canQueue;
    availability.canStart = availability.decision.canStart;
    availability.enoughCredits = availability.decision.enoughCredits;
    availability.lowPower = availability.decision.lowPower;
    availability.lowPowerAfterBuild = availability.decision.lowPowerAfterBuild;
    availability.powerNetAfterBuild = availability.decision.powerNetAfterBuild;
    availability.reason = availability.decision.reason;
    if (respectStructureQueueLimit
        && availability.canQueue
        && runtimeBuildKindUsesSingleStructureSlot(item.kind)) {
        const std::string blockReason =
            runtimeStructureBuildSlotBlockReason(state, item);
        if (!blockReason.empty()) {
            availability.canQueue = false;
            availability.canStart = false;
            availability.reason = blockReason;
        }
    }
    if (respectBuildLimit && availability.canQueue) {
        const std::string blockReason = runtimeBuildLimitBlockReason(
            state,
            state.economy.owner,
            item,
            false,
            true
        );
        if (!blockReason.empty()) {
            availability.canQueue = false;
            availability.canStart = false;
            availability.reason = blockReason;
        }
    }
    if (availability.canQueue) {
        const std::optional<RuntimeProductionLane> lane =
            runtimeProductionLaneForCatalogItem(state, item);
        if (!lane.has_value()) {
            availability.canQueue = false;
            availability.canStart = false;
            availability.reason = "unknown production lane";
        } else {
            const int aircraftDockCapacity =
                *lane == RuntimeProductionLane::Aircraft
                    && runtimeBuildItemUsesPadAircraft(state, item)
                    ? std::numeric_limits<int>::max()
                    : 0;
            const int capacity = runtimeProductionLaneCapacity(
                *lane,
                state.rules.getMaximumQueuedObjects(),
                aircraftDockCapacity
            );
            if (runtimeProductionLaneOccupancy(
                    state.economy.localProductionLanes,
                    *lane
                ) >= capacity) {
                availability.canQueue = false;
                availability.canStart = false;
                availability.reason =
                    "production lane full "
                    + std::string(runtimeProductionLaneName(*lane));
            }
        }
    }
    if (availability.canQueue
        && runtimeBuildItemUsesPadAircraft(state, item)) {
        RuntimeAircraftProductionOrder prospective;
        prospective.serial = std::max<std::uint64_t>(
            1,
            state.economy.localProductionLanes.nextSerial
        );
        prospective.typeId = item.typeId;
        prospective.phase =
            RuntimeAircraftProductionOrderPhase::Prospective;
        RuntimeAircraftProductionMatchResult matched;
        if (state.economy.localProductionLanes.nextSerial
                != std::numeric_limits<std::uint64_t>::max()) {
            matched = runtimeAircraftProductionMatchForOwner(
                state,
                state.economy.owner,
                prospective
            );
        }
        if (!matched.inputValid || !matched.feasible) {
            availability.canQueue = false;
            availability.canStart = false;
            availability.reason = matched.reason.empty()
                ? "no feasible aircraft pad assignment"
                : matched.reason;
        }
    }
    return availability;
}

