std::vector<double> parseRuntimeVerses(const std::string& verses) {
    std::vector<double> values;
    std::stringstream input(verses);
    std::string token;

    while (std::getline(input, token, ',')) {
        token = trimAsciiLocal(token);
        if (!token.empty() && token.back() == '%') {
            token.pop_back();
        }

        try {
            values.push_back(std::stod(token) / 100.0);
        } catch (...) {
            values.push_back(1.0);
        }
    }

    return values;
}

int runtimeArmorIndex(const std::string& armor) {
    static const std::vector<std::string> armorOrder = {
        "none",
        "flak",
        "plate",
        "light",
        "medium",
        "heavy",
        "wood",
        "steel",
        "concrete",
        "special_1",
        "special_2"
    };

    const std::string lower = toLowerAsciiLocal(armor);
    const auto it = std::find(armorOrder.begin(), armorOrder.end(), lower);
    return it == armorOrder.end()
        ? -1
        : static_cast<int>(std::distance(armorOrder.begin(), it));
}

double runtimeWarheadArmorMultiplier(
    const WarheadType* warhead,
    const std::string& armor
) {
    if (warhead == nullptr || warhead->verses.empty()) {
        return 1.0;
    }

    // The text owns the cache key, so rule reloads and edits on the same
    // WarheadType cannot reuse stale values or retain dangling pointers.
    static thread_local std::unordered_map<std::string, std::vector<double>>
        parsedVersesByText;
    auto cached = parsedVersesByText.find(warhead->verses);
    if (cached == parsedVersesByText.end()) {
        constexpr std::size_t MaxCachedVerses = 128;
        if (parsedVersesByText.size() >= MaxCachedVerses) {
            parsedVersesByText.clear();
        }
        cached = parsedVersesByText.emplace(
            warhead->verses, parseRuntimeVerses(warhead->verses)
        ).first;
    }
    // No other lookup or insertion occurs while this reference is in use.
    const std::vector<double>& verses = cached->second;
    const int armorIndex = runtimeArmorIndex(armor);
    if (armorIndex < 0
        || static_cast<std::size_t>(armorIndex) >= verses.size()) {
        return 1.0;
    }

    return verses[static_cast<std::size_t>(armorIndex)];
}

std::string runtimeTargetArmor(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object
) {
    if (const UnitType* unit = findRuntimeUnitType(state.rules, object)) {
        return unit->armor;
    }

    if (const BuildingType* building = findRuntimeBuildingType(state.rules, object)) {
        return building->armor;
    }

    return "";
}

std::string runtimeTargetEffectiveArmor(const RuntimeWindowState& state,
    const WorldObjectInstance& object, const WarheadType* warhead) {
    if (const auto* shield = runtimeActiveShield(object, state.rules, warhead); shield && !shield->inheritArmor)
        return shield->armor;
    return runtimeTargetArmor(state, object);
}

std::string chooseRuntimeImpactAnim(
    const WarheadType* warhead,
    const WeaponType& weapon
) {
    if (warhead != nullptr) {
        const std::vector<std::string> anims =
            splitRuntimeTokenList(warhead->animList);
        if (!anims.empty()) {
            if (toUpperAsciiLocal(weapon.projectile) == "BLIMPBOMBP"
                && anims.size() > 1) {
                return anims.back();
            }
            return anims.front();
        }
    }

    return "";
}

enum class RuntimeMissionIntent {
    Idle,
    Moving,
    Attacking,
    Deploying,
    Deployed,
    Undeploying,
    Entering,
    Occupying,
    Repairing,
    Loading,
    Unloading
};

std::string runtimeMissionName(RuntimeMissionIntent intent) {
    switch (intent) {
    case RuntimeMissionIntent::Idle:
        return "Guard";
    case RuntimeMissionIntent::Moving:
        return "Move";
    case RuntimeMissionIntent::Attacking:
        return "Attack";
    case RuntimeMissionIntent::Deploying:
        return "Deploying";
    case RuntimeMissionIntent::Deployed:
        return "DeployedIdle";
    case RuntimeMissionIntent::Undeploying:
        return "Undeploying";
    case RuntimeMissionIntent::Entering:
        return "Enter";
    case RuntimeMissionIntent::Occupying:
        return "Occupying";
    case RuntimeMissionIntent::Repairing:
        return "Repairing";
    case RuntimeMissionIntent::Loading:
        return "Load";
    case RuntimeMissionIntent::Unloading:
        return "Unload";
    }

    return "Guard";
}

void publishRuntimeReplayEvents(const RuntimeWindowState& state) {
    (void)materializeRuntimeReplayEventSnapshots(state);
}

void recordRuntimeReplayEvent(
    RuntimeWindowState& state,
    RuntimeReplayEventSnapshot event
) {
    event.sequence = state.nextReplayEventSequence++;
    event.tick = state.tick;
    state.recentReplayEvents.push_back(std::move(event));
    constexpr std::size_t maxRecentReplayEvents = 128;
    while (state.recentReplayEvents.size() > maxRecentReplayEvents) {
        state.recentReplayEvents.pop_front();
    }
    state.snapshotCache.replayEventSnapshotsDirty = true;
}

void ensureRuntimeSpecialMechanismsInitialized(RuntimeWindowState& state) {
    if (state.specialMechanismsInitialized || !state.rulesLoaded) {
        return;
    }
    state.specialMechanisms.reset(
        state.rules.getSpecialMechanismRules()
    );
    state.specialMechanismsInitialized = true;
}

void ensureRuntimeGarrisonsInitialized(RuntimeWindowState& state) {
    if (state.garrisonsInitialized || !state.rulesLoaded) {
        return;
    }
    RuntimeGarrisonConfig config;
    const SpecialMechanismRules& rules =
        state.rules.getSpecialMechanismRules();
    config.conditionRedFraction = rules.conditionRed;
    config.occupyDamageMultiplier = rules.occupyDamageMultiplier;
    config.occupyRofMultiplier = rules.occupyRofMultiplier;
    config.occupyWeaponRange = static_cast<double>(rules.occupyWeaponRange);
    config.fixedTickHz = std::max(1, state.config.fixedTickHz);
    state.garrisons.reset(config);
    state.garrisonsInitialized = true;
}

void ensureRuntimeSuperWeaponsInitialized(RuntimeWindowState& state) {
    if (state.superWeaponsInitialized || !state.rulesLoaded) {
        return;
    }
    state.superWeapons.reset(state.rules);
    state.superWeaponsInitialized = true;
}

std::vector<std::array<int, 4>> runtimeParasiteLinkedHostPoses(
    RuntimeWindowState& state
) {
    ensureRuntimeSpecialMechanismsInitialized(state);
    std::vector<std::array<int, 4>> poses;
    poses.reserve(state.specialMechanisms.parasiteLinks().size());
    for (const auto& [targetId, link] :
            state.specialMechanisms.parasiteLinks()) {
        (void)link;
        const WorldObjectInstance* target = findObjectById(state, targetId);
        if (target != nullptr && target->alive) {
            poses.push_back({targetId, target->x, target->y, target->level});
        }
    }
    return poses;
}

bool notifyRuntimeParasiteHostsRelocated(
    RuntimeWindowState& state,
    const std::vector<std::array<int, 4>>& before
) {
    bool changed = false;
    for (const std::array<int, 4>& pose : before) {
        const WorldObjectInstance* target = findObjectById(state, pose[0]);
        if (target == nullptr || !target->alive
            || (target->x == pose[1] && target->y == pose[2]
                && target->level == pose[3])
            || state.specialMechanisms.parasiteLinks().find(pose[0])
                == state.specialMechanisms.parasiteLinks().end()) {
            continue;
        }
        changed = handleRuntimeParasiteHostEvent(
            state,
            pose[0],
            ParasiteHostEventKind::Teleporting,
            std::max(1, state.config.fixedTickHz)
        ) || changed;
    }
    return changed;
}

