RuntimeMapRenderContext runtimeTerrainMetadataContext(
    const RuntimeWindowState& state
) {
    RuntimeMapRenderContext context;
    context.theater = state.theaterLoaded ? &state.theater : nullptr;
    context.tileRootPath = runtimeTileRootPath(state.config, state.report.map);
    context.assetRootPath = runtimeAssetRootPath(state.config);
    return context;
}

bool runtimeCellHasDisconnectedHighBridgeDeck(
    const RuntimeWindowState& state, const TerrainCell& terrain
) {
    // A native bank TMP can overlap the first body segment. Its set name
    // must not restore a deck after that segment's original SHP is broken.
    for (int lane = 0; lane < 3; ++lane) {
        const auto alongX = state.terrainByCell.find(
            runtimeCellKey(terrain.x, terrain.y - lane));
        if (alongX != state.terrainByCell.end() && alongX->second
            && runtimeHighBridgeFrameIsDisconnected(*alongX->second)
            && (alongX->second->overlayFrame == 7
                || alongX->second->overlayFrame == 8)) return true;
        const auto alongY = state.terrainByCell.find(
            runtimeCellKey(terrain.x - lane, terrain.y));
        if (alongY != state.terrainByCell.end() && alongY->second
            && runtimeHighBridgeFrameIsDisconnected(*alongY->second)
            && (alongY->second->overlayFrame == 16
                || alongY->second->overlayFrame == 17)) return true;
    }
    return false;
}

RuntimeTerrainInfo runtimeNavigationTerrainInfoForCell(
    RuntimeWindowState& state,
    const TerrainCell& terrain,
    const RuntimeMapRenderContext& metadataContext
) {
    if (terrain.overlayWall.health > 0 && runtimeOverlayWallRuleForCell(state, terrain)
        && runtimeOverlayWallUsesCurrentOverlay(terrain)) {
        RuntimeTerrainInfo blocked;
        blocked.kind = RuntimeTerrainKind::Blocked;
        blocked.passable = false;
        blocked.cost = std::numeric_limits<int>::max() / 4;
        blocked.movementLandType = blocked.authoredLandType = RuntimeTerrainLandType::Wall;
        return blocked;
    }
    // Resolve only ordinary sentinel ground through canonical metadata. Intact
    // bridge overlays retain their previous underlying movement-surface policy.
    if (terrain.tileIndex == 65535 && state.theaterLoaded
        && !runtimeOverlayProvidesBridgeDeck(terrain)
        && !runtimeHighBridgeFrameIsDisconnected(terrain)
        && !runtimeOverlayIsBrokenLowBridgePlaceholder(terrain)) {
        TerrainCell clear = terrain;
        clear.tileIndex = 0;
        clear.subTileIndex = 0;
        return runtimeNavigationTerrainInfoForCell(state, clear, metadataContext);
    }
    RuntimeTerrainInfo info = runtimeTerrainInfoForCell(state, terrain);
    info.movementLandType = resolveRuntimeTerrainSubTileLandType(terrain, metadataContext, state.renderCache);
    info.movementRampType = resolveRuntimeTerrainSubTileRampType(terrain, metadataContext, state.renderCache);
    if (info.bridge && !runtimeOverlayProvidesBridgeDeck(terrain)
        && runtimeCellHasDisconnectedHighBridgeDeck(state, terrain)) {
        info.bridge = false;
        info.authoredLandType = info.movementLandType;
        info.water = info.movementLandType == RuntimeTerrainLandType::Water;
        info.kind = info.water ? RuntimeTerrainKind::Water : RuntimeTerrainKind::Land;
        info.cost = info.water ? 18
            : (info.movementLandType == RuntimeTerrainLandType::Road ? 8 : 10);
        if (info.movementLandType == RuntimeTerrainLandType::Rock
            || info.movementLandType == RuntimeTerrainLandType::Wall) {
            info.kind = RuntimeTerrainKind::Blocked;
            info.passable = false;
            info.cost = std::numeric_limits<int>::max() / 4;
        }
    }
    if (info.kind != RuntimeTerrainKind::Shore) {
        return info;
    }

    info.authoredLandType = resolveRuntimeTerrainSubTileLandType(
        terrain,
        metadataContext,
        state.renderCache
    );
    if (info.authoredLandType == RuntimeTerrainLandType::Water) {
        info.kind = RuntimeTerrainKind::Water;
        info.water = true;
        info.shore = false;
        info.cost = 18;
    } else if (info.authoredLandType == RuntimeTerrainLandType::Rough
               || info.authoredLandType == RuntimeTerrainLandType::Clear) {
        // Landward shoreline cells remain ordinary traversable land.
        info.kind = RuntimeTerrainKind::Land;
        info.water = false;
        info.shore = false;
        info.cost = 10;
    }
    return info;
}

RuntimeTerrainInfo runtimeNavigationTerrainInfoForCell(
    RuntimeWindowState& state,
    const TerrainCell& terrain
) {
    const RuntimeMapRenderContext metadataContext =
        runtimeTerrainMetadataContext(state);
    return runtimeNavigationTerrainInfoForCell(
        state,
        terrain,
        metadataContext
    );
}

void rebuildRuntimeTerrainInfoCache(RuntimeWindowState& state) {
    const RuntimeMapRenderContext metadataContext =
        runtimeTerrainMetadataContext(state);
    state.terrainInfoByCell.clear();
    state.terrainInfoByCell.reserve(state.world.getTerrainCells().size());
    for (const TerrainCell& terrain : state.world.getTerrainCells()) {
        state.terrainInfoByCell.emplace(
            runtimeCellKey(terrain.x, terrain.y),
            runtimeNavigationTerrainInfoForCell(
                state,
                terrain,
                metadataContext
            )
        );
    }
}

const char* runtimeTerrainLandTypeRulesId(
    RuntimeTerrainLandType landType
) {
    switch (landType) {
    case RuntimeTerrainLandType::Clear:
        return "Clear";
    case RuntimeTerrainLandType::Road:
        return "Road";
    case RuntimeTerrainLandType::Water:
        return "Water";
    case RuntimeTerrainLandType::Rock:
        return "Rock";
    case RuntimeTerrainLandType::Wall:
        return "Wall";
    case RuntimeTerrainLandType::Tiberium:
        return "Tiberium";
    case RuntimeTerrainLandType::Beach:
        return "Beach";
    case RuntimeTerrainLandType::Rough:
        return "Rough";
    case RuntimeTerrainLandType::Ice:
        return "Ice";
    case RuntimeTerrainLandType::Railroad:
        return "Railroad";
    case RuntimeTerrainLandType::Tunnel:
        return "Tunnel";
    case RuntimeTerrainLandType::Unknown:
        break;
    }
    return nullptr;
}

