bool runtimeAuthoredLandOrdinalAllowsMoverUncached(
    const RuntimeWindowState& state,
    RuntimeTerrainLandType authoredLandType,
    const WorldObjectInstance& mover
) {
    const char* landTypeId = runtimeTerrainLandTypeRulesId(authoredLandType);
    if (landTypeId == nullptr) {
        return true;
    }
    const LandType* landType = state.rules.findLandType(landTypeId);
    return landType == nullptr
        || runtimeLandTypePercentForMover(*landType, state, mover) > 0.0;
}

bool runtimeAuthoredLandTypeAllowsMoverUncached(
    const RuntimeWindowState& state,
    const RuntimeTerrainInfo& terrainInfo,
    const WorldObjectInstance& mover
) {
    return runtimeAuthoredLandOrdinalAllowsMoverUncached(state,terrainInfo.authoredLandType,mover);
}

