std::optional<RuntimeCellPoint> runtimeSpecialBuildingInfantryExitCell(
    const RuntimeWindowState& state,
    const WorldObjectInstance& host,
    const std::string& owner,
    const std::string& infantryTypeId
) {
    WorldObjectInstance probe;
    probe.instanceId = -1;
    probe.kind = WorldObjectKind::Infantry;
    probe.owner = owner;
    probe.type = infantryTypeId;
    probe.alive = true;
    const RuntimeCellPoint anchor = runtimeCellPointForObject(host);
    const RuntimeStructureFootprint footprint =
        runtimeStructureFootprintForObject(state, host);
    const int width = std::max(1, footprint.width);
    const int height = std::max(1, footprint.height);
    const int centerX = anchor.x + width / 2;
    const int centerY = anchor.y + height / 2;
    const std::array<RuntimeCellPoint, 8> candidates{{
        {centerX, anchor.y + height},
        {centerX - 1, anchor.y + height},
        {centerX + 1, anchor.y + height},
        {anchor.x + width, centerY},
        {anchor.x - 1, centerY},
        {centerX, anchor.y - 1},
        {anchor.x + width, anchor.y + height},
        {anchor.x - 1, anchor.y + height}
    }};
    const std::unordered_map<int, int> occupiedByCell =
        buildRuntimeOccupancyLookup(state);
    for (int searchRadius : {0, 3, 6}) {
        for (const RuntimeCellPoint& candidate : candidates) {
            const std::optional<RuntimeCellPoint> passable =
                findRuntimePassableCellNear(
                    state,
                    probe,
                    candidate,
                    searchRadius,
                    -1,
                    nullptr,
                    nullptr,
                    &occupiedByCell
                );
            if (passable.has_value()) {
                return passable;
            }
        }
    }
    return std::nullopt;
}

bool reconcileRuntimeCloneDeliveryLeases(RuntimeWindowState& state) {
    bool changed = false;
    for (WorldObjectInstance& host : state.world.accessObjects()) {
        if (host.specialCloneDeliveryObjectId < 0) {
            continue;
        }
        const WorldObjectInstance* clone = findObjectById(
            state,
            host.specialCloneDeliveryObjectId
        );
        const bool invalidClone = clone == nullptr
            || !clone->alive
            || clone->health <= 0
            || clone->kind != WorldObjectKind::Infantry
            || !host.alive
            || host.health <= 0
            || host.kind != WorldObjectKind::Structure
            || runtimeRepairDepotCanonicalOwnerId(state, clone->owner)
                != runtimeRepairDepotCanonicalOwnerId(state, host.owner);
        if (invalidClone) {
            host.specialCloneDeliveryObjectId = -1;
            changed = true;
            continue;
        }

        const RuntimeStructureFootprint footprint =
            runtimeStructureFootprintForObject(state, host);
        const RuntimeCellPoint anchor = runtimeCellPointForObject(host);
        const int width = std::max(1, footprint.width);
        const int height = std::max(1, footprint.height);
        const bool cloneClearedDeliveryArea = clone->x < anchor.x - 1
            || clone->x > anchor.x + width
            || clone->y < anchor.y - 1
            || clone->y > anchor.y + height;
        if (cloneClearedDeliveryArea) {
            host.specialCloneDeliveryObjectId = -1;
            changed = true;
        }
    }
    return changed;
}

#include "simulation/production/RuntimeCloningDeliveries.inl"

bool beginRuntimeFactoryExitAnimation(
    RuntimeWindowState& state,
    WorldObjectInstance& factory,
    const WorldObjectInstance& produced
) {
    if (!factory.alive || factory.kind != WorldObjectKind::Structure) {
        return false;
    }
    const bool airborne =
        runtimeObjectMovementMode(state, produced) == PathMovementMode::Air;
    const ArtType* art = runtimeArtTypeForObject(state, factory);
    if (art == nullptr) {
        return false;
    }
    if (!airborne && runtimeFactoryDeliveryHostDomain(state, factory)
            == RuntimeFactoryDeliveryDomain::Naval) {
        const int duration = runtimeShipyardProductionDuration(*art, state.art, state.config.fixedTickHz);
        if (duration <= 0) return false;
        // Trigger only after a ship was actually created at this host. Queue
        // progress, holds and failed deliveries never enter this branch.
        factory.factoryExitAnimationStartTick = state.tick;
        factory.factoryExitAnimationEndTick = state.tick + duration;
        factory.factoryExitAirborne = false;
        return true;
    }
    const auto matchesLayer = [airborne](
        const ArtType::ActiveAnimation& animation
    ) {
        const std::string key = toLowerAsciiLocal(animation.key);
        return airborne
            ? key == "roofdeployinganim"
                || key == "underroofdooranim"
            : key == "deployinganim"
                || key == "underdooranim"
                || key == "dooranim";
    };
    if (!std::any_of(
            art->auxiliaryAnimations.begin(),
            art->auxiliaryAnimations.end(),
            matchesLayer
        )) {
        return false;
    }
    const int durationTicks = airborne
        ? std::max(100, state.config.fixedTickHz * 4)
        : std::max(24, state.config.fixedTickHz * 2);
    const bool alreadyOpen = airborne && factory.factoryExitAirborne
        && factory.factoryExitAnimationStartTick >= 0
        && factory.factoryExitAnimationEndTick > state.tick;
    if (!alreadyOpen) factory.factoryExitAnimationStartTick = state.tick;
    factory.factoryExitAnimationEndTick = alreadyOpen
        ? std::max(factory.factoryExitAnimationEndTick, state.tick + durationTicks)
        : state.tick + durationTicks;
    factory.factoryExitAirborne = airborne;
    if (airborne) {
        if (auto* liveProduced = findMutableObjectById(state, produced.instanceId)) {
            // Stock war factories face along their long foundation axis.
            // Set this only on first delivery; repeated roof notifications and
            // restored flights must not reset a heading already in motion.
            if (liveProduced->factoryExitHostId != factory.instanceId) {
                liveProduced->facing = runtimeFacingFromDelta(1, 0);
                if (liveProduced->turretFacing >= 0) liveProduced->turretFacing = liveProduced->facing;
            }
            liveProduced->factoryExitHostId = factory.instanceId;
        }
    }
    return true;
}


std::optional<RuntimeCellPoint> findRuntimeSpawnCellNearObjectForOwner(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item,
    const WorldObjectInstance& anchor,
    const std::string& owner
) {
    WorldObjectInstance probe;
    probe.instanceId = -1;
    probe.kind = runtimeKindForBuildItem(item.kind);
    probe.owner = owner;
    probe.type = item.typeId;
    probe.alive = true;

    const RuntimeCellPoint anchorCell = runtimeCellPointForObject(anchor);
    for (int radius = 1; radius <= 6; ++radius) {
        for (int dy = -radius; dy <= radius; ++dy) {
            for (int dx = -radius; dx <= radius; ++dx) {
                if (std::abs(dx) != radius && std::abs(dy) != radius) {
                    continue;
                }
                const RuntimeCellPoint candidate{
                    anchorCell.x + dx,
                    anchorCell.y + dy
                };
                const std::optional<RuntimeCellPoint> passable =
                    findRuntimePassableCellNear(state, probe, candidate, 0);
                if (passable.has_value()) {
                    return passable;
                }
            }
        }
    }

    return std::nullopt;
}

std::optional<RuntimeCellPoint> findRuntimeSpawnCellNearObject(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item,
    const WorldObjectInstance& anchor
) {
    return findRuntimeSpawnCellNearObjectForOwner(
        state,
        item,
        anchor,
        state.economy.owner
    );
}

bool runtimeProductionLaneShellContract(
    const RulesDatabase& rules,
    std::string& errorMessage
) {
    auto probeStorage = std::make_unique<RuntimeWindowState>();
    RuntimeWindowState& probe = *probeStorage;
    probe.rules = rules;
    probe.rulesLoaded = true;
    probe.economy.owner = "ProbeA";
    initializeRuntimeLocalProductionLanes(probe.economy);

    const RuntimeCellPoint shipyardCell{42, 42};
    for (int y = 30; y <= 82; ++y) {
        for (int x = 30; x <= 116; ++x) {
            TerrainCell terrain;
            terrain.x = x;
            terrain.y = y;
            terrain.cellIndex512 = y * 512 + x;
            probe.world.accessTerrainCells().push_back(terrain);

            RuntimeTerrainInfo info;
            if (x >= shipyardCell.x - 3
                && x <= shipyardCell.x + 8
                && y >= shipyardCell.y - 3
                && y <= shipyardCell.y + 8) {
                info.kind = RuntimeTerrainKind::Water;
                info.water = true;
            }
            probe.terrainInfoByCell.emplace(runtimeCellKey(x, y), info);
        }
    }
    probe.terrainByCell = buildRuntimeTerrainLookup(probe.world);

    const auto appendStructure = [
        &probe
    ](
        int objectId,
        const std::string& owner,
        const std::string& type,
        const RuntimeCellPoint& cell
    ) {
        WorldObjectInstance object;
        object.instanceId = objectId;
        object.kind = WorldObjectKind::Structure;
        object.owner = owner;
        object.type = type;
        object.x = cell.x;
        object.y = cell.y;
        object.cell = runtimeCellKey(cell.x, cell.y);
        object.alive = true;
        object.poweredOperational = true;
        if (const BuildingType* building =
                findRuntimeBuildingTypeById(probe.rules, type)) {
            object.health = std::max(1, building->strength);
        }
        probe.world.accessObjects().push_back(std::move(object));
    };
    appendStructure(970001, "ProbeA", "GAYARD", shipyardCell);
    appendStructure(970002, "ProbeA", "GAWEAP", {64, 64});
    appendStructure(970003, "ProbeA", "GAAIRC", {78, 64});
    appendStructure(970004, "ProbeB", "GAWEAP", {94, 64});
    appendStructure(970005, "Legacy", "GAPOWR", {108, 64});
    // Deliberately append a lower-id ProbeB factory last.  Candidate order
    // must be stable by instance id, not by container insertion history.
    appendStructure(969998, "ProbeB", "GAWEAP", {100, 72});
    probe.structureFootprints = buildRuntimeStructureFootprints(probe);

    const auto makeItem = [](
        RuntimeBuildKind kind,
        const std::string& typeId,
        const std::string& requiredFactory
    ) {
        RuntimeBuildCatalogItem item;
        item.kind = kind;
        item.typeId = typeId;
        item.requiredFactory = requiredFactory;
        return item;
    };
    const RuntimeBuildCatalogItem wall = makeItem(
        RuntimeBuildKind::Defense,
        "GAWALL",
        "BuildingType"
    );
    const RuntimeBuildCatalogItem infantry = makeItem(
        RuntimeBuildKind::Infantry,
        "E1",
        "InfantryType"
    );
    const RuntimeBuildCatalogItem tank = makeItem(
        RuntimeBuildKind::Unit,
        "MTNK",
        "UnitType"
    );
    const RuntimeBuildCatalogItem destroyer = makeItem(
        RuntimeBuildKind::Unit,
        "DEST",
        "UnitType"
    );
    const RuntimeBuildCatalogItem orca = makeItem(
        RuntimeBuildKind::Unit,
        "ORCA",
        "AircraftType"
    );
    const RuntimeBuildCatalogItem blackEagle = makeItem(
        RuntimeBuildKind::Unit,
        "BEAG",
        "AircraftType"
    );
    const RuntimeBuildCatalogItem zeppelin = makeItem(
        RuntimeBuildKind::Unit,
        "ZEP",
        "UnitType"
    );
    const RuntimeBuildCatalogItem disk = makeItem(
        RuntimeBuildKind::Unit,
        "DISK",
        "UnitType"
    );
    const RuntimeBuildCatalogItem legacyBuilding = makeItem(
        RuntimeBuildKind::Building,
        "GAPOWR",
        "BuildingType"
    );

    const auto laneIs = [&probe](
        const RuntimeBuildCatalogItem& item,
        RuntimeProductionLane expected
    ) {
        const std::optional<RuntimeProductionLane> actual =
            runtimeProductionLaneForCatalogItem(probe, item);
        return actual.has_value() && *actual == expected;
    };
    const bool sourceListsValid =
        laneIs(wall, RuntimeProductionLane::Armory)
        && laneIs(infantry, RuntimeProductionLane::Infantry)
        && laneIs(tank, RuntimeProductionLane::Vehicles)
        && laneIs(destroyer, RuntimeProductionLane::Ships)
        && laneIs(orca, RuntimeProductionLane::Aircraft)
        && laneIs(blackEagle, RuntimeProductionLane::Aircraft)
        && laneIs(zeppelin, RuntimeProductionLane::Vehicles)
        && laneIs(disk, RuntimeProductionLane::Vehicles);
    if (!sourceListsValid) {
        errorMessage =
            "source-list lane mapping diverged for wall/infantry/land/ship/"
            "aircraft/ConsideredAircraft";
        return false;
    }

    probe.economy.catalog = {
        wall,
        infantry,
        tank,
        destroyer,
        orca,
        blackEagle,
        zeppelin,
        disk
    };
    const std::optional<RuntimeProductionCatalogAdapter> catalogDisk =
        runtimeProductionCatalogLookup(probe, " disk ");
    if (!catalogDisk.has_value()
        || catalogDisk->item == nullptr
        || catalogDisk->lane != RuntimeProductionLane::Vehicles
        || toUpperAsciiLocal(catalogDisk->item->typeId) != "DISK") {
        errorMessage = "catalog adapter did not preserve DISK source lane";
        return false;
    }

    const WorldObjectInstance* probeAFactory =
        findRuntimeFactoryAnchorForOwner(
            probe,
            tank,
            "probea",
            false
        );
    const WorldObjectInstance* probeBFactory =
        findRuntimeFactoryAnchorForOwner(
            probe,
            tank,
            "PROBEB",
            false
        );
    const WorldObjectInstance* localProbeAFactory =
        findRuntimeFactoryAnchor(probe, tank);
    if (probeAFactory == nullptr
        || probeBFactory == nullptr
        || localProbeAFactory == nullptr
        || probeAFactory->instanceId != 970002
        || probeBFactory->instanceId != 969998
        || localProbeAFactory->instanceId != 970002) {
        errorMessage = "strict factory selection crossed canonical owners";
        return false;
    }

    const WorldObjectInstance* strictLegacy =
        findRuntimeFactoryAnchorForOwner(
            probe,
            legacyBuilding,
            "Legacy",
            false
        );
    const WorldObjectInstance* compatibleLegacy =
        findRuntimeFactoryAnchorForOwner(
            probe,
            legacyBuilding,
            "Legacy",
            true
        );
    const std::string savedLocalOwner = probe.economy.owner;
    probe.economy.owner = "legacy";
    const WorldObjectInstance* localLegacy =
        findRuntimeFactoryAnchor(probe, legacyBuilding);
    probe.economy.owner = savedLocalOwner;
    if (strictLegacy != nullptr
        || compatibleLegacy == nullptr
        || localLegacy == nullptr
        || compatibleLegacy->instanceId != 970005
        || localLegacy->instanceId != 970005) {
        errorMessage = "strict rejection/local legacy fallback contract failed";
        return false;
    }

    const std::optional<RuntimeProductionSpawn> destroyerSpawn =
        findRuntimeProductionSpawnForOwner(
            probe,
            destroyer,
            "ProbeA",
            false
        );
    const auto destroyerTerrain = destroyerSpawn.has_value()
        ? probe.terrainInfoByCell.find(runtimeCellKey(
            destroyerSpawn->cell.x,
            destroyerSpawn->cell.y
        ))
        : probe.terrainInfoByCell.end();
    if (!destroyerSpawn.has_value()
        || destroyerSpawn->anchor == nullptr
        || destroyerSpawn->anchor->instanceId != 970001
        || destroyerTerrain == probe.terrainInfoByCell.end()
        || !destroyerTerrain->second.water) {
        errorMessage = "DEST did not use ProbeA shipyard water exit";
        return false;
    }

    const std::optional<RuntimeProductionSpawn> tankSpawn =
        findRuntimeProductionSpawnForOwner(
            probe,
            tank,
            "ProbeA",
            false
        );
    const std::optional<RuntimeProductionSpawn> zeppelinSpawn =
        findRuntimeProductionSpawnForOwner(
            probe,
            zeppelin,
            "ProbeA",
            false
        );
    const std::optional<RuntimeProductionSpawn> diskSpawn =
        findRuntimeProductionSpawnForOwner(
            probe,
            disk,
            "ProbeA",
            false
        );
    if (!tankSpawn.has_value()
        || !zeppelinSpawn.has_value()
        || !diskSpawn.has_value()
        || tankSpawn->anchor == nullptr
        || zeppelinSpawn->anchor == nullptr
        || diskSpawn->anchor == nullptr
        || tankSpawn->anchor->instanceId != 970002
        || zeppelinSpawn->anchor->instanceId != 970002
        || diskSpawn->anchor->instanceId != 970002) {
        errorMessage = "land/ConsideredAircraft vehicles left GAWEAP lane";
        return false;
    }

    const std::optional<RuntimeProductionSpawn> orcaSpawn =
        findRuntimeProductionSpawnForOwner(
            probe,
            orca,
            "ProbeA",
            false
        );
    const BuildingType* airfieldRules =
        findRuntimeBuildingTypeById(probe.rules, "GAAIRC");
    const int dockCapacity =
        runtimeCompatibleAircraftDockCapacityForOwner(
            probe,
            orca,
            "ProbeA"
        );
    if (!orcaSpawn.has_value()
        || orcaSpawn->anchor == nullptr
        || orcaSpawn->anchor->instanceId != 970003
        || !orcaSpawn->aircraftDock
        || airfieldRules == nullptr
        || dockCapacity != std::max(0, airfieldRules->numberOfDocks)) {
        errorMessage = "ORCA did not resolve compatible ProbeA airport docks";
        return false;
    }

    WorldObjectInstance occupiedDock;
    occupiedDock.instanceId = 970006;
    occupiedDock.kind = WorldObjectKind::Unit;
    occupiedDock.owner = "ProbeA";
    occupiedDock.type = "ORCA";
    occupiedDock.alive = true;
    occupiedDock.dockedToObjectId = 970003;
    occupiedDock.dockIndex = 0;
    probe.world.accessObjects().push_back(std::move(occupiedDock));
    if (runtimeCompatibleAircraftDockCapacityForOwner(
            probe,
            orca,
            "probea"
        ) != std::max(0, dockCapacity - 1)) {
        errorMessage = "live dock mirror did not reduce compatible capacity";
        return false;
    }

    WorldObjectInstance* ownerProduced = addRuntimeObjectInstanceForOwner(
        probe,
        "ProbeB",
        RuntimeBuildKind::Unit,
        "MTNK",
        {112, 76}
    );
    const int ownerProducedId = ownerProduced == nullptr
        ? -1
        : ownerProduced->instanceId;
    WorldObjectInstance* localProduced = addRuntimeObjectInstance(
        probe,
        RuntimeBuildKind::Unit,
        "MTNK",
        {114, 76}
    );
    const auto ownerProducedIt = std::find_if(
        probe.world.accessObjects().begin(),
        probe.world.accessObjects().end(),
        [ownerProducedId](const WorldObjectInstance& object) {
            return object.instanceId == ownerProducedId;
        }
    );
    ownerProduced = ownerProducedIt == probe.world.accessObjects().end()
        ? nullptr
        : &*ownerProducedIt;
    if (ownerProduced == nullptr
        || localProduced == nullptr
        || !runtimeProductionOwnersMatch(
            probe,
            ownerProduced->owner,
            "probeb"
        )
        || !runtimeProductionOwnersMatch(
            probe,
            localProduced->owner,
            probe.economy.owner
        )
        || !probe.economy.localProductionLanesInitialized
        || probe.economy.localProductionLanes.nextSerial != 1) {
        errorMessage = "owner-aware/local add or lane initialization failed";
        return false;
    }

    return true;
}

bool runtimeOwnerCanAnchorBuildingPlacement(
    const RuntimeWindowState& state,
    const std::string& owner
) {
    if (owner == state.economy.owner) {
        return true;
    }
    return state.config.buildOffAlly
        && runtimeOwnersAreAllied(state, state.economy.owner, owner);
}

std::optional<RuntimeCellPoint> findRuntimePlacementCellNearBase(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    std::vector<const WorldObjectInstance*> anchors;
    const auto* type = findRuntimeBuildingTypeById(state.rules, item.typeId);
    // Try every owned base building before considering eligible allied yards.
    for (bool alliedPass : {false, true}) {
        for (const auto& object : state.world.getObjects()) {
            const bool own = runtimeCanonicalHumanHouseOwner(object.owner)
                == runtimeCanonicalHumanHouseOwner(state.economy.owner);
            if (own == alliedPass || !runtimeBuildingPlacementAnchorEligible(
                    state, object, state.economy.owner, type && type->wall)) continue;
            anchors.push_back(&object);
        }
    }
    const auto occupiedByCell = buildRuntimeOccupancyLookup(state);
    const auto rubbleCells = runtimeBuildingRubblePlacementCells(state);
    const auto footprint = runtimeStructureFootprintForBuildItem(state, item);
    for (const auto* anchor : anchors) {
        const auto anchorCell = runtimeCellPointForObject(*anchor);
        const auto anchorFootprint = runtimeStructureFootprintForObject(state, *anchor);
        const int maxRadius = static_cast<int>(std::min<std::int64_t>(512,
            static_cast<std::int64_t>(type ? type->adjacent : 1) + 1
            + std::max({footprint.width, footprint.height, anchorFootprint.width, anchorFootprint.height})));
        for (int radius = 1; radius <= maxRadius; ++radius) {
            for (int dy = -radius; dy <= radius; ++dy) {
                for (int dx = -radius; dx <= radius; ++dx) {
                    if (std::abs(dx) != radius && std::abs(dy) != radius) continue;
                    const RuntimeCellPoint candidate{anchorCell.x + dx, anchorCell.y + dy};
                    if (runtimeCellCanPlaceSidebarBuilding(state, item, candidate, &occupiedByCell, {}, &rubbleCells))
                        return candidate;
                }
            }
        }
    }
    return std::nullopt;
}

bool runtimeBuildItemsMatch(
    const RuntimeBuildCatalogItem& left,
    const RuntimeBuildCatalogItem& right
) {
    return left.kind == right.kind
        && toUpperAsciiLocal(left.typeId) == toUpperAsciiLocal(right.typeId);
}

std::vector<RuntimeCellPoint> runtimeWallConnectorCells(
    const RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item,
    const RuntimeCellPoint& placementCell
) {
    std::vector<RuntimeCellPoint> connectors;
    if (!item.wall) {
        return connectors;
    }
    const BuildingType* wall =
        findRuntimeBuildingTypeById(state.rules, item.typeId);
    if (wall == nullptr || !wall->wall) {
        return connectors;
    }
    const int connectionRange = std::clamp(wall->guardRange, 1, 5);
    constexpr RuntimeCellPoint directions[] = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };
    const std::string wallType = toUpperAsciiLocal(item.typeId);
    for (const RuntimeCellPoint& direction : directions) {
        int matchingDistance = -1;
        for (int distance = 1; distance <= connectionRange; ++distance) {
            const RuntimeCellPoint target{
                placementCell.x + direction.x * distance,
                placementCell.y + direction.y * distance
            };
            const auto matchingWall = std::find_if(
                state.world.getObjects().begin(),
                state.world.getObjects().end(),
                [&](const WorldObjectInstance& object) {
                    return object.alive
                        && object.kind == WorldObjectKind::Structure
                        && object.owner == state.economy.owner
                        && toUpperAsciiLocal(object.type) == wallType
                        && object.x == target.x
                        && object.y == target.y;
                }
            );
            if (matchingWall != state.world.getObjects().end()) {
                matchingDistance = distance;
                break;
            }
        }
        if (matchingDistance <= 1) {
            continue;
        }

        std::vector<RuntimeCellPoint> corridor;
        bool corridorClear = true;
        for (int distance = 1; distance < matchingDistance; ++distance) {
            const RuntimeCellPoint cell{
                placementCell.x + direction.x * distance,
                placementCell.y + direction.y * distance
            };
            if (!runtimeCellCanPlaceBuilding(state, item, cell)) {
                corridorClear = false;
                break;
            }
            corridor.push_back(cell);
        }
        if (!corridorClear) {
            continue;
        }
        for (const RuntimeCellPoint& cell : corridor) {
            if (std::find(connectors.begin(), connectors.end(), cell)
                == connectors.end()) {
                connectors.push_back(cell);
            }
        }
    }
    std::sort(connectors.begin(), connectors.end(), RuntimeCellPointLess{});
    return connectors;
}

bool cancelRuntimeReadyPlacement(
    RuntimeWindowState& state,
    const std::string& reason,
    bool silent = false
) {
    const std::optional<RuntimeSelectedPlacement> placement =
        runtimeSelectedPlacement(state);
    if (!placement.has_value() || placement->item == nullptr) {
        return false;
    }

    const RuntimeBuildCatalogItem item = *placement->item;
    const RuntimeProductionCancelResult canceled =
        runtimeCancelProductionSerial(
            state.economy.localProductionLanes,
            placement->lane,
            placement->order.serial
        );
    if (!canceled.removed) {
        return false;
    }
    depositRuntimeCredits(state, canceled.refund);
    state.economy.selectedPlacementLane.reset();
    state.economy.selectedPlacementSerial = 0;
    clearRuntimeInvalidPlacementSelection(state);

    state.economy.status =
        reason + " " + item.typeId
        + (canceled.refund > 0
            ? " refund " + std::to_string(canceled.refund)
            : "");
    state.interactionStatus = state.economy.status;
    if (!silent) {
        emitRuntimeSound(state, runtimeSoundIntentBuildCanceled);
    }
    return true;
}

bool queueRuntimeBuildOrder(
    RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item,
    RuntimeProductionInsertMode insertMode =
        RuntimeProductionInsertMode::Back
) {
    const std::optional<RuntimeProductionLane> lane =
        runtimeProductionLaneForCatalogItem(state, item);
    if (!lane.has_value()) {
        state.economy.status =
            "cannot queue " + item.typeId + ": unknown production lane";
        state.interactionStatus = state.economy.status;
        emitRuntimeSound(state, runtimeSoundIntentSidebarScold);
        return false;
    }
    RuntimeProductionLaneState& laneState =
        state.economy.localProductionLanes.lanes[
            runtimeProductionLaneIndex(*lane)
        ];
    if (laneState.active.has_value()
        && runtimeProductionItemKeysMatch(
            laneState.active->itemKey,
            item.typeId
        )
        && laneState.onHold) {
        runtimeSetProductionHold(
            state.economy.localProductionLanes,
            *lane,
            false
        );
        state.economy.status = "resumed " + item.typeId;
        state.interactionStatus = state.economy.status;
        emitRuntimeSound(state, runtimeSoundIntentSidebarButtonClick);
        return true;
    }

    const RuntimeBuildAvailability availability =
        runtimeBuildAvailability(state, item);
    if (!availability.canQueue) {
        state.economy.status =
            "cannot queue " + item.typeId + ": " + availability.reason;
        state.interactionStatus = state.economy.status;
        emitRuntimeSound(
            state,
            availability.decision.enoughCredits
                ? runtimeSoundIntentSidebarScold
                : runtimeSoundIntentInsufficientFunds
        );
        return false;
    }

    RuntimeProductionLaneOrder order;
    RuntimeProductionLanesState stagedLanes =
        state.economy.localProductionLanes;
    order.itemKey = item.typeId;
    order.cost = std::max(0, item.cost);
    order.totalTicks = std::max(1, item.buildTicks);
    const bool padAircraft = runtimeBuildItemUsesPadAircraft(state, item);
    const std::uint64_t predictedSerial = std::max<std::uint64_t>(
        1,
        state.economy.localProductionLanes.nextSerial
    );
    if (padAircraft) {
        RuntimeAircraftProductionOrder prospective;
        prospective.serial = predictedSerial;
        prospective.typeId = item.typeId;
        prospective.phase =
            RuntimeAircraftProductionOrderPhase::Prospective;
        const RuntimeAircraftProductionMatchResult matched =
            state.economy.localProductionLanes.nextSerial
                    == std::numeric_limits<std::uint64_t>::max()
                ? RuntimeAircraftProductionMatchResult{}
                : runtimeAircraftProductionMatchForOwner(
                    state,
                    state.economy.owner,
                    prospective
                );
        if (!matched.inputValid || !matched.feasible) {
            state.economy.status = "cannot queue " + item.typeId
                + ": " + (matched.reason.empty()
                    ? std::string("no feasible aircraft pad assignment")
                    : matched.reason);
            state.interactionStatus = state.economy.status;
            emitRuntimeSound(state, runtimeSoundIntentSidebarScold);
            return false;
        }
    }
    const int aircraftDockCapacity =
        *lane == RuntimeProductionLane::Aircraft && padAircraft
            ? std::numeric_limits<int>::max()
            : 0;
    const RuntimeProductionQueueResult queued =
        runtimeQueueProductionOrder(
            stagedLanes,
            *lane,
            std::move(order),
            state.rules.getMaximumQueuedObjects(),
            aircraftDockCapacity,
            insertMode
        );
    if (queued.decision != RuntimeProductionQueueDecision::Accepted
        || (padAircraft && queued.serial != predictedSerial)) {
        state.economy.status =
            "cannot queue " + item.typeId + ": production lane full";
        state.interactionStatus = state.economy.status;
        emitRuntimeSound(state, runtimeSoundIntentSidebarScold);
        return false;
    }
    state.economy.localProductionLanes = std::move(stagedLanes);
    state.economy.status =
        "queued " + item.typeId + " #" + std::to_string(queued.serial)
        + " cost " + std::to_string(item.cost);
    state.interactionStatus = state.economy.status;
    emitRuntimeSound(state, runtimeSoundIntentBuildQueued);
    return true;
}

bool queueRuntimeBuildOrderForHumanOwner(
    RuntimeWindowState& state,
    const std::string& commandOwner,
    const RuntimeBuildCatalogItem& item,
    RuntimeProductionInsertMode insertMode =
        RuntimeProductionInsertMode::Back
) {
    RuntimeHumanHouseScope scope(state, commandOwner);
    return scope && queueRuntimeBuildOrder(state, item, insertMode);
}

bool cancelRuntimeBuildOrderForHumanOwner(
    RuntimeWindowState& state,
    const std::string& commandOwner,
    RuntimeProductionLane lane,
    std::uint64_t serial
) {
    RuntimeHumanHouseScope scope(state, commandOwner);
    if (!scope || serial == 0) {
        return false;
    }
    const RuntimeProductionCancelResult canceled =
        runtimeCancelProductionSerial(
            state.economy.localProductionLanes,
            lane,
            serial
        );
    if (!canceled.removed) {
        return false;
    }
    depositRuntimeCredits(state, canceled.refund);
    if (state.economy.selectedPlacementLane == lane
        && state.economy.selectedPlacementSerial == serial) {
        state.economy.selectedPlacementLane.reset();
        state.economy.selectedPlacementSerial = 0;
    }
    clearRuntimeInvalidPlacementSelection(state);
    state.economy.status =
        "canceled production #" + std::to_string(serial)
        + (canceled.refund > 0
            ? " refund " + std::to_string(canceled.refund)
            : "");
    state.interactionStatus = state.economy.status;
    emitRuntimeSound(state, runtimeSoundIntentBuildCanceled);
    return true;
}

bool handleRuntimeBuildButtonSecondaryAction(
    RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    RuntimeProductionLane lane = RuntimeProductionLane::Structures;
    if (const RuntimeProductionLaneOrder* ready =
            runtimeReadyProductionForItem(state, item, &lane)) {
        state.economy.selectedPlacementLane = lane;
        state.economy.selectedPlacementSerial = ready->serial;
        cancelRuntimeReadyPlacement(state, "canceled ready");
        return true;
    }

    const std::optional<RuntimeProductionLane> itemLane =
        runtimeProductionLaneForCatalogItem(state, item);
    if (itemLane.has_value()) {
        RuntimeProductionLaneState& laneState =
            state.economy.localProductionLanes.lanes[
                runtimeProductionLaneIndex(*itemLane)
            ];
        const auto queued = std::find_if(
            laneState.queued.rbegin(),
            laneState.queued.rend(),
            [&](const RuntimeProductionLaneOrder& order) {
                return runtimeProductionItemKeysMatch(
                    order.itemKey,
                    item.typeId
                );
            }
        );
        if (queued != laneState.queued.rend()) {
            const RuntimeProductionCancelResult canceled =
                runtimeCancelProductionSerial(
                    state.economy.localProductionLanes,
                    *itemLane,
                    queued->serial
                );
            depositRuntimeCredits(state, canceled.refund);
            state.economy.status = "canceled queued " + item.typeId;
            state.interactionStatus = state.economy.status;
            emitRuntimeSound(state, runtimeSoundIntentBuildCanceled);
            return true;
        }
    }

    const RuntimeProductionLaneOrder* active =
        runtimeActiveProductionForItem(state, item, &lane);
    if (active != nullptr) {
        RuntimeProductionLaneState& laneState =
            state.economy.localProductionLanes.lanes[
                runtimeProductionLaneIndex(lane)
            ];
        // A completed unit may still be waiting for its factory exit. It
        // cannot be held, so let this right-click cancel and refund it.
        if (!laneState.onHold && runtimeSetProductionHold(
                state.economy.localProductionLanes,
                lane,
                true
            )) {
            state.economy.status = "on hold " + item.typeId;
            state.interactionStatus = state.economy.status;
            emitRuntimeSound(state, runtimeSoundIntentBuildHeld);
            return true;
        }

        const RuntimeProductionCancelResult canceled =
            runtimeCancelProductionSerial(
                state.economy.localProductionLanes,
                lane,
                active->serial
            );
        depositRuntimeCredits(state, canceled.refund);
        state.economy.status = "canceled " + item.typeId;
        state.interactionStatus = state.economy.status;
        emitRuntimeSound(state, runtimeSoundIntentBuildCanceled);
        return true;
    }

    state.economy.status = "nothing to cancel " + item.typeId;
    state.interactionStatus = state.economy.status;
    emitRuntimeSound(state, runtimeSoundIntentSidebarScold);
    return false;
}

bool placeRuntimeReadyBuilding(
    RuntimeWindowState& state,
    const RuntimeCellPoint& cell
) {
    const std::optional<RuntimeSelectedPlacement> placement =
        runtimeSelectedPlacement(state);
    if (!placement.has_value()
        || placement->item == nullptr
        || (placement->item->kind != RuntimeBuildKind::Building
            && placement->item->kind != RuntimeBuildKind::Defense)
        || !runtimeCellCanPlaceSidebarBuilding(state, *placement->item, cell)) {
        state.economy.status = "placement blocked";
        emitRuntimeSound(state, runtimeSoundIntentCannotDeployHere);
        return false;
    }

    const int unlockedOptionsBefore =
        runtimeUnlockedBuildOptionCount(state);
    const RuntimeBuildCatalogItem item = *placement->item;
    const std::vector<RuntimeCellPoint> wallConnectors =
        runtimeWallConnectorCells(state, item, cell);

    WorldObjectInstance* placed = addRuntimeObjectInstance(
        state,
        item.kind,
        item.typeId,
        cell,
        false
    );
    if (placed == nullptr) {
        state.economy.status = "placement failed";
        return false;
    }
    const WorldObjectInstance placedAnchor = *placed;
    const std::string placedTypeId = placedAnchor.type;
    const int placedInstanceId = placedAnchor.instanceId;
    const std::optional<RuntimeProductionLaneOrder> committed =
        runtimeConsumeReadyProduction(
            state.economy.localProductionLanes,
            placement->lane,
            placement->order.serial
        );
    if (!committed.has_value()) {
        std::vector<WorldObjectInstance>& objects =
            state.world.accessObjects();
        const auto rollback = std::find_if(
            objects.begin(),
            objects.end(),
            [placedInstanceId](const WorldObjectInstance& object) {
                return object.instanceId == placedInstanceId;
            }
        );
        if (rollback != objects.end()) {
            objects.erase(rollback);
        }
        refreshRuntimeObjectOccupancyAfterLocalChange(state);
        state.economy.status = "placement commit failed";
        return false;
    }
    recordRuntimeCompletedBuild(
        state,
        placedAnchor.owner,
        item
    );
    state.economy.selectedPlacementLane.reset();
    state.economy.selectedPlacementSerial = 0;
    int placedWallConnectors = 0;
    for (const RuntimeCellPoint& connectorCell : wallConnectors) {
        WorldObjectInstance* connector = addRuntimeObjectInstance(
            state,
            item.kind,
            item.typeId,
            connectorCell
        );
        if (connector != nullptr) {
            ++placedWallConnectors;
        }
    }
    (void)clearRuntimeSmudgesForPlacedStructure(state, placedAnchor);
    state.economy.completedBuildings += 1 + placedWallConnectors;
    clearRuntimeInvalidPlacementSelection(state);
    std::string freeUnitStatus;
    if (const BuildingType* building =
            findRuntimeBuildingTypeById(state.rules, placedAnchor.type)) {
        if (!building->freeUnit.empty()
            && findRuntimeUnitTypeById(state.rules, building->freeUnit) != nullptr) {
            const UnitType* freeUnitType =
                findRuntimeUnitTypeById(state.rules, building->freeUnit);
            RuntimeBuildCatalogItem freeUnitItem;
            freeUnitItem.kind =
                runtimeBuildKindForUnitTypeId(state.rules, building->freeUnit);
            freeUnitItem.typeId = building->freeUnit;
            freeUnitItem.buildLimit = freeUnitType == nullptr
                ? std::optional<int>{}
                : freeUnitType->buildLimit;
            freeUnitItem.cost = 0;
            freeUnitItem.buildTicks = 1;
            (void)state.factoryDeliveries.deferFreeUnit({placedAnchor.instanceId,
                placedAnchor.owner, placedAnchor.type, building->freeUnit});
            const std::optional<RuntimeCellPoint> freeUnitCell =
                findRuntimeSpawnCellNearObject(
                    state,
                    freeUnitItem,
                    placedAnchor
                );
            if (freeUnitCell.has_value()) {
                WorldObjectInstance* freeUnit = addRuntimeObjectInstance(
                    state,
                    freeUnitItem.kind,
                    freeUnitItem.typeId,
                    *freeUnitCell
                );
                if (freeUnit != nullptr) {
                    applyRuntimeProducedObjectVeterancy(state, *freeUnit);
                    recordRuntimeCompletedBuild(
                        state,
                        freeUnit->owner,
                        freeUnitItem
                    );
                    queueRuntimeProductionExitMove(
                        state,
                        *freeUnit,
                        placedAnchor
                    );
                    state.factoryDeliveries.completeFreeUnit(placedAnchor.instanceId);
                    freeUnitStatus =
                        " free " + freeUnit->type + " #"
                        + std::to_string(freeUnit->instanceId);
                }
            }
        }
    }
    state.economy.status =
        "placed " + placedTypeId + " #"
        + std::to_string(placedInstanceId)
        + (placedWallConnectors > 0
            ? " connected " + std::to_string(placedWallConnectors)
            : "")
        + freeUnitStatus;
    state.interactionStatus = state.economy.status;
    emitRuntimeSound(state, runtimeSoundIntentPlacementConfirmed);
    refreshRuntimeObjectOccupancyAfterLocalChange(state);
    rebuildRuntimeEconomyPower(state);
    if (runtimeUnlockedBuildOptionCount(state) > unlockedOptionsBefore) {
        emitRuntimeSound(
            state,
            runtimeSoundIntentNewConstructionOptions
        );
    }
    return true;
}

bool placeRuntimeReadyBuildingForHumanOwner(
    RuntimeWindowState& state,
    const std::string& commandOwner,
    const RuntimeCellPoint& cell
) {
    bool remote = false;
    bool placed = false;
    {
        RuntimeHumanHouseScope scope(state, commandOwner);
        if (!scope) {
            return false;
        }
        remote = scope.remote();
        placed = placeRuntimeReadyBuilding(state, cell);
    }
    if (remote && placed) {
        rebuildRuntimeEconomyPower(state);
    }
    return placed;
}

void queueRuntimeFactoryDeliveryExitMove(
    RuntimeWindowState& state,
    WorldObjectInstance& produced,
    const RuntimeFactoryDeliveryLease& lease
) {
    RuntimeObjectBehavior behavior;
    behavior.kind = RuntimeBehaviorKind::Move;
    behavior.state = RuntimeBehaviorState::Queued;
    behavior.moveTarget = {lease.rallyCell.x, lease.rallyCell.y};
    if (lease.domain == RuntimeFactoryDeliveryDomain::Land
        && lease.lane == RuntimeProductionLane::Vehicles
        && runtimeFactoryLandVehicleEligible(state, produced)) {
        // A fresh car enters the dedicated exit track facing out of its door.
        produced.facing = runtimeFacingFromDelta(
            lease.rallyCell.x - produced.x, lease.rallyCell.y - produced.y);
        produced.bodyFacingClock = {};
        if (produced.turretFacing >= 0) produced.turretFacing = produced.facing;
        produced.turretFacingClock = {};
    }
    produced.mission = "Move";
    state.behaviors[produced.instanceId] = std::move(behavior);
    RuntimeObjectBehavior& queuedBehavior =
        state.behaviors[produced.instanceId];
    if (runtimeObjectMovementMode(state, produced) == PathMovementMode::Air) {
        return; // The air mover owns the path from inside the factory roof.
    }
    submitRuntimeMovePathRequest(
        state,
        produced,
        queuedBehavior,
        runtimeCellPointForObject(produced),
        queuedBehavior.moveTarget,
        -1,
        nullptr,
        false
    );
}

bool completeRuntimeProductionOrder(
    RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item,
    bool allowLegacyFactoryFallback = true,
    std::optional<RuntimeProductionLane> completedLane = std::nullopt,
    std::uint64_t completedOrderSerial = 0
) {
    if (item.kind == RuntimeBuildKind::Building
        || item.kind == RuntimeBuildKind::Defense) {
        return false;
    }

    const bool padAircraft = runtimeBuildItemUsesPadAircraft(state, item);
    std::optional<RuntimeProductionSpawn> groundVehicleSpawn;
    WorldObjectInstance spawnProbe;
    spawnProbe.kind = runtimeKindForBuildItem(item.kind);
    spawnProbe.type = item.typeId;
    if (!padAircraft && spawnProbe.kind == WorldObjectKind::Unit
        && runtimeObjectMovementMode(state, spawnProbe) != PathMovementMode::Air
        && runtimeObjectMovementMode(state, spawnProbe) != PathMovementMode::Naval) {
        groundVehicleSpawn = findRuntimeProductionSpawnForOwner(
            state, item, state.economy.owner, allowLegacyFactoryFallback);
        const auto* factoryType = groundVehicleSpawn && groundVehicleSpawn->anchor
            ? findRuntimeBuildingTypeById(state.rules, groundVehicleSpawn->anchor->type)
            : nullptr;
        if (!factoryType || !factoryType->weaponsFactory) groundVehicleSpawn.reset();
    }
    // Prefer a usable alternate edge before asking occupants at the original
    // doorway to move. That doorway need not be cleared for a rear delivery.
    if (!padAircraft && !groundVehicleSpawn && requestRuntimeProductionDoorClearanceForOwner(
            state, item, state.economy.owner, allowLegacyFactoryFallback)) {
        state.economy.status = "clearing production exit for " + item.typeId;
        return false;
    }
    if (padAircraft && (!completedLane.has_value()
            || completedOrderSerial == 0)) {
        refreshRuntimeAircraftDockAssignments(state);
    }
    std::optional<RuntimeProductionSpawn> spawn;
    if (padAircraft && completedLane.has_value()
        && completedOrderSerial != 0) {
        const std::optional<RuntimeAircraftProductionAssignment> assignment =
            runtimeAircraftProductionAssignmentForSerial(
                state,
                state.economy.owner,
                completedOrderSerial
            );
        const WorldObjectInstance* host = assignment.has_value()
            ? findObjectById(state, assignment->hostId)
            : nullptr;
        const BuildingType* building = host == nullptr
            ? nullptr
            : findRuntimeBuildingTypeById(state.rules, host->type);
        if (assignment.has_value()
            && assignment->phase
                == RuntimeAircraftProductionOrderPhase::Active
            && runtimeProductionItemKeysMatch(
                assignment->typeId,
                item.typeId
            )
            && host != nullptr
            && building != nullptr
            && (!building->powered || host->poweredOperational)
            && assignment->dockIndex >= 0
            && assignment->dockIndex < building->numberOfDocks
            && runtimeAircraftCanDockAtStructureForOwner(
                state,
                item,
                *host,
                state.economy.owner
            )
            && (!state.repairDepotsInitialized
                || !state.repairDepots.claimsDock(
                    host->instanceId,
                    assignment->dockIndex
                ))) {
            spawn = runtimeAircraftDockSpawn(
                state,
                *host,
                assignment->dockIndex
            );
        }
    } else if (padAircraft) {
        // Legacy direct-production probes have no serial to bind. Keep their
        // previous first-free behavior; authoritative lane completion never
        // takes this branch.
        spawn = findRuntimeProductionSpawnForOwner(
            state,
            item,
            state.economy.owner,
            allowLegacyFactoryFallback
        );
    } else {
        spawn = groundVehicleSpawn ? groundVehicleSpawn : findRuntimeProductionSpawnForOwner(
            state,
            item,
            state.economy.owner,
            allowLegacyFactoryFallback
        );
    }
    if (!spawn.has_value()) {
        const bool clearing = !padAircraft && requestRuntimeProductionDoorClearanceForOwner(
            state, item, state.economy.owner, allowLegacyFactoryFallback, true
        );
        state.economy.status = (clearing ? "clearing production exit for " : "no production cell for ")
            + item.typeId;
        return false;
    }
    const int spawnAnchorId =
        spawn->anchor != nullptr ? spawn->anchor->instanceId : -1;

    if (spawn->anchor != nullptr && !padAircraft && !runtimeBuildItemNeedsExitClearance(state, item)
        && requestRuntimeProductionDoorClearance(state,item,*spawn->anchor,state.economy.owner)) {
        state.economy.status = "clearing production air exit for " + item.typeId;
        return false;
    }
    if (spawn->anchor != nullptr && runtimeBuildItemNeedsExitClearance(state, item)) {
        auto outward = runtimeProductionOutwardCell(
            state, *spawn->anchor, spawn->cell
        );
        const auto* factoryType = findRuntimeBuildingTypeById(state.rules, spawn->anchor->type);
        WorldObjectInstance exitProbe;
        exitProbe.instanceId = -1;
        exitProbe.kind = runtimeKindForBuildItem(item.kind);
        exitProbe.owner = state.economy.owner;
        exitProbe.type = item.typeId;
        exitProbe.alive = true;
        exitProbe.x = spawn->cell.x;
        exitProbe.y = spawn->cell.y;
        exitProbe.cell = runtimeCellKey(exitProbe.x, exitProbe.y);
        exitProbe.level = terrainLevelAtRuntimeCell(state, exitProbe.x, exitProbe.y);
        exitProbe.onBridge = runtimeCellIsBridge(state, exitProbe.x, exitProbe.y);
        if (factoryType && factoryType->weaponsFactory
            && exitProbe.kind == WorldObjectKind::Unit
            && runtimeObjectMovementMode(state, exitProbe) != PathMovementMode::Air
            && runtimeObjectMovementMode(state, exitProbe) != PathMovementMode::Naval) {
            outward = findRuntimeProductionExitMoveTarget(state, *spawn->anchor, exitProbe);
        }
        if (outward && requestRuntimeFactoryExitClearance(
                state, state.economy.owner, {spawn->cell, *outward},
                -1, false, spawn->anchor->instanceId)) {
            state.economy.status = "clearing production exit for " + item.typeId;
            return false;
        }
    }

    std::optional<RuntimeFactoryDeliveryLease> deliveryLease;
    if (completedLane.has_value()
        && completedOrderSerial != 0
        && !padAircraft
        && (*completedLane == RuntimeProductionLane::Vehicles
            || *completedLane == RuntimeProductionLane::Ships)) {
        if (spawn->anchor == nullptr) {
            state.economy.status =
                "production host missing for " + item.typeId;
            return false;
        }
        WorldObjectInstance producedProbe;
        producedProbe.instanceId = nextRuntimeObjectInstanceId(state);
        producedProbe.kind = runtimeKindForBuildItem(item.kind);
        producedProbe.owner = state.economy.owner;
        producedProbe.type = item.typeId;
        producedProbe.x = spawn->cell.x;
        producedProbe.y = spawn->cell.y;
        producedProbe.cell = runtimeCellKey(
            producedProbe.x,
            producedProbe.y
        );
        producedProbe.level = terrainLevelAtRuntimeCell(
            state,
            producedProbe.x,
            producedProbe.y
        );
        producedProbe.onBridge = runtimeCellIsBridge(
            state,
            producedProbe.x,
            producedProbe.y
        );
        producedProbe.alive = true;
        const std::optional<RuntimeCellPoint> rally =
            findRuntimeProductionExitMoveTarget(
                state,
                *spawn->anchor,
                producedProbe,
                *completedLane == RuntimeProductionLane::Ships
            );
        if (!rally.has_value()) {
            state.economy.status =
                "production egress blocked for " + item.typeId;
            return false;
        }

        RuntimeFactoryDeliveryAcquireRequest request;
        request.lease.canonicalOwner =
            runtimeRepairDepotCanonicalOwnerId(
                state,
                state.economy.owner
            );
        request.lease.hostId = spawnAnchorId;
        request.lease.dockIndex = *completedLane
                == RuntimeProductionLane::Ships
            ? 0
            : -1;
        request.lease.lane = *completedLane;
        request.lease.orderSerial = completedOrderSerial;
        request.lease.producedObjectId = producedProbe.instanceId;
        request.lease.acquiredTick = std::max(0, state.tick);
        request.lease.rallyCell = {
            rally->x,
            rally->y,
            runtimeCellIsBridge(state, rally->x, rally->y)
        };
        request.lease.domain = *completedLane
                == RuntimeProductionLane::Ships
            ? RuntimeFactoryDeliveryDomain::Naval
            : RuntimeFactoryDeliveryDomain::Land;
        request.repairDockClaimed = state.repairDepotsInitialized
            && state.repairDepots.claimsDock(
                request.lease.hostId,
                0
            );
        const RuntimeFactoryDeliveryAcquireResult acquired =
            state.factoryDeliveries.acquire(request);
        if (!acquired.acquired) {
            state.economy.status =
                "production delivery blocked: " + acquired.reason;
            return false;
        }
        deliveryLease = acquired.lease;
    }

    WorldObjectInstance* unit =
        addRuntimeObjectInstanceForOwner(
            state,
            state.economy.owner,
            item.kind,
            item.typeId,
            spawn->cell,
            completedLane
        );
    if (unit == nullptr) {
        if (deliveryLease.has_value()) {
            (void)state.factoryDeliveries.releaseByOrder(
                deliveryLease->canonicalOwner,
                deliveryLease->lane,
                deliveryLease->orderSerial
            );
        }
        state.economy.status = "production failed";
        return false;
    }
    if (deliveryLease.has_value()
        && unit->instanceId != deliveryLease->producedObjectId) {
        const int unexpectedObjectId = unit->instanceId;
        (void)state.factoryDeliveries.releaseByOrder(
            deliveryLease->canonicalOwner,
            deliveryLease->lane,
            deliveryLease->orderSerial
        );
        std::vector<WorldObjectInstance>& objects =
            state.world.accessObjects();
        if (!objects.empty()
            && objects.back().instanceId == unexpectedObjectId) {
            objects.pop_back();
            state.cloakObservedHealthByObject.erase(unexpectedObjectId);
            invalidateRuntimeObjectProjectionCache(state);
        }
        state.economy.status = "production delivery id changed";
        return false;
    }
    applyRuntimeProducedObjectVeterancy(state, *unit);
    recordRuntimeCompletedBuild(state, unit->owner, item);
    // Airport-bound aircraft are born on their assigned pad.  They must not
    if (spawnAnchorId >= 0) {
        if (WorldObjectInstance* factory =
                findMutableObjectById(state, spawnAnchorId)) {
            beginRuntimeFactoryExitAnimation(state, *factory, *unit);
        }
    }
    // inherit the ordinary factory-exit Move behavior: changing only the
    // visible mission to Dock would leave that queued behavior alive and the
    // next simulation tick would fly the aircraft away from the airfield.
    if (!spawn->aircraftDock) {
        if (deliveryLease.has_value()) {
            queueRuntimeFactoryDeliveryExitMove(
                state,
                *unit,
                *deliveryLease
            );
        } else if (spawnAnchorId >= 0) {
            const WorldObjectInstance* anchor =
                findObjectById(state, spawnAnchorId);
            if (anchor != nullptr) {
                queueRuntimeProductionExitMove(state, *unit, *anchor);
            }
        } else {
            queueRuntimeProductionExitMoveForOwner(
                state,
                *unit,
                item,
                state.economy.owner,
                allowLegacyFactoryFallback
            );
        }
    }

    if (spawnAnchorId >= 0) queueRuntimePlayerFactoryRally(state, spawnAnchorId, unit->instanceId);

    if (item.kind == RuntimeBuildKind::Infantry) {
        ++state.economy.completedInfantry;
    } else {
        ++state.economy.completedUnits;
    }
    state.economy.status =
        "produced " + unit->type + " #"
        + std::to_string(unit->instanceId);
    std::string createSound;
    if (spawn->aircraftDock && spawnAnchorId >= 0) {
        state.behaviors.erase(unit->instanceId);
        const WorldObjectInstance* anchor =
            findObjectById(state, spawnAnchorId);
        if (anchor != nullptr) {
            applyRuntimeAircraftDockPose(
                state,
                *unit,
                *anchor,
                spawn->dockIndex
            );
        }
    } else if (spawnAnchorId >= 0) {
        if (const WorldObjectInstance* anchor =
                findObjectById(state, spawnAnchorId)) {
            if (const BuildingType* factory =
                    findRuntimeBuildingTypeById(state.rules, anchor->type)) {
                createSound = factory->createUnitSound;
            }
        }
    }
    const UnitType* producedType =
        findRuntimeUnitTypeById(state.rules, unit->type);
    if (createSound.empty() && producedType != nullptr) {
        createSound = producedType->createSound;
    }
    if (!trimAsciiLocal(createSound).empty()) {
        emitRuntimeSound(state, "sound:" + trimAsciiLocal(createSound), runtimeSpatialAudioPositionForObject(*unit));
    }
    emitRuntimeSound(state, runtimeSoundIntentUnitReady);
    // Producing an ordinary mobile object cannot change any structure power,
    // refinery, storage, radar, or dock aggregate. Rebuilding those aggregates
    // here scanned the whole world several times at the exact completion tick.
    // Harvesters are the sole mobile economy aggregate and can be maintained
    // incrementally because this path always creates one live local object.
    if (producedType != nullptr && producedType->harvester) {
        ++state.economy.harvesters;
    }
    if (item.kind == RuntimeBuildKind::Infantry) {
        const std::vector<int> cloneIds = cloneRuntimeProducedInfantry(
            state,
            state.economy.owner,
            item.typeId,
            spawnAnchorId
        );
        if (!cloneIds.empty()) {
            state.economy.status +=
                " cloned x" + std::to_string(cloneIds.size());
        }
    }
    return true;
}

RuntimeFactoryDeliveryReconcileInput runtimeFactoryDeliveryReconcileInput(
    const RuntimeWindowState& state
) {
    RuntimeFactoryDeliveryReconcileInput input;
    std::set<int> hostIds;
    std::set<int> objectIds;
    for (const RuntimeFactoryDeliveryLease& lease :
            state.factoryDeliveries.leases()) {
        if (hostIds.insert(lease.hostId).second) {
            const auto host = std::find_if(
                state.world.getObjects().begin(),
                state.world.getObjects().end(),
                [&lease](const WorldObjectInstance& object) {
                    return object.instanceId == lease.hostId;
                }
            );
            if (host != state.world.getObjects().end() && host->alive) {
                const BuildingType* building =
                    findRuntimeBuildingTypeById(state.rules, host->type);
                const bool validFactory = building != nullptr
                    && runtimeFactoryDeliveryHostStructurallyEligibleForOwner(
                        state,
                        *host,
                        lease.canonicalOwner,
                        lease.domain
                    );
                if (validFactory) {
                    const std::optional<RuntimeFactoryDeliveryDomain>
                        hostDomain = runtimeFactoryDeliveryHostDomain(
                            state,
                            *host
                        );
                    if (!hostDomain.has_value()) {
                        continue;
                    }
                    input.hosts.push_back({
                        runtimeRepairDepotCanonicalOwnerId(
                            state,
                            host->owner
                        ),
                        host->instanceId,
                        *hostDomain,
                        true,
                        false
                    });
                }
            }
        }
        if (objectIds.insert(lease.producedObjectId).second) {
            const auto object = std::find_if(
                state.world.getObjects().begin(),
                state.world.getObjects().end(),
                [&lease](const WorldObjectInstance& candidate) {
                    return candidate.instanceId
                        == lease.producedObjectId;
                }
            );
            const UnitType* unit = object == state.world.getObjects().end()
                ? nullptr
                : findRuntimeUnitTypeById(state.rules, object->type);
            const bool navalUnit = unit != nullptr
                && (unit->naval || unit->waterBound);
            const bool validUnit = object != state.world.getObjects().end()
                && object->alive
                && object->kind == WorldObjectKind::Unit
                && (lease.lane == RuntimeProductionLane::Ships
                    ? lease.domain == RuntimeFactoryDeliveryDomain::Naval
                        && navalUnit
                    : lease.lane == RuntimeProductionLane::Vehicles
                        && lease.domain == RuntimeFactoryDeliveryDomain::Land
                        && !navalUnit);
            if (validUnit) {
                input.objects.push_back({
                    runtimeRepairDepotCanonicalOwnerId(
                        state,
                        object->owner
                    ),
                    object->instanceId,
                    true
                });
            }
        }
    }
    return input;
}

#include "simulation/production/RuntimeFreeUnitDelivery.inl"

bool advanceRuntimeFactoryDeliveries(RuntimeWindowState& state) {
    RuntimePerfTraceScope trace("advanceRuntimeFactoryDeliveries", state.tick);
    const std::uint64_t before = state.factoryDeliveries.stateHash();
    (void)advanceRuntimeFreeUnitDeliveries(state);
    const RuntimeFactoryDeliveryReconcileReport report =
        state.factoryDeliveries.reconcile(
            runtimeFactoryDeliveryReconcileInput(state)
        );
    if (!report.accepted) {
        state.simulationStatus =
            "factory delivery reconcile rejected: " + report.error;
        return false;
    }

    std::vector<RuntimeFactoryDeliveryLease> arrivedLeases;
    for (const RuntimeFactoryDeliveryLease& lease :
            state.factoryDeliveries.leases()) {
        const auto object = std::find_if(
            state.world.getObjects().begin(),
            state.world.getObjects().end(),
            [&lease](const WorldObjectInstance& candidate) {
                return candidate.instanceId == lease.producedObjectId;
            }
        );
        if (object != state.world.getObjects().end() && object->alive) {
            (void)requestRuntimeFactoryExitClearance(
                state, object->owner,
                {{lease.rallyCell.x, lease.rallyCell.y}},
                lease.producedObjectId,
                runtimeObjectMovementMode(state, *object) == PathMovementMode::Air,
                lease.domain == RuntimeFactoryDeliveryDomain::Land
                    ? lease.hostId : -1
            );
        }
        if (object != state.world.getObjects().end()
            && object->alive
            && object->x == lease.rallyCell.x
            && object->y == lease.rallyCell.y
            && object->onBridge == lease.rallyCell.onBridge
            && !object->renderMoveActive) {
            arrivedLeases.push_back(lease);
        }
    }
    for (const auto& lease : arrivedLeases) {
        (void)state.factoryDeliveries.releaseByObject(lease.producedObjectId);
        const auto* object = findObjectById(state, lease.producedObjectId);
        const auto queued = state.playerCommands.queues.find(lease.producedObjectId);
        if (object && lease.domain == RuntimeFactoryDeliveryDomain::Land
            && lease.lane == RuntimeProductionLane::Vehicles
            && runtimeFactoryFastClearanceSource(state, *object, lease.hostId)
            && queued != state.playerCommands.queues.end()
            && queued->second.owner == runtimeCanonicalHumanHouseOwner(object->owner)
            && !queued->second.orders.empty()) {
            const auto& first = queued->second.orders.front();
            if (first.order == RuntimeMultiplayerGameplayTargetOrderKind::Move
                && first.objectIds == std::vector<std::int32_t>{lease.producedObjectId}
                && std::holds_alternative<RuntimeMultiplayerGameplayCellTarget>(first.target)) {
                // The physical lease ends at the outside doorway. Clear that
                // slot with a short ordinary yield before dispatching the
                // queued rally, whose full route retains the original Speed.
                (void)requestRuntimeFactoryExitClearance(state, object->owner,
                    {{lease.rallyCell.x, lease.rallyCell.y}}, -1, false, lease.hostId);
            }
        }
    }
    return before != state.factoryDeliveries.stateHash();
}

bool runtimeFactoryDeliveryOwnsEgress(
    const RuntimeWindowState& state,
    int objectId
) {
    return std::any_of(
        state.factoryDeliveries.leases().begin(),
        state.factoryDeliveries.leases().end(),
        [objectId](const RuntimeFactoryDeliveryLease& lease) {
            return lease.producedObjectId == objectId;
        }
    );
}

const WorldObjectInstance* findObjectById(
    const RuntimeWindowState& state,
    int objectId
);
WorldObjectInstance* findMutableObjectById(RuntimeWindowState& state, int objectId);
const WorldObjectInstance* findRuntimeObjectByIdIncludingInactive(
    const RuntimeWindowState& state,
    int objectId
);
WorldObjectInstance* findMutableRuntimeObjectByIdIncludingInactive(
    RuntimeWindowState& state,
    int objectId
);
bool advanceRuntimeUnitTransportBoarding(RuntimeWindowState&, WorldObjectInstance&, const WorldObjectInstance&);
bool runtimeTransportBoardingReadyForManifest(const RuntimeWindowState&, const WorldObjectInstance&, const RuntimeObjectBehavior&);

bool runtimeObjectCanEnterTransport(
    const RuntimeWindowState& state,
    const WorldObjectInstance& passenger,
    const WorldObjectInstance& transport,
    bool includeReservations,
    bool requireBoardingPose = true
);
bool runtimeGarrisonOwnersAllowEntry(
    const WorldObjectInstance& occupier,
    const WorldObjectInstance& host
) {
    return occupier.owner == host.owner
        || (host.garrisonOccupantIds.empty()
            && (runtimeOwnerIsNeutralForAutoTarget(host.owner)
                || toUpperAsciiLocal(trimAsciiLocal(host.owner)) == "CIVILIANS"));
}

bool runtimeOrdinaryAttackRelationLegal(
    const RuntimeWindowState& state,
    const WorldObjectInstance& attacker,
    const WorldObjectInstance& target,
    bool forceFire = false
) {
    if (forceFire) return true;
    if (runtimeOwnersAreAllied(state, attacker.owner, target.owner)) return false;

    // An occupier preserves a usable civilian house even when entry is
    // temporarily blocked by reservations or terrain. Vehicles and enemy
    // garrisons use the ordinary attack relationship; Ctrl still forces fire.
    if (attacker.kind == WorldObjectKind::Infantry
        && target.kind == WorldObjectKind::Structure
        && runtimeGarrisonOwnersAllowEntry(attacker, target)) {
        const UnitType* infantry = findRuntimeUnitType(state.rules, attacker);
        const BuildingType* building = findRuntimeBuildingType(state.rules, target);
        if (infantry != nullptr && infantry->occupier
            && building != nullptr && building->canBeOccupied
            && building->maxNumberOccupants > 0
            && target.health > static_cast<double>(std::max(1, building->strength))
                * state.rules.getSpecialMechanismRules().conditionRed) {
            return false;
        }
    }
    return true;
}

std::string runtimeGarrisonEntryVetoReason(
    const RuntimeWindowState& state,
    const WorldObjectInstance& occupier
) {
    // The relation survives Move/Stop orders and permanent Dominator control;
    // the current mission string and the new owner do not identify it.
    return state.specialMechanisms.mindControlLinks().contains(occupier.instanceId)
        ? "occupant is mind-controlled" : "";
}

