std::string runtimeDefaultSavePath(const RuntimeWindowState& state) {
    if (state.campaignMode
        || toUpperAsciiLocal(trimAsciiLocal(state.config.gameMode))
            == "CAMPAIGNMISSION") {
        if (!trimAsciiLocal(state.config.campaignSavePath).empty()) {
            return state.config.campaignSavePath;
        }
        return campaignSavePath(
            state.config.localDataRootPath,
            state.config.campaignId,
            state.config.campaignMissionId
        );
    }
    const std::filesystem::path root =
        state.config.localDataRootPath.empty()
            ? std::filesystem::path("local_data")
            : std::filesystem::path(state.config.localDataRootPath);
    return pathString(root / "runtime_save.ini");
}

