std::optional<RuntimeBuildCatalogItem> runtimeCatalogItemByKindAndType(
    const RuntimeWindowState& state,
    RuntimeBuildKind kind,
    const std::string& typeId
) {
    const std::string wanted = toUpperAsciiLocal(typeId);
    for (const RuntimeBuildCatalogItem& item : state.economy.catalog) {
        if (item.kind == kind && toUpperAsciiLocal(item.typeId) == wanted) {
            return item;
        }
    }
    return std::nullopt;
}

bool parseRuntimeStrictBool(const std::string& value, bool& output);

std::optional<RuntimeBuildOrder> parseRuntimeBuildOrder(
    const RuntimeWindowState& state,
    const std::string& value
) {
    const std::vector<std::string> tokens = splitRuntimeSaveFields(value);
    if (tokens.size() != 4U && tokens.size() != 5U) {
        return std::nullopt;
    }

    const std::string kindToken = toLowerAsciiLocal(
        trimAsciiLocal(tokens[0])
    );
    if (kindToken != "building"
        && kindToken != "defense"
        && kindToken != "def"
        && kindToken != "infantry"
        && kindToken != "inf"
        && kindToken != "unit"
        && kindToken != "vehicle"
        && kindToken != "veh") {
        return std::nullopt;
    }
    const RuntimeBuildKind kind = runtimeBuildKindFromName(kindToken);
    const std::optional<RuntimeBuildCatalogItem> item =
        runtimeCatalogItemByKindAndType(state, kind, tokens[1]);
    if (!item.has_value()) {
        return std::nullopt;
    }

    RuntimeBuildOrder order;
    order.item = *item;
    if (!parseRuntimeInt(tokens[2], order.remainingTicks)
        || !parseRuntimeStrictBool(tokens[3], order.paid)
        || (tokens.size() == 5U
            && !parseRuntimeStrictBool(tokens[4], order.onHold))) {
        return std::nullopt;
    }
    return order;
}

