std::string serializeRuntimeSlaveMinerTask(
    const RuntimeSlaveMinerTask& task
) {
    return runtimeSlaveMinerPhaseName(task.phase)
        + "|"
        + std::to_string(task.refineryId)
        + "|"
        + std::to_string(task.targetOre.x)
        + "|"
        + std::to_string(task.targetOre.y)
        + "|"
        + std::to_string(task.cargoValue)
        + "|"
        + std::to_string(task.cargoUnits)
        + "|"
        + std::to_string(task.cargoGemUnits)
        + "|"
        + std::to_string(task.workTicksRemaining)
        + "|"
        + runtimeSaveField(task.status);
}

std::optional<RuntimeSlaveMinerTask> parseRuntimeSlaveMinerTask(
    const std::string& value
) {
    const std::vector<std::string> tokens = splitRuntimeSaveFields(value);
    if (tokens.size() < 7) {
        return std::nullopt;
    }

    RuntimeSlaveMinerTask task;
    task.phase = runtimeSlaveMinerPhaseFromName(tokens[0]);
    task.refineryId = parseRuntimeIntOrDefault(tokens[1], -1);
    task.targetOre.x = parseRuntimeIntOrDefault(tokens[2], -1);
    task.targetOre.y = parseRuntimeIntOrDefault(tokens[3], -1);
    task.cargoValue = parseRuntimeIntOrDefault(tokens[4], 0);
    task.cargoUnits = parseRuntimeIntOrDefault(tokens[5], 0);
    if (tokens.size() >= 9) {
        task.cargoGemUnits = parseRuntimeIntOrDefault(tokens[6], 0);
        task.workTicksRemaining = parseRuntimeIntOrDefault(tokens[7], 0);
        task.status = tokens[8];
    } else {
        task.workTicksRemaining = parseRuntimeIntOrDefault(tokens[6], 0);
        task.status = tokens.size() >= 8 ? tokens[7] : "";
    }
    task.cargoGemUnits =
        std::clamp(task.cargoGemUnits, 0, std::max(0, task.cargoUnits));
    return task;
}

