bool parseRuntimeStrictBool(const std::string& value, bool& output) {
    const std::string normalized = toLowerAsciiLocal(trimAsciiLocal(value));
    if (normalized == "yes" || normalized == "true" || normalized == "1") {
        output = true;
        return true;
    }
    if (normalized == "no" || normalized == "false" || normalized == "0") {
        output = false;
        return true;
    }
    return false;
}

bool parseRuntimeFiniteDouble(const std::string& value, double& output) {
    try {
        const std::string trimmed = trimAsciiLocal(value);
        std::size_t consumed = 0;
        const double parsed = std::stod(trimmed, &consumed);
        if (consumed != trimmed.size() || !std::isfinite(parsed)) {
            return false;
        }
        output = parsed;
        return true;
    } catch (...) {
        return false;
    }
}

bool parseRuntimeUint64Strict(
    const std::string& value,
    std::uint64_t& parsed
);

