constexpr bool runtimeProductionLanesModernSectionSchemaSupported(int schema) {
    return schema == runtimeProductionLanesSectionSchemaV2
        || schema == runtimeProductionLanesSectionSchemaV3Alias;
}

std::string serializeRuntimeProjectileEffect(
    const RuntimeProjectileEffect& projectile
) {
    std::ostringstream output;
    output << std::setprecision(std::numeric_limits<double>::max_digits10);
    bool first = true;
    const auto write = [&output, &first](const auto& value) {
        if (!first) {
            output << '|';
        }
        first = false;
        output << value;
    };
    const auto writeBool = [&write](bool value) {
        write(runtimeBoolText(value));
    };
    const auto writeString = [&write](const std::string& value) {
        write(runtimeSaveField(value));
    };

    write(projectile.actorId);
    write(projectile.parentActorId);
    write(projectile.generation);
    write(projectile.attackerObjectId);
    write(projectile.targetObjectId);
    write(projectile.sourceAnchorObjectId);
    writeString(projectile.owner);
    write(projectile.fromCell.x);
    write(projectile.fromCell.y);
    write(projectile.toCell.x);
    write(projectile.toCell.y);
    write(projectile.currentCell.x);
    write(projectile.currentCell.y);
    writeBool(projectile.hasSourcePosition);
    write(projectile.sourceX);
    write(projectile.sourceY);
    write(projectile.sourceZ);
    write(projectile.sourceScreenOffsetX);
    write(projectile.sourceScreenOffsetY);
    writeBool(projectile.hasTargetPosition);
    write(projectile.targetX);
    write(projectile.targetY);
    write(projectile.targetZ);
    write(projectile.fromLevel);
    write(projectile.toLevel);
    write(projectile.currentLevel);
    write(projectile.attackerFacing);
    write(projectile.targetFacing);
    write(projectile.spawnTick);
    write(projectile.impactTick);
    write(projectile.elapsedTicks);
    write(projectile.damage);
    write(projectile.veteranDamageMultiplier);
    writeBool(projectile.spawnedMissileDamage);
    write(projectile.spawnedMissileBaseDamage);
    write(projectile.totalTicks);
    write(projectile.remainingTicks);
    write(static_cast<int>(projectile.lifecycle));
    writeString(projectile.lifecycleState);
    writeString(projectile.renderIntent);
    writeString(projectile.weaponId);
    writeString(projectile.weaponSlot);
    writeString(projectile.projectileId);
    writeString(projectile.projectileImageId);
    writeString(projectile.warheadId);
    writeString(projectile.weaponAnimId);
    writeString(projectile.impactAnimId);
    writeString(projectile.trailerAnimId);
    writeString(projectile.trailerIntentId);
    writeString(projectile.warheadImpactIntentId);
    writeString(projectile.reportSoundId);
    writeBool(projectile.arcing);
    writeBool(projectile.vertical);
    write(projectile.acceleration);
    writeBool(projectile.high);
    writeBool(projectile.veryHigh);
    writeBool(projectile.shadow);
    writeBool(projectile.animates);
    writeBool(projectile.aa);
    writeBool(projectile.ag);
    write(projectile.cluster);
    writeBool(projectile.bright);
    writeBool(projectile.laser);
    writeBool(projectile.houseColorLaser);
    writeBool(projectile.electricBolt);
    writeBool(projectile.alternateElectricColor);
    writeString(projectile.electricColor);
    writeBool(projectile.shrapnel);
    writeBool(projectile.shrapnelReleased);
    write(projectile.laserDuration);
    write(projectile.laserThickness);
    write(projectile.cellSpread);
    write(projectile.percentAtMax);
    writeBool(projectile.affectsAllies);
    writeBool(projectile.affectsEnemies);
    writeString(projectile.particleId);
    write(projectile.progress);
    write(projectile.currentX);
    write(projectile.currentY);
    write(projectile.currentZ);
    write(projectile.speedCellsPerTick);
    write(projectile.rot);
    write(projectile.deathWeaponCascadeId);
    write(projectile.deathWeaponRequestId);
    write(projectile.deathWeaponCascadeDepth);
    write(projectile.launchSourceKind);
    writeString(projectile.launchSourceType);
    writeBool(projectile.launchSourceAuthoredAircraft);
    writeBool(projectile.launchSourceValidated);
    write(projectile.airstrikeStrikeId);
    write(projectile.airstrikePlaneToken);
    writeBool(projectile.particleDamagePulse);
    writeBool(projectile.suppressWarheadParticleSpawn);
    writeString(serializeRuntimeVoxelDebris(projectile.voxelDebris));
    writeBool(projectile.homingInitialized);
    write(projectile.homingYaw);
    write(projectile.homingPitch);
    write(projectile.sourceNativeFixedX);
    write(projectile.sourceNativeFixedY);
    return output.str();
}

bool parseRuntimeProjectileEffect(
    const std::string& value,
    RuntimeProjectileEffect& projectile,
    int schema = runtimeProjectileSaveSchemaV6,
    bool allowExpired = false
) {
    const std::vector<std::string> tokens = splitRuntimeSaveFields(value);
    const std::size_t expectedFieldCount =
        schema == runtimeProjectileSaveSchemaV1
            ? runtimeProjectileSaveFieldCountV1
            : schema == runtimeProjectileSaveSchemaV2
                ? runtimeProjectileSaveFieldCountV2
                : schema == runtimeProjectileSaveSchemaV3
                    ? runtimeProjectileSaveFieldCountV3
                    : schema == runtimeProjectileSaveSchemaV4
                        ? runtimeProjectileSaveFieldCountV4
                        : schema == runtimeProjectileSaveSchemaV5
                            ? runtimeProjectileSaveFieldCountV5
                            : schema == runtimeProjectileSaveSchemaV6
                                ? runtimeProjectileSaveFieldCountV6 : 0U;
    if (expectedFieldCount == 0U || tokens.size() != expectedFieldCount) {
        return false;
    }

    projectile.deathWeaponCascadeId = 0;
    projectile.deathWeaponRequestId = 0;
    projectile.deathWeaponCascadeDepth = 0;
    projectile.launchSourceKind = -1;
    projectile.launchSourceType.clear();
    projectile.launchSourceAuthoredAircraft = false;
    projectile.launchSourceValidated = false;
    projectile.airstrikeStrikeId = 0;
    projectile.airstrikePlaneToken = 0;
    projectile.particleDamagePulse = false;
    projectile.suppressWarheadParticleSpawn = false;
    projectile.voxelDebris = {};
    projectile.homingInitialized = false;
    projectile.homingYaw = projectile.homingPitch = 0.0;
    projectile.sourceNativeFixedX = projectile.sourceNativeFixedY = 0;
    std::string debrisRecord;

    std::size_t cursor = 0;
    const auto readInt = [&tokens, &cursor](int& result) {
        return cursor < tokens.size()
            && parseRuntimeInt(tokens[cursor++], result);
    };
    const auto readBool = [&tokens, &cursor](bool& result) {
        return cursor < tokens.size()
            && parseRuntimeStrictBool(tokens[cursor++], result);
    };
    const auto readDouble = [&tokens, &cursor](double& result) {
        return cursor < tokens.size()
            && parseRuntimeFiniteDouble(tokens[cursor++], result);
    };
    const auto readString = [&tokens, &cursor](std::string& result) {
        if (cursor >= tokens.size()) {
            return false;
        }
        result = tokens[cursor++];
        return true;
    };
    const auto readUint64 = [&tokens, &cursor](std::uint64_t& result) {
        return cursor < tokens.size()
            && parseRuntimeUint64Strict(tokens[cursor++], result);
    };

    int lifecycle = 0;
    std::uint64_t deathWeaponCascadeDepth = 0;
    if (!readInt(projectile.actorId)
        || !readInt(projectile.parentActorId)
        || !readInt(projectile.generation)
        || !readInt(projectile.attackerObjectId)
        || !readInt(projectile.targetObjectId)
        || !readInt(projectile.sourceAnchorObjectId)
        || !readString(projectile.owner)
        || !readInt(projectile.fromCell.x)
        || !readInt(projectile.fromCell.y)
        || !readInt(projectile.toCell.x)
        || !readInt(projectile.toCell.y)
        || !readInt(projectile.currentCell.x)
        || !readInt(projectile.currentCell.y)
        || !readBool(projectile.hasSourcePosition)
        || !readDouble(projectile.sourceX)
        || !readDouble(projectile.sourceY)
        || !readDouble(projectile.sourceZ)
        || !readInt(projectile.sourceScreenOffsetX)
        || !readInt(projectile.sourceScreenOffsetY)
        || !readBool(projectile.hasTargetPosition)
        || !readDouble(projectile.targetX)
        || !readDouble(projectile.targetY)
        || !readDouble(projectile.targetZ)
        || !readInt(projectile.fromLevel)
        || !readInt(projectile.toLevel)
        || !readInt(projectile.currentLevel)
        || !readInt(projectile.attackerFacing)
        || !readInt(projectile.targetFacing)
        || !readInt(projectile.spawnTick)
        || !readInt(projectile.impactTick)
        || !readInt(projectile.elapsedTicks)
        || !readInt(projectile.damage)
        || !readDouble(projectile.veteranDamageMultiplier)
        || !readBool(projectile.spawnedMissileDamage)
        || !readInt(projectile.spawnedMissileBaseDamage)
        || !readInt(projectile.totalTicks)
        || !readInt(projectile.remainingTicks)
        || !readInt(lifecycle)
        || !readString(projectile.lifecycleState)
        || !readString(projectile.renderIntent)
        || !readString(projectile.weaponId)
        || !readString(projectile.weaponSlot)
        || !readString(projectile.projectileId)
        || !readString(projectile.projectileImageId)
        || !readString(projectile.warheadId)
        || !readString(projectile.weaponAnimId)
        || !readString(projectile.impactAnimId)
        || !readString(projectile.trailerAnimId)
        || !readString(projectile.trailerIntentId)
        || !readString(projectile.warheadImpactIntentId)
        || !readString(projectile.reportSoundId)
        || !readBool(projectile.arcing)
        || !readBool(projectile.vertical)
        || !readInt(projectile.acceleration)
        || !readBool(projectile.high)
        || !readBool(projectile.veryHigh)
        || !readBool(projectile.shadow)
        || !readBool(projectile.animates)
        || !readBool(projectile.aa)
        || !readBool(projectile.ag)
        || !readInt(projectile.cluster)
        || !readBool(projectile.bright)
        || !readBool(projectile.laser)
        || !readBool(projectile.houseColorLaser)
        || !readBool(projectile.electricBolt)
        || !readBool(projectile.alternateElectricColor)
        || !readString(projectile.electricColor)
        || !readBool(projectile.shrapnel)
        || !readBool(projectile.shrapnelReleased)
        || !readInt(projectile.laserDuration)
        || !readInt(projectile.laserThickness)
        || !readDouble(projectile.cellSpread)
        || !readDouble(projectile.percentAtMax)
        || !readBool(projectile.affectsAllies)
        || !readBool(projectile.affectsEnemies)
        || !readString(projectile.particleId)
        || !readDouble(projectile.progress)
        || !readDouble(projectile.currentX)
        || !readDouble(projectile.currentY)
        || !readDouble(projectile.currentZ)
        || !readDouble(projectile.speedCellsPerTick)
        || !readInt(projectile.rot)
        || (schema >= runtimeProjectileSaveSchemaV2
            && (!readUint64(projectile.deathWeaponCascadeId)
                || !readUint64(projectile.deathWeaponRequestId)
                || !readUint64(deathWeaponCascadeDepth)))
        || (schema >= runtimeProjectileSaveSchemaV3
            && (!readInt(projectile.launchSourceKind)
                || !readString(projectile.launchSourceType)
                || !readBool(projectile.launchSourceAuthoredAircraft)
                || !readBool(projectile.launchSourceValidated)
                || !readInt(projectile.airstrikeStrikeId)
                || !readInt(projectile.airstrikePlaneToken)
                || !readBool(projectile.particleDamagePulse)
                || !readBool(projectile.suppressWarheadParticleSpawn)))
        || (schema >= runtimeProjectileSaveSchemaV4
            && (!readString(debrisRecord) || !parseRuntimeVoxelDebris(debrisRecord, projectile.voxelDebris)))
        || (schema >= runtimeProjectileSaveSchemaV5
            && (!readBool(projectile.homingInitialized) || !readDouble(projectile.homingYaw)
                || !readDouble(projectile.homingPitch)))
        || (schema >= runtimeProjectileSaveSchemaV6
            && (!readInt(projectile.sourceNativeFixedX) || !readInt(projectile.sourceNativeFixedY)
                || std::abs(static_cast<long long>(projectile.sourceNativeFixedX)) > 65536
                || std::abs(static_cast<long long>(projectile.sourceNativeFixedY)) > 65536))
        || cursor != tokens.size()) {
        return false;
    }

    if (std::abs(projectile.homingYaw) > 3.141592653589794
        || std::abs(projectile.homingPitch) > 1.570796326794897
        || (!projectile.homingInitialized && (projectile.homingYaw != 0.0 || projectile.homingPitch != 0.0))) return false;
    if (projectile.voxelDebris.enabled != (projectile.renderIntent == "unitVoxelDebris")) return false;
    if (projectile.voxelDebris.enabled) {
        const auto& pos = projectile.voxelDebris.position;
        if (std::abs(projectile.currentX - pos[0] / 256.0) > 1e-8
            || std::abs(projectile.currentY - pos[1] / 256.0) > 1e-8
            || std::abs(projectile.currentZ - pos[2] * runtimeDebrisHeightPerLepton) > 1e-8) return false;
    }
    if (deathWeaponCascadeDepth
        > std::numeric_limits<std::uint32_t>::max()) {
        return false;
    }
    projectile.deathWeaponCascadeDepth =
        static_cast<std::uint32_t>(deathWeaponCascadeDepth);

    const bool noDeathWeaponLineage =
        projectile.deathWeaponCascadeId == 0
        && projectile.deathWeaponRequestId == 0
        && projectile.deathWeaponCascadeDepth == 0;
    const bool validDeathWeaponLineage =
        projectile.deathWeaponCascadeId > 0
        && projectile.deathWeaponRequestId
            >= projectile.deathWeaponCascadeId
        && projectile.deathWeaponCascadeDepth < 16U;
    const bool noLaunchProvenance = !projectile.launchSourceValidated
        && projectile.launchSourceKind == -1
        && projectile.launchSourceType.empty()
        && !projectile.launchSourceAuthoredAircraft;
    const bool validLaunchProvenance = projectile.launchSourceValidated
        && projectile.attackerObjectId >= 0
        && !trimAsciiLocal(projectile.owner).empty()
        && projectile.launchSourceKind
            >= static_cast<int>(WorldObjectKind::Structure)
        && projectile.launchSourceKind
            <= static_cast<int>(WorldObjectKind::Infantry)
        && !trimAsciiLocal(projectile.launchSourceType).empty()
        && projectile.launchSourceType.size() <= 128U
        && (!projectile.launchSourceAuthoredAircraft
            || projectile.launchSourceKind
                == static_cast<int>(WorldObjectKind::Unit));
    const bool noAirstrikeAttribution = projectile.airstrikeStrikeId == 0
        && projectile.airstrikePlaneToken == 0;
    const bool validAirstrikeAttribution = projectile.airstrikeStrikeId > 0
        && projectile.airstrikePlaneToken > 0;
    if (projectile.actorId <= 0
        || (projectile.parentActorId < 0 && projectile.parentActorId != -1)
        || projectile.parentActorId == 0
        || projectile.generation < 0
        || projectile.generation > 4
        || lifecycle < static_cast<int>(RuntimeProjectileLifecycleState::Spawned)
        || lifecycle > static_cast<int>(
            allowExpired
                ? RuntimeProjectileLifecycleState::Expired
                : RuntimeProjectileLifecycleState::Traveling
        )
        || projectile.totalTicks <= 0
        || projectile.remainingTicks < 0
        || projectile.remainingTicks > projectile.totalTicks
        || projectile.elapsedTicks < 0
        || projectile.elapsedTicks > projectile.totalTicks
        || projectile.elapsedTicks
            != projectile.totalTicks - projectile.remainingTicks
        || static_cast<long long>(projectile.spawnTick)
                + static_cast<long long>(projectile.totalTicks)
            != static_cast<long long>(projectile.impactTick)
        || projectile.veteranDamageMultiplier < 0.0
        || projectile.laserDuration < 0
        || projectile.laserThickness < 1
        || projectile.laserThickness > 32
        || projectile.cellSpread < 0.0
        || projectile.progress < 0.0
        || projectile.progress > 1.0
        || projectile.speedCellsPerTick < 0.0
        || (!noDeathWeaponLineage && !validDeathWeaponLineage)
        || (!noLaunchProvenance && !validLaunchProvenance)
        || (!noAirstrikeAttribution && !validAirstrikeAttribution)
        || (projectile.particleDamagePulse
            && (!projectile.suppressWarheadParticleSpawn
                || validAirstrikeAttribution))) {
        return false;
    }

    projectile.lifecycle =
        static_cast<RuntimeProjectileLifecycleState>(lifecycle);
    const bool expired = projectile.lifecycle
        == RuntimeProjectileLifecycleState::Expired;
    if ((!expired && projectile.remainingTicks <= 0)
        || (expired
            && (!allowExpired
                || projectile.remainingTicks != 0
                || projectile.elapsedTicks != projectile.totalTicks))
        || (!expired
            && (projectile.lifecycle == RuntimeProjectileLifecycleState::Spawned)
                != (projectile.elapsedTicks == 0))) {
        return false;
    }
    if (toLowerAsciiLocal(trimAsciiLocal(projectile.lifecycleState))
        != toLowerAsciiLocal(runtimeProjectileLifecycleName(
            projectile.lifecycle
        ))) {
        return false;
    }
    return true;
}

struct RuntimeProjectileSaveCandidate {
    std::vector<RuntimeProjectileEffect> projectiles;
    int nextActorId = 1;
    int schema = 0;
};

bool parseRuntimeProjectilesFromSave(
    const IniFile& ini,
    RuntimeProjectileSaveCandidate& candidate,
    std::string& errorMessage
) {
    RuntimeProjectileSaveCandidate parsed;

    if (ini.getSection("Projectiles") == nullptr) {
        candidate = std::move(parsed);
        return true;
    }

    int schema = 0;
    int count = 0;
    int savedNextActorId = 0;
    if (!parseRuntimeInt(ini.getValue("Projectiles", "Schema", ""), schema)
        || (schema != runtimeProjectileSaveSchemaV1
            && schema != runtimeProjectileSaveSchemaV2
            && schema != runtimeProjectileSaveSchemaV3
            && schema != runtimeProjectileSaveSchemaV4
            && schema != runtimeProjectileSaveSchemaV5
            && schema != runtimeProjectileSaveSchemaV6)
        || !parseRuntimeInt(ini.getValue("Projectiles", "Count", ""), count)
        || count < 0
        || count > 100000
        || !parseRuntimeInt(
            ini.getValue("Projectiles", "NextActorId", ""),
            savedNextActorId
        )
        || savedNextActorId <= 0
        || savedNextActorId >= std::numeric_limits<int>::max()) {
        errorMessage = "invalid [Projectiles] header";
        return false;
    }

    std::vector<RuntimeProjectileEffect> restored;
    restored.reserve(static_cast<std::size_t>(count));
    std::unordered_set<int> actorIds;
    actorIds.reserve(static_cast<std::size_t>(count));
    int maximumReferencedActorId = 0;
    for (int index = 0; index < count; ++index) {
        RuntimeProjectileEffect projectile;
        if (!parseRuntimeProjectileEffect(
                ini.getValue("Projectiles", std::to_string(index), ""),
                projectile,
                schema
            )
            || !actorIds.insert(projectile.actorId).second) {
            errorMessage = "invalid [Projectiles] record "
                + std::to_string(index);
            return false;
        }
        maximumReferencedActorId = std::max(
            maximumReferencedActorId,
            projectile.actorId
        );
        if (projectile.parentActorId > 0) {
            maximumReferencedActorId = std::max(
                maximumReferencedActorId,
                projectile.parentActorId
            );
        }
        restored.push_back(std::move(projectile));
    }
    if (maximumReferencedActorId >= std::numeric_limits<int>::max() - 1) {
        errorMessage = "[Projectiles] actor id overflow";
        return false;
    }

    parsed.projectiles = std::move(restored);
    parsed.nextActorId = std::max(
        savedNextActorId,
        maximumReferencedActorId + 1
    );
    parsed.schema = schema;
    candidate = std::move(parsed);
    return true;
}

void commitRuntimeProjectilesFromSave(
    RuntimeWindowState& state,
    RuntimeProjectileSaveCandidate candidate
) {
    state.projectiles = std::move(candidate.projectiles);
    state.nextProjectileActorId = std::max(1, candidate.nextActorId);
    state.recentExpiredProjectiles.clear();
    state.impactEffects.clear();
    state.recentReplayEvents.clear();
    state.nextReplayEventSequence = 1;
    state.snapshotCache.replayEventSnapshotsDirty = true;
    state.actionSummary.projectilesInFlight =
        static_cast<int>(state.projectiles.size());
}

bool runtimeProjectileLaunchRegistrationValid(
    const RulesDatabase& rules,
    int sourceKind,
    const std::string& sourceType,
    bool authoredAircraft
) {
    const std::string type = trimAsciiLocal(sourceType);
    if (type.empty()) {
        return false;
    }
    if (sourceKind == static_cast<int>(WorldObjectKind::Structure)) {
        return !authoredAircraft
            && findRuntimeBuildingTypeById(rules, type) != nullptr;
    }
    if (sourceKind == static_cast<int>(WorldObjectKind::Infantry)) {
        return !authoredAircraft
            && rules.findUnitType("InfantryType", type) != nullptr;
    }
    if (sourceKind != static_cast<int>(WorldObjectKind::Unit)) {
        return false;
    }
    const bool exactVehicle =
        rules.findUnitType("UnitType", type) != nullptr;
    const bool exactAircraft =
        rules.findUnitType("AircraftType", type) != nullptr;
    // Authored aircraft carry an explicit save discriminator. A legacy Unit
    // record still cannot be guessed when the same id is registered in both
    // namespaces.
    return authoredAircraft ? exactAircraft : exactVehicle;
}

bool runtimeRestoreExactSavedObjectRegistration(
    const RulesDatabase& rules,
    WorldObjectInstance& object,
    bool namespaceIsExplicit = false
) {
    bool authoredAircraft = object.authoredAircraft;
    if (object.kind == WorldObjectKind::Structure) {
        if (authoredAircraft
            || findRuntimeBuildingTypeById(rules, object.type) == nullptr) {
            return false;
        }
    } else if (object.kind == WorldObjectKind::Infantry) {
        if (authoredAircraft
            || rules.findUnitType("InfantryType", object.type) == nullptr) {
            return false;
        }
    } else if (object.kind == WorldObjectKind::Unit) {
        const bool exactVehicle =
            rules.findUnitType("UnitType", object.type) != nullptr;
        const bool exactAircraft =
            rules.findUnitType("AircraftType", object.type) != nullptr;
        if (namespaceIsExplicit) {
            if (authoredAircraft ? !exactAircraft : !exactVehicle) {
                return false;
            }
        } else if (authoredAircraft) {
            if (!exactAircraft) {
                return false;
            }
        } else {
            if (exactVehicle == exactAircraft) {
                return false;
            }
            authoredAircraft = exactAircraft;
        }
    } else {
        return false;
    }
    object.authoredAircraft = authoredAircraft;
    return true;
}

bool runtimeProjectileLaunchIdentityForSavedObject(
    const RulesDatabase& rules,
    const WorldObjectInstance& object,
    int& sourceKind,
    std::string& sourceType,
    bool& authoredAircraft
) {
    WorldObjectInstance resolved = object;
    if (!runtimeRestoreExactSavedObjectRegistration(rules, resolved, true)) {
        return false;
    }
    sourceKind = static_cast<int>(resolved.kind);
    sourceType = resolved.type;
    authoredAircraft = resolved.authoredAircraft;
    return runtimeProjectileLaunchRegistrationValid(
        rules,
        sourceKind,
        sourceType,
        authoredAircraft
    );
}

bool validateAndCompleteRuntimeProjectileLaunchProvenance(
    const RuntimeWindowState& liveState,
    RuntimeProjectileSaveCandidate& candidate,
    const std::vector<WorldObjectInstance>& savedObjects,
    const RuntimeDeathWeaponSystemState& deathWeapons,
    std::string& errorMessage,
    const RuntimeAirstrikeSystemState* airstrikeAuthority = nullptr
) {
    std::unordered_map<int, const WorldObjectInstance*> objectsById;
    objectsById.reserve(savedObjects.size());
    for (const WorldObjectInstance& object : savedObjects) {
        objectsById.emplace(object.instanceId, &object);
    }
    std::unordered_map<int, RuntimeProjectileEffect*> projectilesByActor;
    projectilesByActor.reserve(candidate.projectiles.size());
    for (RuntimeProjectileEffect& projectile : candidate.projectiles) {
        projectilesByActor.emplace(projectile.actorId, &projectile);
    }
    std::unordered_map<std::uint64_t,
        const RuntimeDeathWeaponTriggeredObject*> deathByRequest;
    for (const RuntimeDeathWeaponTriggeredObject& triggered :
            deathWeapons.triggeredObjects()) {
        if (triggered.emittedRequestId > 0) {
            deathByRequest.emplace(triggered.emittedRequestId, &triggered);
        }
    }

    // A projectile actor is either a root or a strict, monotonic child.  The
    // actor-id ordering permits an already-expired parent to be absent while
    // still making cycles impossible.  When the parent remains in flight its
    // complete causal identity must agree before legacy provenance can be
    // inherited below.
    for (const RuntimeProjectileEffect& projectile : candidate.projectiles) {
        const bool root = projectile.parentActorId == -1;
        if (root != (projectile.generation == 0)
            || (!root
                && (projectile.parentActorId <= 0
                    || projectile.parentActorId >= projectile.actorId))) {
            errorMessage = "invalid projectile parent/generation identity";
            return false;
        }
        const auto parent = projectilesByActor.find(projectile.parentActorId);
        if (parent == projectilesByActor.end() || parent->second == nullptr) {
            continue;
        }
        if (projectile.attackerObjectId
                != parent->second->attackerObjectId
            || runtimeRepairDepotCanonicalOwnerId(
                    liveState,
                    projectile.owner
                ) != runtimeRepairDepotCanonicalOwnerId(
                    liveState,
                    parent->second->owner
                )
            || projectile.generation != parent->second->generation + 1) {
            errorMessage = "projectile child causal identity mismatch";
            return false;
        }
    }

    if (candidate.schema == runtimeProjectileSaveSchemaV1
        || candidate.schema == runtimeProjectileSaveSchemaV2) {
        for (RuntimeProjectileEffect& projectile : candidate.projectiles) {
            const auto activeParent = projectilesByActor.find(
                projectile.parentActorId
            );
            if (activeParent != projectilesByActor.end()
                && activeParent->second != nullptr) {
                continue;
            }
            const auto savedSource = objectsById.find(
                projectile.attackerObjectId
            );
            int sourceKind = -1;
            std::string sourceType;
            bool authoredAircraft = false;
            bool completed = savedSource != objectsById.end()
                && savedSource->second != nullptr
                && toLowerAsciiLocal(trimAsciiLocal(
                    savedSource->second->owner
                )) == toLowerAsciiLocal(trimAsciiLocal(projectile.owner))
                && runtimeProjectileLaunchIdentityForSavedObject(
                    liveState.rules,
                    *savedSource->second,
                    sourceKind,
                    sourceType,
                    authoredAircraft
                );
            if (!completed && projectile.deathWeaponRequestId > 0) {
                const auto triggered = deathByRequest.find(
                    projectile.deathWeaponRequestId
                );
                if (triggered != deathByRequest.end()
                    && triggered->second != nullptr
                    && triggered->second->objectId
                        == projectile.attackerObjectId) {
                    sourceKind = static_cast<int>(triggered->second->kind);
                    sourceType = triggered->second->type;
                    authoredAircraft = triggered->second->authoredAircraft;
                    completed = runtimeProjectileLaunchRegistrationValid(
                        liveState.rules,
                        sourceKind,
                        sourceType,
                        authoredAircraft
                    );
                }
            }
            if (completed) {
                projectile.launchSourceKind = sourceKind;
                projectile.launchSourceType = sourceType;
                projectile.launchSourceAuthoredAircraft = authoredAircraft;
                projectile.launchSourceValidated = true;
            }
        }
        bool inherited = true;
        while (inherited) {
            inherited = false;
            for (RuntimeProjectileEffect& projectile : candidate.projectiles) {
                if (projectile.launchSourceValidated
                    || projectile.parentActorId <= 0) {
                    continue;
                }
                const auto parent = projectilesByActor.find(
                    projectile.parentActorId
                );
                if (parent == projectilesByActor.end()
                    || parent->second == nullptr
                    || !parent->second->launchSourceValidated
                    || projectile.attackerObjectId
                        != parent->second->attackerObjectId
                    || runtimeRepairDepotCanonicalOwnerId(
                            liveState,
                            projectile.owner
                        ) != runtimeRepairDepotCanonicalOwnerId(
                            liveState,
                            parent->second->owner
                        )
                    || projectile.generation
                        != parent->second->generation + 1) {
                    continue;
                }
                projectile.launchSourceKind =
                    parent->second->launchSourceKind;
                projectile.launchSourceType =
                    parent->second->launchSourceType;
                projectile.launchSourceAuthoredAircraft =
                    parent->second->launchSourceAuthoredAircraft;
                projectile.launchSourceValidated = true;
                inherited = true;
            }
        }
    }

    for (const RuntimeProjectileEffect& projectile : candidate.projectiles) {
        if ((airstrikeAuthority == nullptr
                && (projectile.airstrikeStrikeId != 0
                    || projectile.airstrikePlaneToken != 0))
            || projectile.particleDamagePulse
            || projectile.suppressWarheadParticleSpawn) {
            errorMessage =
                "projectile producer provenance has no host authority";
            return false;
        }
        const auto parent = projectilesByActor.find(projectile.parentActorId);
        if (parent != projectilesByActor.end()
            && parent->second != nullptr
            && (projectile.attackerObjectId
                    != parent->second->attackerObjectId
                || runtimeRepairDepotCanonicalOwnerId(
                        liveState,
                        projectile.owner
                    ) != runtimeRepairDepotCanonicalOwnerId(
                        liveState,
                        parent->second->owner
                    )
                || projectile.generation
                    != parent->second->generation + 1
                || projectile.launchSourceKind
                    != parent->second->launchSourceKind
                || projectile.launchSourceAuthoredAircraft
                    != parent->second->launchSourceAuthoredAircraft
                || projectile.launchSourceValidated
                    != parent->second->launchSourceValidated
                || toLowerAsciiLocal(trimAsciiLocal(
                    projectile.launchSourceType
                )) != toLowerAsciiLocal(trimAsciiLocal(
                    parent->second->launchSourceType
                ))
                || projectile.airstrikeStrikeId
                    != parent->second->airstrikeStrikeId
                || projectile.airstrikePlaneToken
                    != parent->second->airstrikePlaneToken
                || projectile.particleDamagePulse
                    != parent->second->particleDamagePulse
                || projectile.suppressWarheadParticleSpawn
                    != parent->second->suppressWarheadParticleSpawn)) {
            errorMessage = "projectile child causal provenance mismatch";
            return false;
        }
        if (!projectile.launchSourceValidated) {
            continue;
        }
        if (!runtimeProjectileLaunchRegistrationValid(
                liveState.rules,
                projectile.launchSourceKind,
                projectile.launchSourceType,
                projectile.launchSourceAuthoredAircraft
            )) {
            errorMessage = "projectile launch source is not exactly registered";
            return false;
        }
        const auto savedSource = objectsById.find(
            projectile.attackerObjectId
        );
        if (savedSource != objectsById.end()
            && savedSource->second != nullptr) {
            int sourceKind = -1;
            std::string sourceType;
            bool authoredAircraft = false;
            if (!runtimeProjectileLaunchIdentityForSavedObject(
                    liveState.rules,
                    *savedSource->second,
                    sourceKind,
                    sourceType,
                    authoredAircraft
                )
                || sourceKind != projectile.launchSourceKind
                || authoredAircraft
                    != projectile.launchSourceAuthoredAircraft
                || toLowerAsciiLocal(trimAsciiLocal(sourceType))
                    != toLowerAsciiLocal(trimAsciiLocal(
                        projectile.launchSourceType
                    ))
                || toLowerAsciiLocal(trimAsciiLocal(
                    savedSource->second->owner
                )) != toLowerAsciiLocal(trimAsciiLocal(projectile.owner))) {
                errorMessage =
                    "projectile launch source mismatches saved object identity";
                return false;
            }
        }
    }
    return true;
}

bool runtimePsychicSourceRegistrationValid(
    const RulesDatabase& rules,
    RuntimePsychicObjectKind kind,
    const std::string& typeId
) {
    switch (kind) {
    case RuntimePsychicObjectKind::Infantry:
        return runtimeProjectileLaunchRegistrationValid(
            rules,
            static_cast<int>(WorldObjectKind::Infantry),
            typeId,
            false
        );
    case RuntimePsychicObjectKind::Vehicle:
        return runtimeProjectileLaunchRegistrationValid(
            rules,
            static_cast<int>(WorldObjectKind::Unit),
            typeId,
            false
        );
    case RuntimePsychicObjectKind::Structure:
        return runtimeProjectileLaunchRegistrationValid(
            rules,
            static_cast<int>(WorldObjectKind::Structure),
            typeId,
            false
        );
    case RuntimePsychicObjectKind::Aircraft:
        return runtimeProjectileLaunchRegistrationValid(
            rules,
            static_cast<int>(WorldObjectKind::Unit),
            typeId,
            true
        );
    case RuntimePsychicObjectKind::Other:
        return false;
    }
    return false;
}

bool validateRuntimeSavedPsychicStatuses(
    const RuntimeWindowState& liveState,
    RuntimePsychicStatusSystemState& candidate,
    const std::vector<WorldObjectInstance>& savedObjects,
    int savedTick,
    const RuntimeProjectileSaveCandidate& savedProjectiles,
    std::string& errorMessage
) {
    const auto sameText = [](const std::string& left,
                             const std::string& right) {
        return toLowerAsciiLocal(trimAsciiLocal(left))
            == toLowerAsciiLocal(trimAsciiLocal(right));
    };
    std::unordered_map<int, const WorldObjectInstance*> objectsById;
    objectsById.reserve(savedObjects.size());
    RuntimePsychicStatusReconcileInput reconcileInput;
    reconcileInput.currentTick = savedTick;
    reconcileInput.validateSources = true;
    reconcileInput.validateTargets = true;
    reconcileInput.objects.reserve(savedObjects.size());
    for (const WorldObjectInstance& object : savedObjects) {
        objectsById.emplace(object.instanceId, &object);
        reconcileInput.objects.push_back(
            runtimePsychicObjectSnapshot(liveState, object)
        );
    }
    std::unordered_set<std::uint64_t> inFlightProjectileActorIds;
    inFlightProjectileActorIds.reserve(savedProjectiles.projectiles.size());
    for (const RuntimeProjectileEffect& projectile :
            savedProjectiles.projectiles) {
        inFlightProjectileActorIds.insert(
            static_cast<std::uint64_t>(projectile.actorId)
        );
    }

    for (const RuntimePsychicStatusRecord& status : candidate.statuses()) {
        const WarheadType* warhead =
            liveState.rules.findWarheadType(status.warheadId);
        if (!status.sourceValidatedAtLaunch
            || warhead == nullptr
            || !warhead->psychedelic
            || !runtimePsychicSourceRegistrationValid(
                liveState.rules,
                status.sourceKind,
                status.sourceTypeId
            )
            || status.lastHitEventId == 0
            || status.lastHitEventId
                >= static_cast<std::uint64_t>(savedProjectiles.nextActorId)
            || status.startedTick > status.lastRefreshTick
            || status.lastRefreshTick > savedTick
            || savedTick >= status.expiresTick
            || static_cast<long long>(status.expiresTick)
                    - static_cast<long long>(status.lastRefreshTick)
                > 1000000LL) {
            errorMessage = "invalid persisted psychic status attribution";
            return false;
        }
        const auto target = objectsById.find(status.targetObjectId);
        if (target == objectsById.end() || target->second == nullptr) {
            errorMessage = "persisted psychic target is missing";
            return false;
        }
        const RuntimePsychicObjectSnapshot targetSnapshot =
            runtimePsychicObjectSnapshot(liveState, *target->second);
        if (targetSnapshot.kind != status.targetKind
            || !sameText(targetSnapshot.owner, status.targetOwner)
            || !sameText(targetSnapshot.typeId, status.targetTypeId)) {
            errorMessage = "persisted psychic target identity mismatch";
            return false;
        }
        const auto source = objectsById.find(status.sourceObjectId);
        if (source != objectsById.end() && source->second != nullptr) {
            const RuntimePsychicObjectSnapshot sourceSnapshot =
                runtimePsychicObjectSnapshot(liveState, *source->second);
            if (sourceSnapshot.kind != status.sourceKind
                || !sameText(sourceSnapshot.owner, status.sourceOwner)
                || !sameText(sourceSnapshot.typeId, status.sourceTypeId)) {
                errorMessage = "persisted psychic source identity mismatch";
                return false;
            }
        }
    }
    for (const RuntimePsychicStatusHitEventRecord& event :
            candidate.hitEvents()) {
        const WarheadType* warhead =
            liveState.rules.findWarheadType(event.warheadId);
        if (event.projectileActorId == 0
            || event.projectileActorId
                >= static_cast<std::uint64_t>(savedProjectiles.nextActorId)
            || event.acceptedTick > savedTick
            || inFlightProjectileActorIds.contains(
                event.projectileActorId
            )
            || warhead == nullptr
            || !warhead->psychedelic
            || !runtimePsychicSourceRegistrationValid(
                liveState.rules,
                event.sourceKind,
                event.sourceTypeId
            )) {
            errorMessage = "invalid persisted psychic hit receipt";
            return false;
        }
    }

    const RuntimePsychicStatusReconcileReport report =
        candidate.reconcileSavedWorld(
            reconcileInput,
            savedObjects.size()
        );
    if (report.inputRejected
        || report.actionLimitReached
        || report.ended != 0U
        || !report.sourceIdentityChangedStatusIds.empty()) {
        errorMessage = "persisted psychic state failed world reconciliation";
        return false;
    }
    return true;
}

bool runtimeSavedSectionReferencesActor(
    const IniFile& ini,
    const std::string& section,
    int objectId,
    bool& valid
) {
    valid = false;
    if (ini.getSection(section) == nullptr) {
        return false;
    }
    int count = -1;
    if (!parseRuntimeInt(ini.getValue(section, "Count", ""), count)
        || count < 0 || count > 100000) {
        return false;
    }
    valid = true;
    for (int index = 0; index < count; ++index) {
        const std::vector<std::string> tokens = splitRuntimeSaveFields(
            ini.getValue(section, std::to_string(index), "")
        );
        int actorId = -1;
        if (tokens.empty() || !parseRuntimeInt(tokens[0], actorId)) {
            valid = false;
            return false;
        }
        if (actorId == objectId) {
            return true;
        }
    }
    return false;
}

bool validateRuntimeSavedMagBeams(
    const RuntimeWindowState& liveState,
    const IniFile& ini,
    RuntimeMagBeamSystemState& candidate,
    const std::vector<WorldObjectInstance>& savedObjects,
    int savedTick,
    const RuntimeProjectileSaveCandidate& savedProjectiles,
    const RuntimeSpecialMechanismState& specialMechanisms,
    const RuntimeRepairDepotSystemState& repairDepots,
    const RuntimeFactoryDeliveryState& factoryDeliveries,
    const RuntimeAircraftServiceSystemState& aircraftServices,
    std::string& errorMessage
) {
    const auto sameText = [](const std::string& left,
                             const std::string& right) {
        return toLowerAsciiLocal(trimAsciiLocal(left))
            == toLowerAsciiLocal(trimAsciiLocal(right));
    };
    const auto sameDouble = [](double left, double right) {
        return std::abs(left - right) <= 1.0e-9;
    };
    const int lastAdvancedTick = candidate.lastAdvancedTick();
    if ((candidate.bindings().empty()
            && lastAdvancedTick != -1
            && lastAdvancedTick != savedTick)
        || (!candidate.bindings().empty()
            && lastAdvancedTick != savedTick)) {
        errorMessage = "RuntimeMagBeam tick does not match saved world";
        return false;
    }

    std::unordered_map<int, const WorldObjectInstance*> objectsById;
    objectsById.reserve(savedObjects.size());
    for (const WorldObjectInstance& object : savedObjects) {
        objectsById.emplace(object.instanceId, &object);
    }

    // A locomotor projectile is an exclusive mechanism even before impact.
    // Reject malformed mixed producers here rather than allowing a loaded
    // orphan bullet to silently choose a different consumer next tick.
    for (const RuntimeProjectileEffect& projectile :
            savedProjectiles.projectiles) {
        const WeaponType* weapon = liveState.rules.findWeaponType(
            projectile.weaponId
        );
        const WarheadType* warhead = liveState.rules.findWarheadType(
            projectile.warheadId
        );
        if (warhead == nullptr || !warhead->isLocomotor) {
            continue;
        }
        if (weapon == nullptr
            || !sameText(weapon->warhead, warhead->id)
            || warhead->psychedelic || warhead->parasite
            || warhead->airstrike || weapon->limboLaunch
            || projectile.particleDamagePulse
            || projectile.suppressWarheadParticleSpawn
            || !trimAsciiLocal(warhead->particle).empty()
            || !trimAsciiLocal(warhead->particleSystem).empty()) {
            errorMessage =
                "persisted locomotor projectile mixes exclusive mechanisms";
            return false;
        }
    }

    const SpecialMechanismRules& rules =
        liveState.rules.getSpecialMechanismRules();
    std::unordered_set<int> bindingTargetIds;
    bindingTargetIds.reserve(candidate.bindings().size());
    for (const RuntimeMagBeamBindingState& binding : candidate.bindings()) {
        if (!bindingTargetIds.insert(binding.targetObjectId).second) {
            errorMessage = "RuntimeMagBeam has duplicate target authority";
            return false;
        }
        const auto targetIt = objectsById.find(binding.targetObjectId);
        if (targetIt == objectsById.end() || targetIt->second == nullptr) {
            errorMessage = "RuntimeMagBeam target is missing";
            return false;
        }
        const WorldObjectInstance& target = *targetIt->second;
        const UnitType* targetRules = nullptr;
        const RuntimeMagBeamTargetKind targetKind =
            runtimeMagBeamTargetKindForObject(
                liveState,
                target,
                targetRules
            );
        if (!target.alive || target.health <= 0 || targetRules == nullptr
            || targetKind != binding.targetKind
            || !sameText(target.owner, binding.targetOwner)
            || !sameText(target.type, binding.targetTypeId)
            || !sameText(target.mission, "MagBeamSuspended")
            || target.submerged
            || target.dockedToObjectId >= 0 || target.dockIndex >= 0
            || target.x != binding.kinematics.location.x
            || target.y != binding.kinematics.location.y
            || target.cell != binding.kinematics.location.cell
            || target.cell != runtimeCellKey(target.x, target.y)
            || target.level != binding.kinematics.location.level
            || target.onBridge != binding.kinematics.location.onBridge
            || runtimeMaxHealthForObject(liveState, target)
                != binding.targetMaximumStrength
            || targetRules->suppressionThreshold
                != binding.targetSuppressionThreshold
            || !sameDouble(targetRules->weight, binding.targetWeight)
            || !binding.originalLocomotorKnown
            || !sameText(
                targetRules->locomotor,
                binding.originalLocomotorId
            )) {
            errorMessage =
                "RuntimeMagBeam target world/rules identity mismatch";
            return false;
        }

        const MapCellFacts* cellFacts = runtimeMapQueryCell(
            liveState,
            {target.x, target.y}
        );
        constexpr std::int64_t q16One = 1LL << 16U;
        const std::int64_t worldXQ16 = static_cast<std::int64_t>(
            std::llround(binding.kinematics.worldX * q16One)
        );
        const std::int64_t worldYQ16 = static_cast<std::int64_t>(
            std::llround(binding.kinematics.worldY * q16One)
        );
        const std::int64_t worldZQ16 = static_cast<std::int64_t>(
            std::llround(binding.kinematics.worldZ * q16One)
        );
        const std::int64_t groundQ16 =
            static_cast<std::int64_t>(target.level) * q16One;
        const bool expectedOffGround = worldZQ16
            > groundQ16 + (q16One / 256);
        if (cellFacts == nullptr
            || static_cast<int>(std::llround(
                static_cast<double>(worldXQ16) / q16One
            )) != target.x
            || static_cast<int>(std::llround(
                static_cast<double>(worldYQ16) / q16One
            )) != target.y
            || terrainLevelAtRuntimeCell(liveState, target.x, target.y)
                != target.level
            || runtimeCellIsBridge(liveState, target.x, target.y)
                != binding.kinematics.location.onBridge
            || cellFacts->isWater != binding.kinematics.location.water
            || target.airborne != expectedOffGround
            || target.flightLevel != (expectedOffGround
                ? static_cast<int>(std::llround(
                    binding.kinematics.worldZ
                ))
                : target.level)
            || worldZQ16 < groundQ16) {
            errorMessage = "RuntimeMagBeam kinematics mismatch saved map"
                " phase="
                + std::string(runtimeMagBeamPhaseName(binding.phase))
                + " source=" + std::to_string(binding.sourceObjectId)
                + " target=" + std::to_string(binding.targetObjectId)
                + " q16=" + std::to_string(worldXQ16) + ","
                + std::to_string(worldYQ16) + ","
                + std::to_string(worldZQ16)
                + " location="
                + std::to_string(binding.kinematics.location.x) + ","
                + std::to_string(binding.kinematics.location.y) + ","
                + std::to_string(binding.kinematics.location.level)
                + "/" + runtimeBoolText(
                    binding.kinematics.location.onBridge
                )
                + "/" + runtimeBoolText(
                    binding.kinematics.location.water
                )
                + " object=" + std::to_string(target.x) + ","
                + std::to_string(target.y) + ","
                + std::to_string(target.level)
                + "/air=" + runtimeBoolText(target.airborne)
                + "/flight=" + std::to_string(target.flightLevel)
                + "/render=" + runtimeBoolText(target.hasRenderPosition)
                + "," + std::to_string(target.renderX)
                + "," + std::to_string(target.renderY)
                + "," + std::to_string(target.renderLevel)
                + " map=" + runtimeBoolText(cellFacts != nullptr)
                + "/terrain=" + std::to_string(
                    terrainLevelAtRuntimeCell(liveState, target.x, target.y)
                )
                + "/bridge=" + runtimeBoolText(
                    runtimeCellIsBridge(liveState, target.x, target.y)
                )
                + "/water=" + (cellFacts == nullptr
                    ? std::string("missing")
                    : runtimeBoolText(cellFacts->isWater))
                + "/offGround=" + runtimeBoolText(expectedOffGround)
                + "/groundQ16=" + std::to_string(groundQ16);
            return false;
        }

        const WeaponType* weapon = liveState.rules.findWeaponType(
            binding.weaponId
        );
        const WarheadType* warhead = liveState.rules.findWarheadType(
            binding.warheadId
        );
        if (weapon == nullptr || warhead == nullptr
            || !sameText(weapon->warhead, warhead->id)
            || !warhead->isLocomotor
            || !sameText(warhead->locomotor, binding.locomotorId)
            || weapon->damage != binding.rawDamage
            || weapon->magBeam != binding.magBeamVisual
            || !(static_cast<double>(weapon->damage) > targetRules->weight)
            || warhead->psychedelic || warhead->parasite
            || warhead->airstrike || weapon->limboLaunch
            || !trimAsciiLocal(warhead->particle).empty()
            || !trimAsciiLocal(warhead->particleSystem).empty()
            || !sameDouble(
                binding.fallingDamageMultiplier,
                rules.fallingDamageMultiplier
            )
            || binding.currentStrengthDamage
                != rules.currentStrengthDamage) {
            errorMessage = "RuntimeMagBeam weapon/rules mismatch";
            return false;
        }

        if (binding.phase != RuntimeMagBeamPhase::Falling) {
            const auto sourceIt = objectsById.find(binding.sourceObjectId);
            if (sourceIt == objectsById.end() || sourceIt->second == nullptr
                || !sourceIt->second->alive
                || sourceIt->second->health <= 0
                || !sameText(sourceIt->second->owner, binding.sourceOwner)
                || !sameText(sourceIt->second->type, binding.sourceTypeId)) {
                errorMessage = "RuntimeMagBeam live source identity mismatch";
                return false;
            }
        }

        bool sectionValid = false;
        for (const std::string& section : {
                std::string("Behaviors"),
                std::string("SubcellReservations"),
                std::string("EngineerIntents"),
                std::string("OccupyIntents"),
                std::string("TransportIntents"),
                std::string("TimedBombIntents")}) {
            const bool referenced = runtimeSavedSectionReferencesActor(
                ini,
                section,
                binding.targetObjectId,
                sectionValid
            );
            if (!sectionValid || referenced) {
                errorMessage =
                    "RuntimeMagBeam target retains competing saved intent";
                return false;
            }
        }
        if (std::any_of(
                repairDepots.relations().begin(),
                repairDepots.relations().end(),
                [&binding](const RuntimeRepairDepotRelation& relation) {
                    return relation.unitId == binding.targetObjectId;
                }
            )
            || std::any_of(
                factoryDeliveries.leases().begin(),
                factoryDeliveries.leases().end(),
                [&binding](const RuntimeFactoryDeliveryLease& lease) {
                    return lease.producedObjectId == binding.targetObjectId;
                }
            )
            || std::any_of(
                aircraftServices.dockBindings().begin(),
                aircraftServices.dockBindings().end(),
                [&binding](
                    const RuntimeAircraftServiceDockBinding& dock
                ) {
                    return dock.aircraftId == binding.targetObjectId;
                }
            )
            || specialMechanisms.isChronoInTransit(binding.targetObjectId)
            || specialMechanisms.isTemporalFrozen(binding.targetObjectId)
            || specialMechanisms.parasiteLinks().contains(
                binding.targetObjectId
            )
            || specialMechanisms.isCarrierChild(binding.targetObjectId)) {
            errorMessage =
                "RuntimeMagBeam target retains competing runtime authority";
            return false;
        }
    }
    for (const WorldObjectInstance& object : savedObjects) {
        const bool suspended = sameText(
            object.mission,
            "MagBeamSuspended"
        );
        if (suspended != bindingTargetIds.contains(object.instanceId)) {
            errorMessage =
                "RuntimeMagBeam target mission/authority is not bidirectional";
            return false;
        }
    }

    return true;
}

bool restoreRuntimeGattlingTimersFromSave(
    RuntimeWindowState& state,
    const IniFile& ini,
    std::string& errorMessage,
    int saveVersion = 0
) {
    state.gattlingWeaponTimers.clear();
    if (ini.getSection("GattlingWeaponTimers") == nullptr) {
        return true;
    }

    int schema = 0;
    int count = 0;
    if (!parseRuntimeInt(
            ini.getValue("GattlingWeaponTimers", "Schema", ""),
            schema
        )
        || schema != 1
        || !parseRuntimeInt(
            ini.getValue("GattlingWeaponTimers", "Count", ""),
            count
        )
        || count < 0
        || count > 100000) {
        errorMessage = "invalid [GattlingWeaponTimers] header";
        return false;
    }

    std::unordered_set<int> seenObjectIds;
    for (int index = 0; index < count; ++index) {
        const std::vector<std::string> tokens = splitRuntimeSaveFields(
            ini.getValue(
                "GattlingWeaponTimers",
                std::to_string(index),
                ""
            )
        );
        int objectId = -1;
        int timer = 0;
        if (tokens.size() != 2U
            || !parseRuntimeInt(tokens[0], objectId)
            || !parseRuntimeInt(tokens[1], timer)
            || objectId < 0
            || !seenObjectIds.insert(objectId).second) {
            errorMessage = "invalid [GattlingWeaponTimers] record "
                + std::to_string(index);
            return false;
        }
        const WorldObjectInstance* object = findObjectById(state, objectId);
        if (object == nullptr || !object->alive) {
            if (saveVersion >= 13) {
                errorMessage =
                    "v13 gattling timer references unavailable object";
                return false;
            }
            continue;
        }
        const RuntimeCachedCapabilityProfile& cached =
            runtimeCachedCapabilityProfileForObject(state, *object);
        if (!cached.gattling) {
            if (saveVersion >= 13) {
                errorMessage =
                    "v13 gattling timer references non-gattling object";
                return false;
            }
            continue;
        }
        const int timerCap = runtimeGattlingTimerCap(
            cached,
            object->veterancy >= 2
        );
        if (saveVersion >= 13 && (timer < 0 || timer > timerCap)) {
            errorMessage = "v13 gattling timer is outside authored range";
            return false;
        }
        timer = std::clamp(
            timer,
            0,
            timerCap
        );
        if (timer > 0) {
            state.gattlingWeaponTimers.emplace(objectId, timer);
        }
    }
    return true;
}

std::string runtimeCrateArtImageId(
    const RulesDatabase& rules,
    const std::string& overlayTypeId
) {
    const std::string requested = trimAsciiLocal(overlayTypeId);
    if (requested.empty()) {
        return {};
    }
    const std::string requestedKey = toLowerAsciiLocal(requested);
    const auto& overlays = rules.getOverlayTypes();
    const auto found = std::find_if(
        overlays.begin(),
        overlays.end(),
        [&requestedKey](const OverlayType& overlay) {
            return toLowerAsciiLocal(trimAsciiLocal(overlay.id))
                == requestedKey;
        }
    );
    if (found == overlays.end()) {
        return requested;
    }
    const std::string image = trimAsciiLocal(found->image);
    return image.empty() ? requested : image;
}

#include "simulation/buildings/RuntimeBuildingRevealSave.inl"
#include "simulation/combat/damage/RuntimeWreckSave.inl"
#include "simulation/buildings/RuntimeBuildingCollapseSave.inl"

bool restoreRuntimeCratesFromSave(
    RuntimeWindowState& state,
    const IniFile& ini,
    std::string& errorMessage
) {
    if (ini.getSection("Crates") == nullptr) {
        state.skirmishCrates = state.campaignMode
            ? std::vector<RuntimeCrateState>{}
            : state.initialSkirmishCrates;
        return true;
    }

    int schema = 0;
    int count = 0;
    if (!parseRuntimeInt(ini.getValue("Crates", "Schema", ""), schema)
        || (schema != 1 && schema != 2 && schema != 3 && schema != 4)
        || !parseRuntimeInt(ini.getValue("Crates", "Count", ""), count)
        || count < 0
        || count > 100000) {
        errorMessage = "invalid [Crates] header";
        return false;
    }

    std::vector<RuntimeCrateState> restored;
    restored.reserve(static_cast<std::size_t>(count));
    for (int index = 0; index < count; ++index) {
        const std::vector<std::string> tokens = splitRuntimeSaveFields(
            ini.getValue("Crates", std::to_string(index), "")
        );
        RuntimeCrateState crate;
        const std::size_t expectedFields = schema == 1
            ? 5U
            : (schema == 2 ? 9U : (schema == 3 ? 10U : 11U));
        if (tokens.size() != expectedFields
            || !parseRuntimeInt(tokens[0], crate.cell.x)
            || !parseRuntimeInt(tokens[1], crate.cell.y)
            || !parseRuntimeStrictBool(tokens[2], crate.active)
            || !parseRuntimeInt(tokens[3], crate.respawnTick)
            || !parseRuntimeInt(tokens[4], crate.value)
            || crate.respawnTick < 0
            || crate.value < 0
            || (!state.terrainByCell.empty()
                && state.terrainByCell.find(
                    runtimeCellKey(crate.cell.x, crate.cell.y)
                ) == state.terrainByCell.end())) {
            errorMessage = "invalid [Crates] record "
                + std::to_string(index);
            return false;
        }
        if (schema >= 2) {
            if (!parseRuntimeStrictBool(tokens[5], crate.water)
                || !parseRuntimeFiniteDouble(tokens[8], crate.powerupData)
                || crate.powerupData < -runtimeCratePowerupDataLimit
                || crate.powerupData > runtimeCratePowerupDataLimit) {
                errorMessage = "invalid [Crates] powerup record "
                    + std::to_string(index);
                return false;
            }
            crate.powerupType = trimAsciiLocal(tokens[6]);
            crate.powerupAnimation = trimAsciiLocal(tokens[7]);
            if (schema >= 3) {
                crate.imageId = trimAsciiLocal(tokens[9]);
                if (schema >= 4 && !parseRuntimeStrictBool(tokens[10], crate.authored)) {
                    errorMessage = "invalid [Crates] authored record " + std::to_string(index);
                    return false;
                }
            } else {
                crate.imageId = runtimeCrateArtImageId(
                    state.rules,
                    crate.water
                        ? state.rules.getCrateRules().waterImage
                        : state.rules.getCrateRules().image
                );
            }
        } else {
            const auto terrain = state.terrainInfoByCell.find(
                runtimeCellKey(crate.cell.x, crate.cell.y)
            );
            crate.water = terrain != state.terrainInfoByCell.end()
                && terrain->second.water
                && !terrain->second.bridge;
            crate.imageId = runtimeCrateArtImageId(
                state.rules,
                crate.water
                    ? state.rules.getCrateRules().waterImage
                    : state.rules.getCrateRules().image
            );
        }
        if (schema < 4) crate.authored = state.campaignMode || crate.respawnTick == 0;
        restored.push_back(crate);
    }
    if (schema >= 4 && (!parseRuntimeStrictBool(ini.getValue("Crates", "TruckCrate", ""), state.triggers.truckCrate)
        || !parseRuntimeStrictBool(ini.getValue("Crates", "TrainCrate", ""), state.triggers.trainCrate))) {
        errorMessage = "invalid [Crates] map switches";
        return false;
    }
    state.skirmishCrates = std::move(restored);
    return true;
}

bool restoreRuntimeSmudgesFromSave(
    RuntimeWindowState& state,
    const IniFile& ini,
    std::string& errorMessage
) {
    if (ini.getSection("Smudges") == nullptr) {
        // Legacy saves inherit the map-authored collection.
        return true;
    }

    int schema = 0;
    int count = 0;
    if (!parseRuntimeInt(ini.getValue("Smudges", "Schema", ""), schema)
        || (schema != 1 && schema != 2)
        || !parseRuntimeInt(ini.getValue("Smudges", "Count", ""), count)
        || count < 0
        || count > 100000) {
        errorMessage = "invalid [Smudges] header";
        return false;
    }

    std::vector<WorldSmudge> restored;
    restored.reserve(static_cast<std::size_t>(count));
    std::unordered_map<int, bool> occupiedCells;
    for (int index = 0; index < count; ++index) {
        const std::vector<std::string> tokens = splitRuntimeSaveFields(
            ini.getValue("Smudges", std::to_string(index), "")
        );
        WorldSmudge smudge;
        if (tokens.size() != (schema == 2 ? 8U : 7U)
            || !parseRuntimeInt(tokens[2], smudge.x)
            || !parseRuntimeInt(tokens[3], smudge.y)
            || !parseRuntimeInt(tokens[4], smudge.cell)
            || !parseRuntimeInt(tokens[5], smudge.level)
            || !parseRuntimeInt(tokens[6], smudge.data)) {
            errorMessage = "invalid [Smudges] record "
                + std::to_string(index);
            return false;
        }
        smudge.mapId = trimAsciiLocal(tokens[0]);
        smudge.type = trimAsciiLocal(tokens[1]);
        if (schema == 2) {
            const std::string source = toLowerAsciiLocal(
                trimAsciiLocal(tokens[7])
            );
            if (source != "yes" && source != "no"
                && source != "true" && source != "false"
                && source != "1" && source != "0") {
                errorMessage = "invalid [Smudges] source "
                    + std::to_string(index);
                return false;
            }
            smudge.authored = source == "yes"
                || source == "true"
                || source == "1";
        } else {
            smudge.authored = toLowerAsciiLocal(smudge.mapId).rfind(
                "runtime:",
                0
            ) != 0;
        }
        const int expectedCell = runtimeCellKey(smudge.x, smudge.y);
        const auto terrain = state.terrainByCell.find(expectedCell);
        const std::string wantedType = toUpperAsciiLocal(smudge.type);
        const auto smudgeType = std::find_if(
            state.rules.getSmudgeTypes().begin(),
            state.rules.getSmudgeTypes().end(),
            [&wantedType](const SmudgeType& candidate) {
                return toUpperAsciiLocal(trimAsciiLocal(candidate.id))
                    == wantedType;
            }
        );
        if (smudge.type.empty()
            || expectedCell < 0
            || smudge.cell != expectedCell
            || smudge.data != 0
            || smudgeType == state.rules.getSmudgeTypes().end()
            || terrain == state.terrainByCell.end()
            || terrain->second == nullptr
            || smudge.level != terrain->second->level) {
            errorMessage = "invalid [Smudges] value "
                + std::to_string(index);
            return false;
        }
        const int width = std::max(1, smudgeType->width);
        const int height = std::max(1, smudgeType->height);
        for (int dy = 0; dy < height; ++dy) {
            for (int dx = 0; dx < width; ++dx) {
                const int footprintCell = runtimeCellKey(
                    smudge.x + dx,
                    smudge.y + dy
                );
                const auto footprintTerrain = state.terrainByCell.find(
                    footprintCell
                );
                const auto occupied = occupiedCells.find(footprintCell);
                const bool overlapAllowed = occupied != occupiedCells.end()
                    && occupied->second
                    && smudge.authored;
                if (footprintCell < 0
                    || footprintTerrain == state.terrainByCell.end()
                    || footprintTerrain->second == nullptr
                    || footprintTerrain->second->level != smudge.level
                    || (occupied != occupiedCells.end() && !overlapAllowed)) {
                    errorMessage = "invalid [Smudges] footprint "
                        + std::to_string(index);
                    return false;
                }
                if (occupied == occupiedCells.end()) {
                    occupiedCells.emplace(footprintCell, smudge.authored);
                }
            }
        }
        restored.push_back(std::move(smudge));
    }
    state.world.accessSmudges() = std::move(restored);
    state.repaintRequested = true;
    return true;
}

void restoreRuntimeTerrainObjectsFromSave(
    RuntimeWindowState& state,
    const IniFile& ini
) {
    captureRuntimeInitialTerrainObjectState(state);
    std::vector<WorldTerrainObject>& terrainObjects =
        state.world.accessTerrainObjects();
    for (std::size_t index = 0; index < terrainObjects.size(); ++index) {
        WorldTerrainObject& object = terrainObjects[index];
        const auto initial = state.terrainObjectInitialStateByKey.find(
            runtimeTerrainObjectStateKey(object, index)
        );
        if (initial == state.terrainObjectInitialStateByKey.end()) {
            const int maximumHealth = std::max(1, object.strength);
            object.health = std::clamp(object.health, 0, maximumHealth);
            object.alive = object.alive && object.health > 0;
        } else {
            object.health = initial->second.health;
            object.alive = initial->second.alive;
        }
        if (!object.alive) {
            object.health = 0;
        }
    }

    if (ini.getSection("TerrainObjects") != nullptr) {
        std::unordered_map<std::string, WorldTerrainObject*> objectsByKey;
        objectsByKey.reserve(terrainObjects.size());
        for (std::size_t index = 0; index < terrainObjects.size(); ++index) {
            objectsByKey.emplace(
                runtimeTerrainObjectStateKey(terrainObjects[index], index),
                &terrainObjects[index]
            );
        }
        const int count = std::max(
            0,
            parseRuntimeIntOrDefault(
                ini.getValue("TerrainObjects", "Count", "0"),
                0
            )
        );
        for (int index = 0; index < count; ++index) {
            const std::vector<std::string> tokens = splitRuntimeSaveFields(
                ini.getValue(
                    "TerrainObjects",
                    std::to_string(index),
                    ""
                )
            );
            if (tokens.size() < 6) {
                continue;
            }
            const auto found = objectsByKey.find(tokens[0]);
            if (found == objectsByKey.end() || found->second == nullptr) {
                continue;
            }
            WorldTerrainObject& object = *found->second;
            if (toLowerAsciiLocal(trimAsciiLocal(object.type))
                    != toLowerAsciiLocal(trimAsciiLocal(tokens[1]))
                || object.x != parseRuntimeIntOrDefault(tokens[2], -1)
                || object.y != parseRuntimeIntOrDefault(tokens[3], -1)) {
                continue;
            }
            const int maximumHealth = std::max(1, object.strength);
            object.health = std::clamp(
                parseRuntimeIntOrDefault(tokens[4], object.health),
                0,
                maximumHealth
            );
            object.alive = parseRuntimeBool(tokens[5])
                && object.health > 0;
            if (!object.alive) {
                object.health = 0;
            }
        }
    }

    state.attackApproachCache.clear();
    state.pathFailureCache.clear();
    state.placementChecksCacheTick = -1;
    invalidateRuntimeTickOccupancyCache(state);
    invalidateRuntimeObjectProjectionCache(state);
    state.navigationRefreshPending = true;
    state.radarTerrainKey.clear();
    state.repaintRequested = true;
}

#include "simulation/combat/damage/RuntimeOverlayWallSave.inl"

bool materializeRuntimeSavedTerrainProjection(
    RuntimeWindowState& state,
    const IniFile& ini,
    std::string& errorMessage
) {
    if (!resetRuntimeOverlayWallsForSavedProjection(state, errorMessage)) return false;
    const int resourceOverlayCount = parseRuntimeIntOrDefault(
        ini.getValue("ResourceOverlays", "Count", "-1"),
        -1
    );
    const std::string initialOreSeededRaw = trimAsciiLocal(
        ini.getValue("RuntimeSave", "InitialOreFieldsSeeded", "")
    );
    state.initialOreFieldsSeeded = !initialOreSeededRaw.empty()
        ? parseRuntimeBool(initialOreSeededRaw)
        : resourceOverlayCount >= 0;
    state.initialOreCellsSeeded = parseRuntimeIntOrDefault(
        ini.getValue("RuntimeSave", "InitialOreCellsSeeded", "0"),
        0
    );
    state.initialOreCellsDensified = parseRuntimeIntOrDefault(
        ini.getValue("RuntimeSave", "InitialOreCellsDensified", "0"),
        0
    );
    if (resourceOverlayCount >= 0) {
        for (TerrainCell& terrain : state.world.accessTerrainCells()) {
            if (!terrain.overlayIsOre && !terrain.overlayIsGem) {
                continue;
            }
            terrain.hasOverlay = false;
            terrain.overlayIndex = -1;
            terrain.overlayFrame = 0;
            terrain.overlayType.clear();
            terrain.overlayImage.clear();
            terrain.overlayIsOre = false;
            terrain.overlayIsGem = false;
        }

        std::unordered_map<int, TerrainCell*> terrainByCell;
        terrainByCell.reserve(state.world.accessTerrainCells().size());
        for (TerrainCell& terrain : state.world.accessTerrainCells()) {
            terrainByCell[runtimeCellKey(terrain.x, terrain.y)] = &terrain;
        }
        for (int index = 0; index < resourceOverlayCount; ++index) {
            const std::vector<std::string> tokens = splitRuntimeSaveFields(
                ini.getValue("ResourceOverlays", std::to_string(index), "")
            );
            if (tokens.size() < 8U) {
                continue;
            }
            const int x = parseRuntimeIntOrDefault(tokens[0], -1);
            const int y = parseRuntimeIntOrDefault(tokens[1], -1);
            const auto terrainIt = terrainByCell.find(runtimeCellKey(x, y));
            if (terrainIt == terrainByCell.end()
                || terrainIt->second == nullptr) {
                continue;
            }
            TerrainCell& terrain = *terrainIt->second;
            terrain.hasOverlay = true;
            terrain.overlayIndex = parseRuntimeIntOrDefault(tokens[2], -1);
            terrain.overlayFrame = parseRuntimeIntOrDefault(tokens[3], 0);
            terrain.overlayType = tokens[4];
            terrain.overlayImage = tokens[5];
            terrain.overlayIsOre = parseRuntimeBool(tokens[6]);
            terrain.overlayIsGem = parseRuntimeBool(tokens[7]);
        }
    }

    const int bridgeOverlayCount = parseRuntimeIntOrDefault(
        ini.getValue("BridgeOverlays", "Count", "-1"),
        -1
    );
    if (bridgeOverlayCount >= 0) {
        for (TerrainCell& terrain : state.world.accessTerrainCells()) {
            if (!terrain.hasOverlay || !runtimeOverlayLooksBridge(terrain)) {
                continue;
            }
            terrain.hasOverlay = false;
            terrain.overlayIndex = -1;
            terrain.overlayFrame = 0;
            terrain.overlayType.clear();
            terrain.overlayImage.clear();
            terrain.overlayIsOre = false;
            terrain.overlayIsGem = false;
        }

        std::unordered_map<int, TerrainCell*> terrainByCell;
        terrainByCell.reserve(state.world.accessTerrainCells().size());
        for (TerrainCell& terrain : state.world.accessTerrainCells()) {
            terrainByCell[runtimeCellKey(terrain.x, terrain.y)] = &terrain;
        }
        for (int index = 0; index < bridgeOverlayCount; ++index) {
            const std::vector<std::string> tokens = splitRuntimeSaveFields(
                ini.getValue("BridgeOverlays", std::to_string(index), "")
            );
            if (tokens.size() < 8U) {
                continue;
            }
            const int x = parseRuntimeIntOrDefault(tokens[0], -1);
            const int y = parseRuntimeIntOrDefault(tokens[1], -1);
            const auto terrainIt = terrainByCell.find(runtimeCellKey(x, y));
            if (terrainIt == terrainByCell.end()
                || terrainIt->second == nullptr) {
                continue;
            }
            TerrainCell& terrain = *terrainIt->second;
            terrain.hasOverlay = true;
            terrain.overlayIndex = parseRuntimeIntOrDefault(tokens[2], -1);
            terrain.overlayFrame = parseRuntimeIntOrDefault(tokens[3], 0);
            terrain.overlayType = tokens[4];
            terrain.overlayImage = tokens[5];
            terrain.overlayIsOre = parseRuntimeBool(tokens[6]);
            terrain.overlayIsGem = parseRuntimeBool(tokens[7]);
        }
    }

    state.bridgeHealthByCell.clear();
    const int bridgeHealthCount = parseRuntimeIntOrDefault(
        ini.getValue("BridgeHealth", "Count", "0"),
        0
    );
    for (int index = 0; index < bridgeHealthCount; ++index) {
        const std::vector<std::string> tokens = splitRuntimeSaveFields(
            ini.getValue("BridgeHealth", std::to_string(index), "")
        );
        if (tokens.size() < 2U) {
            continue;
        }
        const int cellKey = parseRuntimeIntOrDefault(tokens[0], -1);
        if (cellKey < 0) {
            continue;
        }
        state.bridgeHealthByCell[cellKey] = std::max(
            0,
            parseRuntimeIntOrDefault(tokens[1], 0)
        );
    }

    if (!restoreRuntimeOverlayWallStates(state, ini, errorMessage)) return false;
    restoreRuntimeTerrainObjectsFromSave(state, ini);
    state.terrainByCell = buildRuntimeTerrainLookup(state.world);
    rebuildRuntimeTerrainInfoCache(state);
    return restoreRuntimeSmudgesFromSave(state, ini, errorMessage);
}

