        runtimeMultiplayerAuthoritativeMixBool(nodeHash, capability.canRetaliate);
        runtimeStableHashMix(nodeHash, capability.speed);
        mixId(capability.speedType);
        mixId(capability.movementZone);
        mixId(capability.locomotor);
        mixId(capability.category);

        const WeaponSet& weaponSet = node.weaponSet;
        mixId(weaponSet.primary);
        mixId(weaponSet.secondary);
        mixId(weaponSet.elitePrimary);
        mixId(weaponSet.eliteSecondary);
        mixId(weaponSet.deploy);
        mixId(weaponSet.eliteDeploy);
        mixId(weaponSet.occupy);
        mixId(weaponSet.eliteOccupy);
        runtimeStableHashMix(nodeHash, weaponSet.openTransportWeapon);
        runtimeStableHashMix(nodeHash, weaponSet.indexedWeaponCount);
        mixIdentifierSequence(nodeHash, weaponSet.indexedWeapons);
        mixIdentifierSequence(nodeHash, weaponSet.eliteIndexedWeapons);

        const DeployProfile& deploy = node.deployProfile;
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, deploy.canDeploy);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, deploy.deployer);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, deploy.deployFire);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, deploy.deployToFire);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, deploy.isSimpleDeployer);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, deploy.noMovingFire);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, deploy.deployToLand);
