        const BuildingCapability& building = node.buildingCapability;
        runtimeStableHashMix(nodeHash, building.power);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.powered);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.factory);
        runtimeMultiplayerAuthoritativeMixBool(
            nodeHash,
            building.constructionYard
        );
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.refinery);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.barracksFactory);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.vehicleFactory);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.aircraftFactory);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.navalFactory);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.weaponsFactory);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.factoryPlant);
        runtimeMultiplayerAuthoritativeMixDouble(
            nodeHash,
            building.infantryCostBonus
        );
        runtimeMultiplayerAuthoritativeMixDouble(nodeHash, building.unitsCostBonus);
        runtimeMultiplayerAuthoritativeMixDouble(
            nodeHash,
            building.aircraftCostBonus
        );
        runtimeMultiplayerAuthoritativeMixDouble(
            nodeHash,
            building.buildingsCostBonus
        );
        runtimeMultiplayerAuthoritativeMixDouble(
            nodeHash,
            building.defensesCostBonus
        );
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.unitRepair);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.hospital);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.armory);
        runtimeStableHashMix(nodeHash, building.ammo);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.cloning);
        runtimeStableHashMix(nodeHash, building.infantryGainSelfHeal);
        runtimeStableHashMix(nodeHash, building.unitsGainSelfHeal);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.gapGenerator);
        runtimeStableHashMix(nodeHash, building.gapRadiusInCells);
        runtimeStableHashMix(nodeHash, building.superGapRadiusInCells);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.secretLab);
        mixIdentifierVector(nodeHash, building.secretInfantry);
