        runtimeStableHashMix(nodeHash, building.produceCashStartup);
        runtimeStableHashMix(nodeHash, building.produceCashAmount);
        runtimeStableHashMix(nodeHash, building.produceCashDelay);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.grinding);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.bunker);
        runtimeMultiplayerAuthoritativeMixBool(nodeHash, building.infantryAbsorb);
        runtimeStableHashMix(nodeHash, building.passengers);
