std::string buildRuntimeSoundIntentLine(
    const RuntimeWindowState& state
) {
    bool hasSemanticSidebarIntent = false;
    bool hasPlayableSemanticSample = false;
    bool hasPlayableEvaSample = false;
    int evaEvents = 0;
    int evaPlayableEvents = 0;
    std::string lastSemanticIntent;
    std::string lastSemanticSample;
    std::string lastSemanticStatus;
    for (const std::string& intent : state.runtimeSoundIntentHistory) {
        hasSemanticSidebarIntent =
            hasSemanticSidebarIntent
            || isRuntimeSemanticSidebarSoundIntent(intent);
    }
    for (const RuntimeSoundPlaybackRecord& record :
        state.runtimeSoundPlaybackHistory) {
        if (record.eva) {
            ++evaEvents;
            if (record.playable) {
                ++evaPlayableEvents;
                hasPlayableEvaSample = true;
            }
        }
        if (record.semantic) {
            hasPlayableSemanticSample =
                hasPlayableSemanticSample || record.playable;
            lastSemanticIntent = record.intent;
            lastSemanticSample = record.sample;
            lastSemanticStatus = record.status;
        }
    }

    std::ostringstream stream;
    stream << "sidebarSoundIntent count="
           << state.runtimeSoundIntentHistory.size()
           << " semantic="
           << formatBool(hasSemanticSidebarIntent)
           << " soundIniMapping="
           << formatBool(state.soundLoaded)
           << " evaIniMapping="
           << formatBool(state.evaLoaded)
           << " evaVoice="
           << runtimeEvaVoiceKeyForOwner(state)
           << " evaChannel="
           << (state.runtimeEvaUsingPlaySoundFallback
                ? "playsound-fallback"
                : "dedicated-mci")
           << " evaQueueBounded="
           << formatBool(state.runtimeEvaQueue.size() <= 12)
           << " evaMapping="
           << (hasPlayableEvaSample ? "runtime-playable" : "missing-runtime-api")
           << " playable="
           << formatBool(hasPlayableSemanticSample)
           << " evaEvents="
           << state.runtimeEvaEvents
           << " recentEvaEvents="
           << evaEvents
           << " evaPlayable="
           << state.runtimeEvaPlayableEvents
           << " recentEvaPlayable="
           << evaPlayableEvents
           << " evaSuppressed="
           << state.runtimeEvaSuppressedEvents
           << " evaQueued="
           << state.runtimeEvaQueuedEvents
           << " evaDequeued="
           << state.runtimeEvaDequeuedEvents
           << " evaQueueDepth="
           << state.runtimeEvaQueue.size()
           << " soundPathCache="
           << state.runtimeSoundSamplePathCache.size()
           << "/lookups="
           << state.runtimeSoundSamplePathCacheLookups
           << "/hits="
           << state.runtimeSoundSamplePathCacheHits
           << "/negative="
           << state.runtimeSoundSamplePathNegativeHits
           << "/resolver="
           << state.runtimeSoundSamplePathResolverCalls
           << " lastSemantic="
           << formatMaybe(lastSemanticIntent)
           << " lastSample="
           << formatMaybe(lastSemanticSample)
           << " lastStatus="
           << formatMaybe(lastSemanticStatus)
           << " last="
           << formatMaybe(state.lastRuntimeSound)
           << " playback=";
    bool firstPlayback = true;
    for (const RuntimeSoundPlaybackRecord& record :
        state.runtimeSoundPlaybackHistory) {
        if (!record.semantic) {
            continue;
        }
        if (!firstPlayback) {
            stream << ",";
        }
        firstPlayback = false;
        stream << record.intent
               << ":"
               << (record.sample.empty() ? "-" : record.sample)
               << ":"
               << (record.status.empty() ? "-" : record.status);
    }
    if (firstPlayback) {
        stream << "-";
    }
    stream
           << " history=";
    bool first = true;
    for (const std::string& intent : state.runtimeSoundIntentHistory) {
        if (!first) {
            stream << ",";
        }
        first = false;
        stream << intent;
    }
    if (first) {
        stream << "-";
    }
    return stream.str();
}

std::string buildRuntimePlacementAnchorSamplesLine(
    const RuntimeWindowState& state
) {
    const std::string sampleTypes[] = {"GACNST", "GAWEAP", "GAPOWR", "CAOILD"};
    std::ostringstream stream;
    stream << "Preview anchor samples:";
    for (const std::string& sampleType : sampleTypes) {
        const auto footprintIt = state.structureFootprints.find(sampleType);
        if (footprintIt == state.structureFootprints.end()
            || !footprintIt->second.valid) {
            stream << " " << sampleType << "=missing-footprint";
            continue;
        }

        const WorldObjectInstance* object = nullptr;
        for (const WorldObjectInstance& candidate : state.world.getObjects()) {
            if (candidate.alive
                && candidate.kind == WorldObjectKind::Structure
                && toUpperAsciiLocal(candidate.type)
                    == toUpperAsciiLocal(sampleType)) {
                object = &candidate;
                break;
            }
        }

        const RuntimeCellPoint topLeft =
            object == nullptr ? RuntimeCellPoint{0, 0}
                : runtimeCellPointForObject(*object);
        const RuntimeCellPoint previewTarget =
            runtimePlacementPreviewTargetCellForTopLeft(
                topLeft,
                footprintIt->second
            );
        const RuntimeCellPoint rearCell =
            runtimePlacementRearCellForFootprint(topLeft, footprintIt->second);
        const RuntimeCellPoint foundationAnchorCell =
            runtimePlacementAnchorCellForFootprint(topLeft, footprintIt->second);
        const RuntimeCellPoint roundTripTopLeft =
            runtimePlacementTopLeftForPreviewTarget(
                previewTarget,
                footprintIt->second
            );
        const std::vector<RuntimeCellPoint> cells =
            runtimeStructureFootprintCells(topLeft, footprintIt->second);
        bool rendererInputMatchesTopLeft = true;
        if (object != nullptr && object->hasRenderPosition) {
            rendererInputMatchesTopLeft =
                static_cast<int>(std::llround(object->renderX)) == topLeft.x
                && static_cast<int>(std::llround(object->renderY)) == topLeft.y;
        }
        const bool finalAnchorMatches =
            roundTripTopLeft == topLeft
            && rendererInputMatchesTopLeft;
        stream << " "
               << sampleType
               << "=footprint"
               << std::max(1, footprintIt->second.width)
               << "x"
               << std::max(1, footprintIt->second.height)
               << " topLeft="
               << topLeft.x
               << ","
               << topLeft.y
               << " previewTarget="
               << previewTarget.x
               << ","
               << previewTarget.y
               << " foundationAnchor="
               << foundationAnchorCell.x
               << ","
               << foundationAnchorCell.y
               << " rearCell="
               << rearCell.x
               << ","
               << rearCell.y
               << " cells="
               << cells.size()
               << " hash="
               << runtimeFootprintCellsHash(cells)
               << " roundTrip="
               << formatBool(roundTripTopLeft == topLeft)
               << " previewTargetEqFoundationAnchor="
               << formatBool(previewTarget == foundationAnchorCell)
               << " previewAnchorEqFinalStructureAnchor="
               << formatBool(finalAnchorMatches)
               << " rendererAnchorInput="
               << (rendererInputMatchesTopLeft ? "top-left" : "mismatch");
    }
    return stream.str();
}

