std::string runtimeReplayEventToken(std::string value) {
    for (char& character : value) {
        const unsigned char byte = static_cast<unsigned char>(character);
        if (std::isspace(byte)
            || character == ','
            || character == ';'
            || character == '#') {
            character = '_';
        }
    }
    return value;
}

std::string runtimeReplayCellToken(const RuntimeSnapshotCell& cell) {
    return std::to_string(cell.x) + ":" + std::to_string(cell.y);
}

bool writeRuntimeReplayEventSnapshotsToFile(
    const RuntimeWindowState& state,
    const std::string& outputPath,
    std::string& errorMessage
) {
    if (trimAsciiLocal(outputPath).empty()) {
        return true;
    }

    const std::filesystem::path path(outputPath);
    std::error_code errorCode;
    const std::filesystem::path parent = path.parent_path();
    if (!parent.empty()) {
        std::filesystem::create_directories(parent, errorCode);
        if (errorCode) {
            errorMessage =
                "failed to create runtime replay event directory: "
                + parent.string();
            return false;
        }
    }

    const std::vector<RuntimeReplayEventSnapshot>& events =
        materializeRuntimeReplayEventSnapshots(state);
    std::ofstream output(path, std::ios::binary);
    if (!output) {
        errorMessage =
            "failed to open runtime replay event output path: "
            + path.string();
        return false;
    }

    output << "# ConcordRTS runtime replay events v1\n";
    for (const RuntimeReplayEventSnapshot& event : events) {
        output
            << "sequence=" << event.sequence
            << " tick=" << event.tick
            << " kind=" << runtimeReplayEventToken(event.kind)
            << " objectId=" << event.objectId
            << " targetObjectId=" << event.targetObjectId
            << " projectileActorId=" << event.projectileActorId
            << " commandVerb=" << runtimeReplayEventToken(event.commandVerb)
            << " selectedCount=" << event.selectedCount
            << " acceptedCount=" << event.acceptedCount
            << " rejectedCount=" << event.rejectedCount
            << " commandTargetCell="
            << runtimeReplayCellToken(event.commandTargetCell)
            << " missionFrom=" << runtimeReplayEventToken(event.missionFrom)
            << " missionTo=" << runtimeReplayEventToken(event.missionTo)
            << " reason=" << runtimeReplayEventToken(event.reason)
            << " weaponId=" << runtimeReplayEventToken(event.weaponId)
            << " weaponSlot=" << runtimeReplayEventToken(event.weaponSlot)
            << " projectileId="
            << runtimeReplayEventToken(event.projectileId)
            << " projectileImageId="
            << runtimeReplayEventToken(event.projectileImageId)
            << " warheadId=" << runtimeReplayEventToken(event.warheadId)
            << " lifecycleState="
            << runtimeReplayEventToken(event.lifecycleState)
            << " spawnTick=" << event.spawnTick
            << " impactTick=" << event.impactTick
            << " expiredTick=" << event.expiredTick
            << " renderIntentId="
            << runtimeReplayEventToken(event.renderIntentId)
            << " renderIntentHash=" << event.renderIntentHash
            << " trailerIntentId="
            << runtimeReplayEventToken(event.trailerIntentId)
            << " impactIntentId="
            << runtimeReplayEventToken(event.impactIntentId)
            << " warheadImpactIntentId="
            << runtimeReplayEventToken(event.warheadImpactIntentId)
            << " sourceCell=" << runtimeReplayCellToken(event.sourceCell)
            << " targetCell=" << runtimeReplayCellToken(event.targetCell)
            << " currentCell=" << runtimeReplayCellToken(event.currentCell)
            << " secondTargetCell="
            << runtimeReplayCellToken(event.secondTargetCell)
            << " superWeaponId="
            << runtimeReplayEventToken(event.superWeaponId)
            << " superWeaponEvent="
            << runtimeReplayEventToken(event.superWeaponEvent)
            << "\n";
    }

    if (!output) {
        errorMessage =
            "failed while writing runtime replay events: " + path.string();
        return false;
    }
    return true;
}

bool writeRuntimeSmokeBmp(
    const std::string& outputPath,
    const void* pixels,
    int width,
    int height,
    std::string& errorMessage
) {
    if (trimAsciiLocal(outputPath).empty()) {
        return true;
    }
    if (pixels == nullptr || width <= 0 || height <= 0) {
        errorMessage = "render smoke bitmap has no pixels";
        return false;
    }

    const std::filesystem::path path(outputPath);
    std::error_code errorCode;
    const std::filesystem::path parent = path.parent_path();
    if (!parent.empty()) {
        std::filesystem::create_directories(parent, errorCode);
        if (errorCode) {
            errorMessage =
                "failed to create render smoke bitmap directory: "
                + parent.string();
            return false;
        }
    }

    BITMAPFILEHEADER fileHeader{};
    BITMAPINFOHEADER infoHeader{};
    const std::uint32_t imageSize =
        static_cast<std::uint32_t>(width)
        * static_cast<std::uint32_t>(height)
        * 4U;
    fileHeader.bfType = 0x4d42;
    fileHeader.bfOffBits =
        sizeof(BITMAPFILEHEADER) + sizeof(BITMAPINFOHEADER);
    fileHeader.bfSize = fileHeader.bfOffBits + imageSize;

    infoHeader.biSize = sizeof(BITMAPINFOHEADER);
    infoHeader.biWidth = width;
    infoHeader.biHeight = -height;
    infoHeader.biPlanes = 1;
    infoHeader.biBitCount = 32;
    infoHeader.biCompression = BI_RGB;
    infoHeader.biSizeImage = imageSize;

    std::ofstream output(path, std::ios::binary);
    if (!output) {
        errorMessage =
            "failed to open render smoke bitmap output path: "
            + path.string();
        return false;
    }
    output.write(
        reinterpret_cast<const char*>(&fileHeader),
        sizeof(fileHeader)
    );
    output.write(
        reinterpret_cast<const char*>(&infoHeader),
        sizeof(infoHeader)
    );
    output.write(reinterpret_cast<const char*>(pixels), imageSize);
    if (!output) {
        errorMessage =
            "failed while writing render smoke bitmap output path: "
            + path.string();
        return false;
    }
    return true;
}

std::optional<std::uint64_t> countRuntimeSmokeBmpGoldPixels(
    const std::string& inputPath,
    std::string& errorMessage
) {
    std::ifstream input(std::filesystem::path(inputPath), std::ios::binary);
    if (!input) {
        errorMessage =
            "failed to open render smoke bitmap for color validation: "
            + inputPath;
        return std::nullopt;
    }

    BITMAPFILEHEADER fileHeader{};
    BITMAPINFOHEADER infoHeader{};
    input.read(reinterpret_cast<char*>(&fileHeader), sizeof(fileHeader));
    input.read(reinterpret_cast<char*>(&infoHeader), sizeof(infoHeader));
    if (!input
        || fileHeader.bfType != 0x4d42
        || infoHeader.biWidth <= 0
        || infoHeader.biHeight == 0
        || infoHeader.biBitCount != 32
        || infoHeader.biCompression != BI_RGB) {
        errorMessage = "render smoke color validation requires a 32-bit BMP";
        return std::nullopt;
    }

    const int width = infoHeader.biWidth;
    const int height = std::abs(infoHeader.biHeight);
    const std::size_t rowBytes = static_cast<std::size_t>(width) * 4U;
    std::vector<unsigned char> row(rowBytes);
    input.seekg(static_cast<std::streamoff>(fileHeader.bfOffBits));

    std::uint64_t goldPixels = 0;
    for (int sourceY = 0; sourceY < height; ++sourceY) {
        input.read(reinterpret_cast<char*>(row.data()), row.size());
        if (!input) {
            errorMessage =
                "render smoke bitmap ended before color validation completed";
            return std::nullopt;
        }
        const int displayY =
            infoHeader.biHeight < 0 ? sourceY : height - sourceY - 1;
        if (std::abs(displayY - (height / 2)) > 150) {
            continue;
        }
        for (int x = 0; x < width; ++x) {
            if (std::abs(x - (width / 2)) > 180) {
                continue;
            }
            const std::size_t offset = static_cast<std::size_t>(x) * 4U;
            const int blue = row[offset];
            const int green = row[offset + 1U];
            const int red = row[offset + 2U];
            if (red >= 190
                && green >= 170
                && blue <= 70
                && green >= blue + 80) {
                ++goldPixels;
            }
        }
    }
    return goldPixels;
}

struct RuntimeSmokeBmpPixel {
    int red = 0;
    int green = 0;
    int blue = 0;
};

std::optional<RuntimeSmokeBmpPixel> readRuntimeSmokeBmpPixel(
    const std::string& inputPath,
    int x,
    int y,
    std::string& errorMessage
) {
    std::ifstream input(std::filesystem::path(inputPath), std::ios::binary);
    if (!input) {
        errorMessage =
            "failed to open render smoke bitmap for pixel validation: "
            + inputPath;
        return std::nullopt;
    }

    BITMAPFILEHEADER fileHeader{};
    BITMAPINFOHEADER infoHeader{};
    input.read(reinterpret_cast<char*>(&fileHeader), sizeof(fileHeader));
    input.read(reinterpret_cast<char*>(&infoHeader), sizeof(infoHeader));
    if (!input
        || fileHeader.bfType != 0x4d42
        || infoHeader.biWidth <= 0
        || infoHeader.biHeight == 0
        || infoHeader.biBitCount != 32
        || infoHeader.biCompression != BI_RGB) {
        errorMessage = "render smoke pixel validation requires a 32-bit BMP";
        return std::nullopt;
    }

    const int width = infoHeader.biWidth;
    const int height = std::abs(infoHeader.biHeight);
    if (x < 0 || y < 0 || x >= width || y >= height) {
        errorMessage = "render smoke pixel validation coordinate is out of range";
        return std::nullopt;
    }

    const int sourceY = infoHeader.biHeight < 0 ? y : height - y - 1;
    const std::uint64_t pixelOffset =
        static_cast<std::uint64_t>(fileHeader.bfOffBits)
        + (static_cast<std::uint64_t>(sourceY)
            * static_cast<std::uint64_t>(width) * 4ULL)
        + (static_cast<std::uint64_t>(x) * 4ULL);
    input.seekg(static_cast<std::streamoff>(pixelOffset));
    std::array<unsigned char, 4> bgra{};
    input.read(reinterpret_cast<char*>(bgra.data()), bgra.size());
    if (!input) {
        errorMessage = "render smoke bitmap ended before pixel validation";
        return std::nullopt;
    }
    return RuntimeSmokeBmpPixel{
        static_cast<int>(bgra[2]),
        static_cast<int>(bgra[1]),
        static_cast<int>(bgra[0])
    };
}

std::string runtimeSmokeBmpPathWithSuffix(
    const std::string& outputPath,
    const std::string& suffix
) {
    if (trimAsciiLocal(outputPath).empty()) {
        return "";
    }

    std::string safeSuffix;
    safeSuffix.reserve(suffix.size());
    for (unsigned char ch : suffix) {
        if (std::isalnum(ch)) {
            safeSuffix.push_back(static_cast<char>(ch));
        } else if (!safeSuffix.empty() && safeSuffix.back() != '_') {
            safeSuffix.push_back('_');
        }
    }
    while (!safeSuffix.empty() && safeSuffix.back() == '_') {
        safeSuffix.pop_back();
    }
    if (safeSuffix.empty()) {
        safeSuffix = "probe";
    }

    const std::filesystem::path basePath(outputPath);
    const std::filesystem::path parent = basePath.parent_path();
    const std::string stem =
        basePath.stem().empty() ? "runtime_probe" : basePath.stem().string();
    const std::string extension =
        basePath.extension().empty() ? ".bmp" : basePath.extension().string();
    return (parent / (stem + "_" + safeSuffix + extension)).string();
}

std::string buildRuntimeSnapshotMaterializeLine(
    const RuntimeWindowState& state
) {
    const RuntimeSnapshotMaterializeStats& stats =
        state.snapshotCache.stats;
    std::ostringstream stream;
    stream
        << "snapshots projectile="
        << stats.projectileSnapshotMaterializations
        << " actors="
        << stats.lastProjectileSnapshotActors
        << " replay="
        << stats.replayEventSnapshotMaterializations
        << " events="
        << stats.lastReplayEvents
        << " ui="
        << stats.uiSnapshotMaterializations
        << " mapFacts="
        << stats.mapFactsSnapshotMaterializations
        << " mapFactsReuse="
        << formatBool(stats.mapFactsContextReused)
        << " pathStats="
        << stats.pathStatsSnapshotMaterializations
        << " renderProjectile="
        << stats.projectileRenderActorMaterializations
        << " renderActors="
        << stats.lastProjectileRenderActors
        << " renderImpact="
        << stats.impactRenderActorMaterializations
        << " impactActors="
        << stats.lastImpactRenderActors;
    return stream.str();
}

std::string buildRuntimeMapQueryLine(
    const RuntimeWindowState& state,
    const RuntimeCellPoint& cell
) {
    const int key = runtimeCellKey(cell.x, cell.y);
    const auto terrainIt = state.terrainByCell.find(key);
    const TerrainCell* terrain =
        terrainIt == state.terrainByCell.end() ? nullptr : terrainIt->second;
    std::unordered_map<int, int> occupiedByCell =
        buildRuntimeOccupancyLookup(state);
    const auto occupiedIt = occupiedByCell.find(key);

    std::ostringstream stream;
    stream
        << "mapQuery cell="
        << cell.x
        << ","
        << cell.y
        << " status="
        << (state.mapQueryStatus.empty()
                ? std::string(state.mapFactsLoaded ? "MapQuery loaded" : "MapQuery unavailable")
                : state.mapQueryStatus)
        << " terrain="
        << formatBool(terrain != nullptr);
    const MapCellFacts* facts = runtimeMapQueryCell(state, cell);
    if (facts != nullptr) {
        stream
            << " factsTerrain="
            << formatBool(facts->hasTerrain)
            << " factsLevel="
            << facts->heightLevel
            << " factsPassability="
            << formatMaybe(facts->passabilityHint)
            << " resource="
            << formatBool(facts->isResourceCell)
            << " bridge="
            << formatBool(facts->isBridge)
            << " water="
            << formatBool(facts->isWater)
            << " shore="
            << formatBool(facts->isShore)
            << " cliff="
            << formatBool(facts->isCliff)
            << " ramp="
            << formatBool(facts->isRamp);
    }
    if (terrain != nullptr) {
        const RuntimeTerrainInfo info =
            runtimeCachedTerrainInfoForCell(state, *terrain);
        stream
            << " level="
            << terrain->level
            << " passable="
            << formatBool(info.passable)
            << " bridge="
            << formatBool(info.bridge)
            << " water="
            << formatBool(info.water)
            << " shore="
            << formatBool(info.shore)
            << " cliff="
            << formatBool(info.cliff)
            << " ramp="
            << formatBool(info.ramp)
            << " cost="
            << info.cost;
    }
    stream
        << " occupied="
        << (occupiedIt == occupiedByCell.end()
                ? std::string("-")
                : ("#" + std::to_string(occupiedIt->second)));
    return stream.str();
}

std::string buildCommandLine(const RuntimeWindowState& state) {
    if (!state.lastCommand.valid) {
        return "command none";
    }

    bool pathQueuedLater = false;
    bool visualIntentBeforePath = false;
    for (int objectId : state.selectedObjectIds) {
        const auto behaviorIt = state.behaviors.find(objectId);
        if (behaviorIt == state.behaviors.end()) {
            continue;
        }
        const RuntimeObjectBehavior& behavior = behaviorIt->second;
        if (behavior.kind != RuntimeBehaviorKind::Move
            && behavior.kind != RuntimeBehaviorKind::Attack) {
            continue;
        }
        visualIntentBeforePath = true;
        if (behavior.path.empty() || behavior.pathRequestPending) {
            pathQueuedLater = true;
        }
    }

    std::ostringstream stream;
    stream
        << "command "
        << state.lastCommand.verb
        << " "
        << state.lastCommand.selectedCount
        << " selected accepted "
        << state.lastCommand.acceptedCount
        << " rejected "
        << state.lastCommand.rejectedCount
        << " -> "
        << state.lastCommand.targetX
        << ","
        << state.lastCommand.targetY
        << " tick "
        << state.lastCommand.tick
        << " inputAckImmediate="
        << formatBool(state.lastCommand.inputAckImmediate)
        << " commandFeedbackLatencyTicks="
        << state.lastCommand.feedbackLatencyTicks
        << " pathQueuedLater="
        << formatBool(pathQueuedLater)
        << " visualIntentBeforePath="
        << formatBool(visualIntentBeforePath);
    if (state.lastCommand.targetObjectId >= 0) {
        stream
            << " target "
            << state.lastCommand.targetObjectType
            << " #"
            << state.lastCommand.targetObjectId;
    }
    return stream.str();
}

std::string buildRuntimeCapabilityLine(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object
) {
    const RuntimeCachedCapabilityProfile& cached =
        runtimeCachedCapabilityProfileForObject(state, object);
    const RuntimeDeployProfile& deployProfile = cached.deploy;
    const RuntimeEngineerProfile& engineerProfile = cached.engineer;
    const RuntimeOccupyProfile& occupyProfile = cached.occupy;
    const RuntimeTransportProfile& transportProfile = cached.transport;
    const RuntimeWeaponProfile weaponProfile =
        runtimeWeaponProfileForObject(state, object);

    std::ostringstream stream;
    stream
        << "capability #"
        << object.instanceId
        << " "
        << object.type
        << " mission="
        << runtimeMissionStateNameForObject(object)
        << " deploy="
        << formatBool(deployProfile.hasProfile)
        << " deployed="
        << formatBool(runtimeObjectHasDeployedState(state, object))
        << " deployWeapon="
        << formatMaybe(deployProfile.deployWeaponId)
        << " deploySlot="
        << runtimeWeaponSlotName(deployProfile.deployWeaponSlot)
        << " engineer="
        << formatBool(
            engineerProfile.canCapture
            || engineerProfile.canRepair
            || engineerProfile.canBridgeRepair
        )
        << " occupy="
        << formatBool(occupyProfile.canOccupy)
        << " occupyTarget="
        << formatBool(occupyProfile.targetCanBeOccupied)
        << " maxOccupants="
        << occupyProfile.maxOccupants
        << " occupyWeapon="
        << formatMaybe(occupyProfile.occupyWeaponId)
        << " occupying="
        << formatBool(weaponProfile.occupied)
        << " transport="
        << formatBool(transportProfile.canTransport)
        << " canUnload="
        << formatBool(transportProfile.canUnload)
        << " passengers="
        << transportProfile.passengerCapacity
        << " unloadingClass="
        << formatMaybe(transportProfile.unloadingClass)
        << " transportOpenWeapon="
        << formatBool(weaponProfile.openTransport)
        << " weapon="
        << formatBool(weaponProfile.weapon != nullptr)
        << " weaponId="
        << formatMaybe(weaponProfile.weaponId)
        << " slot="
        << runtimeWeaponSlotName(weaponProfile.slot)
        << " weaponReason="
        << formatMaybe(weaponProfile.selectionReason)
        << " projectile="
        << formatMaybe(weaponProfile.projectileId)
        << " projectileProfile="
        << formatBool(weaponProfile.projectile != nullptr)
        << " warhead="
        << formatMaybe(weaponProfile.warheadId)
        << " warheadProfile="
        << formatBool(weaponProfile.warhead != nullptr)
        << " turret="
        << formatBool(weaponProfile.hasTurret);
    return stream.str();
}

void applySelection(
    RuntimeWindowState& state,
    const std::vector<int>& objectIds,
    bool append,
    bool toggle
) {
    if (!append && !toggle) {
        state.selectedObjectIds.clear();
    }

    bool selectionAdded = false;
    for (int objectId : objectIds) {
        const auto* object = findObjectById(state, objectId);
        if (object && !runtimeObjectAcceptsPlayerSelection(state, *object)) continue;
        if (toggle && selectionContains(state, objectId)) {
            removeSelectedObject(state, objectId);
        } else {
            selectionAdded =
                selectionAdded || !selectionContains(state, objectId);
            addSelectedObject(state, objectId);
        }
    }

    if (state.selectedObjectIds.empty()) {
        state.interactionStatus = "selection cleared";
    } else {
        state.interactionStatus =
            "selected " + std::to_string(state.selectedObjectIds.size());
        if (selectionAdded && !state.runtimeSuppressPlayerAudioFeedback) {
            if (const std::optional<std::string> voice =
                    runtimeVoiceEventForSelectedUnits(state, "select");
                voice.has_value()) {
                emitRuntimeSound(state, *voice);
            }
        }
    }
}

bool runtimeObjectCanBeBoxSelected(const WorldObjectInstance& object) {
    return object.alive
        && object.mission != "SupportFlightEast" && object.mission != "SupportFlightWest"
        && object.mission != "ParadropDrop"
        && (object.kind == WorldObjectKind::Unit
            || object.kind == WorldObjectKind::Infantry);
}

bool runtimeObjectCanReceiveMoveCommand(const RuntimeWindowState& state, const WorldObjectInstance& object);

int selectedMovableObjectCount(const RuntimeWindowState& state) {
    int count = 0;
    for (int objectId : state.selectedObjectIds) {
        const WorldObjectInstance* object = findObjectById(state, objectId);
        if (object != nullptr && (runtimeObjectCanReceiveMoveCommand(state, *object)
                || (object->owner == state.economy.owner
                    && (runtimeStructureCanRepack(state, *object)
                        || runtimeStructureIsRepacking(*object))))) {
            ++count;
        }
    }
    return count;
}

RuntimeCellPoint formationOffsetForIndex(int index, int spacing = 1) {
    spacing = std::max(1, spacing);
    if (index <= 0) {
        return {0, 0};
    }

    int ring = 1;
    while (((ring * 2) + 1) * ((ring * 2) + 1) <= index) {
        ++ring;
    }

    const int previousRingSide = (ring * 2) - 1;
    const int rawSlot = index - (previousRingSide * previousRingSide);
    const int side = ring * 2;
    const int perimeter = std::max(1, side * 4);
    // Keep the formation compact, but avoid filling each ring from one corner
    // in a visible queue. For perimeter 8r, step 4r-1 is coprime, so each
    // slot is still used exactly once.
    const int permutationStep = std::max(1, (side * 2) - 1);
    const int slot = ((rawSlot * permutationStep) + (ring * 3)) % perimeter;
    RuntimeCellPoint offset{-ring, -ring};
    if (slot < side) {
        offset.x = -ring + slot;
        offset.y = -ring;
    } else if (slot < side * 2) {
        offset.x = ring;
        offset.y = -ring + (slot - side);
    } else if (slot < side * 3) {
        offset.x = ring - (slot - (side * 2));
        offset.y = ring;
    } else {
        offset.x = -ring;
        offset.y = ring - (slot - (side * 3));
    }

    offset.x *= spacing;
    offset.y *= spacing;
    return offset;
}

int terrainLevelAtRuntimeCell(
    const RuntimeWindowState& state,
    int x,
    int y
) {
    const int key = runtimeCellKey(x, y);
    const auto cachedIt = state.terrainByCell.find(key);
    if (cachedIt != state.terrainByCell.end() && cachedIt->second != nullptr) {
        return runtimeEffectiveTerrainLevel(*cachedIt->second);
    }

    for (const TerrainCell& cell : state.world.getTerrainCells()) {
        if (runtimeCellKey(cell.x, cell.y) == key) {
            return runtimeEffectiveTerrainLevel(cell);
        }
    }
    return 0;
}

bool runtimeCellIsBridge(
    const RuntimeWindowState& state,
    int x,
    int y
) {
    const int key = runtimeCellKey(x, y);
    const auto cachedIt = state.terrainByCell.find(key);
    if (cachedIt != state.terrainByCell.end() && cachedIt->second != nullptr) {
        return runtimeCachedTerrainInfoForCell(state, *cachedIt->second).bridge;
    }

    for (const TerrainCell& cell : state.world.getTerrainCells()) {
        if (runtimeCellKey(cell.x, cell.y) == key) {
            return runtimeCachedTerrainInfoForCell(state, cell).bridge;
        }
    }

    return false;
}

void setRuntimeObjectCell(
    RuntimeWindowState& state,
    WorldObjectInstance& object,
    const RuntimeCellPoint& point,
    bool resetRenderPosition
) {
    RuntimePerfTraceScope movePhaseTrace("moveSetCell", state.tick);
    object.x = point.x;
    object.y = point.y;
    object.cell = runtimeCellKey(point.x, point.y);
    if (runtimeObjectMovementMode(state, object) == PathMovementMode::Air
        && object.airborne) {
        // Air movement is planar: crossing hills, cliffs, water, or bridges
        // must not pull the aircraft up and down with ground elevation.
        object.level = object.flightLevel;
        object.onBridge = false;
    } else {
        object.level = terrainLevelAtRuntimeCell(state, point.x, point.y);
        object.onBridge = runtimeCellIsBridge(state, point.x, point.y);
    }
    assignRuntimeInfantrySubcellAtCurrentLocation(state, object);
    if (resetRenderPosition) {
        object.hasRenderPosition = false;
        object.renderX = static_cast<double>(object.x);
        object.renderY = static_cast<double>(object.y);
        object.renderMoveActive = false;
        object.renderLevel = static_cast<double>(object.level);
        object.renderOnBridge = object.onBridge;
    }
    syncRuntimeTransportCargoPositions(state, object);
}

void refreshRuntimeBridgeMutationState(
    RuntimeWindowState& state,
    const std::vector<RuntimeCellPoint>& changedCells
) {
    if (state.drainingObjectExits) {
        state.deferredBridgeMutationCells.insert(state.deferredBridgeMutationCells.end(),
            changedCells.begin(), changedCells.end());
        return;
    }
    std::unordered_set<int> changedCellKeys;
    for (const RuntimeCellPoint& point : changedCells) {
        const int key = runtimeCellKey(point.x, point.y);
        const auto terrainIt = state.terrainByCell.find(key);
        if (terrainIt == state.terrainByCell.end()
            || terrainIt->second == nullptr) {
            continue;
        }
        changedCellKeys.insert(key);
        state.terrainInfoByCell[key] =
            runtimeNavigationTerrainInfoForCell(state, *terrainIt->second);
    }

    state.attackApproachCache.clear();
    state.pathFailureCache.clear();
    state.pathTerrainCache.valid = false;
    state.pathTerrainCache.terrainCellCount = 0;
    state.pathTerrainCache.staticCells.clear();
    state.pathTerrainCache.dynamicValid = false;
    state.pathTerrainCache.dynamicCells.clear();
    invalidateRuntimeTickOccupancyCache(state);
    invalidateRuntimeObjectProjectionCache(state);
    state.renderCache.terrainLayer = RuntimeTerrainLayerCache{};
    state.radarTerrainKey.clear();
    state.radarProjectionCacheValid = false;
    state.repaintRequested = true;

    for (WorldObjectInstance& object : state.world.accessObjects()) {
        if (!object.alive) {
            continue;
        }
        if (object.airborne && object.hasRenderPosition && runtimeCarrierHasDeckFlight(state, object)) {
            applyRuntimeCarrierDeckFlightPresentation(state, object); continue;
        }
        const bool stoppedPose = worldObjectHasStoppedGroundPose(object);
        const bool stoppedTerrainChanged = stoppedPose
            && (changedCellKeys.contains(runtimeCellKey(object.x, object.y))
                || changedCellKeys.contains(runtimeCellKey(
                    static_cast<int>(std::lround(object.renderX)),
                    static_cast<int>(std::lround(object.renderY)))));
        const auto terrainIt = state.terrainByCell.find(
            runtimeCellKey(object.x, object.y)
        );
        const bool airborneObject =
            runtimeObjectMovementMode(state, object) == PathMovementMode::Air
            && object.airborne;
        if (airborneObject) {
            object.onBridge = false;
            object.level = object.flightLevel;
        } else {
            object.onBridge = terrainIt != state.terrainByCell.end()
                && terrainIt->second != nullptr
                && runtimeCachedTerrainInfoForCell(
                    state,
                    *terrainIt->second
                ).bridge;
            if (terrainIt != state.terrainByCell.end()
                && terrainIt->second != nullptr) {
                object.level = runtimeEffectiveTerrainLevel(*terrainIt->second);
            }
        }
        if (object.renderMoveActive) {
            const auto behaviorIt = state.behaviors.find(object.instanceId);
            if (behaviorIt != state.behaviors.end()
                && behaviorIt->second.renderMoveTicksTotal > 0) {
                if (behaviorIt->second.transportTransferKind != RuntimeTransportTransferKind::Boarding) {
                    behaviorIt->second.renderToLevel =
                        static_cast<double>(object.level);
                    behaviorIt->second.renderToOnBridge = object.onBridge;
                }
            } else {
                clearRuntimeRenderPosition(object);
            }
        } else if (!stoppedPose || stoppedTerrainChanged) {
            // A distant bridge refresh must not pull a stopped mover's
            // fractional slope height to its committed navigation cell.
            // Local terrain changes still use the normal new ground pose.
            object.renderLevel = static_cast<double>(object.level);
            object.renderOnBridge = object.onBridge;
        }
    }
    for (auto& object : state.world.accessObjects()) {
        applyRuntimeJumpjetPose(state, object);
        applyRuntimeFixedWingPose(state, object);
    }
    rebuildRuntimeNavigationStats(state);
}

void clearRuntimeRenderPosition(WorldObjectInstance& object) {
    object.hasRenderPosition = false;
    object.renderX = static_cast<double>(object.x);
    object.renderY = static_cast<double>(object.y);
    object.renderMoveActive = false;
    object.renderLevel = static_cast<double>(object.level);
    object.renderOnBridge = object.onBridge;
}

void releaseRuntimeAircraftDock(WorldObjectInstance& object) {
    if (object.dockedToObjectId < 0 && object.dockIndex < 0) {
        return;
    }
    object.dockedToObjectId = -1;
    object.dockIndex = -1;
    object.airborne = false;
    object.flightLevel = object.level;
    clearRuntimeRenderPosition(object);
}

void releaseRuntimeAircraftSupportAuthority(WorldObjectInstance& object) {
    object.dockedToObjectId = -1;
    object.dockIndex = -1;
}

int runtimeAircraftCruiseLevel(const RuntimeWindowState& state) {
    int highestTerrainLevel = 0;
    for (const TerrainCell& terrain : state.world.getTerrainCells()) {
        highestTerrainLevel = std::max(
            highestTerrainLevel,
            runtimeEffectiveTerrainLevel(terrain)
        );
    }
    // Four height levels clear the tallest terrain while retaining the
    // existing isometric scale used by WorldObjectInstance::level.
    return highestTerrainLevel + 4;
}

void departRuntimeAircraftDock(
    RuntimeWindowState& state,
    WorldObjectInstance& object
) {
    // DeployToLand keeps the body on the ground until the explicit
    // undeploy transition owns takeoff. Attack/guard orders also pass here.
    const auto* deploymentUnit = findRuntimeUnitType(state.rules, object);
    if (deploymentUnit != nullptr && deploymentUnit->deployToLand
        && (runtimeObjectHasDeployedState(state, object)
            || runtimeMissionIsLandingToDeploy(object))) {
        return;
    }
    if (runtimeObjectMovementMode(state, object) == PathMovementMode::Air) {
        if (!object.airborne) {
            queueRuntimeAircraftAuxSound(state, object, true);
            const UnitType* unit = findRuntimeUnitType(state.rules, object);
            const int groundLevel = terrainLevelAtRuntimeCell(state, object.x, object.y);
            object.flightLevel = unit != nullptr && runtimeUnitUsesJumpjetMovement(*unit)
                ? groundLevel
                : runtimeAircraftCruiseLevel(state);
            object.airborne = true;
            refreshRuntimeObjectOccupancyAfterLocalChange(state);
        }
        object.level = object.flightLevel;
        object.onBridge = false;
    }
    if (object.dockedToObjectId < 0 || object.dockIndex < 0) {
        return;
    }
    if (runtimeFixedWingProfile(state, object)) { applyRuntimeFixedWingPose(state, object); return; }
    // A sortie vacates the visible pad but not the aircraft's support slot.
    // AirportBound capacity is a live-aircraft quota, so the same plane keeps
    // its host/index while airborne and can return to that pad later.
    clearRuntimeRenderPosition(object);
}

#include "simulation/movement/ground/RuntimeGroundMoveFacing.inl"

void beginRuntimeRenderMove(
    WorldObjectInstance& object,
    RuntimeObjectBehavior& behavior,
    const RuntimeCellPoint& from,
    const RuntimeCellPoint& to,
    double fromLevel,
    bool fromOnBridge,
    int cooldownTicks,
    RuntimeWindowState* context = nullptr
) {
    if (context && object.kind == WorldObjectKind::Unit
        && !context->pendingTransportTargets.empty()
        && runtimeCachedCapabilityProfileForObject(*context, object).transport.canTransport)
        cancelRuntimeTransportBoardingForMovingHost(*context, object.instanceId);
    behavior.moveSegmentFrom = from;
    behavior.renderFromOffsetX = behavior.renderFromOffsetY = 0.0;
    behavior.renderToOffsetX = behavior.renderToOffsetY = 0.0;
    const bool stoppedPose = worldObjectHasStoppedGroundPose(object);
    if (stoppedPose) {
        behavior.renderFromOffsetX = object.renderX - from.x;
        behavior.renderFromOffsetY = object.renderY - from.y;
        fromLevel = object.renderLevel;
        fromOnBridge = object.renderOnBridge;
    }
    if (context && object.kind == WorldObjectKind::Unit && !object.airborne) {
        if (object.hasRenderPosition && !stoppedPose) {
            behavior.renderFromOffsetX = object.renderX - from.x;
            behavior.renderFromOffsetY = object.renderY - from.y;
        }
        if (const auto dock = runtimeRepairDepotApproachPoint(*context, object, to)) {
            behavior.renderToOffsetX = (*dock)[0] - to.x;
            behavior.renderToOffsetY = (*dock)[1] - to.y;
        }
    }
    if (context && object.airborne && object.hasRenderPosition
        && runtimeCarrierHasDeckFlight(*context, object)) {
        behavior.renderFromOffsetX = object.renderX - from.x;
        behavior.renderFromOffsetY = object.renderY - from.y;
        fromLevel = object.renderLevel;
    }
    behavior.renderFrom = from;
    behavior.renderTo = to;
    behavior.renderFromLevel = fromLevel;
    behavior.renderToLevel = static_cast<double>(object.level);
    behavior.renderFromOnBridge = fromOnBridge;
    behavior.renderToOnBridge = object.onBridge;
    if (context && runtimeObjectUsesOmniCrushApproach(*context, object)
        && runtimeCellPointForObject(object) == from && from != to) {
        behavior.renderToLevel = terrainLevelAtRuntimeCell(*context, to.x, to.y);
        behavior.renderToOnBridge = runtimeCellIsBridge(*context, to.x, to.y);
    }
    if (runtimeInfantryMoveUsesCommittedCorner(object, behavior)) {
        const double stepDistance = std::hypot(double(to.x - from.x), double(to.y - from.y));
        const double distance = std::hypot(behavior.renderFromOffsetX, behavior.renderFromOffsetY)
            + stepDistance;
        cooldownTicks = static_cast<int>(std::clamp(std::ceil(cooldownTicks * distance / stepDistance),
            1.0, double(std::numeric_limits<int>::max() - 1)));
        behavior.moveCooldownTicks = cooldownTicks;
    } else if (context && stoppedPose && !object.airborne
        && (object.kind == WorldObjectKind::Infantry || object.kind == WorldObjectKind::Unit)
        && behavior.kind == RuntimeBehaviorKind::Move
        && behavior.transportTransferKind == RuntimeTransportTransferKind::None
        && runtimeTransportUnitBoardingPending(*context, object.instanceId)) {
        const auto intent = context->pendingTransportTargets.find(object.instanceId);
        if (intent != context->pendingTransportTargets.end()
            && intent->second == behavior.pendingAllowedOccupiedObjectId) {
            const double stepDistance = std::hypot(double(to.x - from.x), double(to.y - from.y));
            const double actualDistance = std::hypot(to.x + behavior.renderToOffsetX - from.x - behavior.renderFromOffsetX,
                to.y + behavior.renderToOffsetY - from.y - behavior.renderFromOffsetY);
            if (stepDistance > 0.0 && actualDistance > stepDistance) {
                cooldownTicks = static_cast<int>(std::clamp(std::ceil(cooldownTicks * actualDistance / stepDistance),
                    1.0, double(std::numeric_limits<int>::max() - 1)));
                behavior.moveCooldownTicks = cooldownTicks;
            }
        }
    }
    behavior.renderMoveTicksTotal = std::max(1, cooldownTicks);
    behavior.renderMoveTicksRemaining = behavior.renderMoveTicksTotal;
    // The visible body direction is a hard invariant of the active segment.
    // Turning is completed before this point, and no other subsystem may make
    // a moving unit render against (or sideways to) its actual displacement.
    alignRuntimeFacingToRenderMove(object, behavior);
    object.hasRenderPosition = true;
    object.renderX = static_cast<double>(from.x) + behavior.renderFromOffsetX;
    object.renderY = static_cast<double>(from.y) + behavior.renderFromOffsetY;
    object.renderMoveActive = true;
    object.renderLevel = fromLevel;
    object.renderOnBridge = fromOnBridge;
    // Keep same-tick nearby-body queries current when this segment is accepted.
    // Retaining old buckets is conservative and avoids rebuilding the army index.
    if (context && !object.airborne
        && !runtimeTrackGroundPoseSpatialMove(*context, object))
        invalidateRuntimeTickOccupancyCache(*context);
    if (context && object.airborne && runtimeJumpjetProfile(*context, object)) {
        const auto flight=context->jumpjetFlights.find(object.instanceId);
        if(flight!=context->jumpjetFlights.end() && flight->second.active)
            object.movementAnimationDistance=std::fmod(object.movementAnimationDistance
                +double(flight->second.progress)/runtimeJumpjetCellQ16,1024.0);
        applyRuntimeJumpjetPose(*context, object);
    }
}

#include "audio/events/RuntimeInfantryWaterSound.inl"

bool runtimeGroundRenderStepWaitsForStoppedBody(RuntimeWindowState& state,
    const WorldObjectInstance& object, const RuntimeObjectBehavior& behavior) {
    if (!worldObjectHasGroundRenderPose(object) || !object.renderMoveActive
        || behavior.renderMoveTicksTotal <= 0 || behavior.renderMoveTicksRemaining <= 0
        || runtimeObjectMovementMode(state, object) == PathMovementMode::Air) return false;
    (void)runtimeTickOccupancyLookup(state);
    if (state.movementEmptyCellProof.additionalGroundPoseObjectIndices.empty()) return false;
    const double progress = runtimeVehicleMoveRenderProgressAtRemaining(behavior,
        std::max(0, behavior.renderMoveTicksRemaining - 1));
    const auto point = runtimeGroundRenderMovePoint(object, behavior, progress);
    return runtimeStoppedGroundPoseBlocksRenderMove(state, object, point[0], point[1]);
}

bool advanceRuntimeRenderMove(
    RuntimeWindowState& state,
    WorldObjectInstance& object,
    RuntimeObjectBehavior& behavior
) {
    RuntimePerfTraceScope movePhaseTrace("moveRender", state.tick);
    if (behavior.renderMoveTicksTotal <= 0) {
        clearRuntimeRenderPosition(object);
        return false;
    }

    RuntimeInfantryWaterPoseQuery waterPose(state);
    const auto waterBefore = waterPose.pose(object);
    const double previousRenderX = object.renderX;
    const double previousRenderY = object.renderY;
    behavior.renderMoveTicksRemaining =
        std::max(0, behavior.renderMoveTicksRemaining - 1);
    const double progress = runtimeVehicleMoveRenderProgress(behavior);
    object.hasRenderPosition = true;
    object.renderMoveActive = true;
    const auto point = runtimeGroundRenderMovePoint(object, behavior, progress);
    object.renderX = point[0];
    object.renderY = point[1];
    alignRuntimeFacingToRenderMove(object, behavior);
    object.renderLevel =
        behavior.renderFromLevel
        + ((behavior.renderToLevel - behavior.renderFromLevel) * progress);
    object.renderOnBridge = progress < 0.5
        ? behavior.renderFromOnBridge
        : behavior.renderToOnBridge;

    object.movementAnimationDistance += std::hypot(
        object.renderX - previousRenderX,
        object.renderY - previousRenderY
    );
    if (object.movementAnimationDistance >= 1024.0) {
        object.movementAnimationDistance =
            std::fmod(object.movementAnimationDistance, 1024.0);
    }

    if (progress >= 1.0 && !runtimeOmniCrushPendingSegment(state, object, behavior)) {
        if (behavior.transportTransferKind == RuntimeTransportTransferKind::Boarding
            || behavior.renderToOffsetX != 0.0 || behavior.renderToOffsetY != 0.0) {
            object.renderMoveActive = false;
        } else clearRuntimeRenderPosition(object);
        behavior.renderMoveTicksTotal = 0;
        behavior.renderMoveTicksRemaining = 0;
        behavior.renderArrivalDistanceAfter = -1.0;
        behavior.renderStartupAccelerationDistance = 0.0;
        if (behavior.transportTransferKind == RuntimeTransportTransferKind::Egress) {
            if (behavior.kind == RuntimeBehaviorKind::Move
                && behavior.pendingAllowedOccupiedObjectId == behavior.transportTransferHostId
                && !state.pendingTransportTargets.contains(object.instanceId)) {
                behavior.pendingAllowedOccupiedObjectId = -1;
            }
            behavior.transportTransferHostId = -1;
            behavior.transportTransferKind = RuntimeTransportTransferKind::None;
        }
    }
    emitRuntimeInfantryWaterTransition(state, object, waterBefore, &waterPose);
    return true;
}

#include "simulation/movement/aircraft/RuntimeJumpjetKinematics.inl"

int runtimeFacingFromDelta(int dx, int dy) {
    if (dx == 0 && dy == 0) {
        return -1;
    }

    constexpr double pi = 3.14159265358979323846;
    const double screenDx = static_cast<double>(dx - dy);
    const double screenDy = static_cast<double>(dx + dy);
    double directionDegrees =
        std::atan2(screenDx, -screenDy) * 180.0 / pi;
    directionDegrees = std::fmod(directionDegrees + 360.0, 360.0);
    if (directionDegrees < 0.0) {
        directionDegrees += 360.0;
    }

    int facing = static_cast<int>(std::lround((directionDegrees / 360.0) * 256.0));
    facing %= 256;
    if (facing < 0) {
        facing += 256;
    }
    return facing;
}

void updateRuntimeObjectFacing(
    WorldObjectInstance& object,
    const RuntimeCellPoint& from,
    const RuntimeCellPoint& to
) {
    const int facing = runtimeFacingFromDelta(to.x - from.x, to.y - from.y);
    if (facing >= 0) {
        object.facing = facing;
    }
}

int normalizeRuntimeFacing(int facing) {
    int normalized = facing % 256;
    if (normalized < 0) {
        normalized += 256;
    }
    return normalized;
}

int runtimeSignedFacingDelta(int from, int to) {
    int delta = normalizeRuntimeFacing(to) - normalizeRuntimeFacing(from);
    if (delta > 128) {
        delta -= 256;
    } else if (delta < -128) {
        delta += 256;
    }
    return delta;
}

int runtimeFacingAbsDifference(int left, int right) {
    return std::abs(runtimeSignedFacingDelta(left, right));
}

int runtimeTurnFacingToward(int current, int desired, int step) {
    current = normalizeRuntimeFacing(current);
    desired = normalizeRuntimeFacing(desired);
    if (step <= 0) return current;

    const int delta = runtimeSignedFacingDelta(current, desired);
    if (std::abs(delta) <= step) {
        return desired;
    }

    return normalizeRuntimeFacing(current + (delta > 0 ? step : -step));
}

bool runtimeObjectHasTurret(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object
) {
    return runtimeObjectHasTurretCapability(state, object);
}

struct RuntimeSmokeStageTiming {
    std::string name;
    double milliseconds = 0.0;
};

std::chrono::steady_clock::time_point runtimeSmokeNow() {
    return std::chrono::steady_clock::now();
}

double runtimeSmokeElapsedMs(
    std::chrono::steady_clock::time_point start
) {
    return std::chrono::duration<double, std::milli>(
        std::chrono::steady_clock::now() - start
    ).count();
}

void addRuntimeSmokeStageMs(
    std::vector<RuntimeSmokeStageTiming>& timings,
    const std::string& name,
    double milliseconds
) {
    for (RuntimeSmokeStageTiming& timing : timings) {
        if (timing.name == name) {
            timing.milliseconds += milliseconds;
            return;
        }
    }
    timings.push_back(RuntimeSmokeStageTiming{name, milliseconds});
}

void finishRuntimeSmokeStage(
    std::vector<RuntimeSmokeStageTiming>& timings,
    const std::string& name,
    std::chrono::steady_clock::time_point start
) {
    addRuntimeSmokeStageMs(timings, name, runtimeSmokeElapsedMs(start));
}

void printRuntimeSmokeTimings(
    const std::string& label,
    const std::vector<RuntimeSmokeStageTiming>& timings,
    std::chrono::steady_clock::time_point totalStart
) {
    std::ostringstream stream;
    stream << label << " timings:";
    stream << std::fixed << std::setprecision(2);
    for (const RuntimeSmokeStageTiming& timing : timings) {
        stream
            << " "
            << timing.name
            << "="
            << timing.milliseconds
            << "ms";
    }
    stream
        << " total="
        << runtimeSmokeElapsedMs(totalStart)
        << "ms";
    std::cout << stream.str() << "\n";
}

double runtimeSmokeStageMs(
    const std::vector<RuntimeSmokeStageTiming>& timings,
    const std::string& name
) {
    for (const RuntimeSmokeStageTiming& timing : timings) {
        if (timing.name == name) {
            return timing.milliseconds;
        }
    }
    return 0.0;
}

std::string buildRuntimeRenderCacheWarmLine(
    const RuntimeMapRenderCache& cache
) {
    std::ostringstream stream;
    stream
        << "palette="
        << formatBool(cache.paletteLoaded)
        << " structurePalette="
        << formatBool(cache.structurePaletteLoaded)
        << " terrainLayer="
        << formatBool(cache.terrainLayer.built)
        << " tmpTiles="
        << cache.tmpTilesByPath.size()
        << " objectShp="
        << cache.objectShpSpritesByType.size()
        << " auxShp="
        << cache.auxiliaryShpSpritesByImage.size()
        << " voxels="
        << cache.voxelObjectsByType.size();
    return stream.str();
}

std::string buildRuntimeColdPathLine(
    const RuntimeWindowState& state,
    const std::vector<RuntimeSmokeStageTiming>& timings,
    const std::string& label
) {
    std::ostringstream stream;
    stream << std::fixed << std::setprecision(2);
    stream
        << label
        << " coldPath startup="
        << runtimeSmokeStageMs(timings, "startup")
        << "ms renderCheck="
        << runtimeSmokeStageMs(timings, "renderCheck")
        << "ms farAttack="
        << runtimeSmokeStageMs(timings, "farAttack")
        << "ms buildProgress="
        << runtimeSmokeStageMs(timings, "buildProgress")
        << "ms MapFactsReuse="
        << formatBool(state.mapFactsLoaded)
        << " MapFactsSnapshotReuse="
        << formatBool(state.snapshotCache.stats.mapFactsContextReused)
        << " resourceWarm "
        << buildRuntimeRenderCacheWarmLine(state.renderCache);
    return stream.str();
}

int runtimeTurretTurnStep(const RuntimeWindowState& state, const WorldObjectInstance& object) {
    if (const auto* unit = findRuntimeUnitType(state.rules, object)) return std::clamp(unit->rot, 0, 127);
    if (const auto* building = findRuntimeBuildingType(state.rules, object)) return std::clamp(building->rot, 0, 127);
    return 0;
}

int runtimeBodyTurnStep(const RuntimeWindowState& state, const WorldObjectInstance& object) {
    const auto* unit = findRuntimeUnitType(state.rules, object);
    return unit ? std::clamp(unit->rot, 0, 127) : 0;
}

int runtimeMoveTurnStep(const RuntimeWindowState& state, const WorldObjectInstance& object) {
    return runtimeBodyTurnStep(state, object);
}

int runtimeAdvanceBodyFacing(const RuntimeWindowState& state, WorldObjectInstance& object,
    int current, int desired) {
    if (const auto* unit = runtimeJumpjetProfile(state, object)) {
        object.bodyFacingClock = {};
        return runtimeTurnFacingToward(current, desired, runtimeJumpjetTurnStep(state, *unit));
    }
    return runtimeAdvanceFacingClock(object.bodyFacingClock, current, desired,
        runtimeBodyTurnStep(state, object), state.tick, state.config.fixedTickHz);
}

bool updateRuntimeMoveFacingToward(
    const RuntimeWindowState& state,
    WorldObjectInstance& object,
    const RuntimeCellPoint& from,
    const RuntimeCellPoint& to
) {
    const int desiredFacing = runtimeMoveTargetFacing(state, object, from, to);
    if (desiredFacing < 0) {
        return true;
    }

    if (!runtimeJumpjetCanEnter(state, object, to)) return false;
    if ((object.kind == WorldObjectKind::Infantry && !runtimeJumpjetProfile(state, object)) || object.facing < 0) {
        object.facing = desiredFacing;
        return true;
    }

    const int nextFacing = runtimeAdvanceBodyFacing(state, object, object.facing, desiredFacing);
    object.facing = nextFacing;
    return nextFacing == desiredFacing;
}

bool updateRuntimeWeaponFacingToward(
    RuntimeWindowState& state,
    WorldObjectInstance& object,
    const WorldObjectInstance& target,
    bool forceFire = false
) {
    if (runtimeObjectIsTurningInTankBunker(state, object)
        || (object.kind == WorldObjectKind::Structure && object.buildAnimTicksRemaining > 0)) return false;
    const RuntimeWeaponProfile aimingProfile = runtimeWeaponProfileForObject(state, object, &target, forceFire);
    const auto* lifecycle = aimingProfile.weapon == nullptr ? nullptr
        : state.rules.findWeaponLifecycleProfile(aimingProfile.weapon->id);
    if (lifecycle != nullptr && lifecycle->omniFire) return true;
    const UnitType* spinningUnit = findRuntimeUnitType(state.rules, object);
    if (spinningUnit != nullptr && spinningUnit->turretSpins) return true;
    const RuntimeCellPoint from = runtimeCellPointForObject(object);
    const RuntimeCellPoint to = runtimeCellPointForObject(target);
    const int desiredFacing =
        runtimeFacingFromDelta(to.x - from.x, to.y - from.y);
    if (desiredFacing < 0) {
        return true;
    }

    if (!runtimeObjectHasTurret(state, object)) {
        if (object.kind == WorldObjectKind::Structure) {
            object.turretFacing = -1;
            return true;
        }
        const int currentFacing =
            object.facing >= 0 ? object.facing : desiredFacing;
        const int nextFacing = runtimeAdvanceBodyFacing(state, object, currentFacing, desiredFacing);
        object.facing = nextFacing;
        object.turretFacing = -1;
        return runtimeFacingAbsDifference(nextFacing, desiredFacing) <= 8;
    }

    const int currentFacing =
        object.turretFacing >= 0
            ? object.turretFacing
            : (object.facing >= 0 ? object.facing : desiredFacing);
    const int nextFacing = runtimeAdvanceFacingClock(object.turretFacingClock,
        currentFacing, desiredFacing, runtimeTurretTurnStep(state, object), state.tick, state.config.fixedTickHz);
    object.turretFacing = nextFacing;
    if (nextFacing != currentFacing) ++state.actionSummary.turretTurnsThisTick;
    if (object.turretFacingClock.active())
        markRuntimeTurretSoundRotation(state, object);

    return nextFacing == desiredFacing;
}

bool updateRuntimeWeaponFacingTowardBody(
    RuntimeWindowState& state,
    WorldObjectInstance& object
) {
    if (runtimeObjectIsTurningInTankBunker(state, object)) return false;
    if (object.kind == WorldObjectKind::Structure) {
        // A fixed defense keeps its last aim. Its placement facing is not a
        // chassis heading to return to after losing or finishing a target.
        object.turretFacingClock = {};
        return true;
    }
    const UnitType* spinningUnit = findRuntimeUnitType(state.rules, object);
    if (spinningUnit != nullptr && spinningUnit->turretSpins) return true;
    if (!runtimeObjectHasTurret(state, object) || object.facing < 0) {
        return true;
    }

    const int desiredFacing = normalizeRuntimeFacing(object.facing);
    if (object.turretFacing < 0) {
        return true;
    }

    const int currentFacing = normalizeRuntimeFacing(object.turretFacing);
    const int nextFacing = runtimeAdvanceFacingClock(object.turretFacingClock,
        currentFacing, desiredFacing, runtimeTurretTurnStep(state, object), state.tick, state.config.fixedTickHz);
    object.turretFacing =
        nextFacing == desiredFacing ? -1 : nextFacing;
    if (nextFacing != currentFacing) ++state.actionSummary.turretTurnsThisTick;
    if (object.turretFacingClock.active())
        markRuntimeTurretSoundRotation(state, object);

    return nextFacing == desiredFacing;
}

bool runtimeObjectHasOperationalPower(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object
);

bool advanceRuntimeIdleWeaponFacings(RuntimeWindowState& state) {
    RuntimePerfTraceScope trace("advanceRuntimeIdleWeaponFacings", state.tick);
    bool changed = false;
    for (WorldObjectInstance& object : state.world.accessObjects()) {
        if (!object.alive
            || runtimeObjectIsTurningInTankBunker(state, object)
            || !runtimeObjectHasTurret(state, object)
            || !runtimeObjectHasOperationalPower(state, object)) {
            continue;
        }

        const UnitType* unit = findRuntimeUnitType(state.rules, object);
        if (unit != nullptr && unit->turretSpins) {
            // Stock UnitClass::UpdateRotation (0x736A95): advance by 8/256
            // of a turn per authored frame, including while hovering/firing.
            if (state.specialMechanismsInitialized
                && state.specialMechanisms.isTemporalFrozen(object.instanceId)) continue;
            const int frames = runtimeDiskLaserAuthoredFrame(state.tick, state.config.fixedTickHz)
                - runtimeDiskLaserAuthoredFrame(state.tick - 1, state.config.fixedTickHz);
            if (frames > 0) {
                object.turretFacing = normalizeRuntimeFacing(
                    (object.turretFacing >= 0 ? object.turretFacing : object.facing) + 8 * frames);
                changed = true;
            }
            continue;
        }
        const auto behaviorIt = state.behaviors.find(object.instanceId);
        if (behaviorIt != state.behaviors.end()
            && behaviorIt->second.kind == RuntimeBehaviorKind::Attack) {
            continue;
        }

        const int previousFacing = object.turretFacing;
        const bool previousClockActive = object.turretFacingClock.active();
        (void)updateRuntimeWeaponFacingTowardBody(state, object);
        changed = changed || object.turretFacing != previousFacing
            || (previousClockActive && !object.turretFacingClock.active());
    }
    return changed;
}

bool runtimeWarheadCanDamageWallTarget(
    const RuntimeWindowState& state,
    const WarheadType* warhead,
    const WorldObjectInstance& target
) {
    if (target.kind != WorldObjectKind::Structure) {
        return true;
    }
    const BuildingType* building =
        findRuntimeBuildingTypeById(state.rules, target.type);
    if (building == nullptr || !building->wall) {
        return true;
    }
    const bool woodWall =
        toLowerAsciiLocal(trimAsciiLocal(building->armor)) == "wood";
    return warhead != nullptr
        && (warhead->wall || (warhead->wood && woodWall));
}

bool runtimeObjectIsPoisonImmune(
    const RuntimeWindowState& state,
    const WorldObjectInstance& target
) {
    if (target.kind == WorldObjectKind::Structure) {
        const BuildingType* building = findRuntimeBuildingTypeById(state.rules, target.type);
        return building != nullptr && building->immuneToPoison;
    }
    const UnitType* unit = findRuntimeUnitType(state.rules, target);
    return unit != nullptr && unit->immuneToPoison;
}

int runtimeAuthoredDamageAgainst(
    const RuntimeWindowState& state,
    const WorldObjectInstance& target,
    long long signedBaseDamage,
    const std::string& warheadId,
    double distanceFromImpact = 0.0,
    double outgoingDamageMultiplier = 1.0,
    bool attachedIvanBuildingBomb = false
) {
    if (signedBaseDamage == 0
        || (signedBaseDamage > 0 && runtimeCarrierAircraftHasDeckProtection(state, target))) {
        return 0;
    }
    const WarheadType* warhead =
        findRuntimeWarheadType(state.rules, warheadId);
    if (signedBaseDamage > 0 && warhead != nullptr && warhead->poison
        && runtimeObjectIsPoisonImmune(state, target)) {
        return 0;
    }
    if (signedBaseDamage > 0
        && !attachedIvanBuildingBomb
        && !runtimeWarheadCanDamageWallTarget(state, warhead, target)) {
        return 0;
    }
    double rangeMultiplier = 1.0;
    if (warhead != nullptr && warhead->cellSpread > 0.0) {
        const double maxDistance = std::max(0.1, warhead->cellSpread);
        const double clampedDistance =
            std::clamp(distanceFromImpact, 0.0, maxDistance);
        const double percentAtMax =
            runtimeWarheadPercentAtMaxFraction(*warhead);
        const double t = clampedDistance / maxDistance;
        rangeMultiplier = 1.0 - ((1.0 - percentAtMax) * t);
    }
    const double armorMultiplier =
        runtimeWarheadArmorMultiplier(warhead, runtimeTargetEffectiveArmor(state, target, warhead));
    const bool targetIsProneInfantry =
        target.kind == WorldObjectKind::Infantry
        && target.prone && !runtimeActiveShield(target, state.rules, warhead);
    const double proneMultiplier =
        signedBaseDamage > 0
            && warhead != nullptr
            && !warhead->radiation
            && !warhead->temporal
            && targetIsProneInfantry
        ? std::max(0.0, warhead->proneDamageMultiplier)
        : 1.0;
    double targetVeteranArmor = 1.0;
    const auto* shieldArmor = runtimeActiveShield(target, state.rules, warhead);
    if (signedBaseDamage > 0 && (!shieldArmor || shieldArmor->applyArmorMult)) {
        targetVeteranArmor = std::max(
            0.01,
            runtimeVeterancyAbilityMultiplier(
                state,
                target,
                VeteranAbility::Stronger
            )
        );
    }
    const double effectiveOutgoingMultiplier =
        std::max(0.0, outgoingDamageMultiplier);
    if (armorMultiplier <= 0.0
        || rangeMultiplier <= 0.0
        || proneMultiplier <= 0.0
        || effectiveOutgoingMultiplier <= 0.0) {
        return 0;
    }
    const double scaledMagnitude =
        std::abs(static_cast<double>(signedBaseDamage))
        * armorMultiplier
        * rangeMultiplier
        * proneMultiplier
        * effectiveOutgoingMultiplier
        / targetVeteranArmor;
    const double maximumMagnitude = static_cast<double>(
        std::numeric_limits<int>::max()
    );
    const int magnitude = !std::isfinite(scaledMagnitude)
            || scaledMagnitude >= maximumMagnitude
        ? std::numeric_limits<int>::max()
        : std::max(0, static_cast<int>(std::round(scaledMagnitude)));
    return signedBaseDamage < 0 ? -magnitude : magnitude;
}

int runtimeWeaponDamageAgainst(
    const RuntimeWindowState& state,
    const WorldObjectInstance& target,
    const WeaponType& weapon,
    double distanceFromImpact = 0.0,
    double outgoingDamageMultiplier = 1.0
) {
    return runtimeAuthoredDamageAgainst(
        state,
        target,
        static_cast<long long>(weapon.damage),
        weapon.warhead,
        distanceFromImpact,
        outgoingDamageMultiplier
    );
}

bool runtimeObjectIsAirTarget(
    const RuntimeWindowState&,
    const WorldObjectInstance& object
) {
    // Locomotor and aircraft type describe flight capability. The current
    // flight authority decides the target domain, including landed choppers,
    // parachuting infantry and suspended ground vehicles.
    return object.kind != WorldObjectKind::Structure && object.airborne;
}

bool runtimeObjectIsTiberiumProof(
    const RuntimeWindowState& state,
    const WorldObjectInstance& object
) {
    const UnitType* unit = findRuntimeUnitType(state.rules, object);
    return (unit != nullptr && unit->tiberiumProof)
        || runtimeVeterancyHasAbility(
            state,
            object,
            VeteranAbility::TiberiumProof
        );
}

bool runtimeProjectileCanHitTarget(
    const RuntimeWindowState& state,
    const RuntimeProjectileEffect& projectile,
    const WorldObjectInstance& target
) {
    if (runtimeCarrierAircraftHasDeckProtection(state, target)) return false;
    const bool airTarget = runtimeObjectIsAirTarget(state, target);
    if (airTarget && !projectile.aa) {
        return false;
    }
    if (!airTarget && !projectile.ag) {
        return false;
    }
    return true;
}

bool runtimeWeaponCanTargetObject(
    const RuntimeWindowState& state,
    const WeaponType& weapon,
    const WorldObjectInstance& target
) {
    if (runtimeCarrierAircraftHasDeckProtection(state, target)) return false;
    if (weapon.drainWeapon) {
        const auto* building = target.kind == WorldObjectKind::Structure
            ? state.rules.findBuildingType(target.type) : nullptr;
        if (!building || !building->drainable) return false;
    }
    const ProjectileType* projectile =
        findRuntimeProjectileType(state.rules, weapon.projectile);
    const bool airTarget = runtimeObjectIsAirTarget(state, target);
    if (projectile == nullptr) {
        return false;
    }
    const bool aa = projectile->aa;
    const bool ag = projectile->ag;
    if (airTarget && !aa) {
        return false;
    }
    // A spawner projectile is a targeting marker (ASWVirt has AG=no).
    // NavalTargeting/LandTargeting still choose the appropriate weapon slot.
    if (!airTarget && !ag && !weapon.spawner) {
        return false;
    }
    const WarheadType* warhead =
        findRuntimeWarheadType(state.rules, weapon.warhead);
    if (warhead != nullptr && warhead->bombDisarm) {
        // DefuseKit has Damage=1, but is a target-specific ability. Without
        // a bomb it must not become an ordinary attack after a rejected
        // engineer repair/capture, in either the cursor or command path.
        return state.specialMechanismsInitialized
            && state.specialMechanisms.timedBombs().contains(target.instanceId);
    }
    if (warhead != nullptr && warhead->ivanBomb
        && target.kind == WorldObjectKind::Structure
        && findRuntimeBuildingTypeById(state.rules, target.type) != nullptr) {
        // Planting is a relationship, independent of ordinary wall/armor damage.
        return true;
    }
    if (runtimeWarheadArmorMultiplier(
            warhead,
            runtimeTargetEffectiveArmor(state, target, warhead)
        ) <= 0.0) {
        return false;
    }
    if (!runtimeWarheadCanDamageWallTarget(state, warhead, target)) {
        return false;
    }
    return true;
}

bool runtimeWeaponCanTargetObjectFromSource(
    const RuntimeWindowState& state,
    const WorldObjectInstance& source,
    const WeaponType& weapon,
    const WorldObjectInstance& target
) {
    const BuildingType* wall = target.kind == WorldObjectKind::Structure
        ? findRuntimeBuildingTypeById(state.rules, target.type) : nullptr;
    const SpawnedMissileProfile* missile = wall != nullptr && wall->wall
        ? runtimeSpawnedMissileProfileForWeapon(state, source, weapon) : nullptr;
    if (missile == nullptr) {
        return runtimeWeaponCanTargetObject(state, weapon, target);
    }
    const bool elite = source.veterancy >= 2;
    const std::string& warheadId = elite ? missile->eliteWarhead : missile->warhead;
    const WarheadType* warhead = findRuntimeWarheadType(state.rules, warheadId);
    if (warhead == nullptr || (elite ? missile->eliteDamage : missile->damage) <= 0) {
        return false;
    }
    // The spawner weapon is a target marker. Only wall-target damage
    // qualification uses the actual missile payload; projectile/domain,
    // range, minimum range, launch cadence and firing authority stay authored.
    WeaponType targetingWeapon = weapon;
    targetingWeapon.warhead = warheadId;
    return runtimeWeaponCanTargetObject(state, targetingWeapon, target);
}

bool runtimeWarheadCanAffectTarget(
    const RuntimeWindowState& state,
    const RuntimeProjectileEffect& projectile,
    const WorldObjectInstance& attacker,
    const WorldObjectInstance& target
) {
    const bool allied =
        runtimeOwnersAreAllied(state, attacker.owner, target.owner);
    if (allied && !projectile.affectsAllies) {
        return target.instanceId == projectile.targetObjectId;
    }
    if (!allied && !projectile.affectsEnemies) {
        return target.instanceId == projectile.targetObjectId;
    }
    return true;
}

int runtimeWeaponCooldownTicks(const RuntimeWindowState& state,
    const WorldObjectInstance& attacker, const WeaponType& weapon) {
    // Retail GetROF (0x6FCFA0): these continuous emitters use the raw delay.
    // Ordinary completed volleys add 0..2 rule frames before ROF bonuses.
    const bool continuous = weapon.sonic || weapon.isRailgun || weapon.useFireParticles || weapon.useSparkParticles;
    const auto seed = runtimeCombatRandomMix(static_cast<std::uint32_t>(state.nextProjectileActorId)
        ^ (static_cast<std::uint64_t>(static_cast<std::uint32_t>(attacker.instanceId)) << 32U)
        ^ runtimeCombatRandomMix(static_cast<std::uint64_t>(state.config.simulationRandomSeed)) ^ 0x524f46ULL);
    const int ordinaryFrames = static_cast<int>(std::min<std::int64_t>(std::numeric_limits<int>::max(),
        static_cast<std::int64_t>(std::max(0, weapon.rof)) + seed % 3));
    const int frames = continuous ? std::max(0, weapon.rof)
        : runtimeRofScaledFrames(ordinaryFrames,
            runtimeVeterancyAbilityMultiplier(state, attacker, VeteranAbility::Rof));
    return runtimeRuleFramesToTicks(std::max(1, frames), state.config.fixedTickHz);
}

int runtimeWeaponCooldownTicks(const WeaponType& weapon, int fixedTickHz = 30) {
    return runtimeRuleFramesToTicks(std::max(1, weapon.rof), fixedTickHz);
}

int runtimeProjectileTravelTicks(const RulesDatabase& rules, const WeaponType& weapon,
    double distanceCells, int fixedTickHz = 30) {
    const int speed = runtimeProjectileSpeedLeptons(weapon,
        rules.findProjectileType(weapon.projectile), rules.getCombatDetailRules().projectileGravity);
    const auto frames = static_cast<int>(std::clamp(std::ceil(
        std::max(0.0, distanceCells) * 256.0 / std::max(1, speed)), 1.0, 36000.0));
    return std::max(1, runtimeRuleFramesToTicks(frames, fixedTickHz));
}

int nextRuntimeProjectileActorId(RuntimeWindowState& state) {
    int candidate = state.nextProjectileActorId;
    if (candidate <= 0 || candidate >= std::numeric_limits<int>::max()) {
        candidate = 1;
    }
    const auto actorIdInUse = [&state](int actorId) {
        for (const RuntimeProjectileEffect& projectile : state.projectiles) {
            if (projectile.actorId == actorId) {
                return true;
            }
        }
        for (const RuntimeProjectileEffect& projectile :
                state.recentExpiredProjectiles) {
            if (projectile.actorId == actorId) {
                return true;
            }
        }
        for (const RuntimeImpactEffect& impact : state.impactEffects) {
            if (impact.projectileActorId == actorId) {
                return true;
            }
        }
        return false;
    };
    const std::size_t maximumAttempts = state.projectiles.size()
        + state.recentExpiredProjectiles.size()
        + state.impactEffects.size()
        + 1U;
    for (std::size_t attempt = 0; attempt < maximumAttempts; ++attempt) {
        if (!actorIdInUse(candidate)) {
            state.nextProjectileActorId =
                candidate >= std::numeric_limits<int>::max() - 1
                    ? 1
                    : candidate + 1;
            return candidate;
        }
        candidate = candidate >= std::numeric_limits<int>::max() - 1
            ? 1
            : candidate + 1;
    }
    // The number of retained actors is tiny relative to the positive int
    // domain, so reaching this path indicates corrupted bookkeeping.  Keep
    // the allocator positive and deterministic instead of overflowing.
    state.nextProjectileActorId = 2;
    return 1;
}

double runtimeProjectileProgress(const RuntimeProjectileEffect& projectile) {
    const int totalTicks = std::max(1, projectile.totalTicks);
    return std::clamp(
        static_cast<double>(projectile.elapsedTicks)
            / static_cast<double>(totalTicks),
        0.0,
        1.0
    );
}

void updateRuntimeProjectileTravelPosition(
    RuntimeProjectileEffect& projectile
) {
    if (projectile.renderIntent == "sonicWave") return;
    projectile.progress = runtimeProjectileProgress(projectile);
    if (projectile.renderIntent == "diskLaserCharge") {
        projectile.currentX = projectile.sourceX;
        projectile.currentY = projectile.sourceY;
        projectile.currentZ = projectile.sourceZ;
        projectile.currentCell = projectile.fromCell;
        projectile.currentLevel = projectile.fromLevel;
        return;
    }
    const double travelProgress =
        projectile.vertical && projectile.acceleration > 0
            ? std::pow(
                projectile.progress,
                1.0 + static_cast<double>(
                    std::clamp(projectile.acceleration, 0, 4)
                )
            )
            : projectile.progress;
    const double sourceX = projectile.hasSourcePosition
        ? projectile.sourceX
        : static_cast<double>(projectile.fromCell.x);
    const double sourceY = projectile.hasSourcePosition
        ? projectile.sourceY
        : static_cast<double>(projectile.fromCell.y);
    const double sourceZ = projectile.hasSourcePosition
        ? projectile.sourceZ
        : static_cast<double>(projectile.fromLevel);
    const double targetX = projectile.hasTargetPosition
        ? projectile.targetX
        : static_cast<double>(projectile.toCell.x);
    const double targetY = projectile.hasTargetPosition
        ? projectile.targetY
        : static_cast<double>(projectile.toCell.y);
    const double targetZ = projectile.hasTargetPosition
        ? projectile.targetZ
        : static_cast<double>(projectile.toLevel);
    const bool verticalBomb = projectile.vertical && !projectile.projectileImageId.empty();
    projectile.currentX = verticalBomb ? sourceX
        : sourceX + ((targetX - sourceX) * travelProgress);
    projectile.currentY = verticalBomb ? sourceY
        : sourceY + ((targetY - sourceY) * travelProgress);
    const double level =
        sourceZ + ((targetZ - sourceZ) * travelProgress);
    double arcHeight = 0.0;
    if (projectile.arcing) {
        arcHeight = 0.35;
    }
    if (projectile.high) {
        arcHeight = std::max(arcHeight, 0.7);
    }
    if (projectile.veryHigh) {
        arcHeight = std::max(arcHeight, 1.1);
    }
    projectile.currentZ =
        level
        + (arcHeight <= 0.0 || verticalBomb
            ? 0.0
            : (std::sin(projectile.progress * 3.14159265358979323846)
                * arcHeight));
    projectile.currentLevel =
        static_cast<int>(std::round(projectile.currentZ));
    projectile.currentCell = {
        static_cast<int>(std::round(projectile.currentX)),
        static_cast<int>(std::round(projectile.currentY))
    };
}

void rememberRuntimeExpiredProjectile(
    RuntimeWindowState& state,
    RuntimeProjectileEffect projectile
) {
    projectile.lifecycle = RuntimeProjectileLifecycleState::Expired;
    projectile.lifecycleState =
        runtimeProjectileLifecycleName(projectile.lifecycle);
    projectile.elapsedTicks = std::max(1, projectile.totalTicks);
    if (!projectile.voxelDebris.enabled
        && !runtimeProjectileIsParasiteLeap(state, projectile)) {
        updateRuntimeProjectileTravelPosition(projectile);
    }
    state.recentExpiredProjectiles.push_back(std::move(projectile));
    constexpr std::size_t maxRecentExpiredProjectiles = 32;
    while (state.recentExpiredProjectiles.size()
        > maxRecentExpiredProjectiles) {
        state.recentExpiredProjectiles.pop_front();
    }
}

double runtimeProjectileAngleDegrees(
    const RuntimeProjectileEffect& projectile
) {
    const double sourceX = projectile.hasSourcePosition
        ? projectile.sourceX
        : static_cast<double>(projectile.fromCell.x);
    const double sourceY = projectile.hasSourcePosition
        ? projectile.sourceY
        : static_cast<double>(projectile.fromCell.y);
    const double dx =
        static_cast<double>(projectile.toCell.x) - sourceX;
    const double dy =
        static_cast<double>(projectile.toCell.y) - sourceY;
    if (std::abs(dx) < 0.0001 && std::abs(dy) < 0.0001) {
        return 0.0;
    }
    double degrees = std::atan2(dy, dx) * 180.0 / 3.14159265358979323846;
    if (degrees < 0.0) {
        degrees += 360.0;
    }
    return degrees;
}

RuntimeProjectileActorSnapshot makeRuntimeProjectileActorSnapshot(
    const RuntimeProjectileEffect& projectile
) {
    RuntimeProjectileActorSnapshot snapshot;
    snapshot.actorId = projectile.actorId;
    snapshot.attackerObjectId = projectile.attackerObjectId;
    snapshot.targetObjectId = projectile.targetObjectId;
    snapshot.owner = projectile.owner;
    snapshot.lifecycleState = projectile.lifecycleState;
    snapshot.weaponId = projectile.weaponId;
    snapshot.weaponSlot = projectile.weaponSlot;
    snapshot.projectileId = projectile.projectileId;
    snapshot.projectileImageId = projectile.projectileImageId;
    snapshot.warheadId = projectile.warheadId;
    snapshot.sourceCell = toRuntimeSnapshotCell(projectile.fromCell);
    snapshot.targetCell = toRuntimeSnapshotCell(projectile.toCell);
    snapshot.currentCell = toRuntimeSnapshotCell(projectile.currentCell);
    snapshot.sourceLevel = projectile.fromLevel;
    snapshot.targetLevel = projectile.toLevel;
    snapshot.currentLevel = projectile.currentLevel;
    snapshot.currentX = projectile.currentX;
    snapshot.currentY = projectile.currentY;
    snapshot.currentZ = projectile.currentZ;
    snapshot.facing = projectile.attackerFacing;
    snapshot.angleDegrees = runtimeProjectileAngleDegrees(projectile);
    snapshot.trailerIntentId = projectile.trailerIntentId;
    snapshot.impactIntentId = projectile.impactAnimId;
    snapshot.warheadImpactIntentId = projectile.warheadImpactIntentId;
    snapshot.spawnTick = projectile.spawnTick;
    snapshot.impactTick = projectile.impactTick;
    return snapshot;
}

std::string runtimeProjectileReplayRenderIntentId(
    const RuntimeProjectileEffect& projectile,
    const std::string& kind
) {
    if (kind == "ProjectileImpact") {
        return "impact:"
            + projectile.impactAnimId
            + ":"
            + projectile.warheadImpactIntentId;
    }
    if (kind == "ProjectileExpired") {
        return "expired:"
            + projectile.impactAnimId
            + ":"
            + projectile.warheadImpactIntentId;
    }
    return projectile.renderIntent
        + ":"
        + projectile.projectileImageId
        + ":"
        + projectile.trailerIntentId;
}

void recordRuntimeProjectileReplayEvent(
    RuntimeWindowState& state,
    const RuntimeProjectileEffect& projectile,
    const std::string& kind
) {
    RuntimeReplayEventSnapshot event;
    event.kind = kind;
    event.objectId = projectile.attackerObjectId;
    event.targetObjectId = projectile.targetObjectId;
    event.projectileActorId = projectile.actorId;
    event.weaponId = projectile.weaponId;
    event.weaponSlot = projectile.weaponSlot;
    event.projectileId = projectile.projectileId;
    event.projectileImageId = projectile.projectileImageId;
    event.warheadId = projectile.warheadId;
    event.lifecycleState = projectile.lifecycleState;
    event.spawnTick = projectile.spawnTick;
    event.impactTick = projectile.impactTick;
    if (kind == "ProjectileExpired") {
        event.expiredTick = state.tick;
    }
    event.renderIntentId =
        runtimeProjectileReplayRenderIntentId(projectile, kind);
    event.renderIntentHash = runtimeStableHashString(event.renderIntentId);
    event.trailerIntentId = projectile.trailerIntentId;
    event.impactIntentId = projectile.impactAnimId;
    event.warheadImpactIntentId = projectile.warheadImpactIntentId;
    event.sourceCell = toRuntimeSnapshotCell(projectile.fromCell);
    event.targetCell = toRuntimeSnapshotCell(projectile.toCell);
    event.currentCell = toRuntimeSnapshotCell(projectile.currentCell);
    recordRuntimeReplayEvent(state, std::move(event));
}

bool runtimeProjectileIsNuclearDeathDetonation(const RuntimeProjectileEffect& projectile) {
    // The reactor borrows the nuclear payload, whose projectile declaration
    // also names the strategic missile sprite. A death explosion has no missile.
    return projectile.deathWeaponRequestId != 0 && projectile.deathWeaponCascadeId != 0
        && !projectile.voxelDebris.enabled
        && toLowerAsciiLocal(projectile.projectileImageId) == "nkmsldn";
}

bool runtimeProjectileIsCrashDeathDetonation(const RuntimeProjectileEffect& projectile) {
    // BlimpBombEffect supplies a crash's payload, not an extra dropped bomb.
    // Explicit bomb attacks and voxel wreck/debris presentation remain visible.
    return projectile.deathWeaponRequestId != 0 && projectile.deathWeaponCascadeId != 0
        && !projectile.voxelDebris.enabled && projectile.vertical
        && toLowerAsciiLocal(projectile.weaponId) == "blimpbombeffect";
}

RuntimeProjectileRenderActor makeRuntimeProjectileRenderActor(
    const RuntimeProjectileEffect& projectile,
    const RulesDatabase* rules = nullptr,
    const ArtDatabase* art = nullptr
) {
    RuntimeProjectileRenderActor actor;
    actor.actorId = projectile.actorId;
    actor.hasFlightDirection = projectile.homingInitialized;
    actor.flightDirectionX = std::cos(projectile.homingYaw) * std::cos(projectile.homingPitch);
    actor.flightDirectionY = std::sin(projectile.homingYaw) * std::cos(projectile.homingPitch);
    actor.flightDirectionZ = std::sin(projectile.homingPitch) * runtimeMissileLevelsPerCell;
    actor.voxelDebris = projectile.voxelDebris.enabled;
    for (int i = 0; i < 4; ++i) actor.debrisOrientation[i] = projectile.voxelDebris.orientation[i];
    actor.targetObjectId = projectile.targetObjectId;
    actor.sourceAnchorObjectId = projectile.sourceAnchorObjectId;
    actor.shrapnel = projectile.shrapnel;
    actor.owner = projectile.owner;
    actor.projectileId = projectile.projectileId;
    actor.projectileImageId = projectile.projectileImageId;
    actor.weaponId = projectile.weaponId;
    // Muzzle flashes are independent short-lived impact actors. Keeping the
    // weapon animation on the projectile would redraw and loop it for the
    // projectile's entire flight.
    actor.weaponAnimId.clear();
    actor.warheadId = projectile.warheadId;
    actor.trailerAnimId = projectile.trailerAnimId;
    actor.impactAnimId = projectile.impactAnimId;
    actor.particleId = projectile.particleId;
    actor.lifecycleState = projectile.lifecycleState;
    actor.renderIntent = projectile.renderIntent;
    actor.fromX = projectile.hasSourcePosition
        ? projectile.sourceX
        : static_cast<double>(projectile.fromCell.x);
    actor.fromY = projectile.hasSourcePosition
        ? projectile.sourceY
        : static_cast<double>(projectile.fromCell.y);
    actor.fromLevel = projectile.hasSourcePosition
        ? projectile.sourceZ
        : static_cast<double>(projectile.fromLevel);
    actor.sourceScreenOffsetX = projectile.sourceScreenOffsetX;
    actor.sourceNativeFixedX = projectile.sourceNativeFixedX;
    actor.sourceScreenOffsetY = projectile.sourceScreenOffsetY;
    actor.sourceNativeFixedY = projectile.sourceNativeFixedY;
    actor.toX = projectile.hasTargetPosition
        ? projectile.targetX
        : static_cast<double>(projectile.toCell.x);
    actor.toY = projectile.hasTargetPosition
        ? projectile.targetY
        : static_cast<double>(projectile.toCell.y);
    actor.toLevel = projectile.hasTargetPosition
        ? projectile.targetZ
        : static_cast<double>(projectile.toLevel);
    actor.currentX = projectile.currentX;
    actor.currentY = projectile.currentY;
    actor.currentLevel = projectile.currentZ;
    actor.progress = projectile.progress;
    actor.totalTicks = projectile.totalTicks;
    actor.remainingTicks = projectile.remainingTicks;
    actor.frameIndex = projectile.elapsedTicks;
    actor.facing = projectile.renderIntent == "sonicWave" ? projectile.rot : projectile.attackerFacing;
    actor.hasCurrentPosition = true;
    actor.arcing = projectile.arcing;
    actor.high = projectile.high;
    actor.veryHigh = projectile.veryHigh;
    actor.shadow = projectile.shadow;
    actor.bright = projectile.bright;
    actor.laser = projectile.laser;
    actor.houseColorLaser = projectile.houseColorLaser;
    actor.electricBolt = projectile.electricBolt;
    actor.alternateElectricColor = projectile.alternateElectricColor;
    actor.electricColor = projectile.electricColor;
    actor.laserThickness = projectile.laserThickness;
    actor.animates = projectile.animates;
    actor.cluster = projectile.cluster;
    const ProjectileType* authoredProjectile = rules == nullptr
        ? nullptr
        : rules->findProjectileType(projectile.projectileId);
    actor.translucency = authoredProjectile == nullptr
        ? 0
        : std::clamp(authoredProjectile->translucency, 0, 100);
    int trailerSeparation = authoredProjectile == nullptr
        ? 0
        : std::max(0, authoredProjectile->trailerSeperation);
    if (trailerSeparation <= 0 && art != nullptr) {
        const std::string artId = projectile.projectileImageId.empty()
            ? projectile.projectileId
            : projectile.projectileImageId;
        const ArtType* projectileArt = art->findArtType(artId);
        trailerSeparation = projectileArt == nullptr
            ? 0
            : std::max(0, projectileArt->trailerSeperation);
    }
    actor.trailerCadenceManaged = !projectile.trailerAnimId.empty()
        && trailerSeparation > 0;
    if (!runtimeMissileExhaustImage(authoredProjectile, projectile.projectileImageId).empty()) {
        actor.trailerAnimId.clear();
        actor.trailerCadenceManaged = true;
        if (runtimeMissileExhaustImage(authoredProjectile, projectile.projectileImageId) == "NUKEPUFF")
            actor.frameIndex = 0; // Frame 1 is the original empty shadow frame.
    }
    return actor;
}

int runtimeImpactAnimationFrameForStep(const RuntimeImpactEffect& impact, int step);
std::string runtimeWeaponAnimForFacing(const WeaponType& weapon, int firingFacing);

std::optional<std::array<double, 3>> runtimeTransportMuzzleAnchor(
    const RuntimeWindowState& state, int shooterId
) {
    const auto* source = findRuntimeObjectByIdIncludingInactive(state, shooterId);
    if (!source || source->health <= 0) return std::nullopt;
    const WorldObjectInstance* anchor = source;
    if (!source->alive) {
        if (source->mission != "InsideTransport") return std::nullopt;
        anchor = nullptr;
        for (const auto& host : state.world.getObjects()) {
            if (host.alive && host.health > 0 && std::find(host.transportPassengerIds.begin(),
                    host.transportPassengerIds.end(), shooterId) != host.transportPassengerIds.end()) {
                anchor = &host; break;
            }
        }
        if (!anchor) return std::nullopt;
    }
    const auto subCell = worldObjectSubCellOffset(*anchor);
    return std::array<double, 3>{runtimeObjectRenderX(*anchor) + subCell.x,
        runtimeObjectRenderY(*anchor) + subCell.y, runtimeDrawLevelForObject(*anchor)};
}

RuntimeImpactRenderActor makeRuntimeImpactRenderActor(
    const RuntimeImpactEffect& impact
) {
    RuntimeImpactRenderActor actor;
    actor.actorId = impact.projectileActorId;
    actor.projectileActorId = impact.projectileActorId;
    actor.owner = impact.owner;
    actor.cellX = impact.cell.x;
    actor.cellY = impact.cell.y;
    actor.attackerObjectId = impact.attackerObjectId;
    actor.targetObjectId = impact.targetObjectId;
    actor.animId = impact.animId;
    actor.projectileImageId = impact.projectileImageId.empty() && impact.renderIntent == "missileExhaust"
        ? impact.projectileId : impact.projectileImageId;
    actor.particleId = impact.particleId;
    actor.weaponId = impact.weaponId;
    actor.warheadId = impact.warheadId;
    actor.lifecycleState = impact.lifecycleState;
    actor.renderIntent = impact.renderIntent;
    // Impact frames share the projectile endpoint as their global canvas
    // centre. A foot anchor shifts ground flashes/flames by their canvas
    // height; body-targeted impacts refine this same anchor in the renderer.
    actor.centerOnAnchor = impact.targetIsStructure
        || impact.renderIntent == "warheadImpact"
        || impact.renderIntent == "bombImpact"
        || impact.renderIntent == "deathImpact"
        || impact.lifecycleState == "MindControlImpact"
        || impact.lifecycleState == "ChronoWarpOut"
        || impact.lifecycleState == "ChronoWarpIn" || impact.lifecycleState == "ChronoReinforcementIn"
        || impact.lifecycleState == "TemporalErase"
        || impact.renderIntent == "buildingDestruction"
        || impact.renderIntent == "unitDestruction"
        || impact.renderIntent == "oreGather"
        || impact.renderIntent == "refinerySmoke"
        || impact.renderIntent == "weaponAnim"
        || impact.renderIntent == "missileExhaust"
        || impact.renderIntent == "superWeaponEffect";
    actor.x = impact.hasWorldPosition
        ? impact.worldX
        : static_cast<double>(impact.cell.x);
    actor.y = impact.hasWorldPosition
        ? impact.worldY
        : static_cast<double>(impact.cell.y);
    actor.level = impact.hasWorldPosition ? impact.worldLevel : impact.level;
    actor.screenOffsetX = impact.screenOffsetX;
    actor.nativeFixedX = impact.nativeFixedX;
    actor.screenOffsetY = impact.screenOffsetY;
    actor.nativeFixedY = impact.nativeFixedY;
    actor.bodyCenterAnchored = impact.bodyCenterAnchored;
    actor.bodyCenterPresentation = impact.bodyCenterPresentation;
    actor.bodyCenterSpriteOffsetY = impact.bodyCenterSpriteOffsetY;
    actor.totalTicks = impact.totalTicks;
    actor.remainingTicks = impact.remainingTicks;
    actor.fadeTicks = impact.lifecycleState == "InfantryDeath"
        ? std::max(1, (impact.totalTicks - impact.animationSequenceSteps
            * impact.animationFrameDelayTicks) / 2) : 0;
    actor.frameIndex = impact.frameIndex;
    if (impact.lifecycleState == "InfantryDeath") {
        actor.renderIntent = "infantryDeath";
        actor.frameIndex = impact.animationStartFrame + std::clamp(
            (impact.totalTicks - impact.remainingTicks)
                / std::max(1, impact.animationFrameDelayTicks),
            0, std::max(0, impact.animationSequenceSteps - 1));
    }
    if (impact.lifecycleState == "VirusDeath") {
        actor.animId = impact.deferredParticleAnimId;
        actor.renderIntent = "unitDestruction";
        actor.centerOnAnchor = true;
        actor.frameIndex = runtimeImpactAnimationFrameForStep(impact,
            (impact.totalTicks - impact.remainingTicks) / std::max(1, impact.animationFrameDelayTicks));
    }
    if (impact.lifecycleState == "SquidSplash") {
        actor.animId = impact.warheadImpactIntentId;
        actor.renderIntent = "squidSplash";
        actor.centerOnAnchor = true;
        actor.frameIndex = runtimeImpactAnimationFrameForStep(impact,
            (impact.totalTicks - impact.remainingTicks) / std::max(1, impact.animationFrameDelayTicks));
    }
    if (impact.lifecycleState == "GrindingAnimation"
        || impact.lifecycleState == "GrindingAnimationQueued") {
        actor.renderIntent = impact.lifecycleState == "GrindingAnimation"
            ? "grinderCycle" : "grinderCycleQueued";
        actor.frameIndex = runtimeImpactAnimationFrameForStep(impact,
            (impact.totalTicks - impact.remainingTicks) / std::max(1, impact.animationFrameDelayTicks));
    }
    actor.facing = impact.facing;
    actor.damage = impact.damage;
    actor.bright = impact.bright;
    return actor;
}

const std::vector<RuntimeProjectileRenderActor>*
runtimeProjectileRenderActorsForRender(const RuntimeWindowState& state) {
    if (state.projectiles.empty()) {
        return nullptr;
    }

    RuntimeSnapshotCache& cache = state.snapshotCache;
    cache.projectileRenderActors.clear();
    cache.projectileRenderActors.reserve(state.projectiles.size());
    for (const RuntimeProjectileEffect& projectile : state.projectiles) {
        if (runtimeProjectileIsNuclearDeathDetonation(projectile)
            || runtimeProjectileIsCrashDeathDetonation(projectile)) continue;
        cache.projectileRenderActors.push_back(
            makeRuntimeProjectileRenderActor(
                projectile,
                &state.rules,
                &state.art
            )
        );
    }
    ++cache.stats.projectileRenderActorMaterializations;
    cache.stats.lastProjectileRenderActors =
        static_cast<int>(cache.projectileRenderActors.size());
    return &cache.projectileRenderActors;
}

void stopRuntimeChronosphereSelectionAudio(RuntimeWindowState& state, bool decay = true);
void startRuntimeChronosphereSelectionAudio(RuntimeWindowState& state,
    const RuntimeImpactEffect& marker, std::uint64_t nowMilliseconds);
#include "ui/selection/RuntimeChronosphereSelection.inl"
#include "ui/selection/RuntimeChronosphereSelectionAudio.inl"

const std::vector<RuntimeImpactRenderActor>* runtimeImpactRenderActorsForRender(
    const RuntimeWindowState& state
) {

    RuntimeSnapshotCache& cache = state.snapshotCache;
    cache.impactRenderActors.clear();
    cache.impactRenderActors.reserve(state.impactEffects.size());
    for (const RuntimeImpactEffect& impact : state.impactEffects) {
        if (!runtimeChronosphereSelectionVisibleToLocalOwner(state, impact)) continue;
        if (impact.lifecycleState == "GrindingAnimationQueued"
            || (impact.lifecycleState == "GrindingAnimation" && impact.remainingTicks<=0)) continue;
        RuntimeImpactRenderActor actor = makeRuntimeImpactRenderActor(impact);
        // Snapshot transfer deliberately omits cached presentation fields.
        // Dead objects retain their type identity, so rebuild the corpse image
        // without changing authoritative state or restarting its timeline.
        if (impact.lifecycleState == "InfantryDeath" && actor.animId.empty()) {
            const WorldObjectInstance* object = findRuntimeObjectByIdIncludingInactive(
                state, impact.targetObjectId);
            const UnitType* unit = object == nullptr ? nullptr
                : state.rules.findUnitType("InfantryType", object->type);
            if (unit != nullptr) {
                const ArtType* art = runtimeArtTypeForObject(state, *object);
                if (art == nullptr) art = state.art.findArtType(unit->id);
                if (art != nullptr) actor.animId = art->id;
            }
        }
        if (impact.lifecycleState == "UnitDestruction" && actor.animId.empty()) {
            // Network snapshots omit cached images. Rebuild the special
            // infantry death from its lethal warhead and original unit type.
            const auto* object = findRuntimeObjectByIdIncludingInactive(state, impact.targetObjectId);
            const auto* unit = object && object->kind == WorldObjectKind::Infantry
                ? state.rules.findUnitType("InfantryType", object->type) : nullptr;
            const auto* warhead = state.rules.findWarheadType(impact.warheadId);
            if (unit && !unit->notHuman && warhead) {
                const auto& animation = state.rules.getInfantryDeathAnim(warhead->infDeath);
                if (!animation.empty() && state.art.findArtType(animation)) {
                    actor.animId = animation;
                    actor.renderIntent = "unitDestruction";
                    actor.centerOnAnchor = true;
                    actor.frameIndex = runtimeImpactAnimationFrameForStep(impact,
                        (impact.totalTicks - impact.remainingTicks) / std::max(1, impact.animationFrameDelayTicks));
                }
            }
        }
        if (impact.lifecycleState == "ChronoWarpOut" || impact.lifecycleState == "ChronoWarpIn" || impact.lifecycleState == "ChronoReinforcementIn") {
            const auto& rules = state.rules.getSpecialMechanismRules();
            actor.animId = impact.lifecycleState == "ChronoReinforcementIn" ? rules.warpInAnim : rules.warpOutAnim;
            actor.renderIntent = "chronoWarp";
            actor.centerOnAnchor = true;
        }
        if (impact.lifecycleState == "OccupantMuzzle" || impact.lifecycleState == "TransportMuzzle") {
            const WeaponType* weapon = findRuntimeWeaponType(state.rules, impact.weaponId);
            if (impact.lifecycleState == "TransportMuzzle") {
                const auto anchor = runtimeTransportMuzzleAnchor(state, impact.attackerObjectId);
                if (!anchor) continue;
                actor.x += (*anchor)[0] - impact.muzzleAnchorX;
                actor.y += (*anchor)[1] - impact.muzzleAnchorY;
                actor.level += (*anchor)[2] - impact.muzzleAnchorLevel;
                if (actor.animId.empty() && weapon) {
                    actor.animId = runtimeWeaponAnimForFacing(*weapon, impact.muzzleFacing);
                    if (actor.animId.empty()) actor.animId = trimAsciiLocal(weapon->openToppedAnim);
                }
            } else if (actor.animId.empty() && weapon) actor.animId = trimAsciiLocal(weapon->occupantAnim);
            actor.renderIntent = "weaponAnim";
            actor.centerOnAnchor = true;
            if (impact.animationSequenceSteps > 0) actor.frameIndex = runtimeImpactAnimationFrameForStep(impact,
                std::max(0, impact.totalTicks - impact.remainingTicks - 1)
                    / std::max(1, impact.animationFrameDelayTicks));
        }
        if (impact.lifecycleState == "GattlingMuzzle" && impact.animationSequenceSteps > 0) {
            actor.frameIndex = runtimeImpactAnimationFrameForStep(impact,
                std::max(0, impact.totalTicks - impact.remainingTicks - 1)
                    / std::max(1, impact.animationFrameDelayTicks));
        }
        cache.impactRenderActors.push_back(std::move(actor));
    }
#include "simulation/mod_extensions/RuntimeModExtensionRenderActors.inl"
#include "render/effects/RuntimeDiskDrainRenderActors.inl"
    if (const auto marker = runtimeLocalChronosphereRenderActor(state)) {
        cache.impactRenderActors.push_back(*marker);
    }
    ++cache.stats.impactRenderActorMaterializations;
    cache.stats.lastImpactRenderActors =
        static_cast<int>(cache.impactRenderActors.size());
    return &cache.impactRenderActors;
}

const std::vector<RuntimeProjectileActorSnapshot>&
materializeRuntimeProjectileActorSnapshots(
    const RuntimeWindowState& state
) {
    RuntimeSnapshotCache& cache = state.snapshotCache;
    cache.projectileSnapshots.clear();
    cache.projectileSnapshots.reserve(
        state.projectiles.size() + state.recentExpiredProjectiles.size()
    );
    for (const RuntimeProjectileEffect& projectile : state.projectiles) {
        cache.projectileSnapshots.push_back(
            makeRuntimeProjectileActorSnapshot(projectile)
        );
    }
    for (const RuntimeProjectileEffect& projectile :
            state.recentExpiredProjectiles) {
        cache.projectileSnapshots.push_back(
            makeRuntimeProjectileActorSnapshot(projectile)
        );
    }
    ++cache.stats.projectileSnapshotMaterializations;
    cache.stats.lastProjectileSnapshotActors =
        static_cast<int>(cache.projectileSnapshots.size());
    gRuntimeProjectileActorSnapshots = cache.projectileSnapshots;
    return cache.projectileSnapshots;
}

const std::vector<RuntimeReplayEventSnapshot>&
materializeRuntimeReplayEventSnapshots(const RuntimeWindowState& state) {
    RuntimeSnapshotCache& cache = state.snapshotCache;
    if (cache.replayEventSnapshotsDirty
        || cache.replayEventSnapshots.size()
            != state.recentReplayEvents.size()) {
        cache.replayEventSnapshots.clear();
        cache.replayEventSnapshots.reserve(state.recentReplayEvents.size());
        cache.replayEventSnapshots.insert(
            cache.replayEventSnapshots.end(),
            state.recentReplayEvents.begin(),
            state.recentReplayEvents.end()
        );
        cache.replayEventSnapshotsDirty = false;
        ++cache.stats.replayEventSnapshotMaterializations;
    }
    cache.stats.lastReplayEvents =
        static_cast<int>(cache.replayEventSnapshots.size());
    gRuntimeReplayEventSnapshots = cache.replayEventSnapshots;
    return cache.replayEventSnapshots;
}

const RuntimeUiStateSnapshot& materializeRuntimeUiStateSnapshot(
    const RuntimeWindowState& state
) {
    RuntimeSnapshotCache& cache = state.snapshotCache;
    RuntimeUiStateSnapshot snapshot;
    snapshot.specialMechanismStateHash =
        state.specialMechanismsInitialized
            ? state.specialMechanisms.stateHash()
            : 0;
    snapshot.superWeaponStateHash =
        state.superWeaponsInitialized
            ? state.superWeapons.stateHash()
            : 0;
    const std::string snapshotOwner = toLowerAsciiLocal(
        trimAsciiLocal(state.economy.owner)
    );
    for (const SuperWeaponSidebarSnapshot& superWeapon :
            state.superWeapons.sidebarSnapshots()) {
        if (!snapshotOwner.empty()
            && toLowerAsciiLocal(trimAsciiLocal(superWeapon.owner))
                != snapshotOwner) {
            continue;
        }
        ++snapshot.superWeaponCount;
        if (superWeapon.state == SuperWeaponRuntimeState::Ready) {
            ++snapshot.superWeaponReadyCount;
        }
    }
    for (const SuperWeaponSidebarSnapshot& superWeapon :
            state.superWeapons.sidebarSnapshots()) {
        if (!snapshotOwner.empty()
            && toLowerAsciiLocal(trimAsciiLocal(superWeapon.owner))
                != snapshotOwner) {
            continue;
        }
        if (superWeapon.state == SuperWeaponRuntimeState::SelectingTarget
            || superWeapon.state == SuperWeaponRuntimeState::AwaitingSecondTarget) {
            snapshot.selectedSuperWeaponId = superWeapon.superWeaponId;
            snapshot.selectedSuperWeaponState =
                SuperWeaponSystem::stateName(superWeapon.state);
            snapshot.selectedSuperWeaponProgress = superWeapon.progress;
            snapshot.selectedSuperWeaponRemainingTicks =
                superWeapon.remainingTicks;
            break;
        }
    }
    snapshot.cash = state.economy.credits;
    snapshot.resourceStorageUnits = state.economy.storedResourceUnits;
    snapshot.resourceStorageCapacity = state.economy.resourceStorageCapacity;
    snapshot.resourceStorageValue = state.economy.storedResourceValue;
    snapshot.resourceStorageGemUnits =
        state.economy.storedResourceGemUnits;
    snapshot.powerProduced = state.economy.powerProduced;
    snapshot.powerUsed = state.economy.powerUsed;
    snapshot.powerNet = state.economy.powerProduced - state.economy.powerUsed;
    snapshot.powerDrain = state.economy.powerUsed;
    snapshot.powerSurplus = std::max(0, snapshot.powerNet);
    snapshot.powerDeficit = std::max(0, -snapshot.powerNet);
    snapshot.lowPower = snapshot.powerNet < 0;
    snapshot.radarAvailable = runtimeRadarAvailable(state);
    snapshot.radarLowPower = runtimeHasOwnedRadar(state) && !runtimeRadarHasPower(state);
    snapshot.radarStatus = runtimeRadarStatusText(state);
    std::uint64_t projectedActiveSerial =
        std::numeric_limits<std::uint64_t>::max();
    snapshot.productionLanes.reserve(runtimeProductionLanes.size());
    for (const RuntimeProductionLane lane : runtimeProductionLanes) {
        const RuntimeProductionLaneState& laneState =
            state.economy.localProductionLanes.lanes[
                runtimeProductionLaneIndex(lane)
            ];
        RuntimeProductionLaneUiSnapshot laneSnapshot;
        laneSnapshot.lane = std::string(runtimeProductionLaneName(lane));
        laneSnapshot.queuedCount = static_cast<int>(laneState.queued.size());
        laneSnapshot.occupancy = runtimeProductionLaneOccupancy(
            state.economy.localProductionLanes,
            lane
        );
        laneSnapshot.onHold = laneState.onHold;
        laneSnapshot.hasActive = laneState.active.has_value();
        if (laneState.active.has_value()) {
            const RuntimeProductionLaneOrder& active = *laneState.active;
            laneSnapshot.activeSerial = active.serial;
            laneSnapshot.activeTypeId = active.itemKey;
            laneSnapshot.activeRemainingTicks = active.remainingTicks;
            laneSnapshot.activeProgress = active.cost > 0
                ? static_cast<double>(active.creditsSpent)
                    / static_cast<double>(std::max(1, active.cost))
                : static_cast<double>(active.zeroCostProgressMicros)
                    / 1000000.0;
            if (active.serial < projectedActiveSerial) {
                projectedActiveSerial = active.serial;
                snapshot.hasActiveProduction = true;
                snapshot.activeProductionTypeId = active.itemKey;
                snapshot.activeProductionProgress =
                    laneSnapshot.activeProgress;
                snapshot.activeProductionRemainingTicks =
                    active.remainingTicks;
                const std::optional<RuntimeProductionCatalogAdapter> catalog =
                    runtimeProductionCatalogLookup(state, active.itemKey);
                snapshot.activeProductionKind =
                    catalog.has_value() && catalog->item != nullptr
                        ? runtimeBuildKindName(catalog->item->kind)
                        : laneSnapshot.lane;
            }
        }
        laneSnapshot.hasReady = laneState.ready.has_value();
        if (laneState.ready.has_value()) {
            laneSnapshot.readySerial = laneState.ready->serial;
            laneSnapshot.readyTypeId = laneState.ready->itemKey;
        }
        snapshot.buildQueueSize += laneSnapshot.queuedCount;
        if (lane == RuntimeProductionLane::Structures
            || lane == RuntimeProductionLane::Armory) {
            snapshot.structureQueueSize += laneSnapshot.queuedCount;
        } else {
            snapshot.unitQueueSize += laneSnapshot.queuedCount;
        }
        snapshot.productionLanes.push_back(std::move(laneSnapshot));
    }
    const std::optional<RuntimeSelectedPlacement> selectedPlacement =
        runtimeSelectedPlacement(state);
    snapshot.placementReady = selectedPlacement.has_value();
    snapshot.placementTypeId =
        selectedPlacement.has_value()
            ? selectedPlacement->order.itemKey
            : std::string();
    snapshot.readyState = runtimeOldestReadyPlacement(state).has_value();
    snapshot.readyProgress = snapshot.readyState ? 1.0 : 0.0;
    if (selectedPlacement.has_value()) {
        snapshot.selectedPlacementLane = std::string(
            runtimeProductionLaneName(selectedPlacement->lane)
        );
        snapshot.selectedPlacementSerial = selectedPlacement->order.serial;
    }

    for (int objectId : state.selectedObjectIds) {
        const WorldObjectInstance* object = findObjectById(state, objectId);
        if (object == nullptr || !object->alive) {
            continue;
        }
        const RuntimeCachedCapabilityProfile& cached =
            runtimeCachedCapabilityProfileForObject(state, *object);
        snapshot.selectedObjectId = object->instanceId;
        snapshot.selectedTypeId = object->type;
        snapshot.selectedStrength = object->health;
        snapshot.selectedMaxStrength = runtimeMaxHealthForObject(
            state,
            *object
        );
        snapshot.selectedPip = cached.ui.pip;
        snapshot.selectedPipScale =
            toLowerAsciiLocal(cached.ui.pipScale) == "tiberium"
                && runtimeObjectHidesRefineryStoragePips(state, *object)
            ? std::string() : cached.ui.pipScale;
        snapshot.selectedCameoId = cached.ui.cameoId;
        snapshot.selectedPipResourceId = cached.ui.pip;
        snapshot.selectedPipScaleResourceId = snapshot.selectedPipScale;
        snapshot.selectedCameoResourceId = cached.ui.cameoId;
        const UnitType* ammoRules = runtimeAmmoRulesForObject(
            state.rules,
            *object
        );
        const BuildingType* buildingAmmoRules =
            object->kind == WorldObjectKind::Structure
            ? findRuntimeBuildingTypeById(state.rules, object->type)
            : nullptr;
        const int ammoCapacity = ammoRules != nullptr
                && ammoRules->ammo >= 0
            ? ammoRules->ammo
            : runtimeInfantryServiceAmmoCapacity(buildingAmmoRules);
        if (ammoCapacity >= 0) {
            snapshot.selectedAmmoCapacity = ammoCapacity;
            snapshot.selectedAmmoCurrent = std::clamp(
                object->currentAmmo,
                0,
                ammoCapacity
            );
        }
        if (toLowerAsciiLocal(cached.ui.pipScale) == "ammo"
            && snapshot.selectedAmmoCapacity >= 0) {
            snapshot.selectedPipTotal = snapshot.selectedAmmoCapacity;
            snapshot.selectedPipFilled = snapshot.selectedAmmoCurrent;
            snapshot.selectedPipValue = snapshot.selectedAmmoCurrent;
        } else if (toLowerAsciiLocal(snapshot.selectedPipScale) == "tiberium") {
            if (runtimeObjectIsHarvester(state, *object)) {
                const int capacity =
                    std::max(1, runtimeHarvesterCargoCapacity(state, *object));
                snapshot.selectedPipTotal = capacity;
                const auto taskIt =
                    state.harvesterTasks.find(object->instanceId);
                if (taskIt != state.harvesterTasks.end()) {
                    snapshot.selectedPipFilled =
                        std::clamp(taskIt->second.cargoUnits, 0, capacity);
                    snapshot.selectedPipValue =
                        std::max(0, taskIt->second.cargoValue);
                    snapshot.selectedPipGemUnits =
                        std::clamp(
                            taskIt->second.cargoGemUnits,
                            0,
                            snapshot.selectedPipFilled
                        );
                    if (taskIt->second.cargoCapacity > 0) {
                        snapshot.selectedPipTotal =
                            std::max(1, taskIt->second.cargoCapacity);
                        snapshot.selectedPipFilled =
                            std::clamp(
                                taskIt->second.cargoUnits,
                                0,
                                snapshot.selectedPipTotal
                            );
                        snapshot.selectedPipGemUnits =
                            std::clamp(
                                taskIt->second.cargoGemUnits,
                                0,
                                snapshot.selectedPipFilled
                            );
                    }
                }
            } else {
                const int storageCapacity =
                    runtimeResourceStorageCapacityForObject(state, *object);
                if (storageCapacity > 0) {
                    snapshot.selectedPipTotal = storageCapacity;
                    snapshot.selectedPipFilled =
                        runtimeResourceStorageFilledForCapacity(
                            state,
                            storageCapacity
                        );
                    snapshot.selectedPipValue =
                        std::max(0, state.economy.storedResourceValue);
                    snapshot.selectedPipGemUnits =
                        std::clamp(
                            runtimeResourceStorageUnitsForCapacity(
                                state,
                                state.economy.storedResourceGemUnits,
                                storageCapacity
                            ),
                            0,
                            snapshot.selectedPipFilled
                        );
                }
            }
        }

        if (state.specialMechanismsInitialized) {
            const auto parentIt =
                state.specialMechanisms.carrierParents().find(
                    object->instanceId
                );
            if (parentIt != state.specialMechanisms.carrierParents().end()) {
                const CarrierParentState& parent = parentIt->second;
                snapshot.selectedSpawnTypeId = parent.childType;
                snapshot.selectedSpawnCapacity = std::max(0, parent.capacity);
                for (const auto& [slot, childId] : parent.childBySlot) {
                    (void)slot;
                    if (childId < 0) {
                        continue;
                    }
                    const auto childIt =
                        state.specialMechanisms.carrierChildren().find(childId);
                    if (childIt == state.specialMechanisms.carrierChildren().end()
                        || childIt->second.phase == CarrierChildPhase::Destroyed) {
                        continue;
                    }
                    if (childIt->second.phase == CarrierChildPhase::Docked) {
                        ++snapshot.selectedSpawnReady;
                    } else {
                        ++snapshot.selectedSpawnDeployed;
                    }
                }
                for (const auto& [slot, readyTick] : parent.slotReadyTick) {
                    const auto childIt = parent.childBySlot.find(slot);
                    if (childIt != parent.childBySlot.end() && childIt->second >= 0) {
                        continue;
                    }
                    snapshot.selectedSpawnReloadRemainingTicks = std::max(
                        snapshot.selectedSpawnReloadRemainingTicks,
                        std::max(0, readyTick - state.tick)
                    );
                }
            }
        }
        break;
    }

    cache.uiSnapshot = std::move(snapshot);
    ++cache.stats.uiSnapshotMaterializations;
    gRuntimeUiStateSnapshot = cache.uiSnapshot;
    return cache.uiSnapshot;
}

const RuntimeMapFactsContextSnapshot& materializeRuntimeMapFactsContextSnapshot(
    const RuntimeWindowState& state
) {
    RuntimeSnapshotCache& cache = state.snapshotCache;
    RuntimeMapFactsContextSnapshot snapshot;
    snapshot.available = state.mapFactsLoaded;
    snapshot.status = state.mapQueryStatus;
    snapshot.width = state.mapFacts.width;
    snapshot.height = state.mapFacts.height;
    snapshot.cellCount = state.mapFacts.cells.size();
    snapshot.structureAnchorCount = state.mapFacts.structureAnchors.size();
    snapshot.resourceCellCount = state.mapFacts.resourceCellCount;
    for (const TerrainCell& terrain : state.world.getTerrainCells()) {
        if (!terrain.hasOverlay
            || (!terrain.overlayIsOre && !terrain.overlayIsGem)) {
            continue;
        }
        ++snapshot.currentResourceCellCount;
        if (terrain.overlayIsGem) {
            ++snapshot.currentGemCellCount;
        } else {
            ++snapshot.currentOreCellCount;
        }
    }
    snapshot.initialOreCellsSeeded = state.initialOreCellsSeeded;
    snapshot.initialOreCellsDensified = state.initialOreCellsDensified;
    cache.mapFactsSnapshot = std::move(snapshot);
    ++cache.stats.mapFactsSnapshotMaterializations;
    cache.stats.mapFactsContextReused = state.mapFactsLoaded;
    gRuntimeMapFactsContextSnapshot = cache.mapFactsSnapshot;
    return cache.mapFactsSnapshot;
}

const RuntimePathQueueStatsSnapshot& materializeRuntimePathQueueStatsSnapshot(
    const RuntimeWindowState& state
) {
    RuntimeSnapshotCache& cache = state.snapshotCache;
    cache.pathStatsSnapshot = state.lastPathQueueStats;
    ++cache.stats.pathStatsSnapshotMaterializations;
    gRuntimePathQueueStatsSnapshot = cache.pathStatsSnapshot;
    return cache.pathStatsSnapshot;
}

void refreshRuntimePublicSnapshots(const RuntimeWindowState& state) {
    materializeRuntimeProjectileActorSnapshots(state);
    materializeRuntimeReplayEventSnapshots(state);
    materializeRuntimeUiStateSnapshot(state);
    materializeRuntimeMapFactsContextSnapshot(state);
    materializeRuntimePathQueueStatsSnapshot(state);
}

struct RuntimeProjectileSourcePosition {
    double x = 0.0;
    double y = 0.0;
    double z = 0.0;
    int screenOffsetX = 0;
    int screenOffsetY = 0;
    int nativeFixedX = 0;
    int nativeFixedY = 0;
};

struct RuntimeWeaponFireFlh {
    int forwardLeptons = 0;
    int lateralLeptons = 0;
    int heightLeptons = 0;
    bool authored = false;
};

std::optional<RuntimeWeaponFireFlh> parseRuntimeWeaponFireFlh(
    const std::string& rawFlh
) {
    const std::vector<std::string> components =
        splitRuntimeTokenList(rawFlh);
    if (components.size() < 3U) {
        return std::nullopt;
    }

    RuntimeWeaponFireFlh flh;
    if (!parseRuntimeInt(components[0], flh.forwardLeptons)
        || !parseRuntimeInt(components[1], flh.lateralLeptons)
        || !parseRuntimeInt(components[2], flh.heightLeptons)) {
        return std::nullopt;
    }
    flh.authored = true;
    return flh;
}

std::optional<RuntimeWeaponFireFlh> runtimeFallbackWeaponFireFlh(
    const RuntimeWindowState& state,
    const WorldObjectInstance& attacker,
    const RuntimeWeaponProfile& profile
) {
    if (profile.slot == RuntimeWeaponSlot::None
        || ((profile.slot == RuntimeWeaponSlot::Indexed
                || profile.slot == RuntimeWeaponSlot::EliteIndexed)
            && profile.indexedWeaponIndex < 0)) {
        // Indexed profiles without an authored index are synthetic impact
        // weapons (shrapnel, airburst, death weapons). Their origin is the
        // impact coordinate, not a unit muzzle.
        return std::nullopt;
    }

    const UnitType* unit = findRuntimeUnitType(state.rules, attacker);
    if (unit == nullptr) {
        return std::nullopt;
    }

    RuntimeWeaponFireFlh flh;
    if (profile.weapon != nullptr && profile.weapon->areaFire) {
        const auto* warhead = findRuntimeWarheadType(state.rules, profile.weapon->warhead);
        if (warhead != nullptr && warhead->psychedelic) {
            flh.heightLeptons = 48;
            return flh;
        }
    }
    if (attacker.kind == WorldObjectKind::Infantry) {
        // The stock GI/E1 coordinate is the neutral infantry rifle pose and
        // is a substantially safer fallback than the unit's feet/body pivot.
        flh.forwardLeptons = 80;
        flh.heightLeptons = 100;
        return flh;
    }

    if (unit->turret) {
        // Stock medium tanks cluster around 150,0,100. This places mod units
        // with omitted art metadata at the visible end of a conventional
        // turret barrel instead of the hull origin.
        flh.forwardLeptons = 150;
        flh.heightLeptons = 100;
        return flh;
    }

    if (attacker.authoredAircraft
        || unit->consideredAircraft
        || unit->jumpJet
        || unit->balloonHover) {
        flh.forwardLeptons = 96;
        flh.heightLeptons = 48;
        return flh;
    }

    flh.forwardLeptons = unit->naval || unit->waterBound ? 128 : 112;
    flh.heightLeptons = unit->naval || unit->waterBound ? 48 : 80;
    return flh;
}

std::optional<RuntimeWeaponFireFlh> runtimeWeaponFireFlh(
    const RuntimeWindowState& state,
    const WorldObjectInstance& attacker,
    const RuntimeWeaponProfile& profile,
    const ArtType* art
) {
    if (profile.slot == RuntimeWeaponSlot::None
        || ((profile.slot == RuntimeWeaponSlot::Indexed
                || profile.slot == RuntimeWeaponSlot::EliteIndexed)
            && profile.indexedWeaponIndex < 0)) {
        return std::nullopt;
    }

    std::vector<const std::string*> candidates;
    candidates.reserve(8);
    const auto addCandidate = [&candidates](const std::string& value) {
        if (trimAsciiLocal(value).empty()) {
            return;
        }
        const auto duplicate = std::find_if(
            candidates.begin(),
            candidates.end(),
            [&value](const std::string* candidate) {
                return candidate == &value || *candidate == value;
            }
        );
        if (duplicate == candidates.end()) {
            candidates.push_back(&value);
        }
    };
    const auto addStandardCandidates = [
        art,
        &addCandidate
    ](bool elite, bool secondary) {
        if (art == nullptr) {
            return;
        }
        if (secondary) {
            if (elite) {
                addCandidate(art->eliteSecondaryFireFLH);
            }
            addCandidate(art->secondaryFireFLH);
            if (elite) {
                addCandidate(art->elitePrimaryFireFLH);
            }
            addCandidate(art->primaryFireFLH);
        } else {
            if (elite) {
                addCandidate(art->elitePrimaryFireFLH);
            }
            addCandidate(art->primaryFireFLH);
            if (elite) {
                addCandidate(art->eliteSecondaryFireFLH);
            }
            addCandidate(art->secondaryFireFLH);
        }
    };

    if (art != nullptr
        && (profile.slot == RuntimeWeaponSlot::Indexed
            || profile.slot == RuntimeWeaponSlot::EliteIndexed)) {
        const std::size_t index = static_cast<std::size_t>(
            profile.indexedWeaponIndex
        );
        if (profile.slot == RuntimeWeaponSlot::EliteIndexed
            && index < art->eliteWeaponFireFLHs.size()) {
            addCandidate(art->eliteWeaponFireFLHs[index]);
        }
        if (index < art->weaponFireFLHs.size()) {
            addCandidate(art->weaponFireFLHs[index]);
        }
        addStandardCandidates(
            profile.slot == RuntimeWeaponSlot::EliteIndexed,
            index == 1U
        );
    } else {
        bool elite = profile.slot == RuntimeWeaponSlot::ElitePrimary
            || profile.slot == RuntimeWeaponSlot::EliteSecondary
            || profile.slot == RuntimeWeaponSlot::EliteDeploy
            || profile.slot == RuntimeWeaponSlot::EliteOccupy;
        bool secondary = profile.slot == RuntimeWeaponSlot::Secondary
            || profile.slot == RuntimeWeaponSlot::EliteSecondary;

        const UnitType* unit = findRuntimeUnitType(state.rules, attacker);
        const BuildingType* building =
            findRuntimeBuildingType(state.rules, attacker);
        if (profile.slot == RuntimeWeaponSlot::Deploy
            || profile.slot == RuntimeWeaponSlot::EliteDeploy) {
            const std::string source = unit != nullptr
                ? (elite
                    ? unit->eliteDeployWeaponSource
                    : unit->deployWeaponSource)
                : (building != nullptr
                    ? (elite
                        ? building->eliteDeployWeaponSource
                        : building->deployWeaponSource)
                    : std::string{});
            const std::string normalizedSource =
                toLowerAsciiLocal(trimAsciiLocal(source));
            secondary = normalizedSource.find("secondary")
                != std::string::npos;
        } else if (profile.slot == RuntimeWeaponSlot::OpenTransport
            && unit != nullptr) {
            secondary = unit->openTransportWeapon == 1
                || unit->openTransportWeapon == 3;
            elite = unit->openTransportWeapon == 2
                || unit->openTransportWeapon == 3;
        }
        addStandardCandidates(elite, secondary);
    }

    for (const std::string* candidate : candidates) {
        const std::optional<RuntimeWeaponFireFlh> parsed =
            parseRuntimeWeaponFireFlh(*candidate);
        if (parsed.has_value()) {
            return parsed;
        }
    }
    return runtimeFallbackWeaponFireFlh(state, attacker, profile);
}

int runtimeWeaponFiringFacing(
    const RuntimeWindowState& state,
    const WorldObjectInstance& attacker,
    const WorldObjectInstance& target
) {
    if (runtimeObjectHasTurret(state, attacker)
        && attacker.turretFacing >= 0) {
        return normalizeRuntimeFacing(attacker.turretFacing);
    }
    if (attacker.kind == WorldObjectKind::Structure) {
        const RuntimeCellPoint from = runtimeCellPointForObject(attacker);
        const RuntimeCellPoint to = runtimeCellPointForObject(target);
        const int desiredFacing =
            runtimeFacingFromDelta(to.x - from.x, to.y - from.y);
        if (desiredFacing >= 0) {
            return desiredFacing;
        }
    }
    return normalizeRuntimeFacing(attacker.facing >= 0 ? attacker.facing : 0);
}

void triggerRuntimeWeaponVisuals(
    RuntimeWindowState& state,
    WorldObjectInstance& attacker
) {
    const UnitType* unit = attacker.kind == WorldObjectKind::Unit
        ? findRuntimeUnitTypeById(state.rules, attacker.type)
        : nullptr;
    const BuildingType* building =
        attacker.kind == WorldObjectKind::Structure
        ? findRuntimeBuildingTypeById(state.rules, attacker.type)
        : nullptr;
    if ((unit != nullptr && unit->chargeTurret && unit->turretCount > 1)
        || (building != nullptr
            && building->chargeTurret
            && building->turretCount > 1)) {
        // Trigger once per real discharge. The renderer walks the authored
        // highest-to-lowest turret voxels at five ticks per stage.
        attacker.chargeTurretStartTick = state.tick;
    }
    if (building == nullptr
        || !building->turretRecoil
        || (building->turretTravel <= 0
            && building->barrelTravel <= 0)) {
        return;
    }
    // Projectile bursts and shrapnel must not restart the authored recoil
    // sequence for every spawned actor.
    attacker.structureRecoilStartTick = state.tick;
}

double runtimeWeaponHeightInLevels(int heightLeptons) {
    // Authored FLH uses vertical leptons, not terrain elevation steps. At
    // 60x30, native Z projects by 60*sin(60deg)/hypot(256,256) pixels per
    // lepton; one renderer level is 15 pixels. Their ratio is sqrt(6)/256.
    constexpr double levelsPerHeightLepton = 2.449489742783178 / 256.0;
    return static_cast<double>(heightLeptons) * levelsPerHeightLepton;
}

#include "render/geometry/RuntimeOpenTransportMuzzle.inl"

RuntimeProjectileSourcePosition runtimeProjectileSourcePosition(
    const RuntimeWindowState& state,
    const WorldObjectInstance& attacker,
    const RuntimeWeaponProfile& profile,
    int firingFacing
) {
    RuntimeProjectileSourcePosition source;
    source.x = runtimeObjectRenderX(attacker);
    source.y = runtimeObjectRenderY(attacker);
    source.z = runtimeDrawLevelForObject(attacker);
    // Aircraft bodies have a shared presentation lift beyond their world
    // altitude. Muzzles must use the same origin, including released bombs.
    source.screenOffsetY = -runtimeAircraftSpriteLiftPixels(attacker, attacker.airborne);
    source.nativeFixedY = source.screenOffsetY;
    const WorldObjectCellOffset subCellOffset =
        worldObjectSubCellOffset(attacker);
    source.x += subCellOffset.x;
    source.y += subCellOffset.y;

    if (const auto port = runtimeOpenTransportMuzzle(state, attacker, profile)) {
        const auto& host = *port->host;
        const auto forward = runtimeWorldForwardForFacing(std::max(0, host.facing));
        source.x = runtimeObjectRenderX(host) + (forward[0] * port->flh.forwardLeptons
            - forward[1] * port->flh.lateralLeptons) / 256.0;
        source.y = runtimeObjectRenderY(host) + (forward[1] * port->flh.forwardLeptons
            + forward[0] * port->flh.lateralLeptons) / 256.0;
        source.z = runtimeDrawLevelForObject(host) + runtimeWeaponHeightInLevels(port->flh.heightLeptons);
        source.screenOffsetY = -runtimeAircraftSpriteLiftPixels(host, host.airborne);
        source.nativeFixedY = source.screenOffsetY;
        return source;
    }
    if (profile.occupied && attacker.kind == WorldObjectKind::Structure) {
        if (const ArtType* art = runtimeArtTypeForObject(state, attacker);
            art && profile.occupantMuzzleIndex >= 0
            && profile.occupantMuzzleIndex < static_cast<int>(art->muzzleFlashes.size())) {
            const auto offset = art->muzzleFlashes[profile.occupantMuzzleIndex];
            // ART uses 60x30 screen pixels around the building's SHP origin.
            // Store the inverse projection in world coordinates so camera zoom,
            // scrolling and snapshot reconstruction keep the same window.
            source.x += std::trunc((offset.x / 60.0 + offset.y / 30.0) * 256.0) / 256.0;
            source.y += std::trunc((offset.y / 30.0 - offset.x / 60.0) * 256.0) / 256.0;
        }
        return source; // Occupied windows replace ordinary FLH and turret offsets.
    }

    if (const BuildingType* building =
            findRuntimeBuildingType(state.rules, attacker)) {
        if (!trimAsciiLocal(building->turretAnim).empty()) {
            const RuntimeStructureFootprint footprint =
                runtimeStructureFootprintForObject(state, attacker);
            const POINT turretOffset =
                runtimeStructureTurretAnimScreenOffsetForRender(
                    *building,
                    attacker.type,
                    footprint.width,
                    footprint.height,
                    RuntimeMapCamera{}
                );
            source.screenOffsetX = turretOffset.x;
            source.screenOffsetY = turretOffset.y;
            // Structure turret voxels still pass through the foundation SHP
            // anchor. Include that half tile in the gattling muzzle origin.
            if (toLowerAsciiLocal(attacker.type) == "yaggun"
                || toLowerAsciiLocal(building->turretAnim) == "yaggun"
                || toLowerAsciiLocal(attacker.type) == "naflak"
                || toLowerAsciiLocal(building->turretAnim) == "flaktur")
                source.screenOffsetY += 15;
        }
    }

    const ArtType* art = runtimeArtTypeForObject(state, attacker);
    std::optional<RuntimeWeaponFireFlh> flh =
        runtimeWeaponFireFlh(state, attacker, profile, art);
    if (!flh.has_value()) {
        return source;
    }
    if (runtimeCachedCapabilityProfileForObject(state, attacker).gattling) {
        const auto burst = state.combatDetails.bursts.find(attacker.instanceId);
        if (burst != state.combatDetails.bursts.end() && profile.weapon
            && burst->second.weaponId == profile.weapon->id
            && burst->second.nextShotIndex % 2 != 0)
            flh->lateralLeptons = -flh->lateralLeptons;
    }

    constexpr double LeptonsPerCell = 256.0;
    int turretOffsetLeptons = 0;
    if (art != nullptr
        && runtimeObjectHasTurret(state, attacker)
        && parseRuntimeInt(art->turretOffset, turretOffsetLeptons)
        && turretOffsetLeptons != 0) {
        // Primary/Secondary/WeaponX FLH is authored relative to the turret
        // center. TurretOffset moves that center along the hull centerline,
        // so it must be applied using the body facing before the muzzle is
        // rotated using the independently turning turret facing.
        const std::array<double, 2> bodyForward =
            runtimeWorldForwardForFacing(
                attacker.facing >= 0 ? attacker.facing : 0
            );
        source.x += bodyForward[0]
            * static_cast<double>(turretOffsetLeptons)
            / LeptonsPerCell;
        source.y += bodyForward[1]
            * static_cast<double>(turretOffsetLeptons)
            / LeptonsPerCell;
    }

    // A structure without a rotating turret has a fixed SHP muzzle. Aiming
    // at another target must not orbit that muzzle around its foundation.
    const int muzzleFacing = attacker.kind == WorldObjectKind::Structure
            && !runtimeObjectHasTurret(state, attacker)
        ? 0 : firingFacing;
    const std::array<double, 2> forward =
        runtimeWorldForwardForFacing(muzzleFacing >= 0 ? muzzleFacing : 0);
    const std::array<double, 2> lateral{-forward[1], forward[0]};
    source.x += (
        forward[0] * static_cast<double>(flh->forwardLeptons)
        + lateral[0] * static_cast<double>(flh->lateralLeptons)
    ) / LeptonsPerCell;
    source.y += (
        forward[1] * static_cast<double>(flh->forwardLeptons)
        + lateral[1] * static_cast<double>(flh->lateralLeptons)
    ) / LeptonsPerCell;
    // Infantry's cropped SHP uses the existing body-relative muzzle mapping.
    // Structures and voxel vehicles use the authored world-height projection.
    source.z += attacker.kind == WorldObjectKind::Infantry
        ? static_cast<double>(flh->heightLeptons) / LeptonsPerCell
        : runtimeWeaponHeightInLevels(flh->heightLeptons);
    return source;
}

RuntimeProjectileSourcePosition runtimeProjectileSourcePosition(
    const RuntimeWindowState& state,
    const WorldObjectInstance& attacker,
    RuntimeWeaponSlot slot,
    int firingFacing
) {
    RuntimeWeaponProfile profile;
    profile.slot = slot;
    return runtimeProjectileSourcePosition(
        state,
        attacker,
        profile,
        firingFacing
    );
}

int spawnRuntimeProjectileShrapnel(
    RuntimeWindowState& state,
    const RuntimeProjectileEffect& parent,
    const RuntimeCellPoint& impactCell,
    int impactLevel
);

#include "render/geometry/RuntimeWeaponMuzzleAttachment.inl"

const SpawnedMissileProfile* runtimeSpawnedMissileProfileForWeapon(
    const RuntimeWindowState& state,
    const WorldObjectInstance& attacker,
    const WeaponType& weapon
) {
    if (!weapon.spawner) {
        return nullptr;
    }
    const UnitType* unit = findRuntimeUnitType(state.rules, attacker);
    if (unit == nullptr || trimAsciiLocal(unit->spawns).empty()) {
        return nullptr;
    }
    return state.rules.findSpawnedMissileProfile(unit->spawns);
}

std::string runtimeWeaponAnimForFacing(
    const WeaponType& weapon,
    int firingFacing
) {
    const std::vector<std::string> animationIds =
        splitRuntimeTokenList(weapon.anim);
    if (animationIds.empty()) {
        return {};
    }

    std::string animationId = animationIds.front();
    if (animationIds.size() == 8U) {
        animationId = animationIds[static_cast<std::size_t>(
            worldObjectArtFacingBucket(firingFacing, 8)
        )];
    }
    const auto normalized = toLowerAsciiLocal(trimAsciiLocal(animationId));
    if (normalized == "none" || normalized == "<none>") {
        return {};
    }
    return animationId;
}

double runtimeEffectiveWeaponRange(
    const RuntimeWindowState& state,
    const WorldObjectInstance& attacker,
    const WorldObjectInstance& target,
    const WeaponType& weapon
) {
    if (runtimeSpawnerHasInfiniteRange(weapon)) {
        return std::numeric_limits<double>::infinity();
    }
    // Retail 0x6F7261 checks the target's IsInAir before adding this value.
    const double baseRange = std::max(0.0, weapon.range + (target.airborne
        ? runtimeCachedCapabilityProfileForObject(state, attacker).airRangeBonus : 0.0)
        + (attacker.tankBunkerHostId >= 0
            ? state.rules.getSpecialMechanismRules().bunkerWeaponRangeBonus : 0.0));
    const ProjectileType* projectile =
        findRuntimeProjectileType(state.rules, weapon.projectile);
    // Tracking projectiles continuously correct their path and explicitly
    // ignore the classic elevation range model.
    if (projectile == nullptr
        || !projectile->subjectToElevation
        || projectile->rot != 0
        || attacker.airborne
        || target.airborne
        || attacker.level <= target.level) {
        return baseRange;
    }

    const ElevationModelRules& model =
        state.rules.getElevationModelRules();
    const double height = static_cast<double>(
        attacker.level - target.level
    );
    const double bonusCount = std::min(
        std::max(0.0, model.bonusCap),
        std::floor(height / static_cast<double>(std::max(1, model.increment)))
    );
    return baseRange + bonusCount * std::max(0.0, model.incrementBonus);
}

double runtimeWeaponDistanceToTarget(
    const RuntimeWindowState& state,
    const WorldObjectInstance& attacker,
    const WorldObjectInstance& target,
    const WeaponType& weapon
) {
    if (weapon.cellRangefinding) {
        return runtimeCellDistance(
            runtimeCellPointForObject(attacker),
            runtimeCellPointForObject(target)
        );
    }
    return runtimeCellDistanceToObjectFootprint(
        state,
        runtimeCellPointForObject(attacker),
        target
    );
}

int runtimeAuthoredFramesToFixedTicks(
    const RuntimeWindowState& state,
    int frames
) {
    return std::max(
        1,
        static_cast<int>(std::lround(
            static_cast<double>(std::max(1, frames))
                * static_cast<double>(std::max(1, state.config.fixedTickHz))
                / 15.0
        ))
    );
}

int runtimeWeaponPrefireDelayTicks(
    const RuntimeWindowState& state,
    const WorldObjectInstance& attacker,
    const WeaponType& weapon
) {
    const ArtType* art = runtimeArtTypeForObject(state, attacker);
    const bool delayedByArt = art != nullptr && art->isAnimDelayedFire;
    if (!weapon.charges && !delayedByArt) {
        return 0;
    }

    int authoredFrames = delayedByArt ? art->delayedFireDelay : 0;
    if (authoredFrames <= 0 && delayedByArt) {
        authoredFrames = std::max(
            runtimeArtSequenceFrameCount(art, "Special"),
            runtimeArtSequenceFrameCount(art, "Fire")
        );
    }
    if (authoredFrames <= 0) {
        authoredFrames = 8;
    }
    return runtimeAuthoredFramesToFixedTicks(state, authoredFrames);
}

RuntimeParticleSpawnResult spawnRuntimeArtAnimationParticles(
    RuntimeWindowState& state,
    const std::string& animationId,
    const RuntimeParticleSpawnContext& context
) {
    const std::string authoredId = trimAsciiLocal(animationId);
    if (authoredId.empty()) {
        return {};
    }
    const ArtType* animation = state.art.findArtType(authoredId);
    if (animation == nullptr) {
        return {};
    }

    ensureRuntimeParticlesInitialized(state);
    return state.particles.spawnFromAnimation(
        state.rules,
        *animation,
        context
    );
}

void initializeRuntimeImpactAnimationTimeline(
    RuntimeWindowState& state, RuntimeImpactEffect& impact, bool force
);

void spawnRuntimeWeaponMuzzleEffect(
    RuntimeWindowState& state,
    const RuntimeProjectileEffect& projectile,
    bool occupied = false,
    bool openTopped = false
) {
    // Retail TechnoClass's death-weapon path (0x70D690) constructs a
    // bullet and calls Detonate directly; it never enters the Fire Anim
    // path. OilExplosion's RING1 is therefore not a death effect. Keep
    // ordinary discharges and child projectiles on their existing path.
    if (projectile.weaponAnimId.empty()
        || (projectile.deathWeaponRequestId > 0 && projectile.generation == 0)) {
        return;
    }
    // Squid tentacles belong to the attached host and live for the parasite
    // relationship. They are not an eight-tick flash at the launch position.
    if (toUpperAsciiLocal(projectile.weaponAnimId).rfind("SQDG", 0) == 0) {
        return;
    }

    const auto* muzzleSource = findObjectById(state, projectile.attackerObjectId);
    const bool gattling = !occupied && !openTopped && muzzleSource
        && runtimeCachedCapabilityProfileForObject(state, *muzzleSource).gattling;
    const int muzzleLifetimeTicks = runtimeRuleFramesToTicks(4, state.config.fixedTickHz);
    RuntimeImpactEffect muzzle;
    muzzle.projectileActorId = projectile.actorId;
    muzzle.attackerObjectId = projectile.attackerObjectId;
    muzzle.targetObjectId = projectile.targetObjectId;
    muzzle.owner = projectile.owner;
    muzzle.cell = projectile.fromCell;
    muzzle.level = projectile.fromLevel;
    muzzle.hasWorldPosition = true;
    muzzle.worldX = projectile.sourceX;
    muzzle.worldY = projectile.sourceY;
    muzzle.worldLevel = projectile.sourceZ;
    muzzle.screenOffsetX = projectile.sourceScreenOffsetX;
    muzzle.nativeFixedX = projectile.sourceNativeFixedX;
    muzzle.screenOffsetY = projectile.sourceScreenOffsetY;
    muzzle.nativeFixedY = projectile.sourceNativeFixedY;
    muzzle.totalTicks = muzzleLifetimeTicks;
    muzzle.remainingTicks = muzzleLifetimeTicks;
    muzzle.frameIndex = -1;
    muzzle.facing = projectile.attackerFacing;
    muzzle.lifecycleState = openTopped ? "TransportMuzzle" : occupied ? "OccupantMuzzle"
        : gattling ? "GattlingMuzzle" : "Muzzle";
    muzzle.renderIntent = "weaponAnim";
    muzzle.weaponId = projectile.weaponId;
    muzzle.weaponSlot = projectile.weaponSlot;
    muzzle.projectileId = projectile.projectileId;
    muzzle.projectileImageId = projectile.projectileImageId;
    muzzle.animId = projectile.weaponAnimId;
    muzzle.warheadId = projectile.warheadId;
    muzzle.bright = projectile.bright;
    const WarheadType* muzzleWarhead =
        findRuntimeWarheadType(state.rules, projectile.warheadId);
    if (muzzleWarhead != nullptr && muzzleWarhead->mindControl) {
        // Do not squeeze YURICNTL into the generic eight-tick muzzle flash.
        initializeRuntimeImpactAnimationTimeline(state, muzzle, true);
    }
    if (openTopped) {
        const auto anchor = runtimeTransportMuzzleAnchor(state, projectile.attackerObjectId);
        if (!anchor) return;
        muzzle.muzzleAnchorX = (*anchor)[0]; muzzle.muzzleAnchorY = (*anchor)[1];
        muzzle.muzzleAnchorLevel = (*anchor)[2]; muzzle.muzzleFacing = projectile.attackerFacing;
        // Keep the authoritative authored port untouched. The saved pixel
        // correction is presentation-only, in the fixed 60x30 reference view.
    }
    if (occupied || openTopped || gattling) {
        initializeRuntimeImpactAnimationTimeline(state, muzzle, true);
        if (muzzle.animationSequenceSteps > 0) {
            const ArtType* art = state.art.findArtType(muzzle.animId);
            // Retail AnimType defaults to one logic frame. A positive Rate is
            // converted with integer 900 / Rate, not the ordinary flash's 8 ticks.
            int authoredDelay = art && art->rate > 0 ? std::max(1, 900 / art->rate) : 1;
            if (gattling && art && art->normalized) {
                // Retail AnimType defaults to delay 1 and Shadow=false.
                // VTMUZZLE uses GameOptions::GetAnimSpeed (0x5FB2E0).
                authoredDelay = runtimeRuleNormalizedAnimationDelay(authoredDelay,
                    6 - std::clamp(state.config.gameSpeed, 0, 6));
            }
            muzzle.animationFrameDelayTicks = std::max(1,
                (authoredDelay * std::clamp(state.config.fixedTickHz, 1, 1000) + 14) / 15);
            // The creation pass must display frame zero before advancing.
            muzzle.totalTicks = muzzle.animationSequenceSteps * muzzle.animationFrameDelayTicks + 1;
            muzzle.remainingTicks = muzzle.totalTicks;
        }
    }
    state.impactEffects.push_back(std::move(muzzle));

    RuntimeParticleSpawnContext particleContext;
    particleContext.sourceObjectId = projectile.attackerObjectId;
    particleContext.owner = projectile.owner;
    particleContext.sourceTag = "animation:" + projectile.weaponAnimId;
    particleContext.position = {
        projectile.sourceX * 256.0,
        projectile.sourceY * 256.0,
        projectile.sourceZ * 256.0
    };
    particleContext.direction = {
        (projectile.targetX - projectile.sourceX) * 256.0,
        (projectile.targetY - projectile.sourceY) * 256.0,
        (projectile.targetZ - projectile.sourceZ) * 256.0
    };
    particleContext.seed =
        (static_cast<std::uint64_t>(
            static_cast<std::uint32_t>(projectile.actorId)
         ) << 32U)
        ^ static_cast<std::uint64_t>(
            static_cast<std::uint32_t>(state.tick)
          )
        ^ 0x6d757a7a6c65ULL;
    (void)spawnRuntimeArtAnimationParticles(
        state,
        projectile.weaponAnimId,
        particleContext
    );
}

void spawnRuntimeWeaponAttachedParticleSystem(
    RuntimeWindowState& state,
    const WeaponType& weapon,
    const RuntimeProjectileEffect& projectile
) {
    const bool requestsAttachedParticles = weapon.isRailgun
        || weapon.useSparkParticles
        || weapon.useFireParticles;
    const std::string particleSystemId =
        trimAsciiLocal(weapon.attachedParticleSystem);
    if (!requestsAttachedParticles || particleSystemId.empty()) {
        return;
    }

    const double sourceX = projectile.hasSourcePosition
        ? projectile.sourceX
        : static_cast<double>(projectile.fromCell.x);
    const double sourceY = projectile.hasSourcePosition
        ? projectile.sourceY
        : static_cast<double>(projectile.fromCell.y);
    const double sourceZ = projectile.hasSourcePosition
        ? projectile.sourceZ
        : static_cast<double>(projectile.fromLevel);
    const double targetX = projectile.hasTargetPosition
        ? projectile.targetX
        : static_cast<double>(projectile.toCell.x);
    const double targetY = projectile.hasTargetPosition
        ? projectile.targetY
        : static_cast<double>(projectile.toCell.y);
    const double targetZ = projectile.hasTargetPosition
        ? projectile.targetZ
        : static_cast<double>(projectile.toLevel);

    RuntimeParticleSpawnContext particleContext;
    particleContext.sourceObjectId = projectile.attackerObjectId;
    particleContext.owner = projectile.owner;
    particleContext.sourceTag = "weapon:" + weapon.id;
    const bool targetAnchoredSpark = weapon.useSparkParticles
        && !weapon.isRailgun
        && !weapon.useFireParticles;
    particleContext.position = {
        (targetAnchoredSpark ? targetX : sourceX) * 256.0,
        (targetAnchoredSpark ? targetY : sourceY) * 256.0,
        (targetAnchoredSpark ? targetZ : sourceZ) * 256.0
    };
    particleContext.direction = {
        (targetX - sourceX) * 256.0,
        (targetY - sourceY) * 256.0,
        (targetZ - sourceZ) * 256.0
    };
    particleContext.seed = runtimeStableHashString(
        "runtimeWeaponAttachedParticleSystem/1"
    );
    runtimeStableHashMix(particleContext.seed, projectile.actorId);
    runtimeStableHashMix(
        particleContext.seed,
        projectile.attackerObjectId
    );
    runtimeStableHashMix(particleContext.seed, projectile.spawnTick);
    runtimeStableHashMixString(particleContext.seed, weapon.id);

    const ParticleSystemType* attachedType =
        state.rules.findParticleSystemType(particleSystemId);
    if (!weapon.isRailgun
        && attachedType != nullptr
        && attachedType->lifetime <= 0) {
        // Authored Spark systems such as WeldingSys intentionally omit a
        // lifetime because the weapon owns them. Bound that ownership to one
        // ROF window so repeated shots cannot leave immortal emitters behind.
        particleContext.systemLifetimeOverrideFrames = std::max(
            1,
            weapon.rof
        );
    }

    ensureRuntimeParticlesInitialized(state);
    (void)state.particles.spawnSystem(
        state.rules,
        particleSystemId,
        particleContext
    );
}

