    scratch.pathFailureCache = live.pathFailureCache;
    scratch.tickOccupancyCacheTick = live.tickOccupancyCacheTick;
    scratch.tickOccupiedByCell = live.tickOccupiedByCell;
    scratch.tickGroundOccupantCountByCell =
        live.tickGroundOccupantCountByCell;
