    scratch.interactionStatus = live.interactionStatus;
    scratch.repaintRequested = live.repaintRequested;

    // World-projection entries own raw pointers.  A transaction always
    // rebuilds them lazily after its world vector buffer is transferred.
    scratch.projectedObjectsCacheValid = false;
    scratch.projectedObjectsCache.clear();
    scratch.snapshotCache = {};
