void commitRuntimeGrindingTransactionScratch(
    RuntimeWindowState& live,
    RuntimeWindowState& scratch
) noexcept {
#define RUNTIME_GRINDING_SWAP(field) \
    swapRuntimeLoadedField(live.field, scratch.field)

    invalidateRuntimeVisionTerrainCoordinateLeases(live.world);
    invalidateRuntimeVisionTerrainCoordinateLeases(scratch.world);
    RUNTIME_GRINDING_SWAP(world);
    RUNTIME_GRINDING_SWAP(terrainByCell);
    swapRuntimeLoadedEconomy(live.economy, scratch.economy);
    RUNTIME_GRINDING_SWAP(computerAiByOwner);
    RUNTIME_GRINDING_SWAP(computerMiningByOwner);
    swapRuntimeLoadedTriggers(live.triggers, scratch.triggers);

    RUNTIME_GRINDING_SWAP(deathWeapons);
    RUNTIME_GRINDING_SWAP(combatDetails);
    RUNTIME_GRINDING_SWAP(matchScores);
    RUNTIME_GRINDING_SWAP(specialMechanisms);
    RUNTIME_GRINDING_SWAP(specialMechanismsInitialized);
    RUNTIME_GRINDING_SWAP(spies);
    RUNTIME_GRINDING_SWAP(spiesInitialized);
    RUNTIME_GRINDING_SWAP(garrisons);
    RUNTIME_GRINDING_SWAP(garrisonsInitialized);
    RUNTIME_GRINDING_SWAP(subcells);
    RUNTIME_GRINDING_SWAP(subcellsInitialized);
    RUNTIME_GRINDING_SWAP(grinding);
    RUNTIME_GRINDING_SWAP(repairDepots);
    RUNTIME_GRINDING_SWAP(repairDepotsInitialized);
    RUNTIME_GRINDING_SWAP(factoryDeliveries);
    RUNTIME_GRINDING_SWAP(pendingCloneDeliveries);
    RUNTIME_GRINDING_SWAP(playerCommands);
    RUNTIME_GRINDING_SWAP(aircraftServices);
    RUNTIME_GRINDING_SWAP(aircraftServicesInitialized);

    RUNTIME_GRINDING_SWAP(cloakStateInitialized);
    RUNTIME_GRINDING_SWAP(cloakObservedHealthByObject);
    RUNTIME_GRINDING_SWAP(behaviors);
    RUNTIME_GRINDING_SWAP(jumpjetFlights);
    RUNTIME_GRINDING_SWAP(aircraftFlights);
    RUNTIME_GRINDING_SWAP(pendingPathObjectIds);
    RUNTIME_GRINDING_SWAP(pendingEngineerCaptures);
    RUNTIME_GRINDING_SWAP(pendingEngineerActions);
    RUNTIME_GRINDING_SWAP(pendingOccupyTargets);
    RUNTIME_GRINDING_SWAP(pendingTransportTargets);
    RUNTIME_GRINDING_SWAP(pendingTimedBombIntents);
    RUNTIME_GRINDING_SWAP(parasiteStunUntilTickByObject);
    RUNTIME_GRINDING_SWAP(harvesterTasks);
    RUNTIME_GRINDING_SWAP(slaveMinerTasks);
    RUNTIME_GRINDING_SWAP(slaveMinerRegenTicks);
    RUNTIME_GRINDING_SWAP(gattlingWeaponTimers);
    RUNTIME_GRINDING_SWAP(repairingStructureTicks);
    RUNTIME_GRINDING_SWAP(runtimeUnitFeedbackCooldownUntilTick);

    RUNTIME_GRINDING_SWAP(pathTerrainCache);
    RUNTIME_GRINDING_SWAP(attackApproachCache);
    RUNTIME_GRINDING_SWAP(pathFailureCache);
    RUNTIME_GRINDING_SWAP(tickOccupancyCacheTick);
    RUNTIME_GRINDING_SWAP(tickOccupiedByCell);
    RUNTIME_GRINDING_SWAP(tickGroundOccupantCountByCell);
    RUNTIME_GRINDING_SWAP(tickCrushEmptyCellProofValid);
    RUNTIME_GRINDING_SWAP(tickCrushEmptyCellObjectCount);
    RUNTIME_GRINDING_SWAP(tickCrushUnindexedFoundationBounds);
    RUNTIME_GRINDING_SWAP(navigationRefreshPending);
    RUNTIME_GRINDING_SWAP(powerRefreshPending);
    RUNTIME_GRINDING_SWAP(selectedObjectIds);
    RUNTIME_GRINDING_SWAP(actionSummary);
    RUNTIME_GRINDING_SWAP(nextProjectileActorId);
    RUNTIME_GRINDING_SWAP(projectiles);
    RUNTIME_GRINDING_SWAP(recentExpiredProjectiles);
    RUNTIME_GRINDING_SWAP(impactEffects);
    RUNTIME_GRINDING_SWAP(wrecks);
    RUNTIME_GRINDING_SWAP(buildingCollapses);
    RUNTIME_GRINDING_SWAP(nextReplayEventSequence);
    RUNTIME_GRINDING_SWAP(recentReplayEvents);
    RUNTIME_GRINDING_SWAP(simulationStatus);
    RUNTIME_GRINDING_SWAP(interactionStatus);
    RUNTIME_GRINDING_SWAP(projectedObjectsCacheValid);
    RUNTIME_GRINDING_SWAP(projectedObjectsCache);
    RUNTIME_GRINDING_SWAP(snapshotCache);
    RUNTIME_GRINDING_SWAP(repaintRequested);
    swapRuntimeLoadedRenderWorldCaches(live.renderCache, scratch.renderCache);
    RUNTIME_GRINDING_SWAP(radarTerrainKey);
    RUNTIME_GRINDING_SWAP(radarProjectionCacheValid);

    live.applyingGrindingActions = false;

#undef RUNTIME_GRINDING_SWAP
}

