struct RuntimeMenuSliderGeometry {
    RECT valueRect{0, 0, 0, 0};
    int trackLeft = 0;
    int trackRight = 0;
    int trackY = 0;
};

RECT runtimeMenuControlValueRect(const RuntimeMenuControl& control) {
    RECT valueRect = control.rect;
    valueRect.left = control.action==RuntimeMenuAction::KeyboardCategory ? control.rect.left+80 : valueRect.right - 112;
    return valueRect;
}

RuntimeMenuSliderGeometry runtimeMenuSliderGeometryForValueRect(
    const RECT& valueRect
) {
    return RuntimeMenuSliderGeometry{
        valueRect,
        valueRect.left + 6,
        valueRect.right - 6,
        valueRect.bottom - 6
    };
}

RuntimeMenuSliderGeometry runtimeMenuSliderGeometry(
    const RuntimeMenuControl& control
) {
    return runtimeMenuSliderGeometryForValueRect(
        runtimeMenuControlValueRect(control)
    );
}

std::vector<RuntimeMenuControl> runtimeMenuContentControls(
    const RuntimeWindowState& state,
    const RECT& clientRect
) {
    const RuntimeMenuDialogLayout dialog =
        runtimeMenuDialogLayout(state, clientRect);
    const int left = dialog.imageRect.left + 46;
    const int right = dialog.imageRect.right - 46;
    std::vector<RuntimeMenuControl> controls;
    const auto addControl = [&controls, left, right](
        RuntimeMenuAction action,
        RuntimeMenuControlKind kind,
        int top,
        const std::wstring& label,
        const std::wstring& value,
        int valuePosition,
        int valueMaximum,
        bool checked
    ) {
        controls.push_back(RuntimeMenuControl{
            action,
            kind,
            RECT{left, top, right, top + 31},
            label,
            value,
            valuePosition,
            valueMaximum,
            checked
        });
    };

    if (state.runtimeMenuPage == RuntimeMenuPage::Settings) {
        const int firstTop = dialog.imageRect.top + 58;
        constexpr int step = 33;
        addControl(
            RuntimeMenuAction::CycleGameSpeed,
            RuntimeMenuControlKind::Slider,
            firstTop,
            runtimeMenuLabel(state, "GUI:GameSpeed", L"Game Speed"),
            runtimeMenuSpeedValue(state, state.config.gameSpeed),
            std::clamp(state.config.gameSpeed, 0, 6),
            6,
            false
        );
        addControl(
            RuntimeMenuAction::CycleScrollRate,
            RuntimeMenuControlKind::Slider,
            firstTop + step,
            runtimeMenuLabel(state, "GUI:ScrollRate", L"Scroll Rate"),
            runtimeMenuSpeedValue(state, state.runtimeScrollRate),
            state.runtimeScrollRate,
            6,
            false
        );
        addControl(
            RuntimeMenuAction::CycleVisualDetail,
            RuntimeMenuControlKind::Slider,
            firstTop + (step * 2),
            runtimeMenuLabel(state, "GUI:VisualDetails", L"Visual Details"),
            runtimeMenuVisualValue(state, state.runtimeVisualDetail),
            state.runtimeVisualDetail,
            2,
            false
        );
        const std::wstring enabled =
            runtimeMenuLabel(state, "TXT_ON", L"On");
        const std::wstring disabled =
            runtimeMenuLabel(state, "TXT_OFF", L"Off");
        addControl(
            RuntimeMenuAction::ToggleTooltips,
            RuntimeMenuControlKind::Checkbox,
            firstTop + (step * 3),
            runtimeMenuLabel(state, "GUI:Tooltips", L"Tooltips"),
            state.runtimeTooltipsEnabled ? enabled : disabled,
            0,
            0,
            state.runtimeTooltipsEnabled
        );
        addControl(
            RuntimeMenuAction::ToggleTargetLines,
            RuntimeMenuControlKind::Checkbox,
            firstTop + (step * 4),
            runtimeMenuLabel(state, "GUI:TargetLines", L"Target Lines"),
            state.runtimeTargetLinesEnabled ? enabled : disabled,
            0,
            0,
            state.runtimeTargetLinesEnabled
        );
        addControl(
            RuntimeMenuAction::ToggleScrollCoasting,
            RuntimeMenuControlKind::Checkbox,
            firstTop + (step * 5),
            runtimeMenuLabel(
                state,
                "GUI:ScrollCoasting",
                L"Scroll Coasting"
            ),
            state.runtimeScrollCoastingEnabled ? enabled : disabled,
            0,
            0,
            state.runtimeScrollCoastingEnabled
        );
        addControl(RuntimeMenuAction::ToggleHiddenObjects, RuntimeMenuControlKind::Checkbox,
            firstTop + step * 6, L"显示被遮挡单位",
            state.config.seeHiddenObjects ? enabled : disabled, 0, 0, state.config.seeHiddenObjects);
    } else if (state.runtimeMenuPage == RuntimeMenuPage::Display) {
        const int firstTop = dialog.imageRect.top + 104;
        addControl(
            RuntimeMenuAction::CycleResolution,
            RuntimeMenuControlKind::Choice,
            firstTop,
            runtimeMenuLabel(
                state,
                "GUI:ResolutionModes",
                L"Resolution Modes"
            ),
            std::to_wstring(state.runtimeResolutionWidth)
                + L" x "
                + std::to_wstring(state.runtimeResolutionHeight),
            0,
            0,
            false
        );
        addControl(
            RuntimeMenuAction::ApplyResolution,
            RuntimeMenuControlKind::Button,
            firstTop + 62,
            runtimeMenuLabel(
                state,
                "GUI:SetResolution",
                L"Set Resolution"
            ),
            L"",
            0,
            0,
            false
        );
    } else if (state.runtimeMenuPage == RuntimeMenuPage::Sound) {
        const int firstTop = dialog.imageRect.top + 74;
        constexpr int step = 50;
        addControl(
            RuntimeMenuAction::AdjustMusicVolume,
            RuntimeMenuControlKind::Slider,
            firstTop,
            runtimeMenuLabel(state, "GUI:MusicVolume", L"Music Volume"),
            runtimeMenuPercentValue(state.runtimeMusicVolume),
            state.runtimeMusicVolume,
            100,
            false
        );
        addControl(
            RuntimeMenuAction::AdjustSoundVolume,
            RuntimeMenuControlKind::Slider,
            firstTop + step,
            runtimeMenuLabel(state, "GUI:SoundVolume", L"Sound Volume"),
            runtimeMenuPercentValue(state.runtimeSoundVolume),
            state.runtimeSoundVolume,
            100,
            false
        );
        addControl(
            RuntimeMenuAction::AdjustVoiceVolume,
            RuntimeMenuControlKind::Slider,
            firstTop + (step * 2),
            runtimeMenuLabel(state, "GUI:VoiceVolume", L"Voice Volume"),
            runtimeMenuPercentValue(state.runtimeVoiceVolume),
            state.runtimeVoiceVolume,
            100,
            false
        );
        addControl(
            RuntimeMenuAction::ToggleMusic,
            RuntimeMenuControlKind::Checkbox,
            firstTop + (step * 3),
            runtimeMenuLabel(state, "GUI:PlayMusic", L"Play Music"),
            state.runtimeMusicEnabled
                ? runtimeMenuLabel(state, "TXT_ON", L"On")
                : runtimeMenuLabel(state, "TXT_OFF", L"Off"),
            0,
            0,
            state.runtimeMusicEnabled
        );
    } else if (state.runtimeMenuPage == RuntimeMenuPage::Keyboard) {
#include "ui/input/RuntimeKeyboardMenuControls.inl"
    }
    return controls;
}

std::optional<RuntimeMenuControl> runtimeMenuControlForAction(
    const RuntimeWindowState& state,
    const RECT& clientRect,
    RuntimeMenuAction action
) {
    for (const RuntimeMenuControl& control :
        runtimeMenuContentControls(state, clientRect)) {
        if (control.action == action) {
            return control;
        }
    }
    return std::nullopt;
}

int runtimeMenuSliderPositionFromX(
    const RuntimeMenuControl& control,
    int clientX
) {
    const RuntimeMenuSliderGeometry geometry =
        runtimeMenuSliderGeometry(control);
    const int maximum = std::max(0, control.valueMaximum);
    const int travel = std::max(1, geometry.trackRight - geometry.trackLeft);
    const int offset = std::clamp(
        clientX - geometry.trackLeft,
        0,
        travel
    );
    return std::clamp(
        (offset * maximum + travel / 2) / travel,
        0,
        maximum
    );
}

bool setRuntimeMenuSliderFromX(
    RuntimeWindowState& state,
    const RECT& clientRect,
    RuntimeMenuAction action,
    int clientX
) {
    const std::optional<RuntimeMenuControl> control =
        runtimeMenuControlForAction(state, clientRect, action);
    if (!control.has_value()
        || control->kind != RuntimeMenuControlKind::Slider) {
        return false;
    }

    const int position = runtimeMenuSliderPositionFromX(*control, clientX);
    switch (action) {
    case RuntimeMenuAction::CycleGameSpeed:
        state.config.gameSpeed = std::clamp(position, 0, 6);
        break;
    case RuntimeMenuAction::CycleScrollRate:
        state.runtimeScrollRate = std::clamp(position, 0, 6);
        break;
    case RuntimeMenuAction::CycleVisualDetail:
        state.runtimeVisualDetail = std::clamp(position, 0, 2);
        break;
    case RuntimeMenuAction::AdjustMusicVolume:
        state.runtimeMusicVolume = std::clamp(position, 0, 100);
        state.runtimeMusicEnabled = state.runtimeMusicVolume > 0;
        break;
    case RuntimeMenuAction::AdjustSoundVolume:
        state.runtimeSoundVolume = std::clamp(position, 0, 100);
        state.runtimeSoundEffectsEnabled = state.runtimeSoundVolume > 0;
        break;
    case RuntimeMenuAction::AdjustVoiceVolume:
        state.runtimeVoiceVolume = std::clamp(position, 0, 100);
        break;
    default:
        return false;
    }
    return true;
}

bool beginRuntimeMenuSliderDrag(
    RuntimeWindowState& state,
    const RECT& clientRect,
    RuntimeMenuAction action,
    POINT point
) {
    const std::optional<RuntimeMenuControl> control =
        runtimeMenuControlForAction(state, clientRect, action);
    if (!control.has_value()
        || control->kind != RuntimeMenuControlKind::Slider) {
        return false;
    }

    const RECT valueRect = runtimeMenuControlValueRect(*control);
    if (!PtInRect(&valueRect, point)) {
        return false;
    }

    state.runtimeMenuPressed = action;
    state.runtimeMenuSliderDrag = action;
    (void)setRuntimeMenuSliderFromX(state, clientRect, action, point.x);
    return true;
}

bool updateRuntimeMenuSliderDrag(
    RuntimeWindowState& state,
    const RECT& clientRect,
    int clientX
) {
    if (state.runtimeMenuSliderDrag == RuntimeMenuAction::None) {
        return false;
    }
    return setRuntimeMenuSliderFromX(
        state,
        clientRect,
        state.runtimeMenuSliderDrag,
        clientX
    );
}

void applyRuntimeMenuSliderRuntimeEffects(
    RuntimeWindowState& state,
    RuntimeMenuAction action
) {
    if (action == RuntimeMenuAction::AdjustMusicVolume) {
        if (state.runtimeMusicEnabled) {
            startRuntimeMusic(state);
        } else {
            stopRuntimeMusic(state);
        }
    } else if (action == RuntimeMenuAction::AdjustSoundVolume) {
        if (!state.runtimeSoundEffectsEnabled) {
            stopRuntimeWorldAudioBackend(state, true);
        } else {
            applyRuntimeWorldAudioBackendActions(
                state,
                state.worldAudio.rehydrateActions(
                    runtimeWorldAudioContext(state),
                    state.tick
                )
            );
        }
    } else if (action == RuntimeMenuAction::AdjustVoiceVolume
        && state.runtimeVoiceVolume == 0) {
        muteRuntimeEvaPlaybackPreservingSubtitle(state);
    }
}
bool finishRuntimeMenuSliderDrag(
    RuntimeWindowState& state,
    const RECT& clientRect,
    int clientX
) {
    if (state.runtimeMenuSliderDrag == RuntimeMenuAction::None) {
        return false;
    }
    (void)updateRuntimeMenuSliderDrag(state, clientRect, clientX);
    const RuntimeMenuAction completedAction = state.runtimeMenuSliderDrag;
    state.runtimeMenuSliderDrag = RuntimeMenuAction::None;
    state.runtimeMenuPressed = RuntimeMenuAction::None;
    applyRuntimeMenuSliderRuntimeEffects(state, completedAction);
    state.runtimeMenuStatus.clear();
    (void)persistRuntimeMenuPreferences(state);
    return true;
}

bool adjustRuntimeMenuSliderPosition(
    RuntimeWindowState& state,
    RuntimeMenuAction action,
    int positionDelta
) {
    if (positionDelta == 0) {
        return false;
    }
    switch (action) {
    case RuntimeMenuAction::CycleGameSpeed:
        state.config.gameSpeed = std::clamp(
            state.config.gameSpeed + positionDelta,
            0,
            6
        );
        break;
    case RuntimeMenuAction::CycleScrollRate:
        state.runtimeScrollRate = std::clamp(
            state.runtimeScrollRate + positionDelta,
            0,
            6
        );
        break;
    case RuntimeMenuAction::CycleVisualDetail:
        state.runtimeVisualDetail = std::clamp(
            state.runtimeVisualDetail + positionDelta,
            0,
            2
        );
        break;
    case RuntimeMenuAction::AdjustMusicVolume:
        state.runtimeMusicVolume = std::clamp(
            state.runtimeMusicVolume + positionDelta * 5,
            0,
            100
        );
        state.runtimeMusicEnabled = state.runtimeMusicVolume > 0;
        break;
    case RuntimeMenuAction::AdjustSoundVolume:
        state.runtimeSoundVolume = std::clamp(
            state.runtimeSoundVolume + positionDelta * 5,
            0,
            100
        );
        state.runtimeSoundEffectsEnabled = state.runtimeSoundVolume > 0;
        break;
    case RuntimeMenuAction::AdjustVoiceVolume:
        state.runtimeVoiceVolume = std::clamp(
            state.runtimeVoiceVolume + positionDelta * 5,
            0,
            100
        );
        break;
    default:
        return false;
    }
    applyRuntimeMenuSliderRuntimeEffects(state, action);
    state.runtimeMenuStatus.clear();
    (void)persistRuntimeMenuPreferences(state);
    return true;
}

std::vector<RuntimeMenuButton> runtimeMenuButtons(
    const RuntimeWindowState& state,
    const RECT& clientRect
) {
    struct RuntimeMenuButtonDefinition {
        RuntimeMenuAction action = RuntimeMenuAction::None;
        std::wstring label;
        bool bottom = false;
    };
    std::vector<RuntimeMenuButtonDefinition> definitions;
    if (state.runtimeMenuPage == RuntimeMenuPage::Main) {
        definitions = {
            {
                RuntimeMenuAction::Options,
                runtimeMenuLabel(state, "GUI:GameOptions", L"Game Options")
            },
            {
                RuntimeMenuAction::Save,
                runtimeMenuLabel(state, "GUI:SaveMissionMenu", L"Save Mission")
            },
            {
                RuntimeMenuAction::Load,
                runtimeMenuLabel(state, "GUI:LoadMissionMenu", L"Load Mission")
            },
            {
                RuntimeMenuAction::Exit,
                runtimeMenuLabel(state, "GUI:AbortMission", L"Abort Mission")
            },
            {
                RuntimeMenuAction::Resume,
                runtimeMenuLabel(state, "GUI:ResumeMission", L"Resume Mission"),
                true
            }
        };
    } else if (state.runtimeMenuPage == RuntimeMenuPage::Settings) {
        definitions = {
            {
                RuntimeMenuAction::OpenDisplay,
                runtimeMenuLabel(state, "GUI:Display", L"Display")
            },
            {
                RuntimeMenuAction::OpenSound,
                runtimeMenuLabel(state, "GUI:Sound", L"Sound")
            },
            {
                RuntimeMenuAction::OpenKeyboard,
                runtimeMenuLabel(state, "GUI:Keyboard", L"Keyboard")
            },
            {
                RuntimeMenuAction::Back,
                runtimeMenuLabel(state, "GUI:Back", L"Back"),
                true
            }
        };
    } else if (state.runtimeMenuPage == RuntimeMenuPage::Display
        || state.runtimeMenuPage == RuntimeMenuPage::Sound
        || state.runtimeMenuPage == RuntimeMenuPage::Keyboard) {
        definitions = {
            {
                RuntimeMenuAction::Back,
                runtimeMenuLabel(state, "GUI:Back", L"Back"),
                true
            }
        };
    } else {
        definitions = {
            {
                RuntimeMenuAction::ConfirmExit,
                runtimeMenuLabel(state, "GUI:Abort", L"Abort")
            },
            {
                RuntimeMenuAction::CancelExit,
                runtimeMenuLabel(state, "GUI:Cancel", L"Cancel"),
                true
            }
        };
    }

    constexpr int buttonWidth = 125;
    constexpr int buttonHeight = 25;
    constexpr int firstButtonY = 228;
    constexpr int sidebarCardTop = 227;
    constexpr int sidebarBottomHeight = 26;
    constexpr int repeaterHeight = 50;
    const int clientHeight = clientRect.bottom - clientRect.top;
    const int repeaterCount = std::max(
        1,
        (clientHeight - sidebarCardTop - sidebarBottomHeight)
            / repeaterHeight
    );
    const int menuHeight = repeaterHeight * repeaterCount - 2;
    const int startY = clientRect.top + firstButtonY;
    const int bottomY = startY + menuHeight - buttonHeight;
    const int left = clientRect.right - runtimeSidebarWidth + 21;
    std::vector<RuntimeMenuButton> buttons;
    buttons.reserve(definitions.size());
    for (std::size_t index = 0; index < definitions.size(); ++index) {
        const int top = definitions[index].bottom
            ? bottomY
            : startY + static_cast<int>(index) * buttonHeight;
        buttons.push_back(RuntimeMenuButton{
            definitions[index].action,
            RECT{left, top, left + buttonWidth, top + buttonHeight},
            definitions[index].label
        });
    }
    return buttons;
}

std::vector<RuntimeMenuButton> runtimeMenuFocusableButtons(
    const RuntimeWindowState& state,
    const RECT& clientRect
) {
    std::vector<RuntimeMenuButton> focusable =
        runtimeMenuButtons(state, clientRect);
    const std::vector<RuntimeMenuControl> controls =
        runtimeMenuContentControls(state, clientRect);
    focusable.reserve(focusable.size() + controls.size());
    for (const RuntimeMenuControl& control : controls) {
        focusable.push_back(RuntimeMenuButton{
            control.action,
            control.rect,
            control.label
        });
    }
    return focusable;
}

RuntimeMenuAction runtimeMenuActionAtPoint(
    const RuntimeWindowState& state,
    const RECT& clientRect,
    POINT point
) {
    for (const RuntimeMenuControl& control :
        runtimeMenuContentControls(state, clientRect)) {
        if (PtInRect(&control.rect, point)) {
            return control.action;
        }
    }
    for (const RuntimeMenuButton& button : runtimeMenuButtons(state, clientRect)) {
        if (PtInRect(&button.rect, point)) {
            return button.action;
        }
    }
    return RuntimeMenuAction::None;
}

int runtimeTickRateForGameSpeed(int gameSpeed, int fixedTickHz) {
    return runtimeGameSpeedTiming(gameSpeed, fixedTickHz).roundedTickRate();
}

int runtimeSimulationPacingTickRate(const RuntimeConfig& config) {
    // FixedTickHz is the deterministic authored-time conversion rate. Game
    // speed instead controls how quickly whole simulation ticks are consumed
    // in wall-clock time. Keeping the multiplier here, around the complete
    // advanceRuntimeSimulation call, makes construction, production, movement,
    // combat, effects and AI all accelerate together without changing their
    // tick-domain results. In multiplayer the host owns this pacing and peers
    // still advance only the ticks committed by the lockstep barrier.
    // This rounded rate is for diagnostics; the loop uses the exact interval.
    // Speed 6 returns zero to identify retail's unlimited (no wait) setting.
    // Sidebar production multipliers remain independent of global pacing.
    return runtimeTickRateForGameSpeed(config.gameSpeed, config.fixedTickHz);
}

int runtimeCameraScrollStep(const RuntimeWindowState& state) {
    return 24 + (std::clamp(state.runtimeScrollRate, 0, 6) * 8);
}

RuntimeMenuPage runtimeMenuParentPage(RuntimeMenuPage page) {
    if (page == RuntimeMenuPage::Display
        || page == RuntimeMenuPage::Sound
        || page == RuntimeMenuPage::Keyboard) {
        return RuntimeMenuPage::Settings;
    }
    return RuntimeMenuPage::Main;
}

void ensureRuntimeMenuOptionDefaults(RuntimeWindowState& state) {
    if (state.runtimeResolutionWidth <= 0
        || state.runtimeResolutionHeight <= 0) {
        state.runtimeResolutionWidth = std::max(1, state.config.windowWidth);
        state.runtimeResolutionHeight = std::max(1, state.config.windowHeight);
    }
    state.config.gameSpeed = std::clamp(state.config.gameSpeed, 0, 6);
}

void resetRuntimeMenuPage(
    RuntimeWindowState& state,
    RuntimeMenuPage page
) {
    state.runtimeMenuPage = page;
    state.runtimeMenuHover = RuntimeMenuAction::None;
    state.runtimeMenuPressed = RuntimeMenuAction::None;
    state.runtimeMenuSliderDrag = RuntimeMenuAction::None;
    state.runtimeMenuKeyCaptureIndex = -1;
    state.runtimeMenuStatus.clear();
    state.runtimeMenuFocus = 0;
}

void setRuntimeMenuOpen(RuntimeWindowState& state, bool open) {
    ensureRuntimeMenuOptionDefaults(state);
    state.runtimeMenuOpen = open;
    resetRuntimeMenuPage(state, RuntimeMenuPage::Main);
    state.selectionDragActive = false;
    state.selectionDragMoved = false;
    state.rightDragActive = false;
    state.rightDragMoved = false;
    state.interactionStatus = open ? "menu open" : "menu closed";
}

void advanceRuntimeResultPresentation(RuntimeWindowState& state, ULONGLONG now);

#include "network/internet/RuntimeRankedDeparture.inl"

void activateRuntimeMenuAction(
    HWND window,
    RuntimeWindowState& state,
    RuntimeMenuAction action
) {
    if (action == RuntimeMenuAction::None) {
        return;
    }
    bool preferenceChanged = false;
    const char* soundIntent = runtimeSoundIntentSidebarButtonClick;
    if (action == RuntimeMenuAction::Options) {
        resetRuntimeMenuPage(state, RuntimeMenuPage::Settings);
        soundIntent = runtimeSoundIntentMenuOpen;
    } else if (action == RuntimeMenuAction::OpenDisplay) {
        resetRuntimeMenuPage(state, RuntimeMenuPage::Display);
        soundIntent = runtimeSoundIntentMenuOpen;
    } else if (action == RuntimeMenuAction::OpenSound) {
        resetRuntimeMenuPage(state, RuntimeMenuPage::Sound);
        soundIntent = runtimeSoundIntentMenuOpen;
    } else if (action == RuntimeMenuAction::OpenKeyboard) {
        ensureRuntimeMenuKeyboardLoaded(state);
        resetRuntimeMenuPage(state, RuntimeMenuPage::Keyboard);
        soundIntent = runtimeSoundIntentMenuOpen;
    } else if (action == RuntimeMenuAction::Exit) {
        resetRuntimeMenuPage(state, RuntimeMenuPage::ExitConfirm);
        soundIntent = runtimeSoundIntentMenuOpen;
    } else if (action == RuntimeMenuAction::Resume) {
        setRuntimeMenuOpen(state, false);
        soundIntent = runtimeSoundIntentMenuClose;
    } else if (action == RuntimeMenuAction::Back
        || action == RuntimeMenuAction::CancelExit) {
        resetRuntimeMenuPage(
            state,
            action == RuntimeMenuAction::CancelExit
                ? RuntimeMenuPage::Main
                : runtimeMenuParentPage(state.runtimeMenuPage)
        );
        soundIntent = runtimeSoundIntentMenuClose;
    } else if (action == RuntimeMenuAction::CycleGameSpeed) {
        state.config.gameSpeed = (state.config.gameSpeed + 1) % 7;
        preferenceChanged = true;
    } else if (action == RuntimeMenuAction::CycleScrollRate) {
        state.runtimeScrollRate = (state.runtimeScrollRate + 1) % 7;
        preferenceChanged = true;
    } else if (action == RuntimeMenuAction::CycleVisualDetail) {
        state.runtimeVisualDetail = (state.runtimeVisualDetail + 1) % 3;
        preferenceChanged = true;
    } else if (action == RuntimeMenuAction::ToggleTooltips) {
        state.runtimeTooltipsEnabled = !state.runtimeTooltipsEnabled;
        preferenceChanged = true;
    } else if (action == RuntimeMenuAction::ToggleTargetLines) {
        state.runtimeTargetLinesEnabled = !state.runtimeTargetLinesEnabled;
        preferenceChanged = true;
    } else if (action == RuntimeMenuAction::ToggleScrollCoasting) {
        state.runtimeScrollCoastingEnabled =
            !state.runtimeScrollCoastingEnabled;
        preferenceChanged = true;
    } else if (action == RuntimeMenuAction::ToggleHiddenObjects) {
        state.config.seeHiddenObjects = !state.config.seeHiddenObjects;
        preferenceChanged = true;
    } else if (action==RuntimeMenuAction::KeyboardCategory) {
        runtimeKeyboardChangePage(state,1,true);
    } else if (action==RuntimeMenuAction::KeyboardPreviousPage || action==RuntimeMenuAction::KeyboardNextPage) {
        runtimeKeyboardChangePage(state,action==RuntimeMenuAction::KeyboardPreviousPage?-1:1,false);
    } else if (action==RuntimeMenuAction::KeyboardResetAll) {
        for (std::size_t i=0;i<state.runtimeMenuKeyboardBindings.size();++i)
            state.runtimeMenuKeyboardBindings[i].second=runtimeKeyboardDefaultAt(static_cast<int>(i));
        state.runtimeMenuKeyCaptureIndex=-1;
        state.runtimeMenuStatus=L"所有命令已恢复默认键位。";
        preferenceChanged=true;
    } else if (runtimeKeyboardBindingIndexForAction(action) >= 0) {
        state.runtimeMenuKeyCaptureIndex =
            runtimeKeyboardBindingIndexForAction(action);
        const auto& binding = state.runtimeMenuKeyboardBindings[
            static_cast<std::size_t>(state.runtimeMenuKeyCaptureIndex)
        ];
        state.runtimeMenuStatus = runtimeMenuKeyboardBindingLabel(state, binding.first)
            + L"：请按新键。Esc取消，Backspace默认。";
    } else if (action == RuntimeMenuAction::CycleResolution) {
        const auto& resolutions = runtimeMenuResolutions();
        std::size_t nextIndex = 0;
        for (std::size_t index = 0; index < resolutions.size(); ++index) {
            if (resolutions[index].first == state.runtimeResolutionWidth
                && resolutions[index].second
                    == state.runtimeResolutionHeight) {
                nextIndex = (index + 1) % resolutions.size();
                break;
            }
        }
        state.runtimeResolutionWidth = resolutions[nextIndex].first;
        state.runtimeResolutionHeight = resolutions[nextIndex].second;
    } else if (action == RuntimeMenuAction::ApplyResolution) {
        state.config.windowWidth = state.runtimeResolutionWidth;
        state.config.windowHeight = state.runtimeResolutionHeight;
        preferenceChanged = true;
        if (window != nullptr && IsWindow(window)) {
            RECT windowRect{
                0,
                0,
                state.runtimeResolutionWidth,
                state.runtimeResolutionHeight
            };
            AdjustWindowRect(&windowRect, WS_OVERLAPPEDWINDOW, FALSE);
            SetWindowPos(
                window,
                nullptr,
                0,
                0,
                windowRect.right - windowRect.left,
                windowRect.bottom - windowRect.top,
                SWP_NOMOVE | SWP_NOZORDER | SWP_NOACTIVATE
            );
        }
    } else if (action == RuntimeMenuAction::AdjustMusicVolume) {
        state.runtimeMusicVolume = (state.runtimeMusicVolume + 20) % 120;
        state.runtimeMusicEnabled = state.runtimeMusicVolume > 0;
        if (state.runtimeMusicEnabled) {
            startRuntimeMusic(state);
        } else {
            stopRuntimeMusic(state);
        }
        preferenceChanged = true;
    } else if (action == RuntimeMenuAction::AdjustSoundVolume) {
        const int nextVolume = (state.runtimeSoundVolume + 20) % 120;
        if (state.runtimeSoundEffectsEnabled && nextVolume == 0) {
            emitRuntimeSound(state, runtimeSoundIntentSidebarButtonClick);
            soundIntent = nullptr;
        }
        state.runtimeSoundVolume = nextVolume;
        state.runtimeSoundEffectsEnabled = nextVolume > 0;
        if (!state.runtimeSoundEffectsEnabled) {
            stopRuntimeWorldAudioBackend(state, true);
        } else {
            applyRuntimeWorldAudioBackendActions(
                state,
                state.worldAudio.rehydrateActions(
                    runtimeWorldAudioContext(state),
                    state.tick
                )
            );
        }
        preferenceChanged = true;
    } else if (action == RuntimeMenuAction::AdjustVoiceVolume) {
        const int nextVoiceVolume =
            (state.runtimeVoiceVolume + 20) % 120;
        if (state.runtimeVoiceVolume > 0 && nextVoiceVolume == 0) {
            muteRuntimeEvaPlaybackPreservingSubtitle(state);
        }
        state.runtimeVoiceVolume = nextVoiceVolume;
        preferenceChanged = true;
    } else if (action == RuntimeMenuAction::ToggleMusic) {
        state.runtimeMusicEnabled = !state.runtimeMusicEnabled;
        if (state.runtimeMusicEnabled && state.runtimeMusicVolume == 0) {
            state.runtimeMusicVolume = 100;
        }
        if (state.runtimeMusicEnabled) {
            startRuntimeMusic(state);
        } else {
            stopRuntimeMusic(state);
        }
        preferenceChanged = true;
    } else if (action == RuntimeMenuAction::ToggleSound) {
        // Let the disabling click finish before muting subsequent effects.
        // Otherwise the action records the right semantic intent but is
        // silent because emitRuntimeSound observes the new disabled state.
        if (state.runtimeSoundEffectsEnabled) {
            emitRuntimeSound(state, runtimeSoundIntentSidebarButtonClick);
            soundIntent = nullptr;
        }
        state.runtimeSoundEffectsEnabled = !state.runtimeSoundEffectsEnabled;
        state.runtimeSoundVolume =
            state.runtimeSoundEffectsEnabled ? 100 : 0;
        if (!state.runtimeSoundEffectsEnabled) {
            stopRuntimeWorldAudioBackend(state, true);
        } else {
            applyRuntimeWorldAudioBackendActions(
                state,
                state.worldAudio.rehydrateActions(
                    runtimeWorldAudioContext(state),
                    state.tick
                )
            );
        }
        preferenceChanged = true;
    } else if (action == RuntimeMenuAction::Save
        || action == RuntimeMenuAction::Load) {
        std::string errorMessage;
        const bool saved = action == RuntimeMenuAction::Save;
        const bool ok = dispatchRuntimeSaveLoadFromUi(
            state,
            saved,
            errorMessage
        );
        state.interactionStatus = ok
            ? std::string(state.multiplayerBridge != nullptr
                ? (saved
                    ? "multiplayer save proposed"
                    : "multiplayer load proposed")
                : (saved ? "saved " : "loaded "))
                    + (state.multiplayerBridge == nullptr
                        ? runtimeDefaultSavePath(state)
                        : std::string{})
            : std::string(saved ? "save failed: " : "load failed: ")
                + errorMessage;
        if (state.multiplayerBridge == nullptr) {
            state.economy.status = state.interactionStatus;
        }
        soundIntent = ok ? (saved ? "save" : "load") : "blocked";
    } else if (action == RuntimeMenuAction::ConfirmExit) {
        if (state.skirmishMatchFinished) return;
        reportRuntimeRankedDeparture(state);
        emitRuntimeSound(state, runtimeSoundIntentMenuClose);
        if (state.campaignMode) {
            finishRuntimeCampaignMission(state, false, "player resigned");
        } else {
            state.skirmishMatchFinished = true;
            state.skirmishVictory = false;
            state.skirmishResult = "DEFEAT";
            state.economy.skirmishStatus = "player resigned";
            state.behaviors.clear();
            for (auto& object : state.world.accessObjects()) {
                if (object.renderMoveActive) clearRuntimeRenderPosition(object);
            }
        }
        state.resultPresentation = {};
        state.resultPresentation.resigned = true;
        // Keep this window and its statistics alive through the EVA/banner
        // and score page. Only the score's Continue action leaves the match.
        advanceRuntimeResultPresentation(state, GetTickCount64());
        return;
    }
    if (preferenceChanged) {
        state.runtimeMenuStatus.clear();
        (void)persistRuntimeMenuPreferences(state);
    }
    if (soundIntent != nullptr) {
        emitRuntimeSound(state, soundIntent);
    }
    state.repaintRequested = true;
    if (window != nullptr && IsWindow(window)) {
        RedrawWindow(
            window,
            nullptr,
            nullptr,
            RDW_INVALIDATE | RDW_NOERASE
        );
    }
}

void drawRuntimeMenuSidebarBackground(
    HDC dc,
    const RECT& clientRect,
    RuntimeWindowState& state
) {
    const RECT sidebar = runtimeSidebarRect(clientRect);
    HBRUSH background = CreateSolidBrush(RGB(17, 24, 32));
    FillRect(dc, &sidebar, background);
    DeleteObject(background);
    drawRuntimeSidebarSkin(dc, state, sidebar);

    const int listTop = sidebar.top + runtimeSidebarListOffset;
    const int listBottom = runtimeSidebarListBottom(sidebar);
    for (int y = listTop;
        y + runtimeSidebarSide2Height <= listBottom;
        y += runtimeSidebarSide2Height) {
        const RECT panel{
            sidebar.left,
            y,
            sidebar.right,
            y + runtimeSidebarSide2Height
        };
        drawRuntimeUiShpFrame(
            dc,
            state,
            "sidebar",
            "side2b",
            0,
            "sidebar",
            panel,
            true,
            false
        );
    }
    drawRuntimeUiShpFrame(
        dc,
        state,
        "sidebar",
        "radar",
        0,
        "radar",
        runtimeRadarRect(sidebar),
        true,
        false
    );
}

RuntimeMenuAction runtimeMenuFocusedAction(
    const RuntimeWindowState& state,
    const RECT& clientRect
) {
    const std::vector<RuntimeMenuButton> focusable =
        runtimeMenuFocusableButtons(state, clientRect);
    if (focusable.empty()) {
        return RuntimeMenuAction::None;
    }
    const int index = std::clamp(
        state.runtimeMenuFocus,
        0,
        static_cast<int>(focusable.size()) - 1
    );
    return focusable[static_cast<std::size_t>(index)].action;
}

bool handleRuntimeMenuHorizontalKey(
    RuntimeWindowState& state,
    const RECT& clientRect,
    WPARAM key
) {
    if (key != VK_LEFT && key != VK_RIGHT) {
        return false;
    }
    if (state.runtimeMenuPage==RuntimeMenuPage::Keyboard) {
        runtimeKeyboardChangePage(state,key==VK_RIGHT?1:-1,
            runtimeMenuFocusedAction(state,clientRect)==RuntimeMenuAction::KeyboardCategory);
        return true;
    }
    return adjustRuntimeMenuSliderPosition(
        state,
        runtimeMenuFocusedAction(state, clientRect),
        key == VK_RIGHT ? 1 : -1
    );
}

std::wstring runtimeMenuPageTitle(const RuntimeWindowState& state) {
    if (state.runtimeMenuPage == RuntimeMenuPage::Display) {
        return runtimeMenuLabel(
            state,
            "GUI:DisplayOptions",
            L"Display Options"
        );
    }
    if (state.runtimeMenuPage == RuntimeMenuPage::Sound) {
        return runtimeMenuLabel(
            state,
            "GUI:SoundOptions",
            L"Sound Options"
        );
    }
    if (state.runtimeMenuPage == RuntimeMenuPage::Keyboard) {
        return runtimeMenuLabel(
            state,
            "GUI:KeyboardOptions",
            L"Keyboard Options"
        );
    }
    return runtimeMenuLabel(state, "GUI:GameOptions", L"Game Options");
}

std::wstring runtimeMenuKeyboardBindingLabel(
    const RuntimeWindowState& state,
    const std::string& id
) {
    return runtimeFullKeyboardBindingLabel(state,id);
}

bool runtimeKeyboardModifierOnly(WPARAM key) {
    switch (key) {
    case VK_SHIFT:
    case VK_LSHIFT:
    case VK_RSHIFT:
    case VK_CONTROL:
    case VK_LCONTROL:
    case VK_RCONTROL:
    case VK_MENU:
    case VK_LMENU:
    case VK_RMENU:
    case VK_LWIN:
    case VK_RWIN:
        return true;
    default:
        return false;
    }
}

bool assignRuntimeMenuKeyboardBinding(
    RuntimeWindowState& state,
    int bindingIndex,
    int keyCode,
    bool restoredDefault
) {
    ensureRuntimeMenuKeyboardLoaded(state);
    if (bindingIndex < 0
        || bindingIndex
            >= static_cast<int>(state.runtimeMenuKeyboardBindings.size())
        || !runtimePlayerValidKeyCode(keyCode)) {
        state.runtimeMenuStatus = L"此按键无法指定。";
        return false;
    }

    const std::size_t selectedIndex =
        static_cast<std::size_t>(bindingIndex);
    auto& selected = state.runtimeMenuKeyboardBindings[selectedIndex];
    const int previousKey = selected.second;
    int conflictIndex = -1;
    for (std::size_t index = 0;
        index < state.runtimeMenuKeyboardBindings.size();
        ++index) {
        if (index != selectedIndex
            && state.runtimeMenuKeyboardBindings[index].second == keyCode) {
            conflictIndex = static_cast<int>(index);
            break;
        }
    }

    selected.second = keyCode;
    if (conflictIndex >= 0) {
        state.runtimeMenuKeyboardBindings[
            static_cast<std::size_t>(conflictIndex)
        ].second = previousKey;
    }
    state.runtimeMenuKeyCaptureIndex = -1;

    if (!persistRuntimeMenuPreferences(state)) {
        return true;
    }
    state.runtimeMenuStatus = runtimeMenuKeyboardBindingLabel(
        state,
        selected.first
    ) + L" = " + runtimeKeyboardKeyName(keyCode);
    if (conflictIndex >= 0) {
        const auto& exchanged = state.runtimeMenuKeyboardBindings[
            static_cast<std::size_t>(conflictIndex)
        ];
        state.runtimeMenuStatus += L"; "
            + runtimeMenuKeyboardBindingLabel(state, exchanged.first)
            + L" = "
            + runtimeKeyboardKeyName(exchanged.second);
    } else if (restoredDefault) {
        state.runtimeMenuStatus += L"（默认）";
    }
    return true;
}

bool handleRuntimeMenuKeyCapture(
    RuntimeWindowState& state,
    WPARAM key
) {
    if (!state.runtimeMenuOpen
        || state.runtimeMenuPage != RuntimeMenuPage::Keyboard
        || state.runtimeMenuKeyCaptureIndex < 0) {
        return false;
    }
    if (key == VK_ESCAPE) {
        state.runtimeMenuKeyCaptureIndex = -1;
        state.runtimeMenuStatus = L"已取消改键。";
        return true;
    }
    if (runtimeKeyboardModifierOnly(key)) {
        state.runtimeMenuStatus =
            L"请同时按下组合键中的字母、数字或功能键。";
        return true;
    }

    const int bindingIndex = state.runtimeMenuKeyCaptureIndex;
    int keyCode = runtimePlayerCurrentKeyCode(key);
    bool restoredDefault = false;
    if (key == VK_BACK) {
        if (bindingIndex < 0
            || bindingIndex >= static_cast<int>(state.runtimeMenuKeyboardBindings.size())) {
            state.runtimeMenuKeyCaptureIndex = -1;
            state.runtimeMenuStatus = L"已取消改键。";
            return true;
        }
        keyCode = runtimeKeyboardDefaultAt(bindingIndex);
        restoredDefault = true;
    }
    (void)assignRuntimeMenuKeyboardBinding(
        state,
        bindingIndex,
        keyCode,
        restoredDefault
    );
    return true;
}

void drawRuntimeMenuDialogContent(
    HDC dc,
    const RECT& clientRect,
    RuntimeWindowState& state,
    const RuntimePixelSurfaceTarget& target
) {
    if (state.runtimeMenuPage == RuntimeMenuPage::Main) {
        return;
    }

    const RuntimeMenuDialogLayout dialog =
        runtimeMenuDialogLayout(state, clientRect);
    RuntimeUiShpCacheEntry* image = loadRuntimeUiShpFrame(
        state,
        "",
        dialog.imageId,
        0
    );
    const std::vector<RuntimePaletteColor>* palette =
        runtimeUiPaletteForEntry(state, image, dialog.paletteId);
    const bool originalDialog = image != nullptr
        && palette != nullptr
        && drawRuntimeIndexedImage(
            dc,
            dialog.imageRect,
            image->image,
            *palette,
            true,
            false,
            true,
            target.pixels,
            target.width,
            target.height,
            false,
            runtimeIndexedOpaqueAlpha,
            image->pcxFallback,
            image->pcxFallback
        );
    if (originalDialog) {
        state.runtimeMenuDialogSource = image->sourcePath;
    } else {
        HBRUSH fallback = CreateSolidBrush(RGB(33, 31, 29));
        FillRect(dc, &dialog.imageRect, fallback);
        DeleteObject(fallback);
        FrameRect(
            dc,
            &dialog.imageRect,
            static_cast<HBRUSH>(GetStockObject(WHITE_BRUSH))
        );
    }

    SetBkMode(dc, TRANSPARENT);
    SetTextColor(dc, RGB(236, 229, 208));
    RECT titleRect{
        dialog.imageRect.left + 42,
        dialog.imageRect.top + 22,
        dialog.imageRect.right - 42,
        dialog.imageRect.top + 51
    };
    const std::wstring title = state.runtimeMenuPage == RuntimeMenuPage::ExitConfirm
        ? runtimeMenuLabel(state, "GUI:AbortMission", L"Abort Mission")
        : runtimeMenuPageTitle(state);
    DrawTextW(
        dc,
        title.c_str(),
        -1,
        &titleRect,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX
    );

    const RuntimeMenuAction focusedAction =
        runtimeMenuFocusedAction(state, clientRect);
    for (const RuntimeMenuControl& control :
        runtimeMenuContentControls(state, clientRect)) {
        const bool focused = control.action == state.runtimeMenuHover
            || control.action == focusedAction;
        const bool pressed = control.action == state.runtimeMenuPressed;
        const COLORREF lineColor = focused
            ? RGB(255, 218, 120)
            : RGB(181, 166, 132);
        SetTextColor(
            dc,
            focused ? RGB(255, 218, 120) : RGB(236, 229, 208)
        );
        RECT labelRect = control.rect;
        labelRect.right -= 116;
        if (control.kind != RuntimeMenuControlKind::Button) {
            DrawTextW(
                dc,
                control.label.c_str(),
                -1,
                &labelRect,
                DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX
            );
        }
        RECT valueRect = runtimeMenuControlValueRect(control);
        if (pressed) {
            OffsetRect(&valueRect, 1, 1);
        }

        if (control.kind == RuntimeMenuControlKind::Slider) {
            const RuntimeMenuSliderGeometry geometry =
                runtimeMenuSliderGeometryForValueRect(valueRect);
            HPEN pen = CreatePen(PS_SOLID, 2, lineColor);
            HGDIOBJ oldPen = SelectObject(dc, pen);
            MoveToEx(dc, geometry.trackLeft, geometry.trackY, nullptr);
            LineTo(dc, geometry.trackRight, geometry.trackY);
            const int maximum = std::max(1, control.valueMaximum);
            const int knobX = geometry.trackLeft
                + ((geometry.trackRight - geometry.trackLeft)
                    * std::clamp(control.valuePosition, 0, maximum)
                    / maximum);
            HBRUSH knob = CreateSolidBrush(lineColor);
            RECT knobRect{
                knobX - 3,
                geometry.trackY - 5,
                knobX + 4,
                geometry.trackY + 4
            };
            FillRect(dc, &knobRect, knob);
            DeleteObject(knob);
            SelectObject(dc, oldPen);
            DeleteObject(pen);
            valueRect.bottom -= 8;
            DrawTextW(
                dc,
                control.value.c_str(),
                -1,
                &valueRect,
                DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX
            );
        } else if (control.kind == RuntimeMenuControlKind::Checkbox) {
            RECT checkbox{
                valueRect.right - 22,
                valueRect.top + 6,
                valueRect.right - 7,
                valueRect.top + 21
            };
            HPEN pen = CreatePen(PS_SOLID, 1, lineColor);
            HGDIOBJ oldPen = SelectObject(dc, pen);
            HGDIOBJ oldBrush = SelectObject(
                dc,
                GetStockObject(HOLLOW_BRUSH)
            );
            Rectangle(
                dc,
                checkbox.left,
                checkbox.top,
                checkbox.right,
                checkbox.bottom
            );
            if (control.checked) {
                MoveToEx(dc, checkbox.left + 3, checkbox.top + 7, nullptr);
                LineTo(dc, checkbox.left + 7, checkbox.bottom - 3);
                LineTo(dc, checkbox.right - 2, checkbox.top + 3);
            }
            SelectObject(dc, oldBrush);
            SelectObject(dc, oldPen);
            DeleteObject(pen);
            valueRect.right = checkbox.left - 5;
            DrawTextW(
                dc,
                control.value.c_str(),
                -1,
                &valueRect,
                DT_RIGHT | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX
            );
        } else {
            HPEN pen = CreatePen(PS_SOLID, 1, lineColor);
            HGDIOBJ oldPen = SelectObject(dc, pen);
            HGDIOBJ oldBrush = SelectObject(
                dc,
                GetStockObject(HOLLOW_BRUSH)
            );
            Rectangle(
                dc,
                control.rect.left,
                control.rect.top,
                control.rect.right,
                control.rect.bottom
            );
            SelectObject(dc, oldBrush);
            SelectObject(dc, oldPen);
            DeleteObject(pen);
            if (control.kind == RuntimeMenuControlKind::Button) {
                RECT buttonText = control.rect;
                DrawTextW(
                    dc,
                    control.label.c_str(),
                    -1,
                    &buttonText,
                    DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX
                );
            } else {
                DrawTextW(
                    dc,
                    control.value.c_str(),
                    -1,
                    &valueRect,
                    DT_RIGHT | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX
                );
            }
        }
    }


    if (!state.runtimeMenuStatus.empty()) {
        SetTextColor(dc, RGB(255, 218, 120));
        RECT statusRect{
            dialog.imageRect.left + 48,
            dialog.imageRect.bottom - 42,
            dialog.imageRect.right - 48,
            dialog.imageRect.bottom - 14
        };
        DrawTextW(
            dc,
            state.runtimeMenuStatus.c_str(),
            -1,
            &statusRect,
            DT_CENTER | DT_VCENTER | DT_SINGLELINE
                | DT_END_ELLIPSIS | DT_NOPREFIX
        );
    }
}

void drawRuntimeMenuOverlay(
    HDC dc,
    const RECT& clientRect,
    RuntimeWindowState& state
) {
    if (!state.runtimeMenuOpen) {
        return;
    }

    const RuntimeMenuBackgroundLayout layout =
        runtimeMenuBackgroundLayout(clientRect);
    HBRUSH mask = CreateSolidBrush(RGB(0, 0, 0));
    FillRect(dc, &layout.contentRect, mask);
    DeleteObject(mask);
    RuntimeUiShpCacheEntry* background = loadRuntimeUiShpFrame(
        state,
        "sidebar",
        layout.imageId,
        0
    );
    const std::vector<RuntimePaletteColor>* palette =
        runtimeUiPaletteForEntry(state, background, "uibkgd");
    const RuntimePixelSurfaceTarget target =
        runtimePixelSurfaceTargetForDc(state, dc);
    const bool originalBackground = background != nullptr
        && palette != nullptr
        && drawRuntimeIndexedImage(
            dc,
            layout.imageRect,
            background->image,
            *palette,
            true,
            false,
            true,
            target.pixels,
            target.width,
            target.height,
            false,
            runtimeIndexedOpaqueAlpha,
            background->pcxFallback,
            background->pcxFallback
        );
    if (originalBackground) {
        state.runtimeMenuBackgroundSource = background->sourcePath;
    } else {
        HBRUSH fallback = CreateSolidBrush(RGB(38, 31, 23));
        FillRect(dc, &layout.imageRect, fallback);
        DeleteObject(fallback);
        FrameRect(
            dc,
            &layout.imageRect,
            static_cast<HBRUSH>(GetStockObject(WHITE_BRUSH))
        );
    }

    drawRuntimeMenuDialogContent(dc, clientRect, state, target);
    drawRuntimeMenuSidebarBackground(dc, clientRect, state);
    SetBkMode(dc, TRANSPARENT);

    const std::vector<RuntimeMenuButton> buttons =
        runtimeMenuButtons(state, clientRect);
    RuntimeUiShpCacheEntry* normalButton = loadRuntimeUiShpFrame(
        state,
        "sidebar",
        "sidebttn.shp",
        0
    );
    RuntimeUiShpCacheEntry* pressedButton = loadRuntimeUiShpFrame(
        state,
        "sidebar",
        "sidebttn.shp",
        1
    );
    normalButton = loadRuntimeUiShpFrame(
        state,
        "sidebar",
        "sidebttn.shp",
        0
    );
    pressedButton = loadRuntimeUiShpFrame(
        state,
        "sidebar",
        "sidebttn.shp",
        1
    );
    const RuntimeMenuAction focusedAction =
        runtimeMenuFocusedAction(state, clientRect);
    for (std::size_t index = 0; index < buttons.size(); ++index) {
        const RuntimeMenuButton& button = buttons[index];
        const bool focused = button.action == state.runtimeMenuHover
            || button.action == focusedAction;
        const bool pressed = button.action == state.runtimeMenuPressed;
        RuntimeUiShpCacheEntry* image = pressed && pressedButton != nullptr
            ? pressedButton
            : normalButton;
        const std::vector<RuntimePaletteColor>* buttonPalette =
            runtimeUiPaletteForEntry(state, image, "sidebar");
        const bool originalButton = image != nullptr
            && buttonPalette != nullptr
            && drawRuntimeIndexedImage(
                dc,
                button.rect,
                image->image,
                *buttonPalette,
                true,
                false,
                true,
                target.pixels,
                target.width,
                target.height,
                false,
                runtimeIndexedOpaqueAlpha,
                image->pcxFallback,
                image->pcxFallback
            );
        if (!originalButton) {
            HBRUSH brush = CreateSolidBrush(
                pressed ? RGB(83, 28, 18)
                    : focused ? RGB(107, 44, 25)
                    : RGB(53, 34, 24)
            );
            FillRect(dc, &button.rect, brush);
            DeleteObject(brush);
            FrameRect(
                dc,
                &button.rect,
                static_cast<HBRUSH>(GetStockObject(WHITE_BRUSH))
            );
        }
        SetTextColor(
            dc,
            focused ? RGB(255, 218, 120) : RGB(236, 229, 208)
        );
        RECT textRect = button.rect;
        if (pressed) {
            OffsetRect(&textRect, 1, 1);
        }
        DrawTextW(
            dc,
            button.label.c_str(),
            -1,
            &textRect,
            DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX
        );
    }

    if (state.runtimeMenuPage == RuntimeMenuPage::ExitConfirm) {
        SetTextColor(dc, RGB(236, 229, 208));
        const RuntimeMenuDialogLayout dialog =
            runtimeMenuDialogLayout(state, clientRect);
        RECT prompt{
            dialog.imageRect.left + 64,
            dialog.imageRect.top + 86,
            dialog.imageRect.right - 64,
            dialog.imageRect.bottom - 68
        };
        const std::wstring promptLabel = runtimeMenuLabel(
            state,
            "GUI:AskAbortMission",
            L"Abort the current mission?"
        );
        DrawTextW(
            dc,
            promptLabel.c_str(),
            -1,
            &prompt,
            DT_CENTER | DT_VCENTER | DT_WORDBREAK | DT_NOPREFIX
        );
    }
}

RECT runtimeCampaignScoreScaledRect(
    const RECT& clientRect,
    const RECT& baseRect
) {
    const int width = std::max(1L, clientRect.right - clientRect.left);
    const int height = std::max(1L, clientRect.bottom - clientRect.top);
    return RECT{
        clientRect.left + baseRect.left * width / 800,
        clientRect.top + baseRect.top * height / 600,
        clientRect.left + baseRect.right * width / 800,
        clientRect.top + baseRect.bottom * height / 600
    };
}

std::wstring runtimeCampaignScoreTimeText(int ticks, int fixedTickHz) {
    if (ticks < 0) return L"--:--:--";
    const int seconds = ticks / std::max(1, fixedTickHz);
    const int hours = seconds / 3600;
    const int minutes = (seconds / 60) % 60;
    const int remainingSeconds = seconds % 60;
    std::wstringstream stream;
    stream << std::setfill(L'0') << std::setw(2) << hours
           << L":" << std::setw(2) << minutes
           << L":" << std::setw(2) << remainingSeconds;
    return stream.str();
}

enum class RuntimeCampaignScoreTheme {
    Allied,
    Soviet,
    Yuri
};

struct RuntimeCampaignScoreAssets {
    const char* faction = "Allied";
    const char* background = "ascrbkmd.shp";
    const char* transition = "ascrtmd.shp";
    const char* animation = "ascramd.shp";
    const char* palette = "ascore";
    int animationHeight = 220;
};

struct RuntimeCampaignScorePresentation {
    bool underPar = false;
    std::string titleKey;
    std::string messageKey;
    std::wstring title;
    std::wstring message;
};

RuntimeCampaignScoreTheme runtimeCampaignScoreTheme(
    const RuntimeWindowState& state
) {
    const std::string identity = toLowerAsciiLocal(
        state.config.campaignId + " "
        + state.config.campaignPlayerHouse + " "
        + state.config.playerCountry
    );
    if (runtimeCountryIsYuri(state.config.playerCountry)
        || identity.find("yuri") != std::string::npos
        || identity.find("psi") != std::string::npos) {
        return RuntimeCampaignScoreTheme::Yuri;
    }
    if (runtimeCountryIsSoviet(state.config.playerCountry)
        || identity.find("sov") != std::string::npos
        || identity.find("nod") != std::string::npos
        || identity.find("russ") != std::string::npos) {
        return RuntimeCampaignScoreTheme::Soviet;
    }
    return RuntimeCampaignScoreTheme::Allied;
}

RuntimeCampaignScoreAssets runtimeCampaignScoreAssets(
    RuntimeCampaignScoreTheme theme
) {
    if (theme == RuntimeCampaignScoreTheme::Soviet) {
        return {
            "Soviet",
            "sscrbkmd.shp",
            "sscrtmd.shp",
            "sscramd.shp",
            "sscore",
            230
        };
    }
    if (theme == RuntimeCampaignScoreTheme::Yuri) {
        return {
            "Yuri",
            "sycrbkmd.shp",
            "sycrtmd.shp",
            "sycramd.shp",
            "yscore",
            230
        };
    }
    return {};
}

bool runtimeCampaignScoreUsesSovietTheme(const RuntimeWindowState& state) {
    return runtimeCampaignScoreTheme(state)
        == RuntimeCampaignScoreTheme::Soviet;
}

std::wstring runtimeCampaignScoreAuthoredText(
    const RuntimeWindowState& state,
    const std::string& key,
    const wchar_t* fallback
) {
    if (!trimAsciiLocal(key).empty()) {
        const std::wstring localized = runtimeMenuLabel(state, key, L"");
        if (!localized.empty()) {
            return localized;
        }
        // Mod missions may author literal text instead of a CSF key.
        if (key.find(':') == std::string::npos) {
            return widenUtf8(key);
        }
    }
    return std::wstring(fallback);
}

RuntimeCampaignScorePresentation runtimeCampaignScorePresentation(
    const RuntimeWindowState& state
) {
    RuntimeCampaignScorePresentation presentation;
    if (!state.skirmishVictory) {
        presentation.title = L"MISSION FAILED";
        presentation.message =
            L"Mission failed. Review the battle record before returning to command.";
        return presentation;
    }

    const RuntimeCampaignScoreState& score = state.campaignScore;
    presentation.underPar = score.captured
        ? score.finishedUnderPar
        : score.parTicks > 0
            && runtimeCampaignScoreElapsedTicks(score) <= score.parTicks;
    presentation.titleKey = presentation.underPar
        ? score.underParTitleKey
        : score.overParTitleKey;
    presentation.messageKey = presentation.underPar
        ? score.underParMessageKey
        : score.overParMessageKey;
    const std::string defaultTitleKey = presentation.underPar
        ? "GUI:NoUnderParTitle"
        : "GUI:NoOverParTitle";
    const std::string defaultMessageKey = presentation.underPar
        ? "GUI:NoUnderParMessage"
        : "GUI:NoOverParMessage";
    if (presentation.titleKey.empty()) {
        presentation.titleKey = defaultTitleKey;
    }
    if (presentation.messageKey.empty()) {
        presentation.messageKey = defaultMessageKey;
    }
    presentation.title = runtimeCampaignScoreAuthoredText(
        state,
        presentation.titleKey,
        presentation.underPar ? L"MISSION ACCOMPLISHED" : L"MISSION COMPLETE"
    );
    presentation.message = runtimeCampaignScoreAuthoredText(
        state,
        presentation.messageKey,
        L"Mission performance recorded."
    );
    return presentation;
}

void drawRuntimeCampaignScoreFallbackOverlay(
    HDC dc,
    const RECT& clientRect,
    const RuntimeWindowState& state
) {
    const RuntimeCampaignScoreTheme theme = runtimeCampaignScoreTheme(state);
    const bool soviet = theme == RuntimeCampaignScoreTheme::Soviet;
    const bool yuri = theme == RuntimeCampaignScoreTheme::Yuri;
    const COLORREF background = soviet ? RGB(44, 5, 8)
        : yuri ? RGB(29, 8, 43) : RGB(6, 17, 34);
    const COLORREF panel = soviet ? RGB(66, 12, 13)
        : yuri ? RGB(47, 17, 64) : RGB(10, 31, 52);
    const COLORREF accent = soviet ? RGB(190, 44, 31)
        : yuri ? RGB(139, 65, 172) : RGB(53, 129, 184);
    const COLORREF brightAccent = soviet ? RGB(255, 110, 63)
        : yuri ? RGB(215, 143, 242) : RGB(116, 205, 239);
    const COLORREF gold = RGB(232, 199, 94);
    const COLORREF text = RGB(226, 226, 210);
    const int savedDc = SaveDC(dc);
    SetBkMode(dc, TRANSPARENT);

    HBRUSH backgroundBrush = CreateSolidBrush(background);
    FillRect(dc, &clientRect, backgroundBrush);
    DeleteObject(backgroundBrush);
    for (int band = 0; band < 12; ++band) {
        const int shade = band * 3;
        HBRUSH bandBrush = CreateSolidBrush(soviet
            ? RGB(30 + shade, 5 + band, 7 + band)
            : yuri
                ? RGB(18 + band, 6 + band, 29 + shade)
                : RGB(5 + band, 13 + band, 28 + shade));
        const RECT bandRect{
            clientRect.left,
            clientRect.top + band * std::max(1L,
                (clientRect.bottom - clientRect.top) / 12),
            clientRect.right,
            clientRect.top + (band + 1) * std::max(1L,
                (clientRect.bottom - clientRect.top) / 12)
        };
        FillRect(dc, &bandRect, bandBrush);
        DeleteObject(bandBrush);
    }

    const RECT header = runtimeCampaignScoreScaledRect(
        clientRect,
        RECT{20, 18, 520, 145}
    );
    const RECT graphPanel = runtimeCampaignScoreScaledRect(
        clientRect,
        RECT{530, 72, 772, 466}
    );
    const RECT footer = runtimeCampaignScoreScaledRect(
        clientRect,
        RECT{20, 476, 780, 582}
    );
    HBRUSH panelBrush = CreateSolidBrush(panel);
    FillRect(dc, &header, panelBrush);
    FillRect(dc, &graphPanel, panelBrush);
    FillRect(dc, &footer, panelBrush);
    DeleteObject(panelBrush);

    HPEN framePen = CreatePen(PS_SOLID, 3, accent);
    HGDIOBJ oldPen = SelectObject(dc, framePen);
    HGDIOBJ oldBrush = SelectObject(dc, GetStockObject(HOLLOW_BRUSH));
    Rectangle(dc, clientRect.left + 6, clientRect.top + 6,
        clientRect.right - 6, clientRect.bottom - 6);
    Rectangle(dc, header.left, header.top, header.right, header.bottom);
    Rectangle(dc, graphPanel.left, graphPanel.top,
        graphPanel.right, graphPanel.bottom);
    Rectangle(dc, footer.left, footer.top, footer.right, footer.bottom);
    SelectObject(dc, oldBrush);
    SelectObject(dc, oldPen);
    DeleteObject(framePen);

    const double verticalScale = std::max(
        0.65,
        static_cast<double>(clientRect.bottom - clientRect.top) / 600.0
    );
    const auto makeFont = [verticalScale](int size, int weight) {
        return CreateFontW(
            -std::max(10, static_cast<int>(std::lround(size * verticalScale))),
            0, 0, 0, weight, FALSE, FALSE, FALSE,
            DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS,
            ANTIALIASED_QUALITY, DEFAULT_PITCH | FF_DONTCARE,
            L"Arial"
        );
    };
    HFONT titleFont = makeFont(30, FW_BOLD);
    HFONT headingFont = makeFont(21, FW_BOLD);
    HFONT bodyFont = makeFont(16, FW_NORMAL);
    HFONT numberFont = makeFont(32, FW_BOLD);
    const auto drawBaseText = [&](
        HFONT font,
        const std::wstring& value,
        const RECT& baseRect,
        COLORREF color,
        UINT format
    ) {
        RECT rect = runtimeCampaignScoreScaledRect(clientRect, baseRect);
        HGDIOBJ previousFont = SelectObject(dc, font);
        SetTextColor(dc, color);
        DrawTextW(dc, value.c_str(), static_cast<int>(value.size()), &rect,
            format | DT_NOPREFIX);
        SelectObject(dc, previousFont);
    };

    const RuntimeCampaignScorePresentation presentation =
        runtimeCampaignScorePresentation(state);
    drawBaseText(
        titleFont,
        presentation.title,
        RECT{42, 30, 515, 73},
        state.skirmishVictory ? gold : brightAccent,
        DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS
    );
    drawBaseText(
        bodyFont,
        presentation.message,
        RECT{43, 78, 505, 130},
        text,
        DT_LEFT | DT_TOP | DT_WORDBREAK
    );

    const int enemiesDestroyed = state.campaignScore.enemyUnitsDestroyed
        + state.campaignScore.enemyStructuresDestroyed;
    drawBaseText(
        headingFont,
        L"ENEMIES DESTROYED",
        RECT{45, 157, 345, 188},
        text,
        DT_LEFT | DT_VCENTER | DT_SINGLELINE
    );
    drawBaseText(
        numberFont,
        std::to_wstring(enemiesDestroyed),
        RECT{350, 148, 505, 196},
        gold,
        DT_RIGHT | DT_VCENTER | DT_SINGLELINE
    );

    const RECT emblemRect = runtimeCampaignScoreScaledRect(
        clientRect,
        RECT{132, 205, 426, 415}
    );
    HBRUSH emblemBrush = CreateSolidBrush(accent);
    HPEN emblemPen = CreatePen(PS_SOLID, 4, brightAccent);
    oldBrush = SelectObject(dc, emblemBrush);
    oldPen = SelectObject(dc, emblemPen);
    Ellipse(dc, emblemRect.left, emblemRect.top,
        emblemRect.right, emblemRect.bottom);
    SelectObject(dc, oldBrush);
    SelectObject(dc, oldPen);
    DeleteObject(emblemBrush);
    DeleteObject(emblemPen);

    const int emblemCx = (emblemRect.left + emblemRect.right) / 2;
    const int emblemCy = (emblemRect.top + emblemRect.bottom) / 2;
    const int emblemRadius = std::max(
        12,
        static_cast<int>(emblemRect.bottom - emblemRect.top) / 3
    );
    HBRUSH symbolBrush = CreateSolidBrush(soviet ? gold : RGB(225, 235, 239));
    HPEN symbolPen = CreatePen(PS_SOLID, 2, soviet ? gold : brightAccent);
    oldBrush = SelectObject(dc, symbolBrush);
    oldPen = SelectObject(dc, symbolPen);
    if (soviet) {
        std::array<POINT, 10> star{};
        constexpr double pi = 3.14159265358979323846;
        for (std::size_t index = 0; index < star.size(); ++index) {
            const double angle = -pi / 2.0 + index * pi / 5.0;
            const double radius = (index % 2U) == 0U
                ? emblemRadius
                : emblemRadius * 0.42;
            star[index] = POINT{
                emblemCx + static_cast<int>(std::lround(std::cos(angle) * radius)),
                emblemCy + static_cast<int>(std::lround(std::sin(angle) * radius))
            };
        }
        Polygon(dc, star.data(), static_cast<int>(star.size()));
    } else {
        const std::array<POINT, 7> shield{{
            POINT{emblemCx, emblemCy - emblemRadius},
            POINT{emblemCx + emblemRadius * 2 / 3, emblemCy - emblemRadius / 2},
            POINT{emblemCx + emblemRadius / 2, emblemCy + emblemRadius / 2},
            POINT{emblemCx, emblemCy + emblemRadius},
            POINT{emblemCx - emblemRadius / 2, emblemCy + emblemRadius / 2},
            POINT{emblemCx - emblemRadius * 2 / 3, emblemCy - emblemRadius / 2},
            POINT{emblemCx, emblemCy - emblemRadius}
        }};
        Polygon(dc, shield.data(), static_cast<int>(shield.size()));
        SelectObject(dc, GetStockObject(HOLLOW_BRUSH));
        for (int wing = 0; wing < 4; ++wing) {
            const int offset = wing * emblemRadius / 7;
            MoveToEx(dc, emblemCx - emblemRadius / 3, emblemCy - offset, nullptr);
            LineTo(dc, emblemCx - emblemRadius, emblemCy - emblemRadius / 2 - offset);
            MoveToEx(dc, emblemCx + emblemRadius / 3, emblemCy - offset, nullptr);
            LineTo(dc, emblemCx + emblemRadius, emblemCy - emblemRadius / 2 - offset);
        }
    }
    SelectObject(dc, oldBrush);
    SelectObject(dc, oldPen);
    DeleteObject(symbolBrush);
    DeleteObject(symbolPen);

    drawBaseText(
        bodyFont,
        L"Enemy units  " + std::to_wstring(
            state.campaignScore.enemyUnitsDestroyed
        ) + L"    Enemy structures  " + std::to_wstring(
            state.campaignScore.enemyStructuresDestroyed
        ),
        RECT{45, 420, 510, 458},
        text,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE
    );

    drawBaseText(
        headingFont,
        L"APPROX. INTERNAL SCORE",
        RECT{545, 86, 758, 120},
        gold,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE
    );
    drawBaseText(
        numberFont,
        std::to_wstring(state.campaignScore.finalScore),
        RECT{545, 122, 758, 170},
        brightAccent,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE
    );

    const RECT graph = runtimeCampaignScoreScaledRect(
        clientRect,
        RECT{554, 187, 750, 405}
    );
    HPEN gridPen = CreatePen(PS_DOT, 1, soviet ? RGB(109, 45, 38) : RGB(38, 83, 112));
    oldPen = SelectObject(dc, gridPen);
    for (int line = 0; line <= 4; ++line) {
        const int y = graph.top + line * (graph.bottom - graph.top) / 4;
        MoveToEx(dc, graph.left, y, nullptr);
        LineTo(dc, graph.right, y);
    }
    SelectObject(dc, oldPen);
    DeleteObject(gridPen);

    const ULONGLONG now = GetTickCount64();
    const ULONGLONG elapsedMs = state.campaignScore.presentationStartedAtMs == 0
        || now < state.campaignScore.presentationStartedAtMs
        ? 2000ULL
        : now - state.campaignScore.presentationStartedAtMs;
    const int visibleBars = std::clamp<int>(
        1 + static_cast<int>(elapsedMs / 130ULL),
        1,
        12
    );
    HBRUSH graphBrush = CreateSolidBrush(accent);
    for (int index = 0; index < visibleBars; ++index) {
        const int left = graph.left
            + index * (graph.right - graph.left) / 12 + 2;
        const int right = graph.left
            + (index + 1) * (graph.right - graph.left) / 12 - 2;
        const int performance = std::clamp(
            18 + index * 5
                + (state.campaignScore.finalScore / 180 + index * 7) % 28,
            10,
            96
        );
        const int top = graph.bottom
            - performance * (graph.bottom - graph.top) / 100;
        const RECT bar{left, top, std::max(left + 1, right), graph.bottom};
        FillRect(dc, &bar, graphBrush);
    }
    DeleteObject(graphBrush);

    drawBaseText(
        bodyFont,
        L"Units lost  " + std::to_wstring(
            state.campaignScore.friendlyUnitsLost
        ) + L"    Structures lost  " + std::to_wstring(
            state.campaignScore.friendlyStructuresLost
        ),
        RECT{42, 490, 510, 520},
        text,
        DT_LEFT | DT_VCENTER | DT_SINGLELINE
    );
    const int elapsedTicks = runtimeCampaignScoreElapsedTicks(
        state.campaignScore
    );
    drawBaseText(
        bodyFont,
        L"Par Time  " + runtimeCampaignScoreTimeText(
            state.campaignScore.parTicks > 0
                ? state.campaignScore.parTicks
                : -1,
            state.config.fixedTickHz
        ) + L"     Your Time  " + runtimeCampaignScoreTimeText(
            elapsedTicks,
            state.config.fixedTickHz
        ),
        RECT{42, 530, 510, 560},
        gold,
        DT_LEFT | DT_VCENTER | DT_SINGLELINE
    );

    const RECT continueRect = runtimeCampaignScoreScaledRect(
        clientRect,
        RECT{566, 490, 742, 540}
    );
    HBRUSH continueBrush = CreateSolidBrush(background);
    HPEN continuePen = CreatePen(PS_SOLID, 3, gold);
    oldBrush = SelectObject(dc, continueBrush);
    oldPen = SelectObject(dc, continuePen);
    RoundRect(dc, continueRect.left, continueRect.top,
        continueRect.right, continueRect.bottom, 8, 8);
    SelectObject(dc, oldBrush);
    SelectObject(dc, oldPen);
    DeleteObject(continueBrush);
    DeleteObject(continuePen);
    drawBaseText(
        headingFont,
        L"CONTINUE",
        RECT{566, 490, 742, 540},
        gold,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE
    );
    drawBaseText(
        bodyFont,
        widenUtf8(
            state.config.campaignId + " / "
            + state.config.campaignMissionId
        ),
        RECT{540, 548, 765, 574},
        text,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS
    );

    DeleteObject(titleFont);
    DeleteObject(headingFont);
    DeleteObject(bodyFont);
    DeleteObject(numberFont);
    RestoreDC(dc, savedDc);
}

void drawRuntimeCampaignScoreOverlay(
    HDC dc,
    const RECT& clientRect,
    RuntimeWindowState& state
) {
    const RuntimeCampaignScoreAssets assets = runtimeCampaignScoreAssets(
        runtimeCampaignScoreTheme(state)
    );
    RuntimeUiShpCacheEntry* background = loadRuntimeUiShpFrame(
        state,
        "",
        assets.background,
        0
    );
    RuntimeUiShpCacheEntry* transitionFirst = loadRuntimeUiShpFrame(
        state,
        "",
        assets.transition,
        0
    );
    RuntimeUiShpCacheEntry* transitionLast = loadRuntimeUiShpFrame(
        state,
        "",
        assets.transition,
        5
    );
    RuntimeUiShpCacheEntry* animationFirst = loadRuntimeUiShpFrame(
        state,
        "",
        assets.animation,
        0
    );
    RuntimeUiShpCacheEntry* animationLast = loadRuntimeUiShpFrame(
        state,
        "",
        assets.animation,
        43
    );
    const std::vector<RuntimePaletteColor>* palette = runtimeUiPalette(
        state,
        assets.palette
    );
    const bool stockAssetsAvailable = background != nullptr
        && transitionFirst != nullptr
        && transitionLast != nullptr
        && animationFirst != nullptr
        && animationLast != nullptr
        && palette != nullptr
        && (background->image.globalWidth > 0
            ? background->image.globalWidth
            : background->image.width) == 632
        && (background->image.globalHeight > 0
            ? background->image.globalHeight
            : background->image.height) == 568
        && (transitionFirst->image.globalWidth > 0
            ? transitionFirst->image.globalWidth
            : transitionFirst->image.width) == 472
        && (transitionFirst->image.globalHeight > 0
            ? transitionFirst->image.globalHeight
            : transitionFirst->image.height) == 448
        && (animationFirst->image.globalWidth > 0
            ? animationFirst->image.globalWidth
            : animationFirst->image.width) == 424
        && (animationFirst->image.globalHeight > 0
            ? animationFirst->image.globalHeight
            : animationFirst->image.height) == assets.animationHeight;
    if (!stockAssetsAvailable) {
        drawRuntimeCampaignScoreFallbackOverlay(dc, clientRect, state);
        return;
    }

    const int savedDc = SaveDC(dc);
    SetBkMode(dc, TRANSPARENT);
    HBRUSH black = CreateSolidBrush(RGB(0, 0, 0));
    FillRect(dc, &clientRect, black);
    DeleteObject(black);

    const RECT backgroundRect = runtimeCampaignScoreScaledRect(
        clientRect,
        RECT{84, 16, 716, 584}
    );
    const RECT transitionRect = runtimeCampaignScoreScaledRect(
        clientRect,
        RECT{164, 76, 636, 524}
    );
    const int animationTop = 320 - assets.animationHeight / 2;
    const RECT animationRect = runtimeCampaignScoreScaledRect(
        clientRect,
        RECT{188, animationTop, 612, animationTop + assets.animationHeight}
    );

    bool originalDrawn = drawRuntimeUiShpFrame(
        dc,
        state,
        "",
        assets.background,
        0,
        assets.palette,
        backgroundRect,
        true,
        true
    );
    const ULONGLONG now = GetTickCount64();
    const ULONGLONG elapsedMs = state.campaignScore.presentationStartedAtMs == 0
        || now < state.campaignScore.presentationStartedAtMs
        ? 3000ULL
        : now - state.campaignScore.presentationStartedAtMs;
    constexpr ULONGLONG transitionFrameMs = 100ULL;
    constexpr ULONGLONG transitionDurationMs = 6ULL * transitionFrameMs;
    if (elapsedMs < transitionDurationMs) {
        // The authored transition is animation-to-background. Opening the
        // result page therefore plays its six frames in reverse.
        const int transitionFrame = 5 - static_cast<int>(
            elapsedMs / transitionFrameMs
        );
        originalDrawn = drawRuntimeUiShpFrameCanvasTransparent(
            dc,
            state,
            "",
            assets.transition,
            transitionFrame,
            assets.palette,
            transitionRect,
            true
        ) && originalDrawn;
    } else {
        originalDrawn = drawRuntimeUiShpFrameCanvasTransparent(
            dc,
            state,
            "",
            assets.transition,
            0,
            assets.palette,
            transitionRect,
            true
        ) && originalDrawn;

        // Retail assets have 44 frames: 0..28 play once, 29..43 loop. The
        // 15 fps cadence remains a presentation approximation pending a
        // dedicated retail timing trace.
        const std::uint64_t animationTick =
            (elapsedMs - transitionDurationMs) * 15ULL / 1000ULL;
        const int animationFrame = animationTick < 29ULL
            ? static_cast<int>(animationTick)
            : 29 + static_cast<int>((animationTick - 29ULL) % 15ULL);
        originalDrawn = drawRuntimeUiShpFrameCanvasTransparent(
            dc,
            state,
            "",
            assets.animation,
            animationFrame,
            assets.palette,
            animationRect,
            true
        ) && originalDrawn;
    }

    if (!originalDrawn) {
        RestoreDC(dc, savedDc);
        drawRuntimeCampaignScoreFallbackOverlay(dc, clientRect, state);
        return;
    }

    const RuntimeCampaignScoreTheme theme = runtimeCampaignScoreTheme(state);
    const COLORREF titleColor = theme == RuntimeCampaignScoreTheme::Soviet
        ? RGB(255, 222, 133)
        : theme == RuntimeCampaignScoreTheme::Yuri
            ? RGB(226, 186, 255)
            : RGB(204, 235, 255);
    const COLORREF bodyColor = RGB(232, 232, 218);
    const double verticalScale = std::max(
        0.65,
        static_cast<double>(clientRect.bottom - clientRect.top) / 600.0
    );
    const auto makeFont = [verticalScale](int size, int weight) {
        return CreateFontW(
            -std::max(10, static_cast<int>(std::lround(size * verticalScale))),
            0, 0, 0, weight, FALSE, FALSE, FALSE,
            DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS,
            ANTIALIASED_QUALITY, DEFAULT_PITCH | FF_DONTCARE,
            L"Arial"
        );
    };
    HFONT titleFont = makeFont(19, FW_BOLD);
    HFONT messageFont = makeFont(14, FW_NORMAL);
    HFONT labelFont = makeFont(12, FW_BOLD);
    HFONT valueFont = makeFont(15, FW_BOLD);
    const auto drawBaseText = [&] (
        HFONT font,
        const std::wstring& value,
        const RECT& baseRect,
        COLORREF color,
        UINT format
    ) {
        RECT rect = runtimeCampaignScoreScaledRect(clientRect, baseRect);
        HGDIOBJ oldFont = SelectObject(dc, font);
        RECT shadow = rect;
        OffsetRect(&shadow, 1, 1);
        SetTextColor(dc, RGB(0, 0, 0));
        DrawTextW(dc, value.c_str(), static_cast<int>(value.size()), &shadow,
            format | DT_NOPREFIX);
        SetTextColor(dc, color);
        DrawTextW(dc, value.c_str(), static_cast<int>(value.size()), &rect,
            format | DT_NOPREFIX);
        SelectObject(dc, oldFont);
    };

    const RuntimeCampaignScorePresentation presentation =
        runtimeCampaignScorePresentation(state);
    drawBaseText(
        titleFont,
        presentation.title,
        RECT{212, 88, 588, 120},
        titleColor,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS
    );
    drawBaseText(
        messageFont,
        presentation.message,
        RECT{213, 122, 587, 207},
        bodyColor,
        DT_CENTER | DT_VCENTER | DT_WORDBREAK
    );

    const std::wstring parLabel = runtimeMenuLabel(
        state,
        "GUI:ParTime",
        L"Par Time"
    );
    const std::wstring yourLabel = runtimeMenuLabel(
        state,
        "GUI:YourTime",
        L"Your Time"
    );
    const std::wstring destroyedLabel = runtimeMenuLabel(
        state,
        "GUI:HeadsTaken",
        L"Enemies Destroyed"
    );
    drawBaseText(
        labelFont,
        parLabel,
        RECT{242, 446, 382, 463},
        bodyColor,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS
    );
    drawBaseText(
        valueFont,
        runtimeCampaignScoreTimeText(
            state.campaignScore.parTicks > 0
                ? state.campaignScore.parTicks
                : -1,
            state.config.fixedTickHz
        ),
        RECT{242, 462, 382, 481},
        titleColor,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE
    );
    drawBaseText(
        labelFont,
        yourLabel,
        RECT{242, 482, 382, 499},
        bodyColor,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS
    );
    drawBaseText(
        valueFont,
        runtimeCampaignScoreTimeText(
            runtimeCampaignScoreElapsedTicks(state.campaignScore),
            state.config.fixedTickHz
        ),
        RECT{242, 498, 382, 517},
        titleColor,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE
    );
    drawBaseText(
        labelFont,
        destroyedLabel,
        RECT{405, 455, 559, 480},
        bodyColor,
        DT_CENTER | DT_VCENTER | DT_WORDBREAK | DT_END_ELLIPSIS
    );
    drawBaseText(
        valueFont,
        std::to_wstring(
            state.campaignScore.enemyUnitsDestroyed
                + state.campaignScore.enemyStructuresDestroyed
        ),
        RECT{405, 481, 559, 511},
        titleColor,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE
    );
    drawBaseText(
        labelFont,
        runtimeMenuLabel(state, "GUI:Continue", L"Continue"),
        RECT{215, 548, 585, 576},
        titleColor,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS
    );

    DeleteObject(titleFont);
    DeleteObject(messageFont);
    DeleteObject(labelFont);
    DeleteObject(valueFont);
    RestoreDC(dc, savedDc);
}
#include "ui/results/RuntimeMatchScoreRender.inl"
#include "ui/hud/RuntimeSuperWeaponTimerText.inl"

int runtimeResultBannerFrame(const RuntimeWindowState& state) {
    // GRFXTXT's four frames are distinct outcomes, not an animation loop.
    // Retail HouseClass selects 0/1 for missions and 2/3 for multiplayer.
    return (state.campaignMode ? 0 : 2) + (state.skirmishVictory ? 0 : 1);
}

const char* runtimeResultVoice(const RuntimeWindowState& state) {
    if (state.resultPresentation.resigned) return "EVA_YouHaveResigned";
    if (state.campaignMode) {
        return state.skirmishVictory
            ? "EVA_MissionAccomplished" : "EVA_MissionFailed";
    }
    return state.skirmishVictory ? "EVA_YouAreVictorious" : "EVA_YouHaveLost";
}

bool runtimeResultScoreIsAnimated(const RuntimeWindowState& state) {
    return state.skirmishMatchFinished && state.campaignMode
        && !state.resultPresentation.bannerVisible;
}

void beginRuntimeResultScorePage(RuntimeWindowState& state, ULONGLONG now) {
    auto& presentation = state.resultPresentation;
    presentation.bannerVisible = false;
    state.campaignScore.presentationStartedAtMs = now;
    if (!presentation.scoreMusicSelected) {
        presentation.scoreMusicSelected = playRuntimeMusicTheme(state, "SCORE");
    }
    state.repaintRequested = true;
}

void advanceRuntimeResultPresentation(RuntimeWindowState& state, ULONGLONG now) {
    if (!state.skirmishMatchFinished) {
        return;
    }
    auto& presentation = state.resultPresentation;
    if (!presentation.started) {
        presentation.started = true;
        presentation.bannerVisible = true;
        presentation.startedAtMs = now;
        const double minutes = std::clamp(parseRuntimeDoubleOrDefault(
            state.rules.getAudioVisualValue("SavourDelay"), 0.1
        ), 0.0, 60.0);
        presentation.bannerDurationMs = static_cast<ULONGLONG>(
            std::llround(minutes * 60000.0)
        );
        state.runtimeMenuOpen = false;
        state.selectionDragActive = false;
        state.rightDragActive = false;
        // Simulation ticks stop at the result. Old combat announcements must
        // not leave the end-of-game EVA stuck behind a tick-based busy timer.
        if (!state.multiplayerLocalSpectator && !runtimeLocalObserver(state.config)) {
            stopRuntimeEvaPlayback(state);
            state.runtimeEvaQueue.clear();
            emitRuntimeSound(state, runtimeResultVoice(state));
        }
        state.repaintRequested = true;
    }
    if (presentation.bannerVisible
        && now >= presentation.startedAtMs
        && now - presentation.startedAtMs >= presentation.bannerDurationMs) {
        beginRuntimeResultScorePage(state, now);
    }
}

RECT runtimeResultBannerRect(const RECT& clientRect, int width, int height) {
    const RECT viewport = runtimeMapViewport(clientRect);
    const double scale = std::min({1.0,
        static_cast<double>(std::max(1L, viewport.right - viewport.left))
            / std::max(1, width),
        static_cast<double>(std::max(1L, viewport.bottom - viewport.top))
            / std::max(1, height)});
    width = std::max(1, static_cast<int>(std::lround(width * scale)));
    height = std::max(1, static_cast<int>(std::lround(height * scale)));
    const int left = viewport.left + (viewport.right - viewport.left - width) / 2;
    const int top = viewport.top + (viewport.bottom - viewport.top - height) / 2;
    return {left, top, left + width, top + height};
}

void drawRuntimeSkirmishResultOverlay(
    HDC dc,
    const RECT& clientRect,
    RuntimeWindowState& state
) {
    if (!state.skirmishMatchFinished) {
        return;
    }
    if (!state.resultPresentation.bannerVisible) {
        if (state.campaignMode) drawRuntimeCampaignScoreOverlay(dc, clientRect, state);
        else drawRuntimeMatchScorePage(dc, clientRect, state);
        return;
    }
    if (!state.multiplayerLocalSpectator && !runtimeLocalObserver(state.config)) {
        const int frame = runtimeResultBannerFrame(state);
        if (const auto* banner = loadRuntimeUiShpFrame(
                state, "", "grfxtxt.shp", frame
            )) {
            const auto& image = banner->image;
            const RECT rect = runtimeResultBannerRect(clientRect,
                image.globalWidth, image.globalHeight);
            if (drawRuntimeUiShpFrameCanvasTransparent(
                    dc, state, "", "grfxtxt.shp", frame, "grfxtxt", rect, true
                )) {
                return;
            }
        }
    }
    // Only missing/corrupt media uses localized plain text. No invented art.
    const char* key = state.campaignMode
        ? (state.skirmishVictory ? "TXT_SCENARIO_WON" : "TXT_SCENARIO_LOST")
        : (state.skirmishVictory ? "TXT_VICTORIOUS" : "TXT_LOST");
    const std::wstring title = (state.multiplayerLocalSpectator || runtimeLocalObserver(state.config))
        ? runtimeMenuLabel(state, "GUI:MultiplayerScore", L"Match finished")
        : runtimeMenuLabel(state, key,
            state.skirmishVictory ? L"Victory" : L"Defeat");
    RECT rect = runtimeResultBannerRect(clientRect, 436, 112);
    const int savedDc = SaveDC(dc);
    SetBkMode(dc, TRANSPARENT);
    SetTextColor(dc, RGB(255, 226, 102));
    SetTextAlign(dc, TA_LEFT | TA_TOP);
    DrawTextW(dc, title.c_str(), static_cast<int>(title.size()), &rect,
        DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX);
    RestoreDC(dc, savedDc);
}

bool runRuntimeCampaignScorePageRenderSmoke(
    const RuntimeConfig& sourceConfig,
    const std::string& outputPath,
    std::string& errorMessage
) {
    constexpr int width = 800;
    constexpr int height = 600;
    HDC screenDc = GetDC(nullptr);
    HDC memoryDc = screenDc == nullptr ? nullptr : CreateCompatibleDC(screenDc);
    BITMAPINFO info{};
    info.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    info.bmiHeader.biWidth = width;
    info.bmiHeader.biHeight = -height;
    info.bmiHeader.biPlanes = 1;
    info.bmiHeader.biBitCount = 32;
    info.bmiHeader.biCompression = BI_RGB;
    void* pixels = nullptr;
    HBITMAP bitmap = memoryDc == nullptr
        ? nullptr
        : CreateDIBSection(
            screenDc,
            &info,
            DIB_RGB_COLORS,
            &pixels,
            nullptr,
            0
        );
    if (memoryDc == nullptr || bitmap == nullptr || pixels == nullptr) {
        if (bitmap != nullptr) DeleteObject(bitmap);
        if (memoryDc != nullptr) DeleteDC(memoryDc);
        if (screenDc != nullptr) ReleaseDC(nullptr, screenDc);
        errorMessage = "could not allocate campaign score smoke surface";
        return false;
    }
    HGDIOBJ oldBitmap = SelectObject(memoryDc, bitmap);

    RuntimeWindowState probe;
    probe.backBuffer.memoryDc = memoryDc;
    probe.backBuffer.bitmap = bitmap;
    probe.backBuffer.oldBitmap = oldBitmap;
    probe.backBuffer.pixels = pixels;
    probe.backBuffer.width = width;
    probe.backBuffer.height = height;
    const auto cleanup = [&] {
        probe.backBuffer = RuntimeBackBuffer{};
        SelectObject(memoryDc, oldBitmap);
        DeleteObject(bitmap);
        DeleteDC(memoryDc);
        ReleaseDC(nullptr, screenDc);
    };
    const auto fail = [&](const std::string& message) {
        errorMessage = message;
        cleanup();
        return false;
    };

    probe.config = sourceConfig;
    probe.config.fixedTickHz = 30;
    probe.config.campaignSourceId = "yr";
    probe.config.campaignDifficulty = "Normal";
    const std::filesystem::path stockYrAlliedMap =
        std::filesystem::path(probe.config.localDataRootPath)
            / "resources" / "mix_exports" / "mapsmd03" / "all01umd.map";
    std::error_code mapError;
    if (std::filesystem::exists(stockYrAlliedMap, mapError)
        && std::filesystem::is_regular_file(stockYrAlliedMap, mapError)) {
        probe.config.defaultMapPath = pathString(stockYrAlliedMap);
    }
    probe.campaignMode = true;
    probe.skirmishMatchFinished = true;
    probe.skirmishVictory = true;
    probe.skirmishResult = "VICTORY";
    probe.config.campaignId = "gdi";
    probe.config.campaignMissionId = "all01md";
    probe.config.campaignPlayerHouse = "Player";
    probe.config.playerCountry = "Americans";

    const auto parTicksForDifficulty = [&](const char* difficulty) {
        probe.config.campaignDifficulty = difficulty;
        initializeRuntimeCampaignScore(probe);
        return probe.campaignScore.parTicks;
    };
    const int hz = std::max(1, probe.config.fixedTickHz);
    if (parTicksForDifficulty("Easy") != 30 * 60 * hz
        || parTicksForDifficulty("Normal") != 20 * 60 * hz
        || parTicksForDifficulty("Hard") != 15 * 60 * hz
        || probe.campaignScore.parTimeField
            != "Ranking.ParTimeHard") {
        return fail("campaign score did not select authored difficulty ParTime");
    }
    probe.config.campaignDifficulty = "Normal";
    initializeRuntimeCampaignScore(probe);
    if (probe.campaignScore.parTimeField != "Ranking.ParTimeMedium"
        || probe.campaignScore.parTimeText != "00:20:00"
        || toLowerAsciiLocal(probe.campaignScore.underParTitleKey)
            != "gui:partitleall06"
        || toLowerAsciiLocal(probe.campaignScore.underParMessageKey)
            != "gui:underparmsgall01md"
        || toLowerAsciiLocal(probe.campaignScore.overParTitleKey)
            != "gui:partitleall05"
        || toLowerAsciiLocal(probe.campaignScore.overParMessageKey)
            != "gui:overparmsgall01md") {
        return fail("stock [Ranking] title/message authority was not loaded");
    }

    probe.campaignScore.enemyUnitsDestroyed = 105;
    probe.campaignScore.enemyStructuresDestroyed = 17;
    probe.campaignScore.friendlyUnitsLost = 8;
    probe.campaignScore.friendlyStructuresLost = 2;
    probe.tick = probe.campaignScore.missionStartTick
        + probe.campaignScore.parTicks - hz;
    finalizeRuntimeCampaignScore(probe, true);
    probe.campaignScore.presentationStartedAtMs = 0;
    const RuntimeCampaignScorePresentation underPresentation =
        runtimeCampaignScorePresentation(probe);
    if (!probe.campaignScore.finishedUnderPar
        || !underPresentation.underPar
        || underPresentation.titleKey
            != probe.campaignScore.underParTitleKey
        || underPresentation.messageKey
            != probe.campaignScore.underParMessageKey
        || underPresentation.title.empty()
        || underPresentation.message.empty()
        || underPresentation.title == widenUtf8(underPresentation.titleKey)
        || underPresentation.message == widenUtf8(underPresentation.messageKey)
        || toLowerAsciiLocal(std::filesystem::path(
            probe.runtimeMenuCsfSource
        ).filename().string()) != "ra2md.csf") {
        return fail("authored UnderPar title/message was not localized");
    }

    RuntimeCampaignScoreState equalityScore = probe.campaignScore;
    equalityScore.captured = false;
    equalityScore.finishedTick = -1;
    probe.campaignScore = equalityScore;
    probe.tick = probe.campaignScore.missionStartTick
        + probe.campaignScore.parTicks;
    finalizeRuntimeCampaignScore(probe, true);
    if (!probe.campaignScore.finishedUnderPar) {
        return fail("elapsed time equal to ParTime did not select UnderPar");
    }

    initializeRuntimeCampaignScore(probe);
    probe.campaignScore.enemyUnitsDestroyed = 105;
    probe.campaignScore.enemyStructuresDestroyed = 17;
    probe.campaignScore.friendlyUnitsLost = 8;
    probe.campaignScore.friendlyStructuresLost = 2;
    probe.tick = probe.campaignScore.missionStartTick
        + probe.campaignScore.parTicks - hz;
    finalizeRuntimeCampaignScore(probe, true);
    probe.campaignScore.presentationStartedAtMs = 0;

    const auto effectiveWidth = [](const RuntimeUiShpCacheEntry* entry) {
        return entry == nullptr ? 0
            : entry->image.globalWidth > 0
                ? entry->image.globalWidth
                : entry->image.width;
    };
    const auto effectiveHeight = [](const RuntimeUiShpCacheEntry* entry) {
        return entry == nullptr ? 0
            : entry->image.globalHeight > 0
                ? entry->image.globalHeight
                : entry->image.height;
    };
    const auto sourceContains = [](
        const RuntimeUiShpCacheEntry* entry,
        const std::string& archive,
        const std::string& asset
    ) {
        if (entry == nullptr) return false;
        const std::string source = toLowerAsciiLocal(entry->sourcePath);
        return source.find(toLowerAsciiLocal(archive)) != std::string::npos
            && source.find(toLowerAsciiLocal(asset)) != std::string::npos;
    };
    const auto validateAssets = [&] (
        RuntimeCampaignScoreTheme theme,
        const std::string& expectedArchive,
        std::string& backgroundSource
    ) {
        const RuntimeCampaignScoreAssets assets =
            runtimeCampaignScoreAssets(theme);
        RuntimeUiShpCacheEntry* backgroundEntry = loadRuntimeUiShpFrame(
            probe, "", assets.background, 0
        );
        RuntimeUiShpCacheEntry* transitionFirst = loadRuntimeUiShpFrame(
            probe, "", assets.transition, 0
        );
        RuntimeUiShpCacheEntry* transitionLast = loadRuntimeUiShpFrame(
            probe, "", assets.transition, 5
        );
        RuntimeUiShpCacheEntry* animationFirst = loadRuntimeUiShpFrame(
            probe, "", assets.animation, 0
        );
        RuntimeUiShpCacheEntry* animationLast = loadRuntimeUiShpFrame(
            probe, "", assets.animation, 43
        );
        RuntimeUiShpCacheEntry* transitionOverflow = loadRuntimeUiShpFrame(
            probe, "", assets.transition, 6
        );
        RuntimeUiShpCacheEntry* animationOverflow = loadRuntimeUiShpFrame(
            probe, "", assets.animation, 44
        );
        const std::vector<RuntimePaletteColor>* palette =
            runtimeUiPalette(probe, assets.palette);
        backgroundSource = backgroundEntry == nullptr
            ? std::string{}
            : backgroundEntry->sourcePath;
        const bool valid = backgroundEntry != nullptr
            && transitionFirst != nullptr
            && transitionLast != nullptr
            && animationFirst != nullptr
            && animationLast != nullptr
            && transitionOverflow == nullptr
            && animationOverflow == nullptr
            && palette != nullptr
            && palette->size() == 256U
            && effectiveWidth(backgroundEntry) == 632
            && effectiveHeight(backgroundEntry) == 568
            && effectiveWidth(transitionFirst) == 472
            && effectiveHeight(transitionFirst) == 448
            && effectiveWidth(animationFirst) == 424
            && effectiveHeight(animationFirst) == assets.animationHeight
            && sourceContains(
                backgroundEntry,
                expectedArchive,
                assets.background
            )
            && sourceContains(
                transitionFirst,
                expectedArchive,
                assets.transition
            )
            && sourceContains(
                animationFirst,
                expectedArchive,
                assets.animation
            );
        if (!valid) {
            const auto source = [](const RuntimeUiShpCacheEntry* entry) {
                return entry == nullptr ? std::string{"<missing>"}
                    : entry->sourcePath;
            };
            std::ostringstream details;
            details << assets.faction
                    << " expected_archive=" << expectedArchive
                    << " bg=" << source(backgroundEntry)
                    << " bg_size=" << effectiveWidth(backgroundEntry)
                    << "x" << effectiveHeight(backgroundEntry)
                    << " transition=" << source(transitionFirst)
                    << " transition_size=" << effectiveWidth(transitionFirst)
                    << "x" << effectiveHeight(transitionFirst)
                    << " transition_last=" << (transitionLast != nullptr)
                    << " transition_overflow=" << (transitionOverflow != nullptr)
                    << " animation=" << source(animationFirst)
                    << " animation_size=" << effectiveWidth(animationFirst)
                    << "x" << effectiveHeight(animationFirst)
                    << " animation_last=" << (animationLast != nullptr)
                    << " animation_overflow=" << (animationOverflow != nullptr)
                    << " palette_size=" << (palette == nullptr ? 0U : palette->size());
            errorMessage = details.str();
        }
        return valid;
    };
    std::string alliedSource;
    std::string sovietSource;
    std::string yuriSource;
    if (!validateAssets(
            RuntimeCampaignScoreTheme::Allied,
            "neutral.mix",
            alliedSource
        )
        || !validateAssets(
            RuntimeCampaignScoreTheme::Soviet,
            "neutral.mix",
            sovietSource
        )
        || !validateAssets(
            RuntimeCampaignScoreTheme::Yuri,
            "ntrlmd.mix",
            yuriSource
        )) {
        return fail("original campaign score SHP/palette contract failed: "
            + errorMessage);
    }

    const auto capture = [&] {
        GdiFlush();
        const auto* surface = static_cast<const std::uint32_t*>(pixels);
        return std::vector<std::uint32_t>(
            surface,
            surface + static_cast<std::size_t>(width * height)
        );
    };
    const auto drawAndCapture = [&] {
        drawRuntimeCampaignScoreOverlay(
            memoryDc,
            RECT{0, 0, width, height},
            probe
        );
        return capture();
    };
    const auto pixelHash = [](const std::vector<std::uint32_t>& values) {
        std::uint64_t hash = 1469598103934665603ULL;
        for (std::uint32_t value : values) {
            hash ^= value;
            hash *= 1099511628211ULL;
        }
        return hash;
    };
    const auto siblingOutput = [&](const std::string& fileName) {
        return pathString(std::filesystem::path(outputPath).parent_path()
            / fileName);
    };
    const auto writeCapture = [&] (
        const std::string& path,
        const std::vector<std::uint32_t>& values
    ) {
        return writeRuntimeSmokeBmp(
            path,
            values.data(),
            width,
            height,
            errorMessage
        );
    };

    std::vector<std::uint32_t> alliedUnderPixels = drawAndCapture();
    if (!writeCapture(outputPath, alliedUnderPixels)) {
        return fail("could not write Allied UnderPar score smoke: "
            + errorMessage);
    }

    probe.campaignScore.captured = false;
    probe.campaignScore.finishedTick = -1;
    probe.tick = probe.campaignScore.missionStartTick
        + probe.campaignScore.parTicks + hz;
    finalizeRuntimeCampaignScore(probe, true);
    probe.campaignScore.presentationStartedAtMs = 0;
    const RuntimeCampaignScorePresentation overPresentation =
        runtimeCampaignScorePresentation(probe);
    if (probe.campaignScore.finishedUnderPar
        || overPresentation.underPar
        || overPresentation.titleKey != probe.campaignScore.overParTitleKey
        || overPresentation.messageKey != probe.campaignScore.overParMessageKey
        || overPresentation.title.empty()
        || overPresentation.message.empty()
        || overPresentation.title == underPresentation.title
        || overPresentation.message == underPresentation.message) {
        return fail("authored OverPar title/message was not selected");
    }
    std::vector<std::uint32_t> alliedOverPixels = drawAndCapture();
    if (!writeCapture(
            siblingOutput("campaign_score_allied_over_smoke.bmp"),
            alliedOverPixels
        )) {
        return fail("could not write Allied OverPar score smoke: "
            + errorMessage);
    }

    int authoredPanelPixelChanges = 0;
    for (int y = 88; y < 207; ++y) {
        for (int x = 212; x < 588; ++x) {
            const std::size_t at = static_cast<std::size_t>(y * width + x);
            if (alliedUnderPixels[at] != alliedOverPixels[at]) {
                ++authoredPanelPixelChanges;
            }
        }
    }
    if (authoredPanelPixelChanges < 50) {
        return fail("authored UnderPar/OverPar text was not drawn into the page");
    }

    probe.campaignScore.finishedUnderPar = true;
    probe.config.campaignId = "nod";
    probe.config.campaignMissionId = "sov01md";
    probe.config.playerCountry = "Russians";
    std::vector<std::uint32_t> sovietPixels = drawAndCapture();
    if (!writeCapture(
            siblingOutput("campaign_score_soviet_smoke.bmp"),
            sovietPixels
        )) {
        return fail("could not write Soviet score smoke: " + errorMessage);
    }

    probe.config.campaignId = "yuri";
    probe.config.campaignMissionId = "yuri-score-probe";
    probe.config.playerCountry = "YuriCountry";
    std::vector<std::uint32_t> yuriPixels = drawAndCapture();
    if (!writeCapture(
            siblingOutput("campaign_score_yuri_smoke.bmp"),
            yuriPixels
        )) {
        return fail("could not write Yuri score smoke: " + errorMessage);
    }

    const auto nonBlackPixels = [](const std::vector<std::uint32_t>& values) {
        return static_cast<int>(std::count_if(
            values.begin(),
            values.end(),
            [](std::uint32_t value) { return (value & 0x00ffffffU) != 0U; }
        ));
    };
    const std::uint64_t alliedHash = pixelHash(alliedUnderPixels);
    const std::uint64_t sovietHash = pixelHash(sovietPixels);
    const std::uint64_t yuriHash = pixelHash(yuriPixels);
    if (nonBlackPixels(alliedUnderPixels) < 250000
        || nonBlackPixels(sovietPixels) < 250000
        || nonBlackPixels(yuriPixels) < 250000
        || alliedHash == sovietHash
        || alliedHash == yuriHash
        || sovietHash == yuriHash) {
        return fail("campaign score faction pixel fingerprints were not distinct");
    }

    {
        RuntimeWindowState ra2TextProbe;
        ra2TextProbe.config = sourceConfig;
        ra2TextProbe.config.campaignSourceId = "ra2";
        ra2TextProbe.config.campaignId = "ra2-gdi";
        const std::wstring ra2ParLabel = runtimeMenuLabel(
            ra2TextProbe,
            "GUI:ParTime",
            L""
        );
        if (ra2ParLabel.empty()
            || toLowerAsciiLocal(std::filesystem::path(
                ra2TextProbe.runtimeMenuCsfSource
            ).filename().string()) != "ra2.csf") {
            return fail("RA2 score text did not use the RA2 CSF catalog");
        }
    }

    {
        auto fallbackProbe = std::make_unique<RuntimeWindowState>();
        fallbackProbe->config = probe.config;
        fallbackProbe->config.resourceRootPath =
            pathString(std::filesystem::path("build") / "missing-score-media");
        fallbackProbe->config.localDataRootPath =
            pathString(std::filesystem::path("build") / "missing-score-media");
        fallbackProbe->config.modRootPath.clear();
        fallbackProbe->campaignMode = true;
        fallbackProbe->skirmishMatchFinished = true;
        fallbackProbe->skirmishVictory = true;
        fallbackProbe->campaignScore = probe.campaignScore;
        fallbackProbe->campaignScore.underParTitleKey = "Fallback Rank";
        fallbackProbe->campaignScore.underParMessageKey =
            "Fallback score media path";
        fallbackProbe->campaignScore.finishedUnderPar = true;
        fallbackProbe->backBuffer.memoryDc = memoryDc;
        fallbackProbe->backBuffer.bitmap = bitmap;
        fallbackProbe->backBuffer.oldBitmap = oldBitmap;
        fallbackProbe->backBuffer.pixels = pixels;
        fallbackProbe->backBuffer.width = width;
        fallbackProbe->backBuffer.height = height;
        drawRuntimeCampaignScoreOverlay(
            memoryDc,
            RECT{0, 0, width, height},
            *fallbackProbe
        );
        std::vector<std::uint32_t> fallbackPixels = capture();
        fallbackProbe->backBuffer = RuntimeBackBuffer{};
        if (nonBlackPixels(fallbackPixels) < 100000
            || fallbackPixels == yuriPixels
            || !writeCapture(
                siblingOutput("campaign_score_fallback_smoke.bmp"),
                fallbackPixels
            )) {
            return fail("missing score media did not use the safe fallback");
        }
    }

    std::cout << "Campaign score page assets: Allied=" << alliedSource
              << " Soviet=" << sovietSource
              << " Yuri=" << yuriSource << "\n";
    std::cout << "Campaign score page fingerprints: Allied=0x"
              << std::hex << alliedHash
              << " Soviet=0x" << sovietHash
              << " Yuri=0x" << yuriHash << std::dec
              << " authoredPanelChanges=" << authoredPanelPixelChanges
              << "\n";
    cleanup();
    return true;
}
void refreshRuntimeMultiplayerPlayerIntentAuthority(
    RuntimeWindowState& state
);

RuntimeMultiplayerGameplayProductionLane runtimeGameplayLaneForUi(
    RuntimeProductionLane lane
) {
    return static_cast<RuntimeMultiplayerGameplayProductionLane>(lane);
}

RuntimeMultiplayerGameplayCell runtimeGameplayCellForUi(
    const RuntimeCellPoint& cell
) {
    return {cell.x, cell.y};
}

void noteRuntimeMultiplayerIntentResult(
    RuntimeWindowState& state,
    bool accepted,
    const std::string& action,
    const std::string& errorMessage,
    const char* rejectionSoundIntent = runtimeSoundIntentSidebarScold
) {
    state.interactionStatus = accepted
        ? action + (state.multiplayerBridge ? " queued for multiplayer" : " executed")
        : action + " rejected: "
            + (errorMessage.empty()
                ? std::string("multiplayer input unavailable")
                : errorMessage);
    if (!accepted) {
        emitRuntimeSound(state, rejectionSoundIntent);
    }
    state.repaintRequested = true;
}

bool captureRuntimeTargetOrderFromUi(
    RuntimeWindowState& state,
    RuntimeMultiplayerGameplayTargetOrderKind order,
    const RuntimeCellPoint& targetCell,
    const WorldObjectInstance* targetObject
) {
    refreshRuntimeMultiplayerPlayerIntentAuthority(state);
    RuntimeMultiplayerGameplayTarget target =
        targetObject != nullptr
            ? RuntimeMultiplayerGameplayTarget{
                RuntimeMultiplayerGameplayObjectTarget{
                    targetObject->instanceId
                }
              }
            : RuntimeMultiplayerGameplayTarget{
                RuntimeMultiplayerGameplayCellTarget{
                    runtimeGameplayCellForUi(targetCell)
                }
              };
    std::string errorMessage;
    const bool accepted = state.multiplayerIntentRouter.targetOrder(
        order,
        state.selectedObjectIds,
        std::move(target),
        errorMessage,
        state.playerLocalCommands.planning
    );
    noteRuntimeMultiplayerIntentResult(
        state,
        accepted,
        "command",
        errorMessage
    );
    return accepted;
}

bool dispatchRuntimeTargetOrderFromUi(
    RuntimeWindowState& state,
    RuntimeMultiplayerGameplayTargetOrderKind order,
    const RuntimeCellPoint& targetCell,
    const WorldObjectInstance* targetObject = nullptr
) {
    if (targetObject && runtimeIsOverlayWallTargetId(targetObject->instanceId)) {
        using Order = RuntimeMultiplayerGameplayTargetOrderKind;
        if (order != Order::Primary && order != Order::Attack && order != Order::ForceFireCell) return false;
        const auto current = runtimeOverlayWallTargetAtCell(state, {targetObject->x, targetObject->y});
        if (!current || current->instanceId != targetObject->instanceId
            || toUpperAsciiLocal(current->type) != toUpperAsciiLocal(targetObject->type)) return false;
        return dispatchRuntimeTargetOrderFromUi(state,
            Order::ForceFireCell,
            {current->x, current->y}, nullptr);
    }
    if (runtimeUsesGameplayIntentRouter(state)) {
        return captureRuntimeTargetOrderFromUi(
            state,
            order,
            targetCell,
            targetObject
        );
    }
    RuntimeMultiplayerGameplayTargetOrderCommand body;
    body.order = order;
    body.objectIds.assign(state.selectedObjectIds.begin(), state.selectedObjectIds.end());
    body.target = targetObject
        ? RuntimeMultiplayerGameplayTarget{RuntimeMultiplayerGameplayObjectTarget{targetObject->instanceId}}
        : RuntimeMultiplayerGameplayTarget{RuntimeMultiplayerGameplayCellTarget{{targetCell.x, targetCell.y}}};
    body.append = state.playerLocalCommands.planning;
    const bool accepted = applyRuntimePlayerTargetOrder(state, state.economy.owner, body, true);
    if (accepted && body.append) state.interactionStatus = "order appended";
    return accepted;
}

bool dispatchRuntimeSelectionCommandFromUi(
    RuntimeWindowState& state,
    RuntimeMultiplayerGameplayCommandType type
) {
    if (state.offlineGameplayIntentRouting && !state.config.multiplayerActive
        && state.selectedObjectIds.size()>runtimeMultiplayerGameplayMaximumObjectIds) {
        RuntimeMultiplayerGameplayCommand command;
        if(type==RuntimeMultiplayerGameplayCommandType::Stop)
            command.body=RuntimeMultiplayerGameplayStopCommand{state.selectedObjectIds};
        else if(type==RuntimeMultiplayerGameplayCommandType::Guard)
            command.body=RuntimeMultiplayerGameplayGuardCommand{state.selectedObjectIds};
        else command.body=RuntimeMultiplayerGameplayScatterCommand{state.selectedObjectIds};
        std::string error;return dispatchRuntimeOfflineGameplayCommand(state,command,error);
    }
    if (!runtimeUsesGameplayIntentRouter(state)) {
        state.playerCommands.cancel(state.selectedObjectIds);
        if (type == RuntimeMultiplayerGameplayCommandType::Stop) {
            issueRuntimeStopCommand(state);
        } else if (type == RuntimeMultiplayerGameplayCommandType::Guard) {
            issueRuntimeGuardCommand(state);
        } else {
            issueRuntimeScatterCommand(state);
        }
        return state.lastCommand.valid
            && state.lastCommand.acceptedCount > 0;
    }

    refreshRuntimeMultiplayerPlayerIntentAuthority(state);
    std::string errorMessage;
    bool accepted = false;
    if (type == RuntimeMultiplayerGameplayCommandType::Stop) {
        accepted = state.multiplayerIntentRouter.stop(
            state.selectedObjectIds,
            errorMessage
        );
    } else if (type == RuntimeMultiplayerGameplayCommandType::Guard) {
        accepted = state.multiplayerIntentRouter.guard(
            state.selectedObjectIds,
            errorMessage
        );
    } else {
        accepted = state.multiplayerIntentRouter.scatter(
            state.selectedObjectIds,
            errorMessage
        );
    }
    noteRuntimeMultiplayerIntentResult(
        state,
        accepted,
        type == RuntimeMultiplayerGameplayCommandType::Stop
            ? "stop"
            : (type == RuntimeMultiplayerGameplayCommandType::Guard
                ? "guard"
                : "scatter"),
        errorMessage
    );
    return accepted;
}

bool dispatchRuntimeSecondaryActionFromUi(
    RuntimeWindowState& state,
    int objectId,
    RuntimeMultiplayerGameplaySecondaryActionKind action =
        RuntimeMultiplayerGameplaySecondaryActionKind::Contextual
) {
    // A repeated selection is not an ability command. In particular, do not
    // cancel queued movement or send a rejected replay/network intent for Tanya.
    const WorldObjectInstance* object = findObjectById(state, objectId);
    if (object == nullptr || !runtimeObjectHasSecondaryAction(state, *object)) {
        return false;
    }
    if (!runtimeUsesGameplayIntentRouter(state)) {
        state.playerCommands.cancel({objectId});
        return executeRuntimeSecondaryAction(state, objectId);
    }
    refreshRuntimeMultiplayerPlayerIntentAuthority(state);
    std::string errorMessage;
    const bool accepted = state.multiplayerIntentRouter.secondaryAction(
        action,
        {objectId},
        errorMessage
    );
    noteRuntimeMultiplayerIntentResult(
        state,
        accepted,
        "secondary action",
        errorMessage
    );
    return accepted;
}

bool dispatchRuntimeSecondaryActionForSelectionFromUi(
    RuntimeWindowState& state
) {
    if (!runtimeUsesGameplayIntentRouter(state)) {
        return executeRuntimeSecondaryActionForSelection(state);
    }
    cleanRuntimeSelection(state);
    // Choose once from the whole selection. Recomputing in each 256-ID
    // fragment would make an all-deployed fragment fold in a mixed group.
    const std::vector<int> selectedIds = state.selectedObjectIds;
    const auto action = runtimeSecondaryDeploymentActionForObjects(state, selectedIds);
    std::vector<std::int32_t> actorIds;
    for (int objectId : selectedIds) {
        const WorldObjectInstance* object = findObjectById(state, objectId);
        if (object != nullptr
            && !runtimeObjectDisabledByParasite(state, objectId)
            && (runtimeObjectHasSecondaryAction(state, *object)
                || runtimeSecondaryDeploymentState(state, *object).has_value())) {
            actorIds.push_back(objectId);
        }
    }
    if (!actorIds.empty()) {
        refreshRuntimeMultiplayerPlayerIntentAuthority(state);
        bool accepted = false;
        std::string errorMessage;
        // A group uses one frame slot, with large selections split only at
        // the payload's object-ID limit rather than one command per actor.
        for (std::size_t start = 0; start < actorIds.size();
            start += runtimeMultiplayerGameplayMaximumObjectIds) {
            const std::size_t end = std::min(
                start + runtimeMultiplayerGameplayMaximumObjectIds, actorIds.size());
            std::vector<std::int32_t> batch(actorIds.begin() + start, actorIds.begin() + end);
            if (state.multiplayerIntentRouter.secondaryAction(
                    action,
                    std::move(batch), errorMessage)) {
                accepted = true;
            }
        }
        noteRuntimeMultiplayerIntentResult(state, accepted, "secondary action", errorMessage);
        return accepted;
    }
    state.interactionStatus =
        "secondary failed: select deployable unit";
    emitRuntimeSound(state, "blocked");
    return false;
}

bool beginRuntimePlacementFromUi(
    RuntimeWindowState& state,
    const RuntimeSelectedPlacement& placement,
    bool resetPreview
) {
    if (!runtimeUsesGameplayIntentRouter(state)) {
        selectRuntimeReadyPlacement(state, placement, resetPreview);
        return true;
    }
    refreshRuntimeMultiplayerPlayerIntentAuthority(state);
    std::string errorMessage;
    bool accepted = state.multiplayerIntentRouter.beginPlacement(
        runtimeGameplayLaneForUi(placement.lane),
        placement.order.serial,
        placement.item == nullptr ? std::string{} : placement.item->typeId,
        errorMessage
    );
    if (accepted && resetPreview && placement.item != nullptr) {
        const std::optional<RuntimeCellPoint> defaultPlacement =
            findRuntimePlacementCellNearBase(state, *placement.item);
        accepted = state.multiplayerIntentRouter.previewPlacement(
            runtimeGameplayCellForUi(
                defaultPlacement.value_or(RuntimeCellPoint{})
            ),
            defaultPlacement.has_value(),
            errorMessage
        );
    }
    noteRuntimeMultiplayerIntentResult(
        state,
        accepted,
        "building placement",
        errorMessage
    );
    return accepted;
}

bool dismissRuntimePlacementFromUi(RuntimeWindowState& state) {
    if (!runtimeSelectedPlacement(state).has_value()) return false;
    if (runtimeUsesGameplayIntentRouter(state)) state.multiplayerIntentRouter.cancelPlacement();
    else clearRuntimePlacementSelection(state);
    state.interactionStatus = "building ready: click sidebar icon to place";
    state.selectionDragActive = state.selectionDragMoved = false;
    state.rightDragActive = state.rightDragMoved = false;
    return true;
}

bool dispatchRuntimeQueueProductionFromUi(
    RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item,
    RuntimeProductionInsertMode insertMode = RuntimeProductionInsertMode::Back
) {
    if (!runtimeUsesGameplayIntentRouter(state)) {
        return queueRuntimeBuildOrder(state, item, insertMode);
    }
    refreshRuntimeMultiplayerPlayerIntentAuthority(state);
    std::string errorMessage;
    bool accepted = false;
    const std::optional<RuntimeProductionLane> lane =
        runtimeProductionLaneForCatalogItem(state, item);
    if (lane.has_value()) {
        const RuntimeProductionLaneState& laneState =
            state.economy.localProductionLanes.lanes[
                runtimeProductionLaneIndex(*lane)
            ];
        if (laneState.active.has_value()
            && runtimeProductionItemKeysMatch(
                laneState.active->itemKey,
                item.typeId
            )
            && laneState.onHold) {
            accepted = state.multiplayerIntentRouter.resumeProduction(
                runtimeGameplayLaneForUi(*lane),
                laneState.active->serial,
                errorMessage
            );
        } else {
            accepted = state.multiplayerIntentRouter.queueProduction(
                item.typeId,
                insertMode == RuntimeProductionInsertMode::AfterActive
                    ? RuntimeMultiplayerGameplayProductionInsertMode::AfterActive
                    : RuntimeMultiplayerGameplayProductionInsertMode::Back,
                errorMessage
            );
        }
    } else {
        errorMessage = "unknown production lane";
    }
    noteRuntimeMultiplayerIntentResult(
        state,
        accepted,
        "production",
        errorMessage
    );
    return accepted;
}

bool dispatchRuntimeBuildButtonSecondaryActionFromUi(
    RuntimeWindowState& state,
    const RuntimeBuildCatalogItem& item
) {
    if (!runtimeUsesGameplayIntentRouter(state)) {
        return handleRuntimeBuildButtonSecondaryAction(state, item);
    }
    refreshRuntimeMultiplayerPlayerIntentAuthority(state);
    RuntimeProductionLane lane = RuntimeProductionLane::Structures;
    std::uint64_t serial = 0;
    bool setHold = false;
    if (const RuntimeProductionLaneOrder* ready =
            runtimeReadyProductionForItem(state, item, &lane)) {
        serial = ready->serial;
    } else if (const std::optional<RuntimeProductionLane> itemLane =
            runtimeProductionLaneForCatalogItem(state, item)) {
        lane = *itemLane;
        const RuntimeProductionLaneState& laneState =
            state.economy.localProductionLanes.lanes[
                runtimeProductionLaneIndex(lane)
            ];
        const auto queued = std::find_if(
            laneState.queued.rbegin(),
            laneState.queued.rend(),
            [&](const RuntimeProductionLaneOrder& order) {
                return runtimeProductionItemKeysMatch(
                    order.itemKey,
                    item.typeId
                );
            }
        );
        if (queued != laneState.queued.rend()) {
            serial = queued->serial;
        } else if (laneState.active.has_value()
            && runtimeProductionItemKeysMatch(
                laneState.active->itemKey,
                item.typeId
            )) {
            serial = laneState.active->serial;
            setHold = !laneState.onHold
                && !runtimePeekCompletedProduction(
                    state.economy.localProductionLanes,
                    lane
                ).has_value();
        }
    }

    std::string errorMessage;
    bool accepted = false;
    if (serial == 0) {
        errorMessage = "nothing to cancel";
    } else if (setHold) {
        accepted = state.multiplayerIntentRouter.holdProduction(
            runtimeGameplayLaneForUi(lane),
            serial,
            errorMessage
        );
    } else {
        accepted = state.multiplayerIntentRouter.cancelProduction(
            runtimeGameplayLaneForUi(lane),
            serial,
            errorMessage
        );
    }
    noteRuntimeMultiplayerIntentResult(
        state,
        accepted,
        setHold ? "production hold" : "production cancel",
        errorMessage
    );
    return accepted;
}

bool dispatchRuntimeStructureToolFromUi(
    RuntimeWindowState& state,
    RuntimeSidebarTool tool,
    int objectId
) {
    if (!runtimeUsesGameplayIntentRouter(state)) {
        return tool == RuntimeSidebarTool::Sell
            ? sellRuntimeStructure(state, objectId)
            : repairRuntimeStructure(state, objectId);
    }
    refreshRuntimeMultiplayerPlayerIntentAuthority(state);
    std::string errorMessage;
    const bool accepted = tool == RuntimeSidebarTool::Sell
        ? state.multiplayerIntentRouter.sell(objectId, errorMessage)
        : state.multiplayerIntentRouter.repair(objectId, errorMessage);
    noteRuntimeMultiplayerIntentResult(
        state,
        accepted,
        tool == RuntimeSidebarTool::Sell ? "sell" : "repair",
        errorMessage
    );
    return accepted;
}

bool cancelRuntimeActiveSuperWeaponTargetSelection(
    RuntimeWindowState& state,
    const std::string& reason
) {
    if (runtimeUsesGameplayIntentRouter(state)
        && state.multiplayerIntentRouter.superWeapon().has_value()) {
        state.multiplayerIntentRouter.cancelSuperWeapon();
        clearRuntimeLocalChronosphereMarker(state);
        state.interactionStatus =
            "superweapon target canceled: " + reason;
        state.selectionDragActive = false;
        state.selectionDragMoved = false;
        return true;
    }
    ensureRuntimeSuperWeaponsInitialized(state);
    const std::string owner = toLowerAsciiLocal(
        trimAsciiLocal(state.economy.owner)
    );
    for (const SuperWeaponSidebarSnapshot& snapshot :
            state.superWeapons.sidebarSnapshots()) {
        if (!snapshot.targetSelectionActive
            || (!owner.empty()
                && toLowerAsciiLocal(trimAsciiLocal(snapshot.owner))
                    != owner)) {
            continue;
        }

        const std::string superWeaponOwner = snapshot.owner;
        const std::string superWeaponId = snapshot.superWeaponId;
        SuperWeaponWorldContext context = runtimeSuperWeaponContext(state);
        context.emit = runtimeSuperWeaponEventSink(state);
        if (!state.superWeapons.cancelTargetSelection(
                superWeaponOwner,
                superWeaponId,
                context,
                reason
            )) {
            continue;
        }
        state.interactionStatus = "superweapon target canceled";
        clearRuntimeLocalChronosphereMarker(state);
        (void)flushRuntimeSuperWeaponHostEvents(state);
        state.economy.status = state.interactionStatus;
        state.selectionDragActive = false;
        state.selectionDragMoved = false;
        return true;
    }
    return false;
}

