    RuntimeObjectBehavior conflictingBehavior;
    conflictingBehavior.kind = RuntimeBehaviorKind::Move;
    conflictingBehavior.state = RuntimeBehaviorState::Queued;
    conflictingBehavior.targetObjectId = 202;
    conflictingBehavior.pendingAllowedOccupiedObjectId = 202;
    probe.behaviors[200] = conflictingBehavior;
    probe.pendingEngineerCaptures[200] = 202;
    probe.pendingEngineerActions[200] = RuntimeEngineerAction::Capture;
    probe.pendingOccupyTargets[200] = 202;
    probe.pendingTransportTargets[200] = 202;
    probe.pendingTimedBombIntents[200] = {
        RuntimeTimedBombIntentKind::C4,
        202
    };

    WorldObjectInstance* source = findMutableObjectById(probe, 100);
    const WorldObjectInstance* targetBefore = findObjectById(probe, 200);
    if (source == nullptr || targetBefore == nullptr) {
        errorMessage = "psychic impact fixture objects disappeared";
        return false;
    }
    source->alive = false;
    const int targetHealthBefore = targetBefore->health;
    RuntimeProjectileEffect impactProjectile = makeProjectile(1, 200);
    if (!applyRuntimeProjectileImpact(probe, impactProjectile)) {
        errorMessage = "psychedelic impact was not consumed";
        return false;
    }
    const RuntimePsychicStatusRecord* status =
        probe.psychicStatuses.findByTarget(200);
    const WorldObjectInstance* targetAfter = findObjectById(probe, 200);
    if (status == nullptr
        || status->expiresTick != probe.tick + 2400
        || !status->sourceValidatedAtLaunch
        || !status->attackOriginalAllies
        || targetAfter == nullptr
        || targetAfter->health != targetHealthBefore
        || probe.behaviors.contains(200)
        || probe.pendingEngineerCaptures.contains(200)
        || probe.pendingEngineerActions.contains(200)
        || probe.pendingOccupyTargets.contains(200)
        || probe.pendingTransportTargets.contains(200)
        || probe.pendingTimedBombIntents.contains(200)) {
        errorMessage =
            "psychic impact damaged HP, used live source, or kept intents";
        return false;
    }

    // The focused fixture constructs only the objects it exercises. Give the
    // repair-depot pair a small authored land domain so the real dock/path
    // callbacks can validate the reservation instead of seeing an empty map.
    for (int y = 18; y <= 24; ++y) {
        for (int x = 18; x <= 24; ++x) {
            TerrainCell terrain;
            terrain.x = x;
            terrain.y = y;
            terrain.cellIndex512 = runtimeCellKey(x, y);
            terrain.tileIndex = 0;
            probe.world.accessTerrainCells().push_back(terrain);
            probe.terrainInfoByCell.emplace(
                runtimeCellKey(x, y),
                RuntimeTerrainInfo{}
            );
        }
    }
    probe.terrainByCell = buildRuntimeTerrainLookup(probe.world);
    probe.structureFootprints["PSYBLD"] = {2, 1, true};
    ensureRuntimeGarrisonsInitialized(probe);
    ensureRuntimeGatesInitialized(probe);
    ensureRuntimeSubcellsInitialized(probe);
    ensureRuntimeRepairDepotsInitialized(probe);
    RuntimeRepairDepotContext repairContext =
        makeRuntimeRepairDepotContext(probe);
    const RuntimeRepairDepotCommandResult repairReserve =
        probe.repairDepots.reserveDock(
            repairContext,
            204,
            203,
            probe.tick
        );
    if (!repairReserve.accepted
        || !applyRuntimeRepairDepotActions(probe, repairReserve.actions)) {
        errorMessage = "psychic dock-release fixture could not reserve";
        return false;
    }
    const RuntimeRepairDepotRelation* repairRelation =
        findRuntimeRepairDepotRelationForUnit(probe.repairDepots, 203);
    WorldObjectInstance* repairTarget = findMutableObjectById(probe, 203);
    if (repairRelation == nullptr || repairTarget == nullptr) {
        errorMessage = "psychic dock-release reservation disappeared";
        return false;
    }
    const RuntimeRepairDepotCell repairDock = repairRelation->dockCell;
    repairTarget->x = repairDock.x;
    repairTarget->y = repairDock.y;
    repairTarget->cell = runtimeCellKey(repairDock.x, repairDock.y);
    repairTarget->onBridge = repairDock.onBridge;
    clearRuntimeRenderPosition(*repairTarget);
    const RuntimeRepairDepotCommandResult repairAttach =
        probe.repairDepots.attachAtDock(
            repairContext,
            204,
            203,
            repairDock,
            probe.tick
        );
    if (!repairAttach.accepted
        || !applyRuntimeRepairDepotActions(probe, repairAttach.actions)
        || findRuntimeRepairDepotRelationForUnit(
            probe.repairDepots,
            203
        ) == nullptr
        || findRuntimeRepairDepotRelationForUnit(
            probe.repairDepots,
            203
        )->phase != RuntimeRepairDepotRelationPhase::Docked) {
        errorMessage = "psychic dock-release fixture could not attach";
        return false;
    }
    RuntimeProjectileEffect repairPsychicProjectile = makeProjectile(3, 203);
    if (!applyRuntimeProjectileImpact(probe, repairPsychicProjectile)
        || probe.psychicStatuses.findByTarget(203) == nullptr
        || findRuntimeRepairDepotRelationForUnit(
            probe.repairDepots,
            203
        ) != nullptr
        || findObjectById(probe, 203) == nullptr
        || findObjectById(probe, 203)->dockedToObjectId >= 0) {
        errorMessage =
            "Psychic Applied did not atomically release dock repair";
        return false;
    }

    RuntimeFactoryDeliveryAcquireRequest deliveryRequest;
    deliveryRequest.lease.canonicalOwner =
        runtimeRepairDepotCanonicalOwnerId(probe, "HouseA");
    deliveryRequest.lease.hostId = 204;
    deliveryRequest.lease.dockIndex = -1;
    deliveryRequest.lease.lane = RuntimeProductionLane::Vehicles;
    deliveryRequest.lease.orderSerial = 1;
    deliveryRequest.lease.producedObjectId = 205;
    deliveryRequest.lease.acquiredTick = probe.tick;
    deliveryRequest.lease.rallyCell = {31, 30, false};
    deliveryRequest.lease.domain = RuntimeFactoryDeliveryDomain::Land;
    const RuntimeFactoryDeliveryAcquireResult deliveryAcquire =
        probe.factoryDeliveries.acquire(deliveryRequest);
    RuntimeObjectBehavior deliveryBehavior;
    deliveryBehavior.kind = RuntimeBehaviorKind::Move;
    deliveryBehavior.state = RuntimeBehaviorState::Queued;
    deliveryBehavior.moveTarget = {31, 30};
    probe.behaviors[205] = deliveryBehavior;
    RuntimeProjectileEffect deliveryPsychicProjectile = makeProjectile(4, 205);
    if (!deliveryAcquire.acquired
        || !applyRuntimeProjectileImpact(probe, deliveryPsychicProjectile)
        || probe.psychicStatuses.findByTarget(205) == nullptr
        || runtimeFactoryDeliveryOwnsEgress(probe, 205)
        || probe.behaviors.contains(205)) {
        errorMessage =
            "Psychic Applied did not release factory egress authority";
        return false;
    }

    RuntimeProjectileEffect nonLocalPsychicProjectile = makeProjectile(5, 206);
    RuntimeProjectileEffect neutralPsychicProjectile = makeProjectile(6, 208);
    if (!applyRuntimeProjectileImpact(probe, nonLocalPsychicProjectile)
        || !applyRuntimeProjectileImpact(probe, neutralPsychicProjectile)) {
        errorMessage = "psychic guard fixtures did not accept status";
        return false;
    }
    probe.economy.skirmishStartApplied = false;
    // Four retail frames at 60 Hz: exercise an actual Guard scan boundary.
    probe.tick = 112;
