        item.kind = RuntimeBuildKind::Unit;
        item.typeId = "HASHTANK";
        item.label = "Hash Tank";
        item.owner = "Americans,Russians";
        item.prerequisite = "HASHFACTORY";
        item.requiredFactory = "UnitType";
