    int campaignAiProbeTimesFailed = -1;
    double campaignAiProbeWeight = -1.0;
    std::vector<RuntimeCampaignAiTriggerDefinition>
        authoredCampaignAiTriggers =
            std::move(state.triggers.campaignAiTriggers);
    // all01 deliberately enables the global AIMD trigger set.  The focused
